/**
 * A solution to find the largest integer X such that every integer from 1 to X 
 * can have its digits assigned to a unique set of available people.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            // Read the number of people available
            int n = reader.nextInt();
            if (n <= 0) {
                writer.println(0);
                return;
            }

            // availability[i][d] is true if person i has digit d
            boolean[][] availability = new boolean[n][10];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < 6; j++) {
                    int digit = reader.nextInt();
                    if (digit >= 0 && digit <= 9) {
                        availability[i][digit] = true;
                    }
                }
            }

            DigitAssignmentSolver solver = new DigitAssignmentSolver(n, availability);
            int result = solver.findMaxConsecutiveSatisfiableNumber();
            writer.println(result);

        } catch (Exception e) {
            // Log error if necessary; in competitive programming, we usually exit gracefully
        } finally {
            writer.close();
        }
    }

    /**
     * Encapsulates the logic for digit assignment and number checking.
     */
    static class DigitAssignmentSolver {
        private final int numberOfPeople;
        private final boolean[][] availability;

        public DigitAssignmentSolver(int numberOfPeople, boolean[][] availability) {
            this.numberOfPeople = numberOfPeople;
            this.availability = availability;
        }

        /**
         * Finds the largest X such that all numbers from 1 to X are satisfiable.
         */
        public int findMaxConsecutiveSatisfiableNumber() {
            int lastSatisfiable = 0;
            // The original problem constraints imply checking up to 999
            for (int i = 1; i < 1000; i++) {
                if (isSatisfiable(i)) {
                    lastSatisfiable = i;
                } else {
                    // Break as soon as a number cannot be formed
                    break;
                }
            }
            return lastSatisfiable;
        }

        /**
         * Determines if a single number can be formed using the available people.
         */
        private boolean isSatisfiable(int number) {
            int[] digits = extractDigits(number);

            // If the number has more digits than there are people, it's impossible
            if (digits.length > numberOfPeople) {
                return false;
            }

            boolean[] personUsed = new boolean[numberOfPeople];
            return canAssignDigits(digits, 0, personUsed);
        }

        /**
         * Uses backtracking to check if digits can be mapped to unique people.
         * 
         * @param digits The array of digits in the number.
         * @param digitIdx The current digit we are trying to assign.
         * @param personUsed Boolean array tracking which people have already been assigned a digit.
         * @return true if a valid assignment exists.
         */
        private boolean canAssignDigits(int[] digits, int digitIdx, boolean[] personUsed) {
            // Base case: all digits have been successfully assigned
            if (digitIdx == digits.length) {
                return true;
            }

            int currentDigit = digits[digitIdx];

            for (int p = 0; p < numberOfPeople; p++) {
                // If person 'p' is not used and has the required digit
                if (!personUsed[p] && availability[p][currentDigit]) {
                    personUsed[p] = true; // Tentative assignment

                    if (canAssignDigits(digits, digitIdx + 1, personUsed)) {
                        return true;
                    }

                    personUsed[p] = false; // Backtrack
                }
            }

            return false;
        }

        /**
         * Breaks an integer into its component digits.
         */
        private int[] extractDigits(int number) {
            if (number == 0) return new int[]{0};

            int count = 0;
            int temp = number;
            while (temp > 0) {
                count++;
                temp /= 10;
            }

            int[] digits = new int[count];
            temp = number;
            for (int i = 0; i < count; i++) {
                digits[i] = temp % 10;
                temp /= 10;
            }
            return digits;
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String token = next();
            return token != null ? Integer.parseInt(token) : 0;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution to find the largest integer X such that all integers from 1 to X
 * can be formed by selecting one digit from each of a subset of distinct people.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            Solver solver = new Solver();
            solver.solve(reader, writer);
        } catch (Exception e) {
            // In a production environment, use a logger. 
            // For competitive programming, we catch to ensure stream closure.
        } finally {
            writer.close();
        }
    }

    static class Solver {
        private static final int MAX_SEARCH_LIMIT = 1010;

        /**
         * Orchestrates the solving process.
         */
        public void solve(FastReader sc, PrintWriter w) {
            int n = sc.nextInt();
            if (n <= 0) {
                w.println(0);
                return;
            }

            // Store each person's available digits in a Set for O(1) lookup.
            @SuppressWarnings("unchecked")
            Set<Integer>[] personDigits = new HashSet[n];
            for (int i = 0; i < n; i++) {
                personDigits[i] = new HashSet<>();
                for (int j = 0; j < 6; j++) {
                    personDigits[i].add(sc.nextInt());
                }
            }

            int lastValidNumber = 0;

            // Find the largest consecutive number starting from 1 that meets the criteria.
            for (int i = 1; i <= MAX_SEARCH_LIMIT; i++) {
                if (canFormNumber(i, personDigits)) {
                    lastValidNumber = i;
                } else {
                    break;
                }
            }

            w.println(lastValidNumber);
        }

        /**
         * Determines if a number can be formed by assigning a unique person to each digit.
         */
        private boolean canFormNumber(int number, Set<Integer>[] personDigits) {
            List<Integer> digits = getDigits(number);
            int numPeople = personDigits.length;

            // If number of digits exceeds available people, it's impossible.
            if (digits.size() > numPeople) {
                return false;
            }

            // Use backtracking to find a valid assignment of people to digits.
            return backtrack(digits, personDigits, 0, new boolean[numPeople]);
        }

        /**
         * Breaks an integer into its constituent digits.
         */
        private List<Integer> getDigits(int number) {
            List<Integer> digits = new ArrayList<>();
            int temp = number;
            while (temp > 0) {
                digits.add(temp % 10);
                temp /= 10;
            }
            Collections.reverse(digits);
            return digits;
        }

        /**
         * A backtracking approach to solve the bipartite matching problem between 
         * digits and people.
         * 
         * @param digits The list of digits in the target number.
         * @param personDigits The sets of digits available for each person.
         * @param digitIdx The current index in the digits list we are assigning.
         * @param personUsed Boolean array tracking which people have already been assigned.
         * @return true if a valid permutation of people exists.
         */
        private boolean backtrack(List<Integer> digits, Set<Integer>[] personDigits, int digitIdx, boolean[] personUsed) {
            if (digitIdx == digits.size()) {
                return true;
            }

            int targetDigit = digits.get(digitIdx);

            for (int i = 0; i < personDigits.length; i++) {
                // If person 'i' is not used and contains the required digit
                if (!personUsed[i] && personDigits[i].contains(targetDigit)) {
                    personUsed[i] = true;
                    if (backtrack(digits, personDigits, digitIdx + 1, personUsed)) {
                        return true;
                    }
                    personUsed[i] = false; // Backtrack step
                }
            }

            return false;
        }
    }

    /**
     * Efficient I/O reader for handling large inputs.
     */
    static class FastReader {
        private final InputStream inputStream;
        private final byte[] buffer = new byte[1024];
        private int pointer = 0;
        private int bytesRead = 0;

        public FastReader(InputStream inputStream) {
            this.inputStream = inputStream;
        }

        private int readByte() {
            if (pointer >= bytesRead) {
                pointer = 0;
                try {
                    bytesRead = inputStream.read(buffer);
                } catch (IOException e) {
                    return -1;
                }
                if (bytesRead <= 0) return -1;
            }
            return buffer[pointer++] & 0xff;
        }

        public int nextInt() {
            int c = readByte();
            while (c != -1 && c <= 32) c = readByte();
            if (c == -1) return 0;

            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = readByte();
            }

            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = readByte();
            }
            return res * sgn;
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A program to find the largest integer x such that all integers from 1 to x 
 * can be formed by picking one digit from a subset of given digit sets.
 */
public class Main {
    private static final int MAX_SEARCH_LIMIT = 1000000;

    private int numberOfSets;
    private int[][] digitSets;
    private final boolean[] foundNumbers = new boolean[MAX_SEARCH_LIMIT + 1];

    public static void main(String[] args) {
        new Main().run();
    }

    /**
     * Entry point of the application.
     */
    public void run() {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            String firstLine = reader.nextLine();
            if (firstLine == null || firstLine.isEmpty()) {
                return;
            }

            numberOfSets = Integer.parseInt(firstLine.trim());
            digitSets = new int[numberOfSets][6];

            for (int i = 0; i < numberOfSets; i++) {
                for (int j = 0; j < 6; j++) {
                    digitSets[i][j] = reader.nextInt();
                }
            }

            // Generate all possible numbers using permutations of the digit sets
            generatePossibleNumbers();

            // Find the largest x such that 1 to x are all present in foundNumbers
            int result = findLargestConsecutiveInteger();
            writer.println(result);

        } catch (Exception e) {
            // In a production environment, use a logger instead of printStackTrace
        } finally {
            writer.close();
        }
    }

    /**
     * Initializes the recursive generation process by picking the first digit 
     * from each available set.
     */
    private void generatePossibleNumbers() {
        for (int i = 0; i < numberOfSets; i++) {
            for (int digit : digitSets[i]) {
                // We only care about forming numbers > 0 for the search range
                if (digit > 0 && digit <= MAX_SEARCH_LIMIT) {
                    generate(digit, 1 << i);
                }
            }
        }
    }

    /**
     * Recursively builds numbers by picking digits from unused sets.
     * 
     * @param currentNumber The number formed so far.
     * @param usedSetsMask A bitmask representing the sets already used in this permutation.
     */
    private void generate(int currentNumber, int usedSetsMask) {
        if (currentNumber > MAX_SEARCH_LIMIT) {
            return;
        }

        foundNumbers[currentNumber] = true;

        for (int i = 0; i < numberOfSets; i++) {
            // Check if the i-th set has already been used in this path
            if ((usedSetsMask & (1 << i)) == 0) {
                for (int digit : digitSets[i]) {
                    // Use long to prevent overflow during calculation before checking limit
                    long nextNumberLong = (long) currentNumber * 10 + digit;

                    if (nextNumberLong <= MAX_SEARCH_LIMIT) {
                        generate((int) nextNumberLong, usedSetsMask | (1 << i));
                    }
                }
            }
        }
    }

    /**
     * Finds the largest x such that all numbers from 1 to x are present in the array.
     * 
     * @return The value of x.
     */
    private int findLargestConsecutiveInteger() {
        for (int i = 1; i <= MAX_SEARCH_LIMIT; i++) {
            if (!foundNumbers[i]) {
                return i - 1;
            }
        }
        return MAX_SEARCH_LIMIT;
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream inputStream) {
            br = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            String next = next();
            return (next == null) ? 0 : Integer.parseInt(next);
        }

        public String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver designed to find the smallest positive integer that cannot be formed
 * by concatenating digits chosen from distinct provided sets.
 */
public class BeautifulNumberSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        String nInput = reader.next();
        if (nInput == null) {
            return;
        }

        int n = Integer.parseInt(nInput);
        int[][] digitSets = reader.readIntMatrix(n, 6);

        BeautifulNumberSolver solver = new BeautifulNumberSolver();
        int result = solver.solve(n, digitSets);

        System.out.println(result);
    }

    /**
     * Generates all possible 1, 2, and 3-digit numbers using digits from distinct rows
     * and identifies the smallest missing positive integer.
     *
     * @param n         The number of digit sets provided.
     * @param digitSets A 2D array where each row represents a set of 6 digits.
     * @return The smallest positive integer not found in the generated set.
     */
    public int solve(int n, int[][] digitSets) {
        BitSet foundNumbers = new BitSet();

        // 1. Generate all possible 1-digit numbers
        for (int i = 0; i < n; i++) {
            for (int digit : digitSets[i]) {
                foundNumbers.set(digit);
            }
        }

        // 2. Generate all possible 2-digit numbers using digits from two different sets
        if (n >= 2) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (i == j) continue;

                    for (int d1 : digitSets[i]) {
                        for (int d2 : digitSets[j]) {
                            foundNumbers.set(d1 * 10 + d2);
                        }
                    }
                }
            }
        }

        // 3. Generate all possible 3-digit numbers using digits from three different sets
        if (n >= 3) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (i == j) continue;

                    for (int k = 0; k < n; k++) {
                        if (k == i || k == j) continue;

                        for (int d1 : digitSets[i]) {
                            for (int d2 : digitSets[j]) {
                                for (int d3 : digitSets[k]) {
                                    foundNumbers.set(d1 * 100 + d2 * 10 + d3);
                                }
                            }
                        }
                    }
                }
            }
        }

        // Find the smallest positive integer (>= 1) that is not set in the BitSet
        return foundNumbers.nextClearBit(1);
    }

    /**
     * Utility class for high-performance input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        /**
         * Reads a matrix of integers of specified dimensions.
         */
        public int[][] readIntMatrix(int rows, int cols) {
            int[][] matrix = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    String val = next();
                    matrix[i][j] = (val != null) ? Integer.parseInt(val) : 0;
                }
            }
            return matrix;
        }
    }
}

import java.io.InputStream;
import java.io.PrintStream;
import java.util.Scanner;

/**
 * A program to find the smallest non-negative integer (0-999) that cannot 
 * be formed by selecting one digit from each of three provided dice.
 */
public class Main {

    private static final int NUM_DICE = 3;
    private static final int DIGITS_PER_DIE = 10;
    private static final int FACES_PER_DIE = 6;
    private static final int MAX_SEARCH_RANGE = 1000;

    public static void main(String[] args) {
        Main program = new Main();
        program.solve(System.in, System.out);
    }

    /**
     * Orchestrates the input reading and result output.
     * 
     * @param is The input stream.
     * @param ps The print stream for output.
     */
    public void solve(InputStream is, PrintStream ps) {
        Scanner scanner = new Scanner(is);

        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        boolean[][] diceFaces = readDiceData(scanner, n);

        int smallestMissing = findSmallestUnformableNumber(diceFaces);
        ps.println(smallestMissing);
    }

    /**
     * Reads dice face values into a boolean lookup table.
     * 
     * @param scanner The scanner to read from.
     * @param n The number of dice provided in the input.
     * @return A 2D boolean array where [dieIndex][digit] is true if the digit exists on that die.
     */
    private boolean[][] readDiceData(Scanner scanner, int n) {
        boolean[][] diceFaces = new boolean[NUM_DICE][DIGITS_PER_DIE];

        // We only process up to NUM_DICE to avoid ArrayIndexOutOfBounds
        for (int i = 0; i < n && i < NUM_DICE; i++) {
            for (int j = 0; j < FACES_PER_DIE; j++) {
                if (scanner.hasNextInt()) {
                    int digit = scanner.nextInt();
                    if (digit >= 0 && digit < DIGITS_PER_DIE) {
                        diceFaces[i][digit] = true;
                    }
                }
            }
        }
        return diceFaces;
    }

    /**
     * Iterates through possible numbers to find the first one that cannot be formed.
     * 
     * @param diceFaces The boolean lookup table for dice digits.
     * @return The smallest integer that cannot be formed.
     */
    private int findSmallestUnformableNumber(boolean[][] diceFaces) {
        for (int candidate = 0; candidate < MAX_SEARCH_RANGE; candidate++) {
            if (!canForm(candidate, diceFaces)) {
                return candidate;
            }
        }
        return MAX_SEARCH_RANGE;
    }

    /**
     * Checks if a given number can be formed by picking one digit from each die.
     * This uses all permutations of the three dice.
     * 
     * @param number The number to attempt to form.
     * @param diceFaces The boolean lookup table for dice digits.
     * @return True if the number can be formed, false otherwise.
     */
    private boolean canForm(int number, boolean[][] diceFaces) {
        int[] targetDigits = extractDigits(number);

        // All possible permutations of dice indices (0, 1, 2)
        int[][] dicePermutations = {
            {0, 1, 2}, {0, 2, 1}, {1, 0, 2},
            {1, 2, 0}, {2, 0, 1}, {2, 1, 0}
        };

        for (int[] p : dicePermutations) {
            if (diceFaces[p[0]][targetDigits[0]] &&
                diceFaces[p[1]][targetDigits[1]] &&
                diceFaces[p[2]][targetDigits[2]]) {
                return true;
            }
        }
        return false;
    }

    /**
     * Decomposes a number into its hundreds, tens, and units digits.
     * 
     * @param number The number to decompose.
     * @return An array containing [hundreds, tens, units].
     */
    private int[] extractDigits(int number) {
        return new int[] {
            (number / 100) % 10,
            (number / 10) % 10,
            number % 10
        };
    }
}

import java.util.*;
import java.io.*;

/**
 * Task887B Refactored.
 * 
 * This program finds the smallest positive integer that cannot be formed 
 * by selecting one face from each die in any non-empty subset of the provided dice.
 */
public class Task887B {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            // Read the number of dice
            int n = reader.nextInt();
            if (n <= 0) {
                writer.println(1);
                return;
            }

            // Read faces for each die
            int[][] diceFaces = new int[n][6];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < 6; j++) {
                    diceFaces[i][j] = reader.nextInt();
                }
            }

            // Generate all possible numbers using recursion
            Set<Integer> possibleNumbers = new HashSet<>();
            generateNumbers(0, new boolean[n], diceFaces, possibleNumbers);

            // Find the smallest missing positive integer
            int result = findSmallestMissing(possibleNumbers);
            writer.println(result);

        } catch (Exception e) {
            // In a production environment, use a proper logging framework
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Recursively generates all permutations of numbers formed by picking 
     * one face from a subset of the available dice.
     * 
     * @param currentNum    The number constructed in the current recursion path.
     * @param used          A boolean array to track which dice have been used to prevent reuse.
     * @param diceFaces     The 2D array containing the faces of all dice.
     * @param possibleNums  The set storing all unique valid numbers found.
     */
    private static void generateNumbers(int currentNum, boolean[] used, int[][] diceFaces, Set<Integer> possibleNums) {
        for (int i = 0; i < diceFaces.length; i++) {
            if (!used[i]) {
                used[i] = true;
                for (int face : diceFaces[i]) {
                    if (currentNum == 0) {
                        // Rule: The first digit of a number cannot be zero.
                        if (face != 0) {
                            int nextNum = face;
                            possibleNums.add(nextNum);
                            generateNumbers(nextNum, used, diceFaces, possibleNums);
                        }
                    } else {
                        // Subsequent digits can be zero.
                        int nextNum = currentNum * 10 + face;
                        possibleNums.add(nextNum);
                        generateNumbers(nextNum, used, diceFaces, possibleNums);
                    }
                }
                // Backtrack to allow this die to be used in different positions/combinations
                used[i] = false;
            }
        }
    }

    /**
     * Iterates through positive integers starting from 1 to find the first 
     * one not present in the set.
     * 
     * @param possibleNums The set of all generated numbers.
     * @return The smallest missing positive integer.
     */
    private static int findSmallestMissing(Set<Integer> possibleNums) {
        int candidate = 1;
        while (possibleNums.contains(candidate)) {
            candidate++;
        }
        return candidate;
    }

    /**
     * Fast I/O utility class for efficient reading of large inputs.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            if (next == null) throw new NoSuchElementException();
            return Integer.parseInt(next);
        }

        public long nextLong() {
            String next = next();
            if (next == null) throw new NoSuchElementException();
            return Long.parseLong(next);
        }
    }
}

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Scanner;
import java.util.Set;

/**
 * A solution to find the longest sequence of consecutive integers 1, 2, 3...
 * that can be formed by concatenating strings from a given grid,
 * where each string used to form a single number must come from a different row.
 */
public class Solution {

    private static final int COLUMNS_PER_ROW = 6;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rowCount = scanner.nextInt();
        List<List<String>> grid = readGrid(scanner, rowCount);

        int maxSequenceLength = findLongestSequence(grid);
        System.out.println(maxSequenceLength);

        scanner.close();
    }

    /**
     * Reads the grid from the scanner. Each row is expected to have 6 elements.
     *
     * @param scanner   The scanner to read from.
     * @param rowCount  The number of rows in the grid.
     * @return A 2D list representing the grid of strings.
     */
    private static List<List<String>> readGrid(Scanner scanner, int rowCount) {
        List<List<String>> grid = new ArrayList<>(rowCount);
        for (int i = 0; i < rowCount; i++) {
            List<String> row = new ArrayList<>(COLUMNS_PER_ROW);
            for (int j = 0; j < COLUMNS_PER_ROW; j++) {
                if (scanner.hasNext()) {
                    row.add(scanner.next());
                }
            }
            grid.add(row);
        }
        return grid;
    }

    /**
     * Iterates through integers starting from 1 to find the longest continuous sequence
     * that can be successfully formed from the grid.
     *
     * @param grid The grid of available strings.
     * @return The count of consecutive numbers found.
     */
    private static int findLongestSequence(List<List<String>> grid) {
        int currentTarget = 1;
        int count = 0;

        // Attempt to form numbers 1, 2, 3... sequentially.
        while (canFormTarget(String.valueOf(currentTarget), grid, new HashSet<>())) {
            count++;
            currentTarget++;
        }

        return count;
    }

    /**
     * Uses backtracking to determine if a target string can be formed by
     * concatenating strings from the grid, ensuring each string comes from a unique row.
     *
     * @param target      The string representation of the number we want to form.
     * @param grid        The grid of available strings.
     * @param usedRows    A set of row indices already utilized for the current number.
     * @return true if the target can be formed, false otherwise.
     */
    private static boolean canFormTarget(String target, List<List<String>> grid, Set<Integer> usedRows) {
        // Base case: If the target string is empty, we have successfully matched all parts.
        if (target.isEmpty()) {
            return true;
        }

        // Iterate through each row in the grid.
        for (int rowIndex = 0; rowIndex < grid.size(); rowIndex++) {
            // Rule: Each string used to form one number must come from a different row.
            if (usedRows.contains(rowIndex)) {
                continue;
            }

            // Check every string in the current row.
            for (String cellValue : grid.get(rowIndex)) {
                // Avoid infinite recursion on empty strings and check for a prefix match.
                if (!cellValue.isEmpty() && target.startsWith(cellValue)) {

                    // Recursive step: Try to form the remaining part of the target.
                    usedRows.add(rowIndex);
                    if (canFormTarget(target.substring(cellValue.length()), grid, usedRows)) {
                        return true;
                    }

                    // Backtrack: Remove the row from the used set to allow other combinations.
                    usedRows.remove(rowIndex);
                }
            }
        }

        return false;
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver that analyzes digit occurrences across multiple rounds 
 * to find a specific target number based on digit signatures.
 */
public class DigitPatternSolver {

    private static final int DIGIT_COUNT = 10;
    private static final int DIGITS_PER_ROUND = 6;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int numRounds = reader.nextInt();
            int result = solve(reader, numRounds);
            writer.println(result);
        } catch (Exception e) {
            // In competitive programming, errors are usually handled by 
            // terminating or simply ignoring based on problem constraints.
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Processes the rounds and identifies the target number.
     *
     * @param reader     The fast input reader.
     * @param numRounds  The number of rounds to process.
     * @return The calculated target number.
     */
    private static int solve(FastReader reader, int numRounds) throws IOException {
        int[] digitSignatures = new int[DIGIT_COUNT];
        Arrays.fill(digitSignatures, 1);

        for (int round = 0; round < numRounds; round++) {
            int multiplier = getMultiplierForRound(round);
            boolean[] seenInRound = new boolean[DIGIT_COUNT];

            for (int d = 0; d < DIGITS_PER_ROUND; d++) {
                int digit = reader.nextInt();

                // Ensure digit is within valid bounds and process unique digits per round
                if (digit >= 0 && digit < DIGIT_COUNT && !seenInRound[digit]) {
                    digitSignatures[digit] *= multiplier;
                    seenInRound[digit] = true;
                }
            }
        }

        return findTargetNumber(digitSignatures);
    }

    /**
     * Determines the multiplier based on the round index.
     */
    private static int getMultiplierForRound(int round) {
        if (round == 0) return 2;
        if (round == 1) return 3;
        return 5; // For rounds 2 and onwards
    }

    /**
     * Searches for the two-digit number that satisfies the specific 
     * signature patterns defined in the original logic.
     */
    private static int findTargetNumber(int[] digitSignatures) {
        for (int i = 0; i < DIGIT_COUNT; i++) {
            for (int j = 0; j < DIGIT_COUNT; j++) {

                // Case 1: Tens digit is 0
                if (i == 0) {
                    if (j > 0 && digitSignatures[j] == 1) {
                        return j - 1;
                    }
                } 
                // Case 2: Digit 0 was never present in any round
                else if (digitSignatures[0] == 1) {
                    return 9;
                } 
                // Case 3: Both digits appeared only in specific singular rounds
                else {
                    int product = digitSignatures[i] * digitSignatures[j];
                    if (product == 4 || product == 9 || product == 25) {
                        return (i * 10) + j - 1;
                    }
                }
            }
        }
        return 0;
    }

    /**
     * Efficient reader for large input streams.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int curChar;
        private int numChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() throws IOException {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                numChars = stream.read(buffer);
                if (numChars <= 0) return -1;
            }
            return buffer[curChar++];
        }

        public int nextInt() throws IOException {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.util.*;

/**
 * The Solution class finds the largest integer such that every digit in the number
 * can be matched to a unique person who "owns" that digit.
 */
public class Solution {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int numPeople = scanner.nextInt();

        // personDigits[i] stores the set of digits owned by person i
        Set<Integer>[] personDigits = new Set[numPeople];

        for (int i = 0; i < numPeople; i++) {
            personDigits[i] = new HashSet<>();
            for (int j = 0; j < 6; j++) {
                if (scanner.hasNext()) {
                    String digitStr = scanner.next();
                    if (!digitStr.isEmpty()) {
                        // Extract the first digit from the input string
                        int digit = Character.getNumericValue(digitStr.charAt(0));
                        if (digit >= 0 && digit <= 9) {
                            personDigits[i].add(digit);
                        }
                    }
                }
            }
        }

        System.out.println(findLargestValidNumber(numPeople, personDigits));
        scanner.close();
    }

    /**
     * Iterates downwards from the highest possible number to find the first
     * number that satisfies the unique assignment condition.
     * 
     * @param numPeople The number of people available.
     * @param personDigits An array of sets containing digits for each person.
     * @return The largest valid number found.
     */
    private static int findLargestValidNumber(int numPeople, Set<Integer>[] personDigits) {
        // The maximum number of digits is limited by the number of people available
        // and the 6 digits provided per person. We cap the search at 999,999.
        int maxDigits = Math.min(numPeople, 6);
        int maxVal = (int) Math.pow(10, maxDigits) - 1;

        for (int val = maxVal; val >= 0; val--) {
            if (canFormNumber(val, numPeople, personDigits)) {
                return val;
            }
        }
        return 0;
    }

    /**
     * Checks if a specific number can be formed by assigning each of its digits
     * to a unique person.
     */
    private static boolean canFormNumber(int value, int numPeople, Set<Integer>[] personDigits) {
        String s = String.valueOf(value);
        int[] digits = new int[s.length()];
        for (int i = 0; i < s.length(); i++) {
            digits[i] = s.charAt(i) - '0';
        }

        // If the number has more digits than there are people, it's impossible
        if (digits.length > numPeople) {
            return false;
        }

        boolean[] personUsed = new boolean[numPeople];
        return backtrackMatch(digits, 0, personUsed, personDigits);
    }

    /**
     * A backtracking helper function to attempt to match digits to distinct people.
     * 
     * @param digits The array of digits in the target number.
     * @param digitIdx The current digit index we are trying to assign.
     * @param personUsed A boolean array tracking which people have already been assigned a digit.
     * @param personDigits The digits available for each person.
     * @return true if a valid assignment is found, false otherwise.
     */
    private static boolean backtrackMatch(int[] digits, int digitIdx, boolean[] personUsed, Set<Integer>[] personDigits) {
        // Base case: All digits have been successfully assigned
        if (digitIdx == digits.length) {
            return true;
        }

        int currentDigit = digits[digitIdx];

        for (int i = 0; i < personUsed.length; i++) {
            // If person 'i' hasn't been used and owns the current digit
            if (!personUsed[i] && personDigits[i].contains(currentDigit)) {
                personUsed[i] = true; // Tentatively assign person 'i'

                if (backtrackMatch(digits, digitIdx + 1, personUsed, personDigits)) {
                    return true;
                }

                personUsed[i] = false; // Backtrack
            }
        }

        return false;
    }
}

import java.io.*;
import java.util.*;

/**
 * A solution that finds the largest integer that can be formed by selecting 
 * digits from a limited number of provided rows, ensuring each row is used at most once.
 */
public class Main {

    public static void main(String[] args) {
        // Use try-with-resources to ensure I/O streams are closed automatically.
        try (FastReader reader = new FastReader(System.in);
             PrintWriter writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            DigitCombinationSolver solver = new DigitCombinationSolver();
            solver.solve(reader, writer);

        } catch (IOException e) {
            System.err.println("An error occurred while processing input: " + e.getMessage());
        }
    }

    /**
     * Encapsulates the logic for solving the digit combination problem.
     */
    static class DigitCombinationSolver {
        private static final int MAX_ALLOWED_ROWS = 3;
        private static final int COLUMNS_PER_ROW = 6;

        private int rowCount;
        private int[][] digitMatrix;

        /**
         * Reads input data and finds the maximum valid integer.
         *
         * @param reader The efficient input reader.
         * @param writer The efficient output writer.
         * @throws IOException If an I/O error occurs.
         */
        public void solve(FastReader reader, PrintWriter writer) throws IOException {
            this.rowCount = reader.nextInt();
            this.digitMatrix = new int[rowCount][COLUMNS_PER_ROW];

            for (int i = 0; i < rowCount; i++) {
                for (int j = 0; j < COLUMNS_PER_ROW; j++) {
                    digitMatrix[i][j] = reader.nextInt();
                }
            }

            // Search for the largest integer starting from 1.
            // The search terminates as soon as a number cannot be formed.
            int currentNumber = 1;
            while (canFormNumber(currentNumber, 0)) {
                currentNumber++;
            }

            // Since currentNumber failed the check, the last valid number was currentNumber - 1.
            writer.println(currentNumber - 1);
        }

        /**
         * Recursively checks if a number can be constructed using digits from the available rows.
         * Each row can be used at most once.
         *
         * @param number The number being evaluated (digits are processed from right to left).
         * @param usedRowsMask A bitmask where the i-th bit is set if row i has been used.
         * @return true if the number can be formed, false otherwise.
         */
        private boolean canFormNumber(int number, int usedRowsMask) {
            // Base case: All digits of the target number have been successfully matched.
            if (number == 0) {
                return true;
            }

            int digitToMatch = number % 10;
            int remainingDigits = number / 10;

            // The problem logic restricts usage to the first 3 rows (indices 0, 1, 2).
            int effectiveRowCount = Math.min(rowCount, MAX_ALLOWED_ROWS);

            for (int i = 0; i < effectiveRowCount; i++) {
                boolean isRowAlreadyUsed = (usedRowsMask & (1 << i)) != 0;

                if (!isRowAlreadyUsed && containsDigit(i, digitToMatch)) {
                    // Attempt to match the remaining digits using the remaining available rows.
                    if (canFormNumber(remainingDigits, usedRowsMask | (1 << i))) {
                        return true;
                    }
                }
            }

            return false;
        }

        /**
         * Checks if a specific digit exists within a specific row.
         */
        private boolean containsDigit(int rowIndex, int digit) {
            for (int col = 0; col < COLUMNS_PER_ROW; col++) {
                if (digitMatrix[rowIndex][col] == digit) {
                    return true;
                }
            }
            return false;
        }
    }

    /**
     * High-performance input reader for large data sets.
     */
    static class FastReader implements AutoCloseable {
        private final InputStream inputStream;
        private final byte[] buffer = new byte[8192];
        private int pointer = 0;
        private int bytesRead = 0;

        public FastReader(InputStream inputStream) {
            this.inputStream = inputStream;
        }

        private int readByte() throws IOException {
            if (pointer >= bytesRead) {
                pointer = 0;
                bytesRead = inputStream.read(buffer);
                if (bytesRead <= 0) return -1;
            }
            return buffer[pointer++] & 0xFF;
        }

        /**
         * Reads the next integer from the stream, skipping any non-digit/non-sign characters.
         * 
         * @return The parsed integer.
         * @throws IOException If an I/O error occurs.
         * @throws NoSuchElementException If no integer is found.
         */
        public int nextInt() throws IOException {
            int c = readByte();

            // Skip whitespace and common delimiters like commas
            while (c != -1 && (c <= 32 || c == ',')) {
                c = readByte();
            }

            if (c == -1) throw new NoSuchElementException("Unexpected end of input.");

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }

            int result = 0;
            while (c >= '0' && c <= '9') {
                result = result * 10 + (c - '0');
                c = readByte();
            }
            return result * sign;
        }

        @Override
        public void close() throws IOException {
            inputStream.close();
        }
    }
}

import java.util.*;

/**
 * This program calculates the largest integer 'k' such that all integers 
 * from 1 to 'k' can be formed by selecting at most one digit from each 
 * of the 'n' provided sets of digits.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        // Read the number of digit sets available
        int n = scanner.nextInt();
        List<Set<Integer>> digitSets = readDigitSets(scanner, n);

        // Find the largest k in the sequence 1, 2, ..., k
        int maxConsecutive = findMaxConsecutive(digitSets);
        System.out.println(maxConsecutive);

        scanner.close();
    }

    /**
     * Reads n sets of 6 digits from the scanner.
     * Each set is stored in a HashSet for efficient O(1) lookup.
     *
     * @param scanner The scanner to read from.
     * @param n       The number of sets to read.
     * @return A list of sets containing the digits.
     */
    private static List<Set<Integer>> readDigitSets(Scanner scanner, int n) {
        List<Set<Integer>> digitSets = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            Set<Integer> set = new HashSet<>();
            for (int j = 0; j < 6; j++) {
                if (scanner.hasNextInt()) {
                    set.add(scanner.nextInt());
                }
            }
            digitSets.add(set);
        }
        return digitSets;
    }

    /**
     * Iterates through integers starting from 1 to find the first integer 
     * that cannot be formed using the provided digit sets.
     *
     * @param digitSets The available sets of digits.
     * @return The largest k such that 1 to k are all formable.
     */
    private static int findMaxConsecutive(List<Set<Integer>> digitSets) {
        int current = 1;
        while (canForm(current, digitSets)) {
            current++;
        }
        return current - 1;
    }

    /**
     * Checks if a specific number can be formed using the available digit sets.
     * A number is formable if each of its digits can be assigned to a unique set.
     *
     * @param number    The number to check.
     * @param digitSets The available sets of digits.
     * @return True if the number can be formed, false otherwise.
     */
    private static boolean canForm(int number, List<Set<Integer>> digitSets) {
        List<Integer> digits = getDigits(number);

        // If the number has more digits than there are sets, it's impossible to form.
        if (digits.size() > digitSets.size()) {
            return false;
        }

        // Use backtracking to try and match each digit to a unique set.
        return canMatchDigitsToSets(digits, 0, new boolean[digitSets.size()], digitSets);
    }

    /**
     * A backtracking algorithm to solve the bipartite matching problem:
     * matching digits of a number to distinct sets that contain those digits.
     *
     * @param digits      The digits of the target number.
     * @param digitIdx    The current digit index we are trying to match.
     * @param usedSets    A boolean array tracking which sets have already been used.
     * @param digitSets   The list of available digit sets.
     * @return True if a valid matching is found, false otherwise.
     */
    private static boolean canMatchDigitsToSets(List<Integer> digits, int digitIdx, 
                                               boolean[] usedSets, List<Set<Integer>> digitSets) {
        // Base case: All digits have been successfully matched to a unique set.
        if (digitIdx == digits.size()) {
            return true;
        }

        int targetDigit = digits.get(digitIdx);

        for (int i = 0; i < digitSets.size(); i++) {
            // If this set is not yet used and contains the required digit.
            if (!usedSets[i] && digitSets.get(i).contains(targetDigit)) {
                usedSets[i] = true; // Choose this set

                if (canMatchDigitsToSets(digits, digitIdx + 1, usedSets, digitSets)) {
                    return true;
                }

                usedSets[i] = false; // Backtrack: unmark the set
            }
        }

        return false;
    }

    /**
     * Extracts the individual digits from an integer.
     *
     * @param number The integer to decompose.
     * @return A list of integers representing the digits.
     */
    private static List<Integer> getDigits(int number) {
        List<Integer> digits = new ArrayList<>();
        int temp = number;
        while (temp > 0) {
            digits.add(temp % 10);
            temp /= 10;
        }
        return digits;
    }
}

