/**
 * Refactored solution for TaskB.
 * The program identifies the smallest number (minus one) that cannot be 
 * formed by selecting digits from n provided arrays in unique positions.
 */
public class Main {
    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        ProblemSolver solver = new ProblemSolver();
        solver.solve(in, out);

        out.close();
    }

    static class ProblemSolver {

        /**
         * Orchestrates the solving process.
         * @param in FastReader for input.
         * @param out PrintWriter for output.
         */
        public void solve(FastReader in, PrintWriter out) {
            int n = in.nextInt();
            if (n < 1 || n > 3) {
                return;
            }

            // Store the input arrays in a list for generalized processing
            List<int[]> digitSets = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                digitSets.add(in.nextIntArray(6));
            }

            Set<Integer> formableNumbers = generateFormableNumbers(digitSets);

            // The original logic checks up to 9, 99, or 999 based on n
            int limit = (int) Math.pow(10, n) - 1;

            for (int i = 1; i <= limit; i++) {
                if (!formableNumbers.contains(i)) {
                    out.println(i - 1);
                    return;
                }
            }
            out.println(limit);
        }

        /**
         * Generates all possible numbers that can be formed by picking 
         * 1, 2, or 3 digits from the provided digit sets such that 
         * each digit comes from a unique set.
         */
        private Set<Integer> generateFormableNumbers(List<int[]> sets) {
            Set<Integer> formed = new HashSet<>();
            int n = sets.size();

            // 1-digit numbers: pick one digit from any of the available sets
            for (int i = 0; i < n; i++) {
                for (int digit : sets.get(i)) {
                    formed.add(digit);
                }
            }

            // 2-digit numbers: pick two digits from two different sets
            if (n >= 2) {
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < n; j++) {
                        if (i == j) continue;
                        for (int d1 : sets.get(i)) {
                            for (int d2 : sets.get(j)) {
                                formed.add(d1 * 10 + d2);
                            }
                        }
                    }
                }
            }

            // 3-digit numbers: pick three digits from three different sets
            if (n >= 3) {
                for (int i = 0; i < n; i++) {
                    for (int j = 0; j < n; j++) {
                        for (int k = 0; k < n; k++) {
                            if (i == j || i == k || j == k) continue;
                            for (int d1 : sets.get(i)) {
                                for (int d2 : sets.get(j)) {
                                    for (int d3 : sets.get(k)) {
                                        formed.add(d1 * 100 + d2 * 10 + d3);
                                    }
                                }
                            }
                        }
                    }
                }
            }

            return formed;
        }
    }

    /**
     * Efficient reader for fast input parsing.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    // Supports both spaces and commas as delimiters per original requirement
                    tokenizer = new StringTokenizer(line, " ,");
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }

        public int[] nextIntArray(int size) {
            int[] array = new int[size];
            for (int i = 0; i < size; i++) {
                array[i] = nextInt();
            }
            return array;
        }
    }
}

import java.util.*;

/**
 * The DiceGame class finds the smallest positive integer that cannot be formed
 * by picking exactly one digit from each of the n dice provided.
 */
public class DiceGame {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int numDice = scanner.nextInt();
        List<Set<Integer>> diceList = new ArrayList<>();

        // Read the faces for each die
        for (int i = 0; i < numDice; i++) {
            Set<Integer> dieFaces = new HashSet<>();
            for (int j = 0; j < 6; j++) {
                if (scanner.hasNextInt()) {
                    dieFaces.add(scanner.nextInt());
                }
            }
            diceList.add(dieFaces);
        }

        // Iterate to find the smallest positive integer that cannot be formed
        // A limit of 1000 is sufficient for up to 3 dice.
        for (int i = 1; i <= 1000; i++) {
            if (!canFormNumber(i, diceList)) {
                System.out.println(i);
                return;
            }
        }
    }

    /**
     * Determines if a number can be formed using the faces of the given dice.
     * A number is formable if each of its digits can be assigned to a distinct die.
     * 
     * @param number The integer to check.
     * @param dice   A list of sets, where each set represents the faces of one die.
     * @return true if the number can be formed, false otherwise.
     */
    private static boolean canFormNumber(int number, List<Set<Integer>> dice) {
        String numberStr = String.valueOf(number);
        int numDigits = numberStr.length();
        int numDiceAvailable = dice.size();

        // If the number has more digits than there are dice, it's impossible to form.
        if (numDigits > numDiceAvailable) {
            return false;
        }

        // Convert string representation to an array of integer digits.
        int[] digits = new int[numDigits];
        for (int i = 0; i < numDigits; i++) {
            digits[i] = numberStr.charAt(i) - '0';
        }

        // Check possibilities based on the number of digits.
        // Since n is small (up to 3), we can use explicit permutation checks.
        if (numDigits == 1) {
            return canFormOneDigit(digits[0], dice);
        } else if (numDigits == 2) {
            return canFormTwoDigits(digits[0], digits[1], dice);
        } else if (numDigits == 3) {
            return canFormThreeDigits(digits[0], digits[1], digits[2], dice);
        }

        return false;
    }

    private static boolean canFormOneDigit(int d1, List<Set<Integer>> dice) {
        for (Set<Integer> die : dice) {
            if (die.contains(d1)) {
                return true;
            }
        }
        return false;
    }

    private static boolean canFormTwoDigits(int d1, int d2, List<Set<Integer>> dice) {
        for (int i = 0; i < dice.size(); i++) {
            for (int j = 0; j < dice.size(); j++) {
                // Digits must come from different dice
                if (i != j && dice.get(i).contains(d1) && dice.get(j).contains(d2)) {
                    return true;
                }
            }
        }
        return false;
    }

    private static boolean canFormThreeDigits(int d1, int d2, int d3, List<Set<Integer>> dice) {
        for (int i = 0; i < dice.size(); i++) {
            for (int j = 0; j < dice.size(); j++) {
                for (int k = 0; k < dice.size(); k++) {
                    // Digits must come from three distinct dice
                    if (i != j && i != k && j != k &&
                        dice.get(i).contains(d1) &&
                        dice.get(j).contains(d2) &&
                        dice.get(k).contains(d3)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
}

