/**
 * A refactored solution for the digit permutation matching problem.
 * Finds the smallest integer i such that no permutation of its digits 
 * can be mapped to the provided sets of digits.
 */
public class B887 {

    private static final int MAX_SEARCH_RANGE = 1000;
    private static final int NUMBER_OF_SETS = 3;
    private static final int DIGITS_PER_SET = 6;
    private static final int PLACEHOLDER_FOR_ZERO = -1;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        int n = reader.nextInt();
        if (n < 0) return;

        // Initialize sets for the 3 digit groups. 
        // Using 1-based indexing to stay faithful to original logic.
        @SuppressWarnings("unchecked")
        Set<Integer>[] digitSets = new Set[NUMBER_OF_SETS + 1];
        for (int i = 1; i <= NUMBER_OF_SETS; i++) {
            digitSets[i] = new HashSet<>();
            digitSets[i].add(PLACEHOLDER_FOR_ZERO);
        }

        // Read input sets
        for (int i = 1; i <= n; i++) {
            // The original code would crash if n > 3. 
            // We limit input processing to the 3 defined sets to prevent crashes.
            if (i <= NUMBER_OF_SETS) {
                for (int j = 0; j < DIGITS_PER_SET; j++) {
                    digitSets[i].add(reader.nextInt());
                }
            } else {
                // Consume remaining input if n > 3
                for (int j = 0; j < DIGITS_PER_SET; j++) {
                    reader.nextInt();
                }
            }
        }

        int result = findFirstNonMatchingNumber(digitSets);
        System.out.println(result);
    }

    /**
     * Iterates through numbers to find the first one that fails the permutation match.
     * 
     * @param sets The sets of digits to match against.
     * @return The first number i-1 that cannot be matched, or 0 if all match.
     */
    private static int findFirstNonMatchingNumber(Set<Integer>[] sets) {
        for (int i = 1; i <= MAX_SEARCH_RANGE; i++) {
            if (!canMatchAnyPermutation(i, sets)) {
                return i - 1;
            }
        }
        return 0;
    }

    /**
     * Checks if any permutation of the digits of the given number 
     * matches the three provided digit sets.
     */
    private static boolean canMatchAnyPermutation(int number, Set<Integer>[] sets) {
        int[] digits = extractDigits(number);

        // All 6 possible permutations of the indices [0, 1, 2]
        int[][] permutations = {
            {0, 1, 2}, {0, 2, 1}, 
            {1, 0, 2}, {1, 2, 0}, 
            {2, 0, 1}, {2, 1, 0}
        };

        for (int[] p : permutations) {
            if (sets[1].contains(digits[p[0]]) &&
                sets[2].contains(digits[p[1]]) &&
                sets[3].contains(digits[p[2]])) {
                return true;
            }
        }
        return false;
    }

    /**
     * Extracts the three digits of a number. 
     * Per the original logic, a digit of 0 is transformed to -1.
     */
    private static int[] extractDigits(int number) {
        int d1 = number % 10;
        int d2 = (number / 10) % 10;
        int d3 = (number / 100) % 10;

        return new int[] {
            d1 == 0 ? PLACEHOLDER_FOR_ZERO : d1,
            d2 == 0 ? PLACEHOLDER_FOR_ZERO : d2,
            d3 == 0 ? PLACEHOLDER_FOR_ZERO : d3
        };
    }

    /**
     * Efficient reader for fast I/O operations.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }
    }
}

import java.util.Scanner;

/**
 * A solver for a digit-based constraint puzzle.
 * The program finds the smallest positive integer that fails to satisfy 
 * specific digit-set constraints based on the number of sets provided.
 */
public class DigitConstraintSolver {

    private static final int MAX_DIGIT_VALUE = 10;
    private static final int MAX_TEST_VALUE = 100;
    private static final int DIGITS_PER_SET = 6;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        boolean[][] digitSets = readDigitSets(scanner, n);
        scanner.close();

        Integer result = solve(n, digitSets);

        if (result != null) {
            System.out.println(result);
        }
    }

    /**
     * Reads the input sets of digits into a boolean matrix.
     */
    private static boolean[][] readDigitSets(Scanner scanner, int n) {
        boolean[][] digitSets = new boolean[n][MAX_DIGIT_VALUE];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < DIGITS_PER_SET; j++) {
                if (scanner.hasNextInt()) {
                    int digit = scanner.nextInt();
                    if (digit >= 0 && digit < MAX_DIGIT_VALUE) {
                        digitSets[i][digit] = true;
                    }
                }
            }
        }
        return digitSets;
    }

    /**
     * Orchestrates the solving logic based on the number of sets (n).
     * @return The smallest integer (i-1) that fails the constraints, or null if not found.
     */
    private static Integer solve(int n, boolean[][] digitSets) {
        if (n == 1) {
            return solveForN1(digitSets);
        } else if (n == 2) {
            return solveForN2(digitSets);
        } else if (n == 3) {
            return solveForN3(digitSets);
        }
        return null;
    }

    private static Integer solveForN1(boolean[][] digitSets) {
        for (int i = 1; i < 10; i++) {
            if (!digitSets[0][i]) {
                return i - 1;
            }
        }
        return null;
    }

    private static Integer solveForN2(boolean[][] digitSets) {
        for (int i = 1; i < MAX_TEST_VALUE; i++) {
            if (!isValidForN2(i, digitSets)) {
                return i - 1;
            }
        }
        return null;
    }

    private static Integer solveForN3(boolean[][] digitSets) {
        for (int i = 1; i < MAX_TEST_VALUE; i++) {
            if (!isValidForN3(i, digitSets)) {
                return i - 1;
            }
        }
        // If no invalid number is found in the loop for n=3, return 100 per original logic
        return 100;
    }

    /**
     * Validation logic for n=2.
     * A number is valid if it's in the union of sets (for < 10) 
     * or if its digits are split between Set 0 and Set 1 (for >= 10).
     */
    private static boolean isValidForN2(int value, boolean[][] digitSets) {
        if (value < 10) {
            return digitSets[0][value] || digitSets[1][value];
        } else {
            int tens = value / 10;
            int units = value % 10;
            return (digitSets[0][units] && digitSets[1][tens]) ||
                   (digitSets[0][tens] && digitSets[1][units]);
        }
    }

    /**
     * Validation logic for n=3.
     * A number is valid if it's in the union of the 3 sets (for < 10)
     * or if it satisfies the cross-set relationship (for >= 10).
     */
    private static boolean isValidForN3(int value, boolean[][] digitSets) {
        if (value < 10) {
            return digitSets[0][value] || digitSets[1][value] || digitSets[2][value];
        } else {
            return isCrossSetPairPossible(value % 10, value / 10, digitSets);
        }
    }

    /**
     * Checks if a pair of digits (units, tens) can be formed using different sets.
     */
    private static boolean isCrossSetPairPossible(int unit, int tens, boolean[][] digitSets) {
        if (digitSets[0][unit]) {
            return digitSets[1][tens] || digitSets[2][tens];
        }
        if (digitSets[1][unit]) {
            return digitSets[0][tens] || digitSets[2][tens];
        }
        if (digitSets[2][unit]) {
            return digitSets[0][tens] || digitSets[1][tens];
        }
        return false;
    }
}

import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

/**
 * This program determines the largest integer x such that all integers from 1 to x
 * can be constructed using the digits provided in the input sets.
 */
public class MissingNumberFinder {

    private static final int DIGITS_PER_SET = 6;
    private static final int MAX_SEARCH_LIMIT = 1000;

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) {
                return;
            }

            int numSets = scanner.nextInt();
            int[][] digitSets = readDigitSets(scanner, numSets);

            Set<Integer> constructibleNumbers = generateConstructibleNumbers(numSets, digitSets);
            int result = findMaxContiguousSequence(constructibleNumbers);

            System.out.println(result);
        } catch (Exception e) {
            // In a production environment, consider using a logging framework.
            System.err.println("An error occurred: " + e.getMessage());
        }
    }

    /**
     * Reads the input digit sets from the scanner.
     * 
     * @param scanner   The scanner to read from.
     * @param numSets   The number of digit sets to read.
     * @return A 2D array containing the input digits.
     */
    private static int[][] readDigitSets(Scanner scanner, int numSets) {
        int[][] digitSets = new int[numSets][DIGITS_PER_SET];
        for (int i = 0; i < numSets; i++) {
            for (int j = 0; j < DIGITS_PER_SET; j++) {
                if (scanner.hasNextInt()) {
                    digitSets[i][j] = scanner.nextInt();
                }
            }
        }
        return digitSets;
    }

    /**
     * Generates all possible numbers that can be constructed from the provided sets.
     * Numbers are formed by taking at most one digit from each unique set.
     * 
     * @param n         The number of available sets.
     * @param digitSets The 2D array of available digits.
     * @return A set of all constructible numbers.
     */
    private static Set<Integer> generateConstructibleNumbers(int n, int[][] digitSets) {
        Set<Integer> constructible = new HashSet<>();

        // 1. Add all single digits from all available sets
        for (int i = 0; i < n; i++) {
            for (int digit : digitSets[i]) {
                constructible.add(digit);
            }
        }

        // 2. Add 2-digit combinations (one digit from set i, one from set j, where i != j)
        if (n >= 2) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (i == j) continue;
                    for (int d1 : digitSets[i]) {
                        for (int d2 : digitSets[j]) {
                            constructible.add(d1 * 10 + d2);
                        }
                    }
                }
            }
        }

        // 3. Add 3-digit combinations (one digit from each of three unique sets)
        if (n >= 3) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (i == j) continue;
                    for (int k = 0; k < n; k++) {
                        if (k == i || k == j) continue;
                        for (int d1 : digitSets[i]) {
                            for (int d2 : digitSets[j]) {
                                for (int d3 : digitSets[k]) {
                                    constructible.add(d1 * 100 + d2 * 10 + d3);
                                }
                            }
                        }
                    }
                }
            }
        }

        return constructible;
    }

    /**
     * Finds the largest integer x such that all integers from 1 to x are present in the set.
     * This mimics the logic of the original code's search loop.
     * 
     * @param constructible The set of constructible numbers.
     * @return The result of the search.
     */
    private static int findMaxContiguousSequence(Set<Integer> constructible) {
        for (int i = 1; i <= MAX_SEARCH_LIMIT; i++) {
            if (!constructible.contains(i)) {
                return i - 1;
            }
        }
        return MAX_SEARCH_LIMIT;
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Scanner;
import java.util.Set;

/**
 * A utility to find the smallest positive integer that cannot be represented 
 * by mapping its digits to distinct sets of integers.
 */
public class DigitSetMatcher {

    public static void main(String[] args) {
        try (Scanner sc = new Scanner(System.in)) {
            if (!sc.hasNextInt()) {
                return;
            }

            int numSets = sc.nextInt();
            List<Set<Integer>> sets = new ArrayList<>();

            for (int i = 0; i < numSets; i++) {
                Set<Integer> currentSet = new HashSet<>();
                for (int j = 0; j < 6; j++) {
                    if (sc.hasNextInt()) {
                        currentSet.add(sc.nextInt());
                    }
                }
                sets.add(currentSet);
            }

            System.out.println(findSmallestInvalidNumber(numSets, sets));
        }
    }

    /**
     * Finds the largest number X such that all numbers from 1 to X are "valid".
     * A number is valid if its digits can be uniquely assigned to distinct sets.
     *
     * @param n The number of sets available.
     * @param sets The list of sets provided.
     * @return The value i-1, where i is the first invalid number.
     */
    private static int findSmallestInvalidNumber(int n, List<Set<Integer>> sets) {
        // Determine search range based on the original program's constraints
        int upperLimit = switch (n) {
            case 1 -> 10;
            case 2 -> 100;
            case 3 -> 1000;
            default -> 0;
        };

        if (upperLimit == 0) {
            return 0;
        }

        for (int i = 1; i < upperLimit; i++) {
            if (!isValid(i, sets)) {
                return i - 1;
            }
        }

        // If no invalid number is found within the original problem's constraints, return 0.
        return 0;
    }

    /**
     * Checks if the digits of a number can be matched to distinct sets.
     */
    private static boolean isValid(int number, List<Set<Integer>> sets) {
        List<Integer> digits = getDigits(number);
        return canMatchDigitsToSets(digits, 0, sets, new boolean[sets.size()]);
    }

    /**
     * Recursive backtracking algorithm to find a bipartite matching between 
     * the number's digits and the available sets.
     *
     * @param digits The digits of the number to check.
     * @param digitIdx The current digit index we are trying to match.
     * @param sets The list of available integer sets.
     * @param usedSets A boolean array tracking which sets have already been assigned.
     * @return true if a valid assignment exists, false otherwise.
     */
    private static boolean canMatchDigitsToSets(List<Integer> digits, int digitIdx, 
                                                List<Set<Integer>> sets, boolean[] usedSets) {
        // Base case: all digits have been successfully matched to distinct sets
        if (digitIdx == digits.size()) {
            return true;
        }

        int currentDigit = digits.get(digitIdx);

        for (int i = 0; i < sets.size(); i++) {
            // If the set is not used and contains the current digit
            if (!usedSets[i] && sets.get(i).contains(currentDigit)) {
                usedSets[i] = true; // Tentatively assign set i to this digit

                if (canMatchDigitsToSets(digits, digitIdx + 1, sets, usedSets)) {
                    return true;
                }

                usedSets[i] = false; // Backtrack
            }
        }

        return false;
    }

    /**
     * Converts an integer into a list of its individual digits.
     */
    private static List<Integer> getDigits(int number) {
        List<Integer> digits = new ArrayList<>();
        int temp = number;
        while (temp > 0) {
            digits.add(temp % 10);
            temp /= 10;
        }
        // Reverse to maintain the natural order of digits (e.g., 123 -> [1, 2, 3])
        Collections.reverse(digits);
        return digits;
    }
}

import java.util.*;
import java.io.*;

/**
 * Refactored solution for the Codeforces problem.
 * The goal is to find the smallest non-negative integer that cannot be formed
 * by assigning each of its digits to a unique set from the provided collections.
 */
public class Codeforces {

    public static void main(String[] args) {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int n = sc.nextInt();
            List<Set<Integer>> sets = new ArrayList<>();

            // Read n sets, each containing 6 digits
            for (int i = 0; i < n; i++) {
                Set<Integer> currentSet = new HashSet<>();
                for (int j = 0; j < 6; j++) {
                    currentSet.add(sc.nextInt());
                }
                sets.add(currentSet);
            }

            // Find the smallest integer i >= 1 such that i cannot be formed.
            // The original logic implies that if 1 is not possible, the answer is 0.
            // We check up to 1000 as the maximum possible answer for n=3 is 999.
            int result = 0;
            for (int i = 1; i < 1000; i++) {
                if (!canFormNumber(i, sets)) {
                    result = i - 1;
                    break;
                }
            }
            out.println(result);

        } catch (Exception e) {
            // In a competitive programming context, we typically don't swallow exceptions,
            // but we handle them to keep the program robust.
        } finally {
            out.close();
        }
    }

    /**
     * Determines if a number can be formed using the available sets.
     * A number is "formable" if each of its digits can be assigned to a 
     * distinct set from the provided list.
     *
     * @param number The integer to check.
     * @param sets   The list of available sets of digits.
     * @return true if the number can be formed, false otherwise.
     */
    private static boolean canFormNumber(int number, List<Set<Integer>> sets) {
        List<Integer> digits = getDigits(number);

        // If the number has more digits than available sets, it cannot be formed.
        if (digits.size() > sets.size()) {
            return false;
        }

        // Use backtracking to see if there's a valid assignment of digits to sets.
        return backtrack(digits, 0, new boolean[sets.size()], sets);
    }

    /**
     * Recursive backtracking helper to assign digits to distinct sets.
     *
     * @param digits    The list of digits of the number.
     * @param index     The current digit index we are trying to assign.
     * @param setUsed   A boolean array tracking which sets have already been assigned.
     * @param sets      The list of available sets.
     * @return true if a valid assignment is found.
     */
    private static boolean backtrack(List<Integer> digits, int index, boolean[] setUsed, List<Set<Integer>> sets) {
        if (index == digits.size()) {
            return true;
        }

        int currentDigit = digits.get(index);

        for (int i = 0; i < sets.size(); i++) {
            // If this set has not been used yet and contains the current digit
            if (!setUsed[i] && sets.get(i).contains(currentDigit)) {
                setUsed[i] = true; // Choose
                if (backtrack(digits, index + 1, setUsed, sets)) { // Explore
                    return true;
                }
                setUsed[i] = false; // Un-choose (Backtrack)
            }
        }

        return false;
    }

    /**
     * Extracts digits from an integer into a list.
     */
    private static List<Integer> getDigits(int n) {
        List<Integer> digits = new ArrayList<>();
        if (n == 0) {
            digits.add(0);
            return digits;
        }
        int temp = n;
        while (temp > 0) {
            digits.add(temp % 10);
            temp /= 10;
        }
        return digits;
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.util.*;

/**
 * A utility to find the largest number that can be formed using digits
 * from a given set of dice.
 * 
 * Rules:
 * - 1-digit numbers: The digit must exist on at least one die.
 * - 2-digit numbers: The digits must exist on two different dice.
 * - 3-digit numbers: The digits must exist on three different dice.
 */
public class DiceNumberFinder {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int numDice = scanner.nextInt();
        List<Set<Integer>> diceList = new ArrayList<>();

        // Populate the dice list
        for (int i = 0; i < numDice; i++) {
            Set<Integer> dieFaces = new HashSet<>();
            for (int j = 0; j < 6; j++) {
                if (scanner.hasNextInt()) {
                    dieFaces.add(scanner.nextInt());
                }
            }
            diceList.add(dieFaces);
        }

        System.out.println(findMaxFormableNumber(diceList));
        scanner.close();
    }

    /**
     * Searches from the highest possible number (999) downwards to find
     * the first number that satisfies the dice formation rules.
     *
     * @param diceList A list of sets, where each set represents the faces of a die.
     * @return The maximum formable number.
     */
    private static int findMaxFormableNumber(List<Set<Integer>> diceList) {
        for (int number = 999; number >= 1; number--) {
            if (canForm(number, diceList)) {
                return number;
            }
        }
        return 0;
    }

    /**
     * Determines if a specific number can be formed using the available dice
     * based on the number of digits.
     *
     * @param number   The number to validate.
     * @param diceList The list of available dice.
     * @return true if the number can be formed, false otherwise.
     */
    private static boolean canForm(int number, List<Set<Integer>> diceList) {
        List<Integer> digits = getDigits(number);
        int numDigits = digits.size();
        int numDice = diceList.size();

        if (numDigits == 1) {
            return canFormOneDigit(digits.get(0), diceList);
        } else if (numDigits == 2) {
            return canFormTwoDigits(digits.get(0), digits.get(1), diceList);
        } else if (numDigits == 3) {
            return canFormThreeDigits(digits.get(0), digits.get(1), digits.get(2), diceList);
        }

        return false;
    }

    private static boolean canFormOneDigit(int d1, List<Set<Integer>> diceList) {
        for (Set<Integer> die : diceList) {
            if (die.contains(d1)) return true;
        }
        return false;
    }

    private static boolean canFormTwoDigits(int d1, int d2, List<Set<Integer>> diceList) {
        for (int i = 0; i < diceList.size(); i++) {
            for (int j = 0; j < diceList.size(); j++) {
                if (i != j && diceList.get(i).contains(d1) && diceList.get(j).contains(d2)) {
                    return true;
                }
            }
        }
        return false;
    }

    private static boolean canFormThreeDigits(int d1, int d2, int d3, List<Set<Integer>> diceList) {
        if (diceList.size() < 3) return false;

        for (int i = 0; i < diceList.size(); i++) {
            for (int j = 0; j < diceList.size(); j++) {
                if (i == j) continue;
                for (int k = 0; k < diceList.size(); k++) {
                    if (k == i || k == j) continue;

                    if (diceList.get(i).contains(d1) &&
                        diceList.get(j).contains(d2) &&
                        diceList.get(k).contains(d3)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Utility to split an integer into its individual digits.
     */
    private static List<Integer> getDigits(int number) {
        List<Integer> digits = new ArrayList<>();
        String s = Integer.toString(number);
        for (char c : s.toCharArray()) {
            digits.add(Character.getNumericValue(c));
        }
        return digits;
    }
}

import java.util.*;

/**
 * A program to find the longest consecutive sequence of integers starting from 1
 * that can be formed by selecting faces from a given set of n dice.
 */
public class DiceSequenceFinder {

    private final int[][] dice;
    private final int numDice;
    private final Set<Integer> possibleNumbers;

    /**
     * Initializes the finder with the given dice faces.
     * @param dice A 2D array where dice[i] contains the 6 faces of the i-th die.
     */
    public DiceSequenceFinder(int[][] dice) {
        this.dice = dice;
        this.numDice = dice.length;
        this.possibleNumbers = new HashSet<>();
    }

    /**
     * Orchestrates the generation of numbers and finds the result.
     */
    public void solve() {
        // Generate all possible numbers using any subset of the available dice
        generateCombinations(0, new ArrayList<>());

        // Find the longest sequence 1, 2, 3... X
        int result = findLongestConsecutiveSequence();
        System.out.println(result);
    }

    /**
     * Uses backtracking to pick a subset of dice and exactly one face from each.
     * 
     * @param dieIdx The current die index being considered.
     * @param currentFaces The list of faces selected from the chosen subset of dice.
     */
    private void generateCombinations(int dieIdx, List<Integer> currentFaces) {
        if (dieIdx == numDice) {
            if (!currentFaces.isEmpty()) {
                // For the chosen subset of faces, generate all possible permutations (orderings)
                permuteFaces(new ArrayList<>(currentFaces), 0);
            }
            return;
        }

        // Option 1: Do not include this die in the current number
        generateCombinations(dieIdx + 1, currentFaces);

        // Option 2: Include this die by picking one of its 6 faces
        for (int face : dice[dieIdx]) {
            currentFaces.add(face);
            generateCombinations(dieIdx + 1, currentFaces);
            currentFaces.remove(currentFaces.size() - 1); // Backtrack
        }
    }

    /**
     * Generates all permutations of a list of faces to form multi-digit numbers.
     * 
     * @param faces The list of face values to permute.
     * @param start The starting index for permutation logic.
     */
    private void permuteFaces(List<Integer> faces, int start) {
        if (start == faces.size()) {
            int number = 0;
            for (int face : faces) {
                number = number * 10 + face;
            }
            possibleNumbers.add(number);
            return;
        }

        for (int i = start; i < faces.size(); i++) {
            Collections.swap(faces, start, i);
            permuteFaces(faces, start + 1);
            Collections.swap(faces, start, i); // Backtrack
        }
    }

    /**
     * Finds the largest X such that every integer from 1 to X exists in the set.
     * 
     * @return The largest consecutive integer X.
     */
    private int findLongestConsecutiveSequence() {
        int current = 1;
        while (possibleNumbers.contains(current)) {
            current++;
        }
        return current - 1;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) {
            sc.close();
            return;
        }

        int n = sc.nextInt();
        int[][] dice = new int[n][6];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 6; j++) {
                if (sc.hasNextInt()) {
                    dice[i][j] = sc.nextInt();
                }
            }
        }
        sc.close();

        DiceSequenceFinder finder = new DiceSequenceFinder(dice);
        finder.solve();
    }
}

import java.util.Scanner;

/**
 * PatternSolver identifies the smallest non-negative integer whose digits 
 * cannot be represented by picking distinct rows from a given dataset.
 */
public class PatternSolver {

    private static final int MAX_VAL_TO_CHECK = 999;
    private static final int DIGITS_PER_ROW = 6;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rowCount = scanner.nextInt();
        boolean[][] digitPresence = readDigitPresence(scanner, rowCount);

        int result = findSmallestMissingPattern(digitPresence, rowCount);
        System.out.println(result);

        scanner.close();
    }

    /**
     * Reads input and creates a lookup table where presence[i][d] is true 
     * if digit 'd' exists in row 'i'.
     */
    private static boolean[][] readDigitPresence(Scanner scanner, int n) {
        boolean[][] presence = new boolean[n][10];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < DIGITS_PER_ROW; j++) {
                int digit = scanner.nextInt();
                if (digit >= 0 && digit <= 9) {
                    presence[i][digit] = true;
                }
            }
        }
        return presence;
    }

    /**
     * Iterates through possible numbers to find the first one that 
     * fails the distinct-row requirement.
     */
    private static int findSmallestMissingPattern(boolean[][] presence, int n) {
        // The original logic checks integers starting from 1, 10, 100...
        // and returns V - 1. This is equivalent to checking V = 1 to 999.
        for (int v = 1; v <= MAX_VAL_TO_CHECK; v++) {
            if (!canFormPattern(v, presence, n)) {
                return v - 1;
            }
        }
        return MAX_VAL_TO_CHECK;
    }

    /**
     * Determines if the digits of the given value can be mapped to 
     * distinct rows in the presence table.
     */
    private static boolean canFormPattern(int value, boolean[][] presence, int n) {
        int[] digits = extractDigits(value);
        int numDigits = digits.length;

        if (numDigits == 1) {
            return hasDigitInAnyRow(digits[0], presence, n);
        } else if (numDigits == 2) {
            return hasTwoDigitsInDistinctRows(digits[0], digits[1], presence, n);
        } else if (numDigits == 3) {
            return hasThreeDigitsInDistinctRows(digits[0], digits[1], digits[2], presence, n);
        }

        return false;
    }

    private static boolean hasDigitInAnyRow(int d1, boolean[][] presence, int n) {
        for (int i = 0; i < n; i++) {
            if (presence[i][d1]) return true;
        }
        return false;
    }

    private static boolean hasTwoDigitsInDistinctRows(int d1, int d2, boolean[][] presence, int n) {
        for (int i = 0; i < n; i++) {
            if (presence[i][d1]) {
                for (int j = 0; j < n; j++) {
                    if (i != j && presence[j][d2]) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private static boolean hasThreeDigitsInDistinctRows(int d1, int d2, int d3, boolean[][] presence, int n) {
        for (int i = 0; i < n; i++) {
            if (presence[i][d1]) {
                for (int j = 0; j < n; j++) {
                    if (i != j && presence[j][d2]) {
                        for (int k = 0; k < n; k++) {
                            if (i != k && j != k && presence[k][d3]) {
                                return true;
                            }
                        }
                    }
                }
            }
        }
        return false;
    }

    /**
     * Helper to break an integer into its constituent digits.
     */
    private static int[] extractDigits(int v) {
        if (v < 10) {
            return new int[]{v};
        } else if (v < 100) {
            return new int[]{v / 10, v % 10};
        } else {
            return new int[]{v / 100, (v / 10) % 10, v % 10};
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Solves the problem of finding the longest sequence of consecutive 
 * integers starting from 1 that can be formed by picking at most 
 * one digit from each of the N provided numbers.
 */
public class Main {

    public static void main(String[] args) {
        try (InputStream inputStream = System.in;
             PrintWriter out = new PrintWriter(System.out)) {

            FastReader reader = new FastReader(inputStream);
            int n = reader.nextInt();

            if (n < 0) {
                return;
            }

            // The problem specifies each number has 6 digits provided as separate integers.
            int[][] digitGrid = new int[n][6];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < 6; j++) {
                    digitGrid[i][j] = reader.nextInt();
                }
            }

            ConsecutiveNumberSolver solver = new ConsecutiveNumberSolver(n, digitGrid);
            out.println(solver.solve());

        } catch (IOException e) {
            // In a production environment, use a logging framework.
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Logic class to determine how many consecutive integers can be formed.
     */
    static class ConsecutiveNumberSolver {
        private final List<Integer>[] digitMap;
        private static final int MAX_TARGET = 1000;

        @SuppressWarnings("unchecked")
        public ConsecutiveNumberSolver(int n, int[][] digitGrid) {
            this.digitMap = new ArrayList[10];
            for (int i = 0; i < 10; i++) {
                digitMap[i] = new ArrayList<>();
            }

            // Populate the map of which input numbers contain which digits.
            // Using a boolean array to ensure we don't add the same index multiple times for one digit.
            boolean[][] hasDigit = new boolean[n][10];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < 6; j++) {
                    int digit = digitGrid[i][j];
                    if (digit >= 0 && digit <= 9 && !hasDigit[i][digit]) {
                        hasDigit[i][digit] = true;
                        digitMap[digit].add(i);
                    }
                }
            }
        }

        /**
         * Calculates the count of consecutive integers starting from 1.
         * @return The number of consecutive integers found.
         */
        public int solve() {
            int consecutiveCount = 0;

            // Since we only care about forming numbers up to 3 digits (1-999),
            // we check each target number sequentially.
            for (int target = 1; target < MAX_TARGET; target++) {
                if (canForm(target)) {
                    consecutiveCount++;
                } else {
                    break;
                }
            }

            return consecutiveCount;
        }

        /**
         * Checks if a target number can be formed using distinct source numbers.
         */
        private boolean canForm(int target) {
            List<Integer> targetDigits = extractDigits(target);
            int numDigits = targetDigits.size();

            if (numDigits == 1) {
                return !digitMap[targetDigits.get(0)].isEmpty();
            } 

            if (numDigits == 2) {
                int d1 = targetDigits.get(0);
                int d2 = targetDigits.get(1);
                return hasDistinctIndices(d1, d2);
            } 

            if (numDigits == 3) {
                int d1 = targetDigits.get(0);
                int d2 = targetDigits.get(1);
                int d3 = targetDigits.get(2);
                return hasDistinctIndices(d1, d2, d3);
            }

            return false;
        }

        /**
         * Helper to decompose target number into its constituent digits.
         */
        private List<Integer> extractDigits(int n) {
            List<Integer> digits = new ArrayList<>();
            if (n < 10) {
                digits.add(n);
            } else if (n < 100) {
                digits.add(n / 10);
                digits.add(n % 10);
            } else {
                digits.add(n / 100);
                digits.add((n / 10) % 10);
                digits.add(n % 10);
            }
            return digits;
        }

        /**
         * Checks for 2 distinct indices for two digits.
         */
        private boolean hasDistinctIndices(int d1, int d2) {
            // Optimization: We only need to check the first few indices to find a pair.
            // Checking up to 2 indices is sufficient for 2 digits.
            int limit1 = Math.min(digitMap[d1].size(), 2);
            int limit2 = Math.min(digitMap[d2].size(), 2);
            for (int i = 0; i < limit1; i++) {
                for (int j = 0; j < limit2; j++) {
                    if (!digitMap[d1].get(i).equals(digitMap[d2].get(j))) {
                        return true;
                    }
                }
            }
            return false;
        }

        /**
         * Checks for 3 distinct indices for three digits.
         */
        private boolean hasDistinctIndices(int d1, int d2, int d3) {
            // Optimization: Checking the first 3 indices is sufficient for 3 digits.
            int limit1 = Math.min(digitMap[d1].size(), 3);
            int limit2 = Math.min(digitMap[d2].size(), 3);
            int limit3 = Math.min(digitMap[d3].size(), 3);

            for (int i = 0; i < limit1; i++) {
                int idx1 = digitMap[d1].get(i);
                for (int j = 0; j < limit2; j++) {
                    int idx2 = digitMap[d2].get(j);
                    if (idx1 == idx2) continue;
                    for (int k = 0; k < limit3; k++) {
                        int idx3 = digitMap[d3].get(k);
                        if (idx3 != idx1 && idx3 != idx2) {
                            return true;
                        }
                    }
                }
            }
            return false;
        }
    }

    /**
     * High-performance byte-based reader for fast I/O.
     */
    static class FastReader {
        private final InputStream in;
        private final byte[] buffer = new byte[8192];
        private int pointer = 0;
        private int bufferLength = 0;

        public FastReader(InputStream in) {
            this.in = in;
        }

        private boolean fillBuffer() throws IOException {
            bufferLength = in.read(buffer);
            pointer = 0;
            return bufferLength > 0;
        }

        private byte read() throws IOException {
            if (pointer >= bufferLength) {
                if (!fillBuffer()) return -1;
            }
            return buffer[pointer++];
        }

        public int nextInt() throws IOException {
            byte c = read();
            while (c != -1 && c <= 32) c = read();
            if (c == -1) return -1;

            int neg = 1;
            if (c == '-') {
                neg = -1;
                c = read();
            }

            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = read();
            }
            return res * neg;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored version of the Digit Combiner program.
 * This program calculates how many consecutive integers (starting from 1) 
 * can be formed by picking digits from different provided sets.
 */
public class Main {

    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = in.nextInt();
            DigitSolver solver = new DigitSolver(n, in);
            solver.solve(out);
        } catch (Exception e) {
            // Silently handle or log error as per requirement
        } finally {
            out.close();
        }
    }

    /**
     * Solver class containing the core logic for the digit combination problem.
     */
    static class DigitSolver {
        private final int n;
        private final boolean[][] digitSets;
        private final FastReader reader;

        /**
         * @param n Number of sets available (1, 2, or 3).
         * @param reader The fast input reader.
         */
        public DigitSolver(int n, FastReader reader) {
            this.n = n;
            this.reader = reader;
            this.digitSets = new boolean[3][10];
            initializeSets();
        }

        /**
         * Populates the digit presence arrays for each of the n sets.
         */
        private void initializeSets() {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < 6; j++) {
                    int digit = reader.nextInt();
                    if (digit >= 0 && digit <= 9) {
                        digitSets[i][digit] = true;
                    }
                }
            }
        }

        /**
         * Executes the solving logic and prints the result to the provided PrintWriter.
         */
        public void solve(PrintWriter out) {
            int counter = 0;

            // Check 1-digit numbers (1-9)
            if (n >= 1) {
                for (int i = 1; i <= 9; i++) {
                    if (isValidSingleDigit(i)) {
                        counter++;
                    } else {
                        out.println(counter);
                        return;
                    }
                }
            }

            // Check 2-digit numbers (10-99)
            if (n >= 2) {
                for (int i = 10; i <= 99; i++) {
                    if (isValidDoubleDigit(i)) {
                        counter++;
                    } else {
                        out.println(counter);
                        return;
                    }
                }
            }

            // Check 3-digit numbers (100-999)
            if (n >= 3) {
                for (int i = 100; i <= 999; i++) {
                    if (isValidTripleDigit(i)) {
                        counter++;
                    } else {
                        out.println(counter);
                        return;
                    }
                }
            }

            out.println(counter);
        }

        private boolean isValidSingleDigit(int num) {
            for (int i = 0; i < n; i++) {
                if (digitSets[i][num]) return true;
            }
            return false;
        }

        private boolean isValidDoubleDigit(int num) {
            int d1 = num / 10;
            int d2 = num % 10;
            // Check if digits can be formed by two different sets
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (i != j && digitSets[i][d1] && digitSets[j][d2]) {
                        return true;
                    }
                }
            }
            return false;
        }

        private boolean isValidTripleDigit(int num) {
            int d1 = num / 100;
            int d2 = (num / 10) % 10;
            int d3 = num % 10;
            // Check if digits can be formed by three different sets
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    for (int k = 0; k < n; k++) {
                        if (i != j && j != k && i != k) {
                            if (digitSets[i][d1] && digitSets[j][d2] && digitSets[k][d3]) {
                                return true;
                            }
                        }
                    }
                }
            }
            return false;
        }
    }

    /**
     * Efficient utility for fast I/O operations.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int curChar;
        private int numChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) return -1;
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buffer);
                } catch (IOException e) {
                    return -1;
                }
                if (numChars <= 0) return -1;
            }
            return buffer[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') break;
                res = res * 10 + (c - '0');
                c = read();
            } while (c != -1 && !isSpaceChar(c));
            return res * sgn;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

/**
 * This program finds the smallest non-negative integer that cannot be formed
 * by concatenating digits from distinct rows of input.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rowCount = scanner.nextInt();
        int[][] digitMatrix = readDigitMatrix(scanner, rowCount, 6);

        Set<Integer> formedNumbers = new HashSet<>();
        generateAllPossibleNumbers(digitMatrix, 0, 0, 0, formedNumbers);

        int smallestMissing = findSmallestMissing(formedNumbers);
        System.out.println(smallestMissing);

        scanner.close();
    }

    /**
     * Reads the input matrix of digits.
     *
     * @param scanner The scanner to read from.
     * @param rows    Number of rows.
     * @param cols    Number of columns per row.
     * @return A 2D array containing the digits.
     */
    private static int[][] readDigitMatrix(Scanner scanner, int rows, int cols) {
        int[][] matrix = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (scanner.hasNextInt()) {
                    matrix[i][j] = scanner.nextInt();
                }
            }
        }
        return matrix;
    }

    /**
     * Recursively generates all possible numbers by picking at most one digit from each row.
     * This handles 1-digit, 2-digit, ..., N-digit numbers using distinct rows.
     *
     * @param matrix         The input digit matrix.
     * @param usedRowsMask   A bitmask representing which rows have already been used.
     * @param currentCount   How many digits have been used to form the current number.
     * @param currentVal     The integer value formed so far.
     * @param formedNumbers  The set storing all unique numbers formed.
     */
    private static void generateAllPossibleNumbers(int[][] matrix, int usedRowsMask, 
                                                   int currentCount, int currentVal, 
                                                   Set<Integer> formedNumbers) {
        // If we have formed a number (at least 1 digit), add it to our set
        if (currentCount > 0) {
            formedNumbers.add(currentVal);
        }

        // Base case: if we have used all available rows, stop recursion
        if (currentCount == matrix.length) {
            return;
        }

        // Try adding a digit from every row that hasn't been used yet
        for (int i = 0; i < matrix.length; i++) {
            if (!isRowUsed(usedRowsMask, i)) {
                int nextMask = usedRowsMask | (1 << i);
                for (int digit : matrix[i]) {
                    // Calculate the new value: current number shifted left + new digit
                    int nextVal = (currentVal * 10) + digit;
                    generateAllPossibleNumbers(matrix, nextMask, currentCount + 1, nextVal, formedNumbers);
                }
            }
        }
    }

    /**
     * Checks if a specific row index is set in the bitmask.
     */
    private static boolean isRowUsed(int mask, int rowIndex) {
        return (mask & (1 << rowIndex)) != 0;
    }

    /**
     * Finds the smallest non-negative integer (0, 1, 2...) not present in the set.
     *
     * @param formedNumbers The set of numbers that were successfully formed.
     * @return The smallest missing non-negative integer.
     */
    private static int findSmallestMissing(Set<Integer> formedNumbers) {
        int candidate = 0;
        while (formedNumbers.contains(candidate)) {
            candidate++;
        }
        return candidate;
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution to find the largest number x such that:
 * 1. Every digit in x is present in at least one of the provided n sets.
 * 2. The number of sets containing at least one digit of x is at least the number of digits in x.
 */
public class Main {
    public static void main(String[] args) {
        try {
            Solution solution = new Solution();
            solution.execute();
        } catch (IOException e) {
            System.err.println("An error occurred during execution: " + e.getMessage());
        }
    }
}

class Solution {
    private FastReader reader;
    private PrintWriter writer;

    public void execute() throws IOException {
        reader = new FastReader(System.in);
        writer = new PrintWriter(System.out);

        int numSets = reader.nextInt();
        if (numSets <= 0) {
            writer.println(0);
            writer.close();
            return;
        }

        // Pre-process input into a boolean matrix for O(1) lookup
        // isDigitInSet[setIndex][digit]
        boolean[][] isDigitInSet = new boolean[numSets][10];
        for (int i = 0; i < numSets; i++) {
            for (int j = 0; j < 6; j++) {
                int digit = reader.nextInt();
                if (digit >= 0 && digit <= 9) {
                    isDigitInSet[i][digit] = true;
                }
            }
        }

        long currentNumber = 1;
        // The limit is 10^n
        long limit = (long) Math.pow(10, numSets);

        while (currentNumber <= limit) {
            List<Integer> digits = extractDigits(currentNumber);
            int digitCount = digits.size();

            // Requirement 1: Every digit must exist in at least one set
            int digitPositionCoverage = 0;
            for (int digit : digits) {
                if (isDigitInAnySet(digit, isDigitInSet)) {
                    digitPositionCoverage++;
                }
            }

            // Requirement 2: Number of sets containing any digit must be >= number of digits
            int setCoverage = 0;
            for (int i = 0; i < numSets; i++) {
                if (isSetContainingAnyDigit(i, digits, isDigitInSet)) {
                    setCoverage++;
                }
            }

            // If both conditions are met, continue to next number; otherwise, stop.
            if (digitPositionCoverage >= digitCount && setCoverage >= digitCount) {
                currentNumber++;
            } else {
                break;
            }
        }

        // The loop breaks at the first invalid number, so the answer is currentNumber - 1
        writer.println(currentNumber - 1);
        writer.flush();
        writer.close();
    }

    /**
     * Breaks a number into its individual digits.
     */
    private List<Integer> extractDigits(long number) {
        List<Integer> digits = new ArrayList<>();
        long temp = number;
        while (temp > 0) {
            digits.add((int) (temp % 10));
            temp /= 10;
        }
        return digits;
    }

    /**
     * Checks if a specific digit exists in at least one of the provided sets.
     */
    private boolean isDigitInAnySet(int digit, boolean[][] isDigitInSet) {
        for (boolean[] set : isDigitInSet) {
            if (set[digit]) {
                return true;
            }
        }
        return false;
    }

    /**
     * Checks if a specific set contains at least one of the digits from the provided list.
     */
    private boolean isSetContainingAnyDigit(int setIdx, List<Integer> digits, boolean[][] isDigitInSet) {
        for (int digit : digits) {
            if (isDigitInSet[setIdx][digit]) {
                return true;
            }
        }
        return false;
    }
}

/**
 * Utility class for fast I/O operations.
 */
class FastReader {
    private BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream));
        tokenizer = null;
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                return null;
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        String next = next();
        return next != null ? Integer.parseInt(next) : 0;
    }

    public long nextLong() {
        String next = next();
        return next != null ? Long.parseLong(next) : 0L;
    }
}

import java.util.*;
import java.io.*;

/**
 * Solution class to find the largest consecutive integer starting from 1 
 * that can be formed using digits from the provided input numbers.
 */
public class Solution {

    public static void main(String[] args) {
        Solution solution = new Solution();
        solution.solve();
    }

    /**
     * Core logic of the program.
     */
    public void solve() {
        FastReader reader = new FastReader();

        // Read number of rows
        int n = reader.nextInt();
        if (n <= 0) {
            return;
        }

        // Store input in a 2D array where each row contains 6 digits
        int[][] numbers = new int[n][6];
        boolean[] isPossible = new boolean[1001];

        // 1. Read input and mark individual digits as possible
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 6; j++) {
                int digit = reader.nextInt();
                numbers[i][j] = digit;

                // Mark single digits as possible if within range
                if (digit >= 0 && digit <= 1000) {
                    isPossible[digit] = true;
                }
            }
        }

        // 2. Mark two-digit combinations formed by digits from different numbers
        // The logic follows the original: pick one digit from row i and one from row j
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                for (int k = 0; k < 6; k++) {
                    for (int l = 0; l < 6; l++) {
                        int digitFromI = numbers[i][k];
                        int digitFromJ = numbers[j][l];

                        // Formation: [Digit from i][Digit from j]
                        int combo1 = digitFromI * 10 + digitFromJ;
                        if (combo1 <= 1000) {
                            isPossible[combo1] = true;
                        }

                        // Formation: [Digit from j][Digit from i]
                        int combo2 = digitFromJ * 10 + digitFromI;
                        if (combo2 <= 1000) {
                            isPossible[combo2] = true;
                        }
                    }
                }
            }
        }

        // 3. Find the smallest integer 'i' that cannot be formed.
        // Per the original logic, the output is i - 1.
        for (int i = 1; i <= 1000; i++) {
            if (!isPossible[i]) {
                System.out.println(i - 1);
                return;
            }
        }
    }

    /**
     * Optimized reader for faster input processing.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
