/**
 * A solution to find the smallest positive integer that cannot be formed 
 * by concatenating the digits from 1, 2, or 3 distinct cubes.
 */
public class DiceProblem {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        try {
            String firstLine = reader.next();
            if (firstLine == null) return;

            int numCubes = Integer.parseInt(firstLine);
            Cube[] cubes = new Cube[numCubes];

            for (int i = 0; i < numCubes; i++) {
                int[] faces = new int[6];
                for (int j = 0; j < 6; j++) {
                    faces[j] = reader.nextInt();
                }
                cubes[i] = new Cube(faces);
            }

            DiceSolver solver = new DiceSolver();
            int smallestMissing = solver.findSmallestMissing(cubes);
            out.println(smallestMissing);

        } catch (IOException | NumberFormatException e) {
            // In a production environment, log this error appropriately
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Represents a die containing 6 faces.
     */
    static class Cube {
        private final int[] faces;

        public Cube(int[] faces) {
            if (faces == null || faces.length != 6) {
                throw new IllegalArgumentException("A cube must have exactly 6 faces.");
            }
            this.faces = faces;
        }

        public int[] getFaces() {
            return faces;
        }
    }

    /**
     * Logic for calculating possible numbers formed by dice faces.
     */
    static class DiceSolver {
        private static final int MAX_LOOKUP = 1000;

        /**
         * Finds the smallest positive integer (1, 2, 3...) not formable 
         * by concatenating digits from 1, 2, or 3 distinct cubes.
         *
         * @param cubes The array of available cubes.
         * @return The smallest missing positive integer.
         */
        public int findSmallestMissing(Cube[] cubes) {
            int n = cubes.length;
            boolean[] possibleNumbers = new boolean[MAX_LOOKUP + 1];

            // 1. Single-digit numbers (using 1 cube)
            for (int i = 0; i < n; i++) {
                for (int face : cubes[i].getFaces()) {
                    if (face >= 0 && face <= MAX_LOOKUP) {
                        possibleNumbers[face] = true;
                    }
                }
            }

            // 2. Two-digit numbers (using 2 distinct cubes)
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (i == j) continue;
                    for (int f1 : cubes[i].getFaces()) {
                        for (int f2 : cubes[j].getFaces()) {
                            int num = f1 * 10 + f2;
                            if (num >= 0 && num <= MAX_LOOKUP) {
                                possibleNumbers[num] = true;
                            }
                        }
                    }
                }
            }

            // 3. Three-digit numbers (using 3 distinct cubes)
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    if (i == j) continue;
                    for (int k = 0; k < n; k++) {
                        // Ensure all three cubes are distinct
                        if (k == i || k == j) continue;

                        for (int f1 : cubes[i].getFaces()) {
                            for (int f2 : cubes[j].getFaces()) {
                                for (int f3 : cubes[k].getFaces()) {
                                    int num = f1 * 100 + f2 * 10 + f3;
                                    if (num >= 0 && num <= MAX_LOOKUP) {
                                        possibleNumbers[num] = true;
                                    }
                                }
                            }
                        }
                    }
                }
            }

            // Search for the smallest missing positive integer
            for (int val = 1; val <= MAX_LOOKUP; val++) {
                if (!possibleNumbers[val]) {
                    return val;
                }
            }

            return MAX_LOOKUP + 1;
        }
    }

    /**
     * Fast I/O utility for efficient reading of large inputs.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * Represents a physical cube with six faces, each containing a single digit.
 */
class Cube {
    private final boolean[] digitPresence;

    public Cube(int[] faces) {
        this.digitPresence = new boolean[10];
        for (int face : faces) {
            if (face >= 0 && face <= 9) {
                this.digitPresence[face] = true;
            }
        }
    }

    /**
     * Checks if the cube contains a specific digit.
     * @param digit The digit to look for.
     * @return true if the digit is present on one of the faces.
     */
    public boolean containsDigit(int digit) {
        return digit >= 0 && digit <= 9 && digitPresence[digit];
    }
}

/**
 * Logic engine to determine if a number can be formed using a set of cubes.
 */
class CubeMatcher {
    private final Cube[] cubes;

    public CubeMatcher(Cube[] cubes) {
        this.cubes = cubes;
    }

    /**
     * Determines if a given number can be formed such that each digit 
     * is provided by a unique cube.
     */
    public boolean canFormNumber(int number) {
        int[] digits = extractDigits(number);
        boolean[] usedCubes = new boolean[cubes.length];
        return backtrack(digits, usedCubes, 0);
    }

    /**
     * Recursive backtracking to match digits to available cubes.
     */
    private boolean backtrack(int[] digits, boolean[] usedCubes, int digitIndex) {
        // Base case: all digits have been successfully matched to a cube
        if (digitIndex == digits.length) {
            return true;
        }

        int currentDigit = digits[digitIndex];

        for (int i = 0; i < cubes.length; i++) {
            // If the cube is not used and contains the required digit
            if (!usedCubes[i] && cubes[i].containsDigit(currentDigit)) {
                usedCubes[i] = true; // Mark cube as used

                if (backtrack(digits, usedCubes, digitIndex + 1)) {
                    return true;
                }

                usedCubes[i] = false; // Backtrack (unmark cube)
            }
        }

        return false;
    }

    /**
     * Converts an integer into an array of its constituent digits.
     */
    private int[] extractDigits(int number) {
        if (number == 0) return new int[]{0};

        int temp = number;
        int count = 0;
        while (temp > 0) {
            temp /= 10;
            count++;
        }

        int[] digits = new int[count];
        temp = number;
        for (int i = count - 1; i >= 0; i--) {
            digits[i] = temp % 10;
            temp /= 10;
        }
        return digits;
    }
}

public class Main {

    private static final int MAX_NUMBER_LIMIT = 1000;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int numberOfCubes = scanner.nextInt();
        Cube[] cubes = new Cube[numberOfCubes];

        for (int i = 0; i < numberOfCubes; i++) {
            int[] faces = new int[6];
            for (int j = 0; j < 6; j++) {
                faces[j] = scanner.nextInt();
            }
            cubes[i] = new Cube(faces);
        }

        int result = solve(cubes);
        System.out.println(result);

        scanner.close();
    }

    /**
     * Finds the largest integer (up to 999) that can be formed using the cubes.
     */
    private static int solve(Cube[] cubes) {
        CubeMatcher matcher = new CubeMatcher(cubes);
        int lastSuccessfulNumber = 0;

        for (int currentNumber = 1; currentNumber < MAX_NUMBER_LIMIT; currentNumber++) {
            if (matcher.canFormNumber(currentNumber)) {
                lastSuccessfulNumber = currentNumber;
            } else {
                // Since we are looking for the largest contiguous number 
                // from 1 upwards, we stop at the first failure.
                break;
            }
        }

        return lastSuccessfulNumber;
    }
}

