import java.util.*;

/**
 * Main entry point for the program.
 * Handles I/O orchestration and invokes the solver.
 */
public class Main {
    public static void main(String[] args) {
        try (InputReader in = new InputReader(System.in);
             PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)))) {

            int n = in.nextInt();
            boolean[][] sets = new boolean[n][10];

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < 6; j++) {
                    int digit = in.nextInt();
                    if (digit >= 0 && digit <= 9) {
                        sets[i][digit] = true;
                    }
                }
            }

            Solver solver = new Solver(n, sets);
            solver.solve(out);
            out.flush();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Encapsulates the logic for solving the specific task.
     */
    static class Solver {
        private final int numSets;
        private final boolean[][] sets;

        public Solver(int numSets, boolean[][] sets) {
            this.numSets = numSets;
            this.sets = sets;
        }

        /**
         * Orchestrates the multi-step process of finding the largest valid number.
         */
        public void solve(PrintWriter out) {
            int maxPrefix = findMaxPrefix();

            // Rule 1: If the largest consecutive prefix of 1-9 is less than 9, return it.
            if (maxPrefix < 9) {
                out.println(maxPrefix);
                return;
            }

            // Rule 2: If prefix is 9, attempt to find the largest 2-digit number.
            int ans2 = findMax2Digit(maxPrefix);

            // Rule 3: If n=3 and the largest 2-digit number is 99, attempt 3-digit number.
            if (numSets == 3 && ans2 == 99) {
                out.println(findMax3Digit(ans2));
            } else {
                out.println(ans2);
            }
        }

        private int findMaxPrefix() {
            int k = 0;
            for (int i = 1; i <= 9; i++) {
                boolean foundInAnySet = false;
                for (int s = 0; s < numSets; s++) {
                    if (sets[s][i]) {
                        foundInAnySet = true;
                        break;
                    }
                }
                if (foundInAnySet) {
                    k = i;
                } else {
                    break;
                }
            }
            return k;
        }

        private int findMax2Digit(int initialAns) {
            int ans = initialAns;
            boolean continueSearching = true;
            for (int i = 1; i <= 9 && continueSearching; i++) {
                for (int j = 0; j <= 9 && continueSearching; j++) {
                    if (canForm2(i, j)) {
                        ans = i * 10 + j;
                    } else {
                        continueSearching = false;
                    }
                }
            }
            return ans;
        }

        private int findMax3Digit(int initialAns) {
            int ans = initialAns;
            boolean continueSearching = true;
            for (int i = 1; i <= 9 && continueSearching; i++) {
                for (int j = 0; j <= 9 && continueSearching; j++) {
                    for (int k = 0; k <= 9 && continueSearching; k++) {
                        if (canForm3(i, j, k)) {
                            ans = i * 100 + j * 10 + k;
                        } else {
                            continueSearching = false;
                        }
                    }
                }
            }
            return ans;
        }

        private boolean canForm2(int d1, int d2) {
            if (numSets < 2) return false;
            if (numSets == 2) {
                return (sets[0][d1] && sets[1][d2]) || (sets[1][d1] && sets[0][d2]);
            } else {
                // For n=3, d1 and d2 must be in any two different sets
                return (sets[0][d1] && (sets[1][d2] || sets[2][d2])) ||
                       (sets[1][d1] && (sets[0][d2] || sets[2][d2])) ||
                       (sets[2][d1] && (sets[0][d2] || sets[1][d2]));
            }
        }

        private boolean canForm3(int d1, int d2, int d3) {
            // For n=3, d1, d2, and d3 must belong to three distinct sets.
            // Checking all 6 permutations of the 3 sets.
            int[][] perms = {
                {0, 1, 2}, {0, 2, 1}, {1, 0, 2}, 
                {1, 2, 0}, {2, 0, 1}, {2, 1, 0}
            };
            for (int[] p : perms) {
                if (sets[p[0]][d1] && sets[p[1]][d2] && sets[p[2]][d3]) {
                    return true;
                }
            }
            return false;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class InputReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Refactored solution for the Digit Problem.
 * Uses SOS DP (Sum Over Subsets) to optimize the search for the largest valid integer.
 */
public class Main {

    public static void main(String[] args) {
        FastReader in = new FastReader(System.in);
        FastWriter out = new FastWriter(System.out);

        DigitProblemSolver solver = new DigitProblemSolver();
        solver.solve(in, out);

        out.close();
    }

    /**
     * Core logic solver.
     */
    static class DigitProblemSolver {

        /**
         * Reads input and solves the problem.
         * 
         * @param in  The fast input reader.
         * @param out The fast output writer.
         */
        public void solve(FastReader in, FastWriter out) {
            int n = in.nextInt();
            if (n <= 0) {
                out.print(0);
                return;
            }

            int[] freq = new int[1024]; // Frequency of each bitmask (0-1023)
            int allDigitsMask = 0;

            // Read N sets, each containing 6 integers
            for (int i = 0; i < n; i++) {
                int currentSetMask = 0;
                for (int j = 0; j < 6; j++) {
                    int digit = in.nextInt();
                    currentSetMask |= (1 << digit);
                }
                freq[currentSetMask]++;
                allDigitsMask |= currentSetMask;
            }

            // Pre-calculate subset sums using SOS DP
            // subsetSum[mask] will store the count of sets whose bitmask is a subset of 'mask'
            int[] subsetSum = new int[1024];
            for (int i = 0; i < 1024; i++) {
                subsetSum[i] = freq[i];
            }
            for (int i = 0; i < 10; i++) {
                for (int mask = 0; mask < 1024; mask++) {
                    if ((mask & (1 << i)) != 0) {
                        subsetSum[mask] += subsetSum[mask ^ (1 << i)];
                    }
                }
            }

            // Find the first number that violates the rules
            int result = 999;
            for (int i = 1; i <= 999; i++) {
                if (!isValid(i, n, subsetSum, allDigitsMask)) {
                    result = i - 1;
                    break;
                }
            }

            out.print(result);
        }

        /**
         * Checks if a number is valid based on the problem constraints.
         * 
         * @param val            The number to check.
         * @param totalSets      Total number of sets provided in input.
         * @param subsetSum      Pre-calculated SOS DP array.
         * @param allDigitsMask  Bitmask of all digits present across all sets.
         * @return true if the number satisfies the criteria, false otherwise.
         */
        private boolean isValid(int val, int totalSets, int[] subsetSum, int allDigitsMask) {
            int numberMask = 0;
            int digitLength = 0;
            int temp = val;

            // Extract digits and build the number's bitmask
            while (temp > 0) {
                int digit = temp % 10;
                // Requirement 1: Every digit in the number must exist in at least one input set
                if ((allDigitsMask & (1 << digit)) == 0) {
                    return false;
                }
                numberMask |= (1 << digit);
                digitLength++;
                temp /= 10;
            }

            // Requirement 2: The number of sets containing at least one digit of 'val' must be >= digitLength
            // To find sets containing at least one digit: Total - (sets containing ZERO digits of 'val')
            // Sets containing zero digits of 'val' are subsets of the complement of 'numberMask'.
            int complementMask = 1023 ^ numberMask;
            int setsWithNoDigits = subsetSum[complementMask];
            int setsWithAtLeastOneDigit = totalSets - setsWithNoDigits;

            return setsWithAtLeastOneDigit >= digitLength;
        }
    }

    /**
     * Fast I/O reader using BufferedReader and StringTokenizer.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /**
     * Fast I/O writer using PrintWriter.
     */
    static class FastWriter {
        private final PrintWriter writer;

        public FastWriter(OutputStream os) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(os)));
        }

        public void print(int i) {
            writer.print(i);
        }

        public void close() {
            writer.close();
        }
    }
}

