/**
 * Problem: Find the smallest integer (represented by i-1 in original logic) 
 * that cannot be formed by selecting one digit from each of a subset of 
 * available rows and permuting them.
 */
public class SmallestMissingNumber {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        try {
            int n = reader.nextInt();
            if (n <= 0) return;

            int[][] rows = new int[n][6];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < 6; j++) {
                    rows[i][j] = reader.nextInt();
                }
            }

            ProblemSolver solver = new ProblemSolver(rows);
            solver.solveAndPrint();

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Encapsulates the logic for calculating possible numbers.
     */
    static class ProblemSolver {
        private static final int MAX_POSSIBLE_VALUE = 100000;
        private final int[][] rows;
        private final boolean[] possibleNumbers = new boolean[MAX_POSSIBLE_VALUE];

        public ProblemSolver(int[][] rows) {
            this.rows = rows;
            // The original code initialized vis[0] = true
            this.possibleNumbers[0] = true;
        }

        public void solveAndPrint() {
            int n = rows.length;

            // Iterate through every non-empty subset of rows using a bitmask
            // 1 << n represents 2^n
            for (int i = 1; i < (1 << n); i++) {
                List<Integer> selectedRowIndices = new ArrayList<>();
                for (int r = 0; r < n; r++) {
                    if (((i >> r) & 1) == 1) {
                        selectedRowIndices.add(r);
                    }
                }
                // For the chosen subset of rows, pick one digit from each
                generateDigitCombinations(selectedRowIndices, 0, new int[selectedRowIndices.size()]);
            }

            // Find the smallest index i >= 1 that was not marked as possible
            for (int i = 1; i < MAX_POSSIBLE_VALUE; i++) {
                if (!possibleNumbers[i]) {
                    // The original code output (i - 1)
                    System.out.println(i - 1);
                    return;
                }
            }
        }

        /**
         * Recursively picks one digit from each selected row.
         */
        private void generateDigitCombinations(List<Integer> rowIndices, int currentIndex, int[] selectedDigits) {
            if (currentIndex == rowIndices.size()) {
                // Once one digit is picked from every selected row, permute them
                generatePermutations(selectedDigits.clone(), 0);
                return;
            }

            int rowIndex = rowIndices.get(currentIndex);
            for (int digit : rows[rowIndex]) {
                selectedDigits[currentIndex] = digit;
                generateDigitCombinations(rowIndices, currentIndex + 1, selectedDigits);
            }
        }

        /**
         * Generates all permutations of the selected digits and marks the resulting numbers.
         */
        private void generatePermutations(int[] digits, int start) {
            if (start == digits.length) {
                int value = 0;
                for (int d : digits) {
                    value = value * 10 + d;
                }
                if (value < MAX_POSSIBLE_VALUE) {
                    possibleNumbers[value] = true;
                }
                return;
            }

            for (int i = start; i < digits.length; i++) {
                swap(digits, start, i);
                generatePermutations(digits, start + 1);
                swap(digits, start, i); // Backtrack
            }
        }

        private void swap(int[] arr, int i, int j) {
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }
    }

    /**
     * Utility class for high-performance input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

