/**
 * This program finds the largest integer in a continuous sequence starting from 1
 * that can be formed by picking one digit from each of the N rows of a given matrix,
 * where the order of the rows can be any permutation of the indices 0 to N-1.
 * 
 * Refactored for improved maintainability, readability, and memory efficiency.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int[][] matrix = new int[n][6];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 6; j++) {
                if (scanner.hasNextInt()) {
                    matrix[i][j] = scanner.nextInt();
                }
            }
        }

        SequenceFinder finder = new SequenceFinder(n, matrix);
        System.out.println(finder.findMaxContinuousSequence());

        scanner.close();
    }
}

/**
 * Encapsulates the logic for generating number sequences from the matrix.
 */
class SequenceFinder {
    private final int rowCount;
    private final int[][] matrix;
    private final Set<Integer> foundNumbers = new HashSet<>();

    /**
     * @param rowCount The number of rows in the input matrix.
     * @param matrix   The input matrix containing digits.
     */
    public SequenceFinder(int rowCount, int[][] matrix) {
        this.rowCount = rowCount;
        this.matrix = matrix;
    }

    /**
     * Finds the maximum integer x such that all integers from 1 to x 
     * are present in the generated set of numbers.
     *
     * @return The highest value in the continuous sequence starting from 1.
     */
    public int findMaxContinuousSequence() {
        if (rowCount == 0) {
            return 0;
        }

        // Step 1: Generate all possible numbers using all permutations of row indices.
        // This uses backtracking to avoid heavy object allocation.
        generatePermutations(new int[rowCount], new boolean[rowCount], 0);

        // Step 2: Find the first missing positive integer (MEX - 1 logic).
        int current = 1;
        while (foundNumbers.contains(current)) {
            current++;
        }

        return current - 1;
    }

    /**
     * Generates all permutations of row indices using backtracking.
     * 
     * @param currentOrder An array to store the current permutation of row indices.
     * @param used         A boolean array to track which rows are already in the permutation.
     * @param depth        The current recursion depth (index being filled in currentOrder).
     */
    private void generatePermutations(int[] currentOrder, boolean[] used, int depth) {
        if (depth == rowCount) {
            // Once a full permutation of rows is selected, generate all digit combinations.
            generateCombinations(currentOrder, 0, 0);
            return;
        }

        for (int i = 0; i < rowCount; i++) {
            if (!used[i]) {
                used[i] = true;
                currentOrder[depth] = i;
                generatePermutations(currentOrder, used, depth + 1);
                used[i] = false; // Backtrack
            }
        }
    }

    /**
     * Generates all combinations of digits for a fixed row order using backtracking.
     *
     * @param order      The specific permutation of row indices to use.
     * @param depth      The current row index within the permutation being processed.
     * @param currentNum The integer value built so far.
     */
    private void generateCombinations(int[] order, int depth, int currentNum) {
        if (depth == rowCount) {
            foundNumbers.add(currentNum);
            return;
        }

        int rowIndex = order[depth];
        for (int colIndex = 0; colIndex < 6; colIndex++) {
            // Concatenate the digit into the current number.
            // Note: The original logic uses (current * 10 + nextDigit).
            int nextNum = currentNum * 10 + matrix[rowIndex][colIndex];
            generateCombinations(order, depth + 1, nextNum);
        }
    }
}

