/**
 * DigitMatcher finds the largest integer x such that every integer from 1 to x 
 * can have its digits uniquely assigned to distinct sets of integers provided in the input.
 */
public class DigitMatcher {

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter pw = new PrintWriter(new BufferedOutputStream(System.out));

        int numberOfSets = fs.nextInt();
        if (numberOfSets <= 0) {
            pw.println(0);
            pw.close();
            return;
        }

        // Pre-process input: Map each digit (0-9) to the indices of sets that contain it.
        // Using a Set during construction to handle duplicate digits within the same input set.
        Set<Integer>[] digitToSetsMap = new HashSet[10];
        for (int i = 0; i < 10; i++) {
            digitToSetsMap[i] = new HashSet<>();
        }

        for (int i = 0; i < numberOfSets; i++) {
            for (int j = 0; j < 6; j++) {
                int digit = fs.nextInt();
                if (digit >= 0 && digit <= 9) {
                    digitToSetsMap[digit].add(i);
                }
            }
        }

        // Convert to List for faster iteration during backtracking
        List<Integer>[] digitToSets = new ArrayList[10];
        for (int i = 0; i < 10; i++) {
            digitToSets[i] = new ArrayList<>(digitToSetsMap[i]);
        }

        // Find the largest x in [1, 999] such that all integers from 1 to x are matchable.
        int maxConsecutiveMatchable = 0;
        for (int candidate = 1; candidate <= 999; candidate++) {
            if (isMatchable(candidate, digitToSets, numberOfSets)) {
                maxConsecutiveMatchable = candidate;
            } else {
                // As soon as one number fails the condition, we stop.
                break;
            }
        }

        pw.println(maxConsecutiveMatchable);
        pw.close();
    }

    /**
     * Checks if the digits of a given number can be assigned to distinct sets.
     */
    private static boolean isMatchable(int number, List<Integer>[] digitToSets, int n) {
        List<Integer> digits = getDigits(number);
        boolean[] usedSets = new boolean[n];
        return canAssignDigits(digits, 0, usedSets, digitToSets);
    }

    /**
     * Backtracking algorithm to find a valid assignment of digits to unique sets.
     */
    private static boolean canAssignDigits(List<Integer> digits, int digitIdx, boolean[] usedSets, List<Integer>[] digitToSets) {
        if (digitIdx == digits.size()) {
            return true;
        }

        int currentDigit = digits.get(digitIdx);

        // Only iterate over sets that are known to contain the current digit
        for (int setIdx : digitToSets[currentDigit]) {
            if (!usedSets[setIdx]) {
                usedSets[setIdx] = true;
                if (canAssignDigits(digits, digitIdx + 1, usedSets, digitToSets)) {
                    return true;
                }
                usedSets[setIdx] = false; // Backtrack
            }
        }

        return false;
    }

    /**
     * Helper to extract digits from an integer.
     */
    private static List<Integer> getDigits(int number) {
        List<Integer> digits = new ArrayList<>();
        int temp = number;
        while (temp > 0) {
            digits.add(temp % 10);
            temp /= 10;
        }
        return digits;
    }

    /**
     * Optimized scanner for fast I/O operations.
     */
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = new StringTokenizer("");
        }

        public String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }
}

