/**
 * Logic class responsible for solving the number decomposition problem.
 */
class Solver {

    /**
     * Reads input and executes the search for the largest valid integer.
     */
    public void solve(FastReader in, PrintWriter out) {
        int n = in.nextInt();

        // The problem logic is built around the interaction of 3 specific sets.
        // We initialize an array of sets to hold the input data.
        Set<Integer>[] sets = new HashSet[n];
        for (int i = 0; i < n; i++) {
            sets[i] = new HashSet<>();
            for (int j = 0; j < 6; j++) {
                sets[i].add(in.nextInt());
            }
        }

        // If the problem constraints require exactly 3 sets to satisfy the decomposition logic.
        if (n < 3) {
            out.print(0);
            return;
        }

        int x = 1;
        // Find the first integer that cannot be formed via the specified decomposition rules.
        while (canFormNumber(x, sets[0], sets[1], sets[2])) {
            x++;
        }

        // The largest valid number is the one immediately before the first invalid number.
        out.print(x - 1);
    }

    /**
     * Determines if a number 'x' satisfies any of the 1, 2, or 3-part decomposition rules.
     */
    private boolean canFormNumber(int x, Set<Integer> s1, Set<Integer> s2, Set<Integer> s3) {
        return isMatch1Part(x, s1, s2, s3) ||
               isMatch2Parts(x, s1, s2, s3) ||
               isMatch3Parts(x, s1, s2, s3);
    }

    /**
     * Rule 1: The number itself exists in one of the sets.
     */
    private boolean isMatch1Part(int x, Set<Integer> s1, Set<Integer> s2, Set<Integer> s3) {
        return s1.contains(x) || s2.contains(x) || s3.contains(x);
    }

    /**
     * Rule 2: The number can be split into two parts that exist in two different sets.
     */
    private boolean isMatch2Parts(int x, Set<Integer> s1, Set<Integer> s2, Set<Integer> s3) {
        return checkTwoParts(x, s1, s2) ||
               checkTwoParts(x, s1, s3) ||
               checkTwoParts(x, s2, s3);
    }

    /**
     * Rule 3: The number can be split into three parts (based on powers of 10) 
     * across the three sets.
     */
    private boolean isMatch3Parts(int x, Set<Integer> s1, Set<Integer> s2, Set<Integer> s3) {
        int firstPart = x / 100;
        int remainder = x % 100;

        // Check if the first part is in S1 and the remainder is split between S2 and S3, etc.
        if (s1.contains(firstPart) && checkTwoParts(remainder, s2, s3)) return true;
        if (s2.contains(firstPart) && checkTwoParts(remainder, s1, s3)) return true;
        if (s3.contains(firstPart) && checkTwoParts(remainder, s1, s2)) return true;

        return false;
    }

    /**
     * Helper to check if a value can be split into two parts (using /10 and %10)
     * and found in two provided sets.
     */
    private boolean checkTwoParts(int val, Set<Integer> s1, Set<Integer> s2) {
        int partA = val / 10;
        int partB = val % 10;
        return (s1.contains(partA) && s2.contains(partB)) ||
               (s2.contains(partA) && s1.contains(partB));
    }
}

