import java.util.Set;
import java.util.TreeSet;

/**
 * This program calculates numbers formed by concatenating digits from a collection of digit groups.
 * It then identifies the length of the longest contiguous sequence of positive integers 
 * starting from 1 that can be formed using these groups.
 */
public class DigitSequenceGenerator {

    private static final int DIGITS_PER_GROUP = 6;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);

        int n;
        try {
            n = sc.nextInt();
        } catch (Exception e) {
            return;
        }

        // Read the input digit groups
        int[][] digitGroups = new int[n][DIGITS_PER_GROUP];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < DIGITS_PER_GROUP; j++) {
                digitGroups[i][j] = sc.nextInt();
            }
        }

        // Set to store all unique numbers reachable via the digit combinations
        Set<Integer> reachableNumbers = new TreeSet<>();

        // Start the recursive generation process
        generateReachableNumbers(0, 0, digitGroups, reachableNumbers);

        // Find the longest contiguous sequence of positive integers [1, 2, ..., k]
        int result = findLongestContiguousPositiveSequence(reachableNumbers);
        System.out.println(result);
    }

    /**
     * Recursively explores combinations of digits from the provided groups.
     *
     * @param currentNumber   The number formed by the current path of recursion.
     * @param usedGroupsMask  A bitmask representing which groups have already been used.
     * @param digitGroups     The source arrays containing digits.
     * @param reachableNumbers The set containing all successfully formed numbers.
     */
    private static void generateReachableNumbers(long currentNumber, int usedGroupsMask, 
                                                 int[][] digitGroups, Set<Integer> reachableNumbers) {
        // Add the number formed so far to the set
        // We cast to int to match the intended logic of looking for 32-bit integers
        reachableNumbers.add((int) currentNumber);

        for (int i = 0; i < digitGroups.length; i++) {
            // Skip this group if it has already been used in the current number construction
            if ((usedGroupsMask & (1 << i)) != 0) {
                continue;
            }

            for (int digit : digitGroups[i]) {
                long nextNumber = currentNumber * 10 + digit;

                // Only continue recursion if the number is within the range of a signed 32-bit integer.
                // This prevents uncontrolled integer overflow and matches the original logic.
                if (nextNumber <= Integer.MAX_VALUE) {
                    generateReachableNumbers(nextNumber, usedGroupsMask | (1 << i), digitGroups, reachableNumbers);
                }
            }
        }
    }

    /**
     * Finds the largest integer 'k' such that all integers from 1 to 'k' are present in the set.
     * This follows the original implementation's logic of finding the first missing positive 
     * integer and returning i - 1.
     *
     * @param set The set of reachable numbers.
     * @return The length of the contiguous sequence.
     */
    private static int findLongestContiguousPositiveSequence(Set<Integer> set) {
        for (int i = 1; ; i++) {
            if (!set.contains(i)) {
                return i - 1;
            }
        }
    }

    /**
     * Fast I/O utility to handle large inputs efficiently.
     */
    static class FastScanner {
        private final InputStream stream;
        private final byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }
    }
}

