/**
 * DigitSequenceMatcher solves the problem of finding the largest integer 'i' 
 * such that all integers from 1 to 'i' can be formed by selecting unique 
 * sets of digits from the provided input.
 */
public class DigitSequenceMatcher {

    private static final int MAX_SEARCH_VALUE = 999;
    private static final int DIGITS_PER_SET = 6;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();

        // Pre-process: Map each digit (0-9) to the indices of sets that contain it.
        // Optimization: For a number with at most 3 digits, we only need to track 
        // at most 3 sets per digit to guarantee finding a valid matching if one exists.
        List<Integer>[] digitToSets = new ArrayList[10];
        for (int i = 0; i < 10; i++) {
            digitToSets[i] = new ArrayList<>();
        }

        for (int i = 0; i < n; i++) {
            Set<Integer> uniqueDigitsInCurrentSet = new HashSet<>();
            for (int j = 0; j < DIGITS_PER_SET; j++) {
                if (scanner.hasNextInt()) {
                    uniqueDigitsInCurrentSet.add(scanner.nextInt());
                }
            }
            for (int digit : uniqueDigitsInCurrentSet) {
                if (digit >= 0 && digit <= 9 && digitToSets[digit].size() < 3) {
                    digitToSets[digit].add(i);
                }
            }
        }

        int result = 0;
        // Find the largest i such that all numbers from 1 to i are "formable".
        for (int i = 1; i <= MAX_SEARCH_VALUE; i++) {
            if (canFormNumber(i, digitToSets)) {
                result = i;
            } else {
                break;
            }
        }

        System.out.println(result);
        scanner.close();
    }

    /**
     * Determines if a specific number can be formed using a unique set for each digit.
     *
     * @param number       The number to check.
     * @param digitToSets  A mapping from digits to the indices of sets containing them.
     * @return true if a valid assignment of sets to digits exists.
     */
    private static boolean canFormNumber(int number, List<Integer>[] digitToSets) {
        int[] digits = extractDigits(number);
        // We use a Set to track which set indices have already been used in the current matching.
        return backtrack(0, digits, digitToSets, new HashSet<>());
    }

    /**
     * Extracts digits of a number into an array without using String conversion for speed.
     * 
     * @param number The number to decompose.
     * @return An array of integers representing the digits.
     */
    private static int[] extractDigits(int number) {
        if (number >= 100) {
            return new int[]{number / 100, (number / 10) % 10, number % 10};
        } else if (number >= 10) {
            return new int[]{number / 10, number % 10};
        } else {
            return new int[]{number};
        }
    }

    /**
     * A backtracking algorithm to find a bipartite matching between digits and sets.
     *
     * @param digitIdx     The current index in the digit array we are trying to match.
     * @param digits       The array of digits in the number being checked.
     * @param digitToSets  The pre-processed mapping of digits to available set indices.
     * @param usedSets     The set of indices currently assigned to digits.
     * @return true if a complete matching is found.
     */
    private static boolean backtrack(int digitIdx, int[] digits, List<Integer>[] digitToSets, Set<Integer> usedSets) {
        // Base case: All digits in the number have been successfully matched to a unique set.
        if (digitIdx == digits.length) {
            return true;
        }

        int currentDigit = digits[digitIdx];
        // Attempt to assign an available set that contains the current digit.
        for (int setIdx : digitToSets[currentDigit]) {
            if (!usedSets.contains(setIdx)) {
                usedSets.add(setIdx);

                if (backtrack(digitIdx + 1, digits, digitToSets, usedSets)) {
                    return true;
                }

                // Backtrack: remove the set to try other possibilities.
                usedSets.remove(setIdx);
            }
        }
        return false;
    }
}

import java.io.InputStream;
import java.io.PrintStream;
