/**
 * Represents a single six-sided die.
 */
class Die {
    private final Set<Integer> faces;

    public Die(int[] faceValues) {
        this.faces = new HashSet<>();
        for (int val : faceValues) {
            this.faces.add(val);
        }
    }

    public boolean hasFace(int value) {
        return faces.contains(value);
    }
}

/**
 * Logic engine to solve the dice formation problem.
 */
class DiceSolver {

    /**
     * Finds the largest integer X such that all numbers from 1 to X 
     * can be formed using the provided dice.
     */
    public int findMaxFormableNumber(List<Die> dice) {
        int currentNumber = 1;
        while (canForm(currentNumber, dice)) {
            currentNumber++;
        }
        return currentNumber - 1;
    }

    /**
     * Checks if a specific number can be formed by picking unique dice 
     * for each of its digits.
     */
    private boolean canForm(int number, List<Die> dice) {
        List<Integer> digits = getDigits(number);

        // If the number has more digits than available dice, it's impossible.
        if (digits.size() > dice.size()) {
            return false;
        }

        return canAssignDiceToDigits(digits, 0, new boolean[dice.size()], dice);
    }

    /**
     * A backtracking helper to attempt assigning a unique die to each digit.
     */
    private boolean canAssignDiceToDigits(List<Integer> digits, int digitIndex, boolean[] usedDice, List<Die> dice) {
        // Base case: All digits have been successfully assigned to a die.
        if (digitIndex == digits.size()) {
            return true;
        }

        int targetDigit = digits.get(digitIndex);

        for (int i = 0; i < dice.size(); i++) {
            // If this die hasn't been used yet and contains the required digit
            if (!usedDice[i] && dice.get(i).hasFace(targetDigit)) {
                usedDice[i] = true; // Mark die as used

                if (canAssignDiceToDigits(digits, digitIndex + 1, usedDice, dice)) {
                    return true;
                }

                usedDice[i] = false; // Backtrack
            }
        }

        return false;
    }

    private List<Integer> getDigits(int number) {
        List<Integer> digits = new ArrayList<>();
        String s = Integer.toString(number);
        for (char c : s.toCharArray()) {
            digits.add(Character.getNumericValue(c));
        }
        return digits;
    }
}

public class Main {

    public static void main(String[] args) {
        run(System.in, System.out);
    }

    public static void run(InputStream in, PrintStream out) {
        try (Scanner sc = new Scanner(in)) {
            if (!sc.hasNextInt()) {
                return;
            }

            int n = sc.nextInt();
            List<Die> diceList = new ArrayList<>(n);

            for (int i = 0; i < n; i++) {
                int[] faces = new int[6];
                for (int j = 0; j < 6; j++) {
                    faces[j] = sc.nextInt();
                }
                diceList.add(new Die(faces));
            }

            DiceSolver solver = new DiceSolver();
            int result = solver.findMaxFormableNumber(diceList);

            out.print(result);
        } catch (Exception e) {
            // In a production environment, use a logger.
            e.printStackTrace();
        }
    }
}

