/**
 * DigitCombinationSolver finds the largest number X such that all integers 
 * from 0 to X (or starting from 1) are present in the set of numbers 
 * generated from the provided digit sets.
 */
public class DigitCombinationSolver {

    private static final int DIGITS_PER_SET = 6;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int n = reader.nextInt();
            int[][] digitSets = new int[n][DIGITS_PER_SET];

            for (int i = 0; i < n; i++) {
                digitSets[i] = reader.nextIntArray(DIGITS_PER_SET);
            }

            List<Integer> combinedNumbers = generateAllPossibleNumbers(n, digitSets);
            Collections.sort(combinedNumbers);

            int result = findMaxConsecutiveSequence(combinedNumbers);
            writer.println(result);

        } catch (Exception e) {
            // In a real-world application, use a logger.
            // For this context, we ensure the program terminates gracefully.
        } finally {
            writer.close();
        }
    }

    /**
     * Generates all possible numbers by combining digits from the given sets
     * following the specific permutation rules of the original program.
     */
    private static List<Integer> generateAllPossibleNumbers(int n, int[][] sets) {
        List<Integer> combinedNumbers = new ArrayList<>();

        if (n >= 1) {
            int[] a = sets[0];
            for (int i = 0; i < DIGITS_PER_SET; i++) {
                combinedNumbers.add(a[i]);
            }
        }

        if (n >= 2) {
            int[] a = sets[0];
            int[] b = sets[1];
            for (int i = 0; i < DIGITS_PER_SET; i++) {
                combinedNumbers.add(a[i]);
                combinedNumbers.add(b[i]);
                for (int j = 0; j < DIGITS_PER_SET; j++) {
                    combinedNumbers.add(a[i] + 10 * b[j]);
                    combinedNumbers.add(b[i] + 10 * a[j]);
                }
            }
        }

        if (n >= 3) {
            int[] a = sets[0];
            int[] b = sets[1];
            int[] c = sets[2];
            for (int i = 0; i < DIGITS_PER_SET; i++) {
                combinedNumbers.add(a[i]);
                combinedNumbers.add(b[i]);
                combinedNumbers.add(c[i]);
                for (int j = 0; j < DIGITS_PER_SET; j++) {
                    combinedNumbers.add(a[i] + 10 * b[j]);
                    combinedNumbers.add(b[i] + 10 * a[j]);
                    combinedNumbers.add(a[i] + 10 * c[j]);
                    combinedNumbers.add(c[i] + 10 * a[j]);
                    combinedNumbers.add(b[i] + 10 * c[j]);
                    combinedNumbers.add(c[i] + 10 * b[j]);
                    for (int k = 0; k < DIGITS_PER_SET; k++) {
                        combinedNumbers.add(a[i] + 10 * b[j] + 100 * c[k]);
                        combinedNumbers.add(a[i] + 10 * b[k] + 100 * c[j]);
                        combinedNumbers.add(a[j] + 10 * b[i] + 100 * c[k]);
                        combinedNumbers.add(a[j] + 10 * b[k] + 100 * c[i]);
                        combinedNumbers.add(a[k] + 10 * b[i] + 100 * c[j]);
                        combinedNumbers.add(a[k] + 10 * b[j] + 100 * c[i]);
                    }
                }
            }
        }

        return combinedNumbers;
    }

    /**
     * Logic to find the end of the continuous sequence starting from 0 or 1.
     * Mimics the specific behavior of the original algorithm.
     */
    private static int findMaxConsecutiveSequence(List<Integer> sortedNumbers) {
        if (sortedNumbers.isEmpty()) {
            return 0;
        }

        int lastVal = -1;
        for (int i = 0; i < sortedNumbers.size() - 1; i++) {
            if (sortedNumbers.get(i + 1) - sortedNumbers.get(i) > 1) {
                lastVal = sortedNumbers.get(i);
                break;
            }
            lastVal = sortedNumbers.get(i + 1);
        }

        // The original logic returns 0 if the sequence doesn't start with 0 or 1.
        // If the sequence starts with 1, it returns the last element of the sequence.
        boolean startsWithValidDigit = sortedNumbers.get(0) == 0 || sortedNumbers.get(0) == 1;
        if (lastVal != -1 && startsWithValidDigit) {
            return lastVal;
        }
        return 0;
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int pointer = 0;
        private int bytesRead = 0;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() {
            if (pointer >= bytesRead) {
                pointer = 0;
                try {
                    bytesRead = stream.read(buffer);
                } catch (IOException e) {
                    return -1;
                }
                if (bytesRead <= 0) return -1;
            }
            return buffer[pointer++];
        }

        public int nextInt() {
            int c = readByte();
            while (c >= 0 && c <= 32) c = readByte();
            if (c == -1) return -1;
            int neg = 1;
            if (c == '-') {
                neg = -1;
                c = readByte();
            }
            int res = 0;
            while (c > 32) {
                res = res * 10 + (c - '0');
                c = readByte();
            }
            return res * neg;
        }

        public int[] nextIntArray(int n) {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++) {
                arr[i] = nextInt();
            }
            return arr;
        }
    }
}

import java.util.Scanner;
import java.io.PrintWriter;

/**
 * An expert refactoring of the Dice Problem Solver.
 * This program finds the largest integer 'i' such that all integers from 1 to 'i' 
 * can be formed using a given set of dice.
 */
public class Main {

    public static void main(String[] args) {
        // Using try-with-resources to ensure Scanner and PrintWriter are closed automatically
        try (Scanner scanner = new Scanner(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            DiceProblemSolver solver = new DiceProblemSolver();
            writer.println(solver.solve(scanner));
        } catch (Exception e) {
            System.err.println("An error occurred during execution: " + e.getMessage());
        }
    }
}

/**
 * Contains the core logic for solving the dice matching problem.
 */
class DiceProblemSolver {

    /**
     * Reads input from the scanner and initiates the solving process.
     * 
     * @param scanner The input source.
     * @return The maximum consecutive formable number.
     */
    public int solve(Scanner scanner) {
        if (!scanner.hasNextInt()) {
            return 0;
        }

        int numCubes = scanner.nextInt();
        boolean[][] cubeCapabilities = new boolean[numCubes][10];

        // Populate the capability matrix: cubeCapabilities[cubeIndex][digit]
        for (int i = 0; i < numCubes; i++) {
            for (int j = 0; j < 6; j++) {
                if (scanner.hasNextInt()) {
                    int digit = scanner.nextInt();
                    if (digit >= 0 && digit <= 9) {
                        cubeCapabilities[i][digit] = true;
                    }
                }
            }
        }

        return findMaxConsecutiveFormableNumber(numCubes, cubeCapabilities);
    }

    /**
     * Iterates through integers starting from 1 to find the maximum consecutive 
     * number that can be formed.
     * 
     * @param numCubes The total number of dice available.
     * @param cubeCapabilities A boolean matrix indicating which digits each cube can show.
     * @return The largest 'i' such that 1 to 'i' are all formable.
     */
    private int findMaxConsecutiveFormableNumber(int numCubes, boolean[][] cubeCapabilities) {
        int maxFormable = 0;

        // Maintaining the original logic's upper bound for consistency
        int searchLimit = numCubes * 100 - 1;

        for (int i = 1; i <= searchLimit; i++) {
            if (isNumberFormable(i, numCubes, cubeCapabilities)) {
                maxFormable = i;
            } else {
                // The problem asks for the largest 'i' where all numbers up to 'i' are possible.
                // If 'i' cannot be formed, we stop.
                break;
            }
        }
        return maxFormable;
    }

    /**
     * Determines if a specific number can be constructed using the available dice.
     * 
     * @param number The integer to check.
     * @param numCubes Total dice available.
     * @param cubeCapabilities Matrix of cube digit capabilities.
     * @return True if the number can be formed, false otherwise.
     */
    private boolean isNumberFormable(int number, int numCubes, boolean[][] cubeCapabilities) {
        int[] targetDigits = convertNumberToDigitArray(number);

        // If the number requires more dice than we have, it is impossible.
        if (targetDigits.length > numCubes) {
            return false;
        }

        boolean[] usedCubes = new boolean[numCubes];
        return canAssignCubesToDigits(0, targetDigits, usedCubes, cubeCapabilities);
    }

    /**
     * A backtracking helper that attempts to assign a unique die to each digit in the target number.
     * 
     * @param digitIdx The current digit index in the target number we are trying to satisfy.
     * @param targetDigits The array of digits needed.
     * @param usedCubes A tracker for which dice have already been assigned.
     * @param cubeCapabilities Matrix of cube digit capabilities.
     * @return True if a valid assignment is found.
     */
    private boolean canAssignCubesToDigits(int digitIdx, int[] targetDigits, 
                                           boolean[] usedCubes, boolean[][] cubeCapabilities) {
        // Base case: All digits have been successfully matched to a cube
        if (digitIdx == targetDigits.length) {
            return true;
        }

        int neededDigit = targetDigits[digitIdx];

        // Try assigning every available cube to the current digit
        for (int cubeIdx = 0; cubeIdx < usedCubes.length; cubeIdx++) {
            if (!usedCubes[cubeIdx] && cubeCapabilities[cubeIdx][neededDigit]) {
                // Tentatively use this cube
                usedCubes[cubeIdx] = true;

                // Recursively try to satisfy the rest of the digits
                if (canAssignCubesToDigits(digitIdx + 1, targetDigits, usedCubes, cubeCapabilities)) {
                    return true;
                }

                // Backtrack: Unmark the cube to try other combinations
                usedCubes[cubeIdx] = false;
            }
        }

        return false;
    }

    /**
     * Utility to break an integer into its constituent digits.
     * 
     * @param number The integer to decompose.
     * @return An array of integers representing the digits.
     */
    private int[] convertNumberToDigitArray(int number) {
        String s = Integer.toString(number);
        int[] digits = new int[s.length()];
        for (int i = 0; i < s.length(); i++) {
            digits[i] = Character.getNumericValue(s.charAt(i));
        }
        return digits;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * A program to find the largest integer (up to 1000) that can be represented
 * by the faces of a given set of cubes.
 */
public class CubeDigitSolver {

    private static final int MAX_NUMBER_LIMIT = 1000;

    public static void main(String[] args) {
        FastReader reader = new FastReader();

        try {
            int numberOfCubes = reader.nextInt();
            Cube[] cubes = new Cube[numberOfCubes];

            for (int i = 0; i < numberOfCubes; i++) {
                cubes[i] = new Cube(reader);
            }

            int result = solve(cubes);
            System.out.println(result);

        } catch (Exception e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Iterates through numbers to find the highest one that can be formed using the cubes.
     * 
     * @param cubes The available cubes.
     * @return The largest formable number.
     */
    private static int solve(Cube[] cubes) {
        int lastSuccessfulNumber = 0;

        for (int i = 1; i <= MAX_NUMBER_LIMIT; i++) {
            if (canFormNumber(i, cubes)) {
                lastSuccessfulNumber = i;
            } else {
                // Since we are looking for a continuous sequence from 1, 
                // the first number we can't form tells us the limit.
                break;
            }
        }
        return lastSuccessfulNumber;
    }

    /**
     * Determines if a specific number can be formed using the available cubes.
     */
    private static boolean canFormNumber(int number, Cube[] cubes) {
        int[] digits = convertToDigitArray(number);
        return backtrack(digits, 0, cubes, 0);
    }

    /**
     * Recursive backtracking to match digits to available cubes.
     * 
     * @param digits The target digits to match.
     * @param digitIndex The current digit index we are trying to match.
     * @param cubes The available cubes.
     * @param usedMask A bitmask representing which cubes have already been used.
     * @return true if the sequence of digits can be satisfied.
     */
    private static boolean backtrack(int[] digits, int digitIndex, Cube[] cubes, int usedMask) {
        // Base case: All digits have been successfully matched
        if (digitIndex == digits.length) {
            return true;
        }

        int targetDigit = digits[digitIndex];

        for (int i = 0; i < cubes.length; i++) {
            // Check if this cube has already been used in the current recursion path
            boolean isCubeUsed = (usedMask & (1 << i)) != 0;

            if (!isCubeUsed && cubes[i].hasFace(targetDigit)) {
                // Try using this cube and move to the next digit
                if (backtrack(digits, digitIndex + 1, cubes, usedMask | (1 << i))) {
                    return true;
                }
            }
        }

        return false;
    }

    private static int[] convertToDigitArray(int number) {
        String s = Integer.toString(number);
        int[] digits = new int[s.length()];
        for (int i = 0; i < s.length(); i++) {
            digits[i] = s.charAt(i) - '0';
        }
        return digits;
    }

    /**
     * Represents a single cube with 6 numerical faces.
     */
    private static class Cube {
        private final int[] faces = new int[6];

        public Cube(FastReader reader) {
            for (int i = 0; i < faces.length; i++) {
                faces[i] = reader.nextInt();
            }
        }

        public boolean hasFace(int digit) {
            for (int face : faces) {
                if (face == digit) {
                    return true;
                }
            }
            return false;
        }
    }

    /**
     * Utility class for fast I/O operations.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
            this.tokenizer = new StringTokenizer("");
        }

        public String next() {
            while (!tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * DigitSequenceSolver finds the largest integer X such that for every integer i in [1, X],
 * there exists a permutation of given digit sets where the digits of i appear as 
 * a subsequence of allowed digits in those sets.
 */
public class DigitSequenceSolver {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            // Read the number of digit sets
            int numSets = scanner.nextInt();
            if (numSets <= 0) {
                out.println(0);
                return;
            }

            // allowedDigits[setIndex][digit] is true if 'digit' is allowed in that set
            boolean[][] allowedDigits = new boolean[numSets][10];

            for (int i = 0; i < numSets; i++) {
                // Each set contains 6 allowed digits according to problem constraints
                for (int j = 0; j < 6; j++) {
                    int digit = scanner.nextInt();
                    if (digit >= 0 && digit <= 9) {
                        allowedDigits[i][digit] = true;
                    }
                }
            }

            DigitMatcher matcher = new DigitMatcher(numSets, allowedDigits);
            long result = matcher.findLargestContinuousValidNumber();
            out.println(result);

        } catch (IOException | NoSuchElementException e) {
            // In a production environment, use a logger. 
            // For competitive programming, we simply terminate.
        } finally {
            out.close();
        }
    }

    /**
     * Core logic class to determine the validity of numbers based on digit set permutations.
     */
    static class DigitMatcher {
        private final int numSets;
        private final boolean[][] allowedDigits;

        public DigitMatcher(int numSets, boolean[][] allowedDigits) {
            this.numSets = numSets;
            this.allowedDigits = allowedDigits;
        }

        /**
         * Iterates through numbers starting from 1 to find the largest continuous 
         * range of valid numbers.
         */
        public long findLargestContinuousValidNumber() {
            long lastValidNumber = 0;
            long limit = calculateLimit(numSets);

            for (long i = 1; i < limit; i++) {
                if (canMatchWithAnyPermutation(i)) {
                    lastValidNumber = i;
                } else {
                    // The problem requires a continuous sequence from 1 upwards.
                    // If i is invalid, no number > i can satisfy the "continuous" requirement.
                    break;
                }
            }
            return lastValidNumber;
        }

        private long calculateLimit(int n) {
            long limit = 1;
            for (int i = 0; i < n; i++) {
                limit *= 10;
            }
            return limit;
        }

        /**
         * Checks if there is at least one permutation of digit sets that 
         * satisfies the subsequence condition for the given number.
         */
        private boolean canMatchWithAnyPermutation(long number) {
            List<Integer> permutation = new ArrayList<>(numSets);
            for (int i = 0; i < numSets; i++) {
                permutation.add(i);
            }

            // Iterate through all permutations lexicographically
            do {
                if (isSubsequenceMatch(number, permutation)) {
                    return true;
                }
            } while (nextPermutation(permutation));

            return false;
        }

        /**
         * Verifies if the digits of 'number' can be picked as a subsequence 
         * from the allowed digits in the provided set order.
         */
        private boolean isSubsequenceMatch(long number, List<Integer> permutation) {
            String numberStr = Long.toString(number);
            int digitPointer = 0;
            int setPointer = 0;

            while (digitPointer < numberStr.length() && setPointer < numSets) {
                int currentDigit = numberStr.charAt(digitPointer) - '0';
                int currentSetIdx = permutation.get(setPointer);

                if (allowedDigits[currentSetIdx][currentDigit]) {
                    // If the current digit is allowed in this set, move to the next digit
                    digitPointer++;
                }
                // Move to the next set in the permutation regardless
                setPointer++;
            }

            // If we successfully matched all digits of the number
            return digitPointer == numberStr.length();
        }

        /**
         * Standard algorithm to transform a list into its next lexicographical permutation.
         * @return true if a next permutation was found, false if it was the last permutation.
         */
        private boolean nextPermutation(List<Integer> list) {
            int i = list.size() - 2;
            while (i >= 0 && list.get(i) >= list.get(i + 1)) {
                i--;
            }

            if (i < 0) return false;

            int j = list.size() - 1;
            while (list.get(j) <= list.get(i)) {
                j--;
            }

            Collections.swap(list, i, j);
            Collections.reverse(list.subList(i + 1, list.size()));
            return true;
        }
    }

    /**
     * Fast I/O utility for efficient reading of input.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            String token = next();
            if (token == null) throw new NoSuchElementException();
            return Integer.parseInt(token);
        }
    }
}

import java.util.Scanner;
import java.util.Set;
import java.util.HashSet;

/**
 * A refactored solution to find the smallest non-negative integer i 
 * such that i + 1 satisfies specific digit-set exclusion constraints.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        // N represents the number of sets provided (up to 3)
        int n = scanner.nextInt();

        // Initialize sets based on the input count N
        Set<Integer> setA = readSet(scanner, 6, true);
        Set<Integer> setB = readSet(scanner, 6, n >= 2);
        Set<Integer> setC = readSet(scanner, 6, n >= 3);

        int candidate = 1;
        while (true) {
            if (!isInvalid(candidate, setA, setB, setC)) {
                // The problem asks for i-1 where i is the first valid integer found
                System.out.println(candidate - 1);
                break;
            }
            candidate++;
        }

        scanner.close();
    }

    /**
     * Reads up to 'count' integers from the scanner into a Set if the condition is met.
     * 
     * @param scanner The input scanner.
     * @param count   The number of elements to attempt to read.
     * @param shouldRead Whether the set should be populated based on N.
     * @return A set containing the integers read.
     */
    private static Set<Integer> readSet(Scanner scanner, int count, boolean shouldRead) {
        Set<Integer> set = new HashSet<>();
        if (shouldRead) {
            for (int i = 0; i < count; i++) {
                if (scanner.hasNextInt()) {
                    set.add(scanner.nextInt());
                }
            }
        }
        return set;
    }

    /**
     * Checks if the given number violates any of the exclusion rules.
     * 
     * @param i    The number to check.
     * @param setA Set A containing excluded values.
     * @param setB Set B containing excluded values.
     * @param setC Set C containing excluded values.
     * @return true if the number is "invalid" (should be skipped), false otherwise.
     */
    private static boolean isInvalid(int i, Set<Integer> setA, Set<Integer> setB, Set<Integer> setC) {
        // Rule 1: If the number itself is in any of the sets, it is invalid.
        if (setA.contains(i) || setB.contains(i) || setC.contains(i)) {
            return true;
        }

        // Extract digits: d0 is ones, d1 is tens, d2 is hundreds
        int d0 = i % 10;
        int d1 = (i / 10) % 10;
        int d2 = (i / 100) % 10;

        // Rule 2: Two-digit digit-set interaction rules
        // Check if combinations of the last two digits trigger an exclusion
        if (setA.contains(d0) && (setB.contains(d1) || setC.contains(d1))) return true;
        if (setB.contains(d0) && (setA.contains(d1) || setC.contains(d1))) return true;
        if (setC.contains(d0) && (setB.contains(d1) || setA.contains(d1))) return true;

        // Rule 3: Three-digit permutation rules
        // Check if any permutation of the last three digits maps to sets (A, B, C)
        if (hasInvalidThreeDigitPermutation(d0, d1, d2, setA, setB, setC)) {
            return true;
        }

        return false;
    }

    /**
     * Checks if any permutation of the three digits (p, q, r) results in 
     * (p in A, q in B, r in C).
     */
    private static boolean hasInvalidThreeDigitPermutation(int p, int q, int r, 
                                                           Set<Integer> a, Set<Integer> b, Set<Integer> c) {
        return (a.contains(p) && b.contains(q) && c.contains(r)) ||
               (a.contains(p) && b.contains(r) && c.contains(q)) ||
               (a.contains(q) && b.contains(p) && c.contains(r)) ||
               (a.contains(q) && b.contains(r) && c.contains(p)) ||
               (a.contains(r) && b.contains(q) && c.contains(p)) ||
               (a.contains(r) && b.contains(p) && c.contains(q));
    }
}

import java.io.*;
import java.util.*;

/**
 * This program finds the largest integer 'num' such that its digits satisfy
 * specific set-coverage criteria based on an input collection of number sets.
 */
public class Main {

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        String nLine = reader.readLine();
        if (nLine == null || nLine.isEmpty()) {
            return;
        }

        int numberOfSets = Integer.parseInt(nLine.trim());
        if (numberOfSets <= 0) {
            System.out.println(0);
            return;
        }

        // digitToSets[d] stores a BitSet of all set indices that contain the digit 'd'
        BitSet[] digitToSets = new BitSet[10];
        for (int i = 0; i < 10; i++) {
            digitToSets[i] = new BitSet();
        }

        // Parse input sets
        for (int i = 0; i < numberOfSets; i++) {
            String line = reader.readLine();
            if (line == null) break;

            StringTokenizer st = new StringTokenizer(line);
            for (int j = 0; j < 6; j++) {
                if (st.hasMoreTokens()) {
                    int value = Integer.parseInt(st.nextToken());
                    // The logic requires checking if a single digit exists in the set.
                    if (value >= 0 && value <= 9) {
                        digitToSets[value].set(i);
                    }
                }
            }
        }

        // Search for the largest valid number
        int currentNum = 1;
        while (isValid(currentNum, numberOfSets, digitToSets)) {
            currentNum++;
        }

        // The loop terminates when currentNum is no longer valid, 
        // so the answer is the previous number.
        System.out.println(currentNum - 1);
    }

    /**
     * Validates if a number meets the problem's specific digit-to-set coverage criteria.
     * 
     * @param num The number to validate.
     * @param n The total number of sets available.
     * @param digitToSets Pre-calculated BitSet mapping for digits 0-9.
     * @return true if the number meets the criteria, false otherwise.
     */
    private static boolean isValid(int num, int n, BitSet[] digitToSets) {
        int[] digits = extractDigits(num);
        int len = digits.length;

        // Store the BitSet representing which sets contain each digit of the number
        BitSet[] digitPresenceInSets = new BitSet[len];

        for (int i = 0; i < len; i++) {
            BitSet presence = digitToSets[digits[i]];
            if (presence.isEmpty()) {
                return false; // A digit in the number does not exist in any set
            }
            digitPresenceInSets[i] = presence;
        }

        // Criterion for 1-digit numbers
        if (len == 1) {
            return true;
        }

        // Criterion for 2-digit numbers
        if (len == 2) {
            BitSet b0 = digitPresenceInSets[0];
            BitSet b1 = digitPresenceInSets[1];

            // If both digits are found in exactly one set
            if (b0.cardinality() == 1 && b1.cardinality() == 1) {
                // Valid only if they are found in different sets
                return b0.nextSetBit(0) != b1.nextSetBit(0);
            } else {
                // Otherwise, valid if at least one digit is in multiple sets
                return b0.cardinality() > 1 || b1.cardinality() > 1;
            }
        }

        // Criterion for numbers with 3 or more digits
        // Valid if the union of the sets containing these digits covers all n sets
        BitSet union = new BitSet();
        for (BitSet bs : digitPresenceInSets) {
            union.or(bs);
        }
        return union.cardinality() >= n;
    }

    /**
     * Breaks an integer into its constituent digits using mathematical operations.
     * This is more performant than String conversion.
     */
    private static int[] extractDigits(int num) {
        int temp = num;
        int length = 0;

        // Calculate number of digits
        if (temp == 0) return new int[]{0};
        int copy = temp;
        while (copy > 0) {
            copy /= 10;
            length++;
        }

        int[] digits = new int[length];
        for (int i = length - 1; i >= 0; i--) {
            digits[i] = temp % 10;
            temp /= 10;
        }
        return digits;
    }
}

import java.util.Scanner;

/**
 * CubeDigitSolver finds the largest consecutive integer starting from 1 
 * that can be formed using the digits available on a set of cubes.
 */
public class CubeDigitSolver {

    private final int numberOfCubes;
    private final boolean[][] cubeHasDigit;

    /**
     * Constructs a solver with the given cube data.
     *
     * @param numberOfCubes The total number of cubes provided.
     * @param cubeHasDigit  A 2D boolean array where cubeHasDigit[i][d] is true 
     *                      if cube i contains digit d.
     */
    public CubeDigitSolver(int numberOfCubes, boolean[][] cubeHasDigit) {
        this.numberOfCubes = numberOfCubes;
        this.cubeHasDigit = cubeHasDigit;
    }

    /**
     * Entry point of the program. Handles input parsing and outputs the result.
     */
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        int n = scanner.nextInt();
        boolean[][] cubeHasDigit = new boolean[n][10];

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 6; j++) {
                if (scanner.hasNextInt()) {
                    int digit = scanner.nextInt();
                    if (digit >= 0 && digit <= 9) {
                        cubeHasDigit[i][digit] = true;
                    }
                }
            }
        }

        CubeDigitSolver solver = new CubeDigitSolver(n, cubeHasDigit);
        System.out.println(solver.findLargestConsecutiveFormableNumber());

        scanner.close();
    }

    /**
     * Iterates through integers starting from 1 to find the first integer 
     * that cannot be formed by the cubes.
     *
     * @return The largest integer x such that all integers from 1 to x can be formed.
     */
    public int findLargestConsecutiveFormableNumber() {
        int current = 1;
        while (canForm(current, 0)) {
            current++;
        }
        return current - 1;
    }

    /**
     * Recursively checks if a target number can be formed using the available cubes.
     *
     * @param targetNumber   The number we are attempting to form.
     * @param usedCubesMask  A bitmask representing which cubes have already been used.
     * @return true if the number can be formed, false otherwise.
     */
    private boolean canForm(int targetNumber, int usedCubesMask) {
        if (targetNumber == 0) {
            return true;
        }

        // Handle single-digit case
        if (targetNumber < 10) {
            return checkSingleDigit(targetNumber, usedCubesMask);
        }

        // Handle multi-digit case
        return checkMultiDigit(targetNumber, usedCubesMask);
    }

    /**
     * Checks if a single digit can be provided by any unused cube.
     */
    private boolean checkSingleDigit(int digit, int usedCubesMask) {
        for (int i = 0; i < numberOfCubes; i++) {
            if (isCubeAvailable(usedCubesMask, i) && cubeHasDigit[i][digit]) {
                return true;
            }
        }
        return false;
    }

    /**
     * Checks if a multi-digit number can be formed by matching the last digit 
     * and recursing for the remaining digits.
     */
    private boolean checkMultiDigit(int targetNumber, int usedCubesMask) {
        int lastDigit = targetNumber % 10;
        int remainingDigits = targetNumber / 10;

        for (int i = 0; i < numberOfCubes; i++) {
            if (isCubeAvailable(usedCubesMask, i) && cubeHasDigit[i][lastDigit]) {
                // Recurse with the remaining number and update the mask to mark cube 'i' as used
                if (canForm(remainingDigits, usedCubesMask | (1 << i))) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Helper to check if a specific cube is available (not yet used in the bitmask).
     */
    private boolean isCubeAvailable(int mask, int cubeIndex) {
        return (mask & (1 << cubeIndex)) == 0;
    }
}

