/**
 * DigitAssignmentSolver contains the logic to find the largest consecutive 
 * integer (starting from 1) whose digits can be uniquely mapped to a 
 * provided collection of digit sets.
 */
class DigitAssignmentSolver {
    private static final int MAX_NUMBER_TO_CHECK = 999;
    private static final int DIGITS_PER_SET = 6;
    private static final int BASE_10 = 10;

    /**
     * Orchestrates the input reading, processing, and output writing.
     * 
     * @param in  The Scanner providing input data.
     * @param out The PrintWriter for outputting the result.
     */
    public void solve(Scanner in, PrintWriter out) {
        if (!in.hasNextInt()) {
            return;
        }

        int numSets = in.nextInt();
        // digitAvailability[setIndex][digit] is true if the digit exists in that set.
        boolean[][] digitAvailability = new boolean[numSets][BASE_10];

        for (int i = 0; i < numSets; i++) {
            for (int j = 0; j < DIGITS_PER_SET; j++) {
                int digit = in.nextInt();
                // Basic bounds check to prevent ArrayIndexOutOfBoundsException
                if (digit >= 0 && digit < BASE_10) {
                    digitAvailability[i][digit] = true;
                }
            }
        }

        int result = findLargestConsecutiveSatisfyingNumber(numSets, digitAvailability);
        out.println(result);
    }

    /**
     * Iterates through numbers starting from 1 to find the largest number 
     * such that all preceding numbers also satisfy the digit matching condition.
     */
    private int findLargestConsecutiveSatisfyingNumber(int numSets, boolean[][] digitAvailability) {
        int maxConsecutive = 0;
        boolean[] usedSets = new boolean[numSets];

        for (int i = 1; i <= MAX_NUMBER_TO_CHECK; i++) {
            int[] digits = extractDigits(i);

            // Reset the used sets tracking for the current number
            Arrays.fill(usedSets, false);

            if (canAssignDigits(digits, 0, usedSets, digitAvailability)) {
                maxConsecutive = i;
            } else {
                // The original logic terminates at the first number that cannot be formed.
                break;
            }
        }
        return maxConsecutive;
    }

    /**
     * Decomposes an integer into its constituent digits.
     * 
     * @param number The integer to decompose.
     * @return An array of digits.
     */
    private int[] extractDigits(int number) {
        int temp = number;
        int count = 0;
        while (temp > 0) {
            temp /= BASE_10;
            count++;
        }

        int[] digits = new int[count];
        temp = number;
        for (int i = 0; i < count; i++) {
            digits[i] = temp % BASE_10;
            temp /= BASE_10;
        }
        return digits;
    }

    /**
     * A backtracking algorithm to determine if the digits of a number can be 
     * mapped to unique sets.
     * 
     * @param digits            The digits of the number we are trying to match.
     * @param digitIndex        The current index in the digits array.
     * @param usedSets          A boolean array tracking which sets have already been assigned.
     * @param digitAvailability A 2D array containing the presence of digits in sets.
     * @return true if a valid matching exists, false otherwise.
     */
    private boolean canAssignDigits(int[] digits, int digitIndex, boolean[] usedSets, boolean[][] digitAvailability) {
        // Base case: all digits have been successfully assigned to a set
        if (digitIndex == digits.length) {
            return true;
        }

        int currentDigit = digits[digitIndex];

        for (int setIdx = 0; setIdx < usedSets.length; setIdx++) {
            // If this set is available and contains the required digit
            if (!usedSets[setIdx] && digitAvailability[setIdx][currentDigit]) {
                // Choose
                usedSets[setIdx] = true;

                // Explore
                if (canAssignDigits(digits, digitIndex + 1, usedSets, digitAvailability)) {
                    return true;
                }

                // Backtrack (Un-choose)
                usedSets[setIdx] = false;
            }
        }
        return false;
    }
}

import java.util.*;

/**
 * DiceSequenceSolver calculates the maximum integer k such that all integers 
 * from 1 to k can be formed using the faces of n dice.
 * 
 * Rules:
 * - For k < 10: The digit must appear on at least one die.
 * - For k >= 10: The digits of k must appear on two different dice.
 */
public class DiceSequenceSolver {

    private static final int FACES_PER_DIE = 6;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int numDice = scanner.nextInt();
        List<Set<Integer>> dice = readDiceFaces(scanner, numDice);

        int maxK = findMaxSequence(dice);
        System.out.println(maxK);

        scanner.close();
    }

    /**
     * Reads the input and organizes face values into a list of Sets for efficient lookup.
     */
    private static List<Set<Integer>> readDiceFaces(Scanner scanner, int numDice) {
        List<Set<Integer>> dice = new ArrayList<>();

        for (int i = 0; i < numDice; i++) {
            Set<Integer> currentDie = new HashSet<>();
            for (int j = 0; j < FACES_PER_DIE; j++) {
                if (scanner.hasNextInt()) {
                    currentDie.add(scanner.nextInt());
                }
            }
            dice.add(currentDie);
        }
        return dice;
    }

    /**
     * Iterates from 1 upwards to find the first integer that cannot be formed.
     */
    private static int findMaxSequence(List<Set<Integer>> dice) {
        int k = 1;
        while (canFormNumber(k, dice)) {
            k++;
        }
        return k - 1;
    }

    /**
     * Checks if the number k can be formed based on the dice faces.
     */
    private static boolean canFormNumber(int k, List<Set<Integer>> dice) {
        if (k < 10) {
            return containsDigitInAnyDie(k, dice);
        } else {
            int tensDigit = k / 10;
            int unitsDigit = k % 10;
            return containsDigitsOnDifferentDice(tensDigit, unitsDigit, dice);
        }
    }

    /**
     * Logic for single digit numbers: must exist on any one die.
     */
    private static boolean containsDigitInAnyDie(int digit, List<Set<Integer>> dice) {
        for (Set<Integer> die : dice) {
            if (die.contains(digit)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Logic for two digit numbers: digits must be on two distinct dice.
     */
    private static boolean containsDigitsOnDifferentDice(int d1, int d2, List<Set<Integer>> dice) {
        int numDice = dice.size();
        for (int i = 0; i < numDice; i++) {
            for (int j = 0; j < numDice; j++) {
                // Ensure we are looking at two different dice
                if (i != j) {
                    if (dice.get(i).contains(d1) && dice.get(j).contains(d2)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }
}

import java.io.*;
import java.util.*;

/**
 * This program finds the largest integer X such that all integers from 1 to X 
 * can be formed by selecting one number from each of a subset of N given sets 
 * and concatenating them in some order.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            NumberSequenceSolver solver = new NumberSequenceSolver();
            solver.solve(reader, writer);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Core logic for solving the sequence problem.
     */
    static class NumberSequenceSolver {

        /**
         * Orchestrates the input reading, number generation, and result output.
         *
         * @param in  The utility for fast input reading.
         * @param out The utility for efficient output writing.
         */
        public void solve(FastReader in, PrintWriter out) {
            int n = in.nextInt();
            if (n <= 0) {
                out.println(0);
                return;
            }

            // Each set contains 6 integers.
            int[][] digitSets = new int[n][6];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < 6; j++) {
                    digitSets[i][j] = in.nextInt();
                }
            }

            Set<Integer> possibleNumbers = new HashSet<>();
            generateAllPossibleNumbers(digitSets, 0, 0, possibleNumbers);

            int maxContinuousInteger = 0;
            // The original requirement checks for continuity up to 999.
            for (int i = 1; i <= 999; i++) {
                if (possibleNumbers.contains(i)) {
                    maxContinuousInteger = i;
                } else {
                    break;
                }
            }

            out.println(maxContinuousInteger);
        }

        /**
         * Recursively generates all numbers that can be formed by picking elements 
         * from a permutation of a subset of the provided digit sets.
         *
         * @param digitSets       The array of available integer sets.
         * @param usedMask        Bitmask representing which sets have already been used.
         * @param currentVal      The integer value constructed so far.
         * @param results         The set where all discovered numbers are stored.
         */
        private void generateAllPossibleNumbers(int[][] digitSets, int usedMask, int currentVal, Set<Integer> results) {
            // If a valid number has been formed, add it to the results set.
            if (currentVal > 0) {
                results.add(currentVal);
            }

            // Optimization: Since we only care about numbers up to 999, 
            // we stop recursing if the current value exceeds this threshold.
            if (currentVal >= 1000) {
                return;
            }

            int n = digitSets.length;
            for (int i = 0; i < n; i++) {
                // If the i-th set has not been used in this specific number construction
                if ((usedMask & (1 << i)) == 0) {
                    for (int digit : digitSets[i]) {
                        // Construct the new number: (current * 10) + new_digit
                        int nextVal = currentVal * 10 + digit;
                        generateAllPossibleNumbers(digitSets, usedMask | (1 << i), nextVal, results);
                    }
                }
            }
        }
    }

    /**
     * Fast I/O utility to handle input more efficiently than a standard Scanner.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input stream", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String token = next();
            return token == null ? 0 : Integer.parseInt(token);
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.StringTokenizer;

/**
 * Refactored solution for the "Cube of Masha" problem.
 * 
 * The problem seeks to find the largest integer X such that every integer 
 * from 1 to X can be "formed" using digits from n provided sets (cubes). 
 * To form a number, each of its digits must be assigned to a unique cube 
 * that contains that digit.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        MashaCubeSolver solver = new MashaCubeSolver();
        solver.solve(reader, out);

        out.flush();
        out.close();
    }

    /**
     * Encapsulates the logic for solving the problem.
     */
    static class MashaCubeSolver {

        /**
         * Reads input data and executes the solving algorithm.
         * 
         * @param in  The fast reader for input.
         * @param out The print writer for output.
         */
        public void solve(FastReader in, PrintWriter out) {
            Integer n = in.nextInt();
            if (n == null) return;

            // Each cube is represented as a Set of available digits for O(1) lookup.
            @SuppressWarnings("unchecked")
            Set<Integer>[] cubes = new HashSet[n];
            for (int i = 0; i < n; i++) {
                cubes[i] = new HashSet<>();
                for (int j = 0; j < 6; j++) {
                    Integer digit = in.nextInt();
                    if (digit != null) {
                        cubes[i].add(digit);
                    }
                }
            }

            int firstUnformable = 0;

            /*
             * The original logic iterates from 1 up to 10^n to find the first integer
             * that cannot be formed by the cubes. The answer is then that integer minus 1.
             * This is equivalent to finding the largest X such that all numbers 1..X are formable.
             */
            long limit = (long) Math.pow(10, n);
            for (int i = 1; i < limit; i++) {
                if (!canForm(i, cubes)) {
                    firstUnformable = i;
                    break;
                }
            }

            out.println(firstUnformable - 1);
        }

        /**
         * Checks if a specific number can be formed using digits from the given cubes.
         * 
         * @param number The number to verify.
         * @param cubes   The collection of cubes available.
         * @return true if the number can be formed by assigning digits to distinct cubes.
         */
        private boolean canForm(int number, Set<Integer>[] cubes) {
            List<Integer> digits = getDigits(number);

            // A number cannot be formed if it has more digits than available cubes.
            if (digits.size() > cubes.length) {
                return false;
            }

            // Use backtracking to find a valid assignment of digits to unique cubes.
            return backtrack(digits, 0, cubes, new boolean[cubes.length]);
        }

        /**
         * Decomposes an integer into a list of its individual digits.
         * 
         * @param number The integer to decompose.
         * @return A list containing the digits of the number.
         */
        private List<Integer> getDigits(int number) {
            List<Integer> digits = new ArrayList<>();
            int temp = number;
            while (temp > 0) {
                digits.add(temp % 10);
                temp /= 10;
            }
            return digits;
        }

        /**
         * A backtracking helper method to solve the assignment problem (bipartite matching).
         * 
         * @param digits      The list of digits extracted from the number.
         * @param digitIndex  The index of the digit currently being assigned.
         * @param cubes       The available cubes.
         * @param usedCubes   A tracking array to ensure each cube is only used once per number.
         * @return true if a valid assignment exists for all digits.
         */
        private boolean backtrack(List<Integer> digits, int digitIndex, Set<Integer>[] cubes, boolean[] usedCubes) {
            // Base case: all digits have been successfully assigned to a unique cube.
            if (digitIndex == digits.size()) {
                return true;
            }

            int currentDigit = digits.get(digitIndex);
            for (int i = 0; i < cubes.length; i++) {
                // Try assigning the current digit to an unused cube that contains it.
                if (!usedCubes[i] && cubes[i].contains(currentDigit)) {
                    usedCubes[i] = true;

                    // Recurse to assign the next digit.
                    if (backtrack(digits, digitIndex + 1, cubes, usedCubes)) {
                        return true;
                    }

                    // If assignment doesn't work, backtrack by unmarking the cube.
                    usedCubes[i] = false;
                }
            }
            return false;
        }
    }

    /**
     * An efficient input reader using BufferedReader and StringTokenizer.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        /**
         * Fetches the next token from the input stream.
         * 
         * @return The next token, or null if end of stream is reached.
         */
        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        /**
         * Parses the next token as an integer.
         * 
         * @return The parsed integer, or null if no token is available.
         */
        public Integer nextInt() {
            String s = next();
            if (s == null) return null;
            try {
                return Integer.parseInt(s);
            } catch (NumberFormatException e) {
                return null;
            }
        }
    }
}

import java.util.*;

/**
 * A program to solve a maze puzzle by finding how many unique direction mappings 
 * (assigning Up, Down, Left, Right to commands 0, 1, 2, 3) 
 * allow a robot to reach the exit 'E' from start 'S'.
 */
public class Solution {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) {
            return;
        }

        int rows = sc.nextInt();
        int cols = sc.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = sc.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        String commands = sc.hasNext() ? sc.next() : "";
        sc.close();

        MazeSolver solver = new MazeSolver(rows, cols, grid, commands);
        System.out.println(solver.countSuccessfulPermutations());
    }

    /**
     * Represents the four cardinal directions and their coordinate offsets.
     */
    private enum Direction {
        UP(-1, 0),
        DOWN(1, 0),
        LEFT(0, -1),
        RIGHT(0, 1);

        final int rowOffset;
        final int colOffset;

        Direction(int rowOffset, int colOffset) {
            this.rowOffset = rowOffset;
            this.colOffset = colOffset;
        }
    }

    private static class MazeSolver {
        private static final char START = 'S';
        private static final char END = 'E';
        private static final char WALL = '#';

        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final String commands;
        private final int startRow;
        private final int startCol;

        public MazeSolver(int rows, int cols, char[][] grid, String commands) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.commands = commands;

            // Find starting position during initialization
            int[] startPos = findPosition(START);
            this.startRow = startPos[0];
            this.startCol = startPos[1];
        }

        /**
         * Scans the grid to find the coordinates of a specific character.
         */
        private int[] findPosition(char target) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == target) {
                        return new int[]{r, c};
                    }
                }
            }
            return new int[]{-1, -1};
        }

        /**
         * Orchestrates the permutation generation and simulation.
         */
        public int countSuccessfulPermutations() {
            List<List<Direction>> allPermutations = new ArrayList<>();
            generatePermutations(Direction.values(), 0, allPermutations);

            int successCount = 0;
            for (List<Direction> mapping : allPermutations) {
                if (simulate(mapping)) {
                    successCount++;
                }
            }
            return successCount;
        }

        /**
         * Standard recursive algorithm to generate all permutations of directions.
         */
        private void generatePermutations(Direction[] directions, int index, List<List<Direction>> result) {
            if (index == directions.length) {
                result.add(Arrays.asList(directions.clone()));
                return;
            }

            for (int i = index; i < directions.length; i++) {
                swap(directions, index, i);
                generatePermutations(directions, index + 1, result);
                swap(directions, index, i); // backtrack
            }
        }

        private void swap(Direction[] arr, int i, int j) {
            Direction temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }

        /**
         * Simulates the robot's movement based on a specific command-to-direction mapping.
         * @param directionMapping A list where index i represents the direction for command 'i'.
         * @return true if the robot reaches 'E', false if it hits a wall, boundary, or ends without reaching 'E'.
         */
        private boolean simulate(List<Direction> directionMapping) {
            int currentRow = startRow;
            int currentCol = startCol;

            for (int i = 0; i < commands.length(); i++) {
                int commandIdx = Character.getNumericValue(commands.charAt(i));

                // Bounds check for command index safety
                if (commandIdx < 0 || commandIdx >= 4) return false;

                Direction dir = directionMapping.get(commandIdx);
                currentRow += dir.rowOffset;
                currentCol += dir.colOffset;

                // Check for invalid movements
                if (isOutOfBounds(currentRow, currentCol) || grid[currentRow][currentCol] == WALL) {
                    return false;
                }

                // Check for success
                if (grid[currentRow][currentCol] == END) {
                    return true;
                }
            }
            return false;
        }

        private boolean isOutOfBounds(int r, int c) {
            return r < 0 || r >= rows || c < 0 || c >= cols;
        }
    }
}

import java.util.Scanner;

/**
 * GridNavigator simulates a pathfinding game on a grid where a sequence of commands
 * determines movement. It calculates how many digit-to-direction mappings allow 
 * a traveler to reach an end point 'E' from a start point 'S'.
 */
public class GridNavigator {

    private int rows;
    private int cols;
    private char[][] grid;
    private String commands;

    private int startRow;
    private int startCol;
    private int endRow;
    private int endCol;

    public static void main(String[] args) {
        GridNavigator navigator = new GridNavigator();
        navigator.run();
    }

    /**
     * Orchestrates the execution of the program.
     */
    public void run() {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        // Parse grid dimensions
        rows = scanner.nextInt();
        cols = scanner.nextInt();

        // Parse grid and locate Start (S) and End (E) positions
        grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String rowString = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = rowString.charAt(j);
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                } else if (grid[i][j] == 'E') {
                    endRow = i;
                    endCol = j;
                }
            }
        }

        // Parse the movement command sequence
        if (scanner.hasNext()) {
            commands = scanner.next();
        } else {
            commands = "";
        }

        int successfulMappings = solve();
        System.out.println(successfulMappings);

        scanner.close();
    }

    /**
     * Iterates through all possible permutations of digit-to-direction mappings.
     * There are 4! (24) ways to map digits 0-3 to the four cardinal directions.
     * 
     * @return The number of valid mappings that reach the destination.
     */
    private int solve() {
        int successfulMappings = 0;

        // We try all permutations of the digits {0, 1, 2, 3}
        // Each digit in the permutation represents a movement:
        // i: Row Increment, j: Row Decrement, k: Column Increment, l: Column Decrement
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                if (j == i) continue;
                for (int k = 0; k < 4; k++) {
                    if (k == i || k == j) continue;
                    for (int l = 0; l < 4; l++) {
                        if (l == i || l == j || l == k) continue;

                        if (canReachTarget(i, j, k, l)) {
                            successfulMappings++;
                        }
                    }
                }
            }
        }

        return successfulMappings;
    }

    /**
     * Simulates the movement based on a specific mapping of digits to directions.
     *
     * @param rowIncDigit Digit that increments the row index.
     * @param rowDecDigit Digit that decrements the row index.
     * @param colIncDigit Digit that increments the column index.
     * @param colDecDigit Digit that decrements the column index.
     * @return true if the target 'E' is reached, false otherwise.
     */
    private boolean canReachTarget(int rowIncDigit, int rowDecDigit, int colIncDigit, int colDecDigit) {
        int currentRow = startRow;
        int currentCol = startCol;

        for (int i = 0; i < commands.length(); i++) {
            // Check if we have already reached the target
            if (currentRow == endRow && currentCol == endCol) {
                return true;
            }

            // If current position is out of bounds or a wall, the path is invalid
            if (!isWithinBounds(currentRow, currentCol) || grid[currentRow][currentCol] == '#') {
                return false;
            }

            int commandDigit = commands.charAt(i) - '0';

            if (commandDigit == rowIncDigit) {
                currentRow++;
            } else if (commandDigit == rowDecDigit) {
                currentRow--;
            } else if (commandDigit == colIncDigit) {
                currentCol++;
            } else if (commandDigit == colDecDigit) {
                currentCol--;
            }
        }

        // Final check after the last command is executed
        return currentRow == endRow && currentCol == endCol;
    }

    /**
     * Validates if the given coordinates are within the grid boundaries.
     */
    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

