/**
 * Handles the logic for generating permutations and simulating movement.
 */
class PathfindingSolver {
    private final char[][] grid;
    private final int rows;
    private final int cols;
    private final Position start;
    private final Position end;
    private final int[] commands;

    // Directional offsets: 0:Left, 1:Right, 2:Up, 3:Down
    private final int[] dr = {0, 0, -1, 1};
    private final int[] dc = {-1, 1, 0, 0};

    private int successfulMappingsCount = 0;

    public PathfindingSolver(char[][] grid, Position start, Position end, int[] commands) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
        this.start = start;
        this.end = end;
        this.commands = commands;
    }

    /**
     * Main entry point for the solver.
     * @return Number of permutations that reach the end.
     */
    public int solve() {
        int[] mapping = new int[4]; // maps digit (0-3) to direction index (0-3)
        boolean[] usedDirections = new boolean[4];
        generateMappings(0, mapping, usedDirections);
        return successfulMappingsCount;
    }

    /**
     * Backtracking algorithm to generate all 4! permutations of the 4 possible directions.
     */
    private void generateMappings(int digit, int[] mapping, boolean[] usedDirections) {
        if (digit == 4) {
            if (canReachEnd(mapping)) {
                successfulMappingsCount++;
            }
            return;
        }

        for (int i = 0; i < 4; i++) {
            if (!usedDirections[i]) {
                usedDirections[i] = true;
                mapping[digit] = i;
                generateMappings(digit + 1, mapping, usedDirections);
                usedDirections[i] = false;
            }
        }
    }

    /**
     * Simulates the robot's path given a specific digit-to-direction mapping.
     */
    private boolean canReachEnd(int[] mapping) {
        int currentR = start.getRow();
        int currentC = start.getCol();

        // If starting position is the end position
        if (currentR == end.getRow() && currentC == end.getCol()) {
            return true;
        }

        for (int cmdDigit : commands) {
            int directionIndex = mapping[cmdDigit];
            currentR += dr[directionIndex];
            currentC += dc[directionIndex];

            // Check boundaries and obstacles
            if (isOutOfBounds(currentR, currentC) || isWall(currentR, currentC)) {
                return false;
            }

            // Check if destination is reached
            if (currentR == end.getRow() && currentC == end.getCol()) {
                return true;
            }
        }

        return false;
    }

    private boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }

    private boolean isWall(int r, int c) {
        return grid[r][c] == '#';
    }
}

