/**
 * Represents movement directions and their coordinate offsets.
 */
enum Direction {
    UP(-1, 0), DOWN(1, 0), LEFT(0, -1), RIGHT(0, 1);

    private final int rowOffset;
    private final int colOffset;

    Direction(int rowOffset, int colOffset) {
        this.rowOffset = rowOffset;
        this.colOffset = colOffset;
    }

    public Coordinate move(Coordinate current) {
        return new Coordinate(current.getRow() + rowOffset, current.getCol() + colOffset);
    }

    /**
     * Maps a character key to a Direction.
     */
    public static Direction fromKey(char key) {
        return switch (key) {
            case 'w' -> UP;
            case 's' -> DOWN;
            case 'a' -> LEFT;
            case 'd' -> RIGHT;
            default -> throw new IllegalArgumentException("Invalid key: " + key);
        };
    }
}

/**
 * Represents the maze structure and handles boundary/obstacle checks.
 */
class Maze {
    private final char[][] grid;
    private final int rows;
    private final int cols;
    private final Coordinate start;
    private final Coordinate end;

    public Maze(char[][] grid, int rows, int cols) {
        this.grid = grid;
        this.rows = rows;
        this.cols = cols;

        Coordinate tempStart = null;
        Coordinate tempEnd = null;

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'S') tempStart = new Coordinate(i, j);
                else if (grid[i][j] == 'E') tempEnd = new Coordinate(i, j);
            }
        }
        this.start = tempStart;
        this.end = tempEnd;
    }

    public Coordinate getStart() { return start; }
    public boolean isExit(Coordinate coord) { return coord.equals(end); }

    public boolean isValidMove(Coordinate coord) {
        int r = coord.getRow();
        int c = coord.getCol();
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != '#';
    }
}

/**
 * Utility for generating lexicographical permutations.
 */
class PermutationUtils {
    /**
     * Generates the next lexicographical permutation of the array in-place.
     * @return true if a next permutation exists, false otherwise.
     */
    public static boolean nextPermutation(char[] array) {
        int i = array.length - 2;
        while (i >= 0 && array[i] >= array[i + 1]) {
            i--;
        }

        if (i < 0) return false;

        int j = array.length - 1;
        while (array[j] <= array[i]) {
            j--;
        }

        swap(array, i, j);
        reverse(array, i + 1, array.length - 1);
        return true;
    }

    private static void swap(char[] array, int i, int j) {
        char temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }

    private static void reverse(char[] array, int start, int end) {
        while (start < end) {
            swap(array, start++, end--);
        }
    }
}

/**
 * Orchestrates the maze solving process.
 */
class MazeSolver {
    private final Maze maze;
    private final int[] instructionSequence;
    private final char[] directionKeys = {'a', 'd', 's', 'w'};

    public MazeSolver(Maze maze, int[] instructionSequence) {
        this.maze = maze;
        this.instructionSequence = instructionSequence;
    }

    public int countSuccessfulPermutations() {
        int successCount = 0;
        // We use a copy to avoid mutating the original keys if needed elsewhere
        char[] currentMapping = directionKeys.clone();

        // Sort to ensure we start from the first lexicographical permutation
        Arrays.sort(currentMapping);

        do {
            if (tryPath(currentMapping)) {
                successCount++;
            }
        } while (PermutationUtils.nextPermutation(currentMapping));

        return successCount;
    }

    private boolean tryPath(char[] mapping) {
        Coordinate currentPos = maze.getStart();

        for (int cmdIdx : instructionSequence) {
            char key = mapping[cmdIdx];
            Direction direction = Direction.fromKey(key);
            currentPos = direction.move(currentPos);

            if (!maze.isValidMove(currentPos)) {
                return false;
            }

            if (maze.isExit(currentPos)) {
                return true;
            }
        }
        return false;
    }
}

