        for (int i = 0; i < instructionStr.length(); i++) {
            instructions[i] = Character.getNumericValue(instructionStr.charAt(i));
        }

        Maze maze = new Maze(grid, rows, cols);
        MazeSolver solver = new MazeSolver(maze, instructions);

        System.out.println(solver.countSuccessfulPermutations());

        scanner.close();
    }
}

