/**
 * A simulation to determine how many digit-mapping permutations 
 * allow a path from a starting point to an end point in a grid.
 */
public class MazeSimulation {

    private static final char START_CHAR = 'S';
    private static final char END_CHAR = 'E';
    private static final char WALL_CHAR = '#';
    private static final int[][] DIRECTIONS = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
    private static final int DIGIT_COUNT = 4;

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];

        Point startPos = null;
        Point endPos = null;

        // Parse grid and locate Start and End positions in one pass
        for (int r = 0; r < rows; r++) {
            String line = scanner.next();
            grid[r] = line.toCharArray();
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == START_CHAR) {
                    startPos = new Point(r, c);
                } else if (grid[r][c] == END_CHAR) {
                    endPos = new Point(r, c);
                }
            }
        }

        String instructionString = scanner.next();

        // Generate all possible permutations of {0, 1, 2, 3}
        List<int[]> permutations = new ArrayList<>();
        generatePermutations(new int[]{0, 1, 2, 3}, 0, permutations);

        int successfulPaths = 0;
        for (int[] mapping : permutations) {
            if (simulatePath(instructionString, mapping, startPos, endPos, grid, rows, cols)) {
                successfulPaths++;
            }
        }

        System.out.println(successfulPaths);
    }

    /**
     * Simulates the movement through the maze based on a specific digit mapping.
     * 
     * @return true if the path reaches the end point without hitting a wall or boundary.
     */
    private static boolean simulatePath(String instructions, int[] mapping, Point start, Point end, 
                                        char[][] grid, int rows, int cols) {
        int currentRow = start.row;
        int currentCol = start.col;

        for (char ch : instructions.toCharArray()) {
            int originalDigit = ch - '0';
            int moveIdx = mapping[originalDigit];

            currentRow += DIRECTIONS[moveIdx][0];
            currentCol += DIRECTIONS[moveIdx][1];

            // Boundary Check
            if (currentRow < 0 || currentRow >= rows || currentCol < 0 || currentCol >= cols) {
                return false;
            }

            // Obstacle Check
            if (grid[currentRow][currentCol] == WALL_CHAR) {
                return false;
            }

            // Success Check
            if (grid[currentRow][currentCol] == END_CHAR) {
                return true;
            }
        }

        return false;
    }

    /**
     * Generates all permutations of the input array using backtracking.
     */
    private static void generatePermutations(int[] arr, int index, List<int[]> result) {
        if (index == arr.length) {
            result.add(arr.clone());
            return;
        }

        for (int i = index; i < arr.length; i++) {
            swap(arr, index, i);
            generatePermutations(arr, index + 1, result);
            swap(arr, index, i); // Backtrack
        }
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Optimized scanner for fast input reading.
     */
    public static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            this(new InputStreamReader(System.in));
        }

        public FastScanner(Reader in) {
            br = new BufferedReader(in);
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

