    public Grid(int rows, int cols, char[][] cells) {
        this.rows = rows;
        this.cols = cols;
        this.cells = cells;
        findStart();
    }

    private void findStart() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (cells[r][c] == START_CHAR) {
                    this.startRow = r;
                    this.startCol = c;
                    return;
                }
            }
        }
    }

    public int getRows() { return rows; }
    public int getCols() { return cols; }
    public int getStartRow() { return startRow; }
    public int getStartCol() { return startCol; }

    public boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public char getCell(int r, int c) {
        return cells[r][c];
    }

    public boolean isWall(int r, int c) {
        return cells[r][c] == WALL_CHAR;
    }

    public boolean isEnd(int r, int c) {
        return cells[r][c] == END_CHAR;
    }
}

/**
 * Handles the movement logic and permutation testing.
 */
class PathSimulator {
    // Mapping indices to directional movement (dr, dc)
    // 0: Up, 1: Down, 2: Right, 3: Left
    private static final int[][] DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, 1}, {0, -1}
    };

    /**
     * Simulates the path for a specific permutation of direction mappings.
     * 
     * @param grid The grid environment.
     * @param instructions The sequence of digit-based instructions.
     * @param mapping A permutation array where mapping[digit] = directionIndex.
     * @return true if the end is reached successfully.
     */
    public boolean simulate(Grid grid, int[] instructions, int[] mapping) {
        int currentRow = grid.getStartRow();
        int currentCol = grid.getStartCol();

        for (int instructionDigit : instructions) {
            int directionIdx = mapping[instructionDigit];
            currentRow += DIRECTIONS[directionIdx][0];
            currentCol += DIRECTIONS[directionIdx][1];

            if (!grid.isWithinBounds(currentRow, currentCol) || grid.isWall(currentRow, currentCol)) {
                return false;
            }

            if (grid.isEnd(currentRow, currentCol)) {
                return true;
            }
        }

        return false;
    }

    /**
     * Calculates how many permutations of direction mappings lead to the exit.
     */
    public int countSuccessfulPaths(Grid grid, int[] instructions) {
        int successfulPaths = 0;
        int[] permutation = new int[4];

        // We need to check all permutations of {0, 1, 2, 3}
        // Using nested loops to represent all possible unique assignments of directions to digits
        for (int a = 0; a < 4; a++) {
            for (int b = 0; b < 4; b++) {
                if (b == a) continue;
                for (int c = 0; c < 4; c++) {
                    if (c == a || c == b) continue;
                    for (int d = 0; d < 4; d++) {
                        if (d == a || d == b || d == c) continue;

                        permutation[0] = a;
                        permutation[1] = b;
                        permutation[2] = c;
                        permutation[3] = d;

                        if (simulate(grid, instructions, permutation)) {
                            successfulPaths++;
                        }
                    }
                }
            }
        }
        return successfulPaths;
    }
}

