/**
 * A program to calculate how many permutations of direction mappings 
 * allow a path from a starting point 'S' to an end point 'E' in a grid.
 */
public class MazeNavigator {

    public static void main(String[] args) {
        try {
            FastScanner scanner = new FastScanner(System.in);

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            Maze maze = new Maze(rows, cols, scanner);
