        }
    }

    /**
     * Represents the game grid, including boundaries, obstacles, and start/end points.
     */
    static class Maze {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private int startRow, startCol;
        private int endRow, endCol;

        public Maze(int rows, int cols, FastScanner scanner) throws IOException {
            this.rows = rows;
            this.cols = cols;
            this.grid = new char[rows][cols];
            parseGrid(scanner);
        }

        private void parseGrid(FastScanner scanner) throws IOException {
            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                    } else if (grid[i][j] == 'E') {
                        endRow = i;
                        endCol = j;
                    }
                }
            }
        }

        public boolean isValidMove(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != '#';
        }

        public boolean isEnd(int r, int c) {
            return grid[r][c] == 'E';
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }
        public int getStartRow() { return startRow; }
        public int getStartCol() { return startCol; }
        public int getEndRow() { return endRow; }
        public int getEndCol() { return endCol; }
    }

    /**
     * Handles the logic of simulating paths using direction permutations.
     */
    static class PathSimulator {
        // Direction vectors matching the original logic:
        // 0: Left (-1, 0), 1: Right (1, 0), 2: Up (0, -1), 3: Down (0, 1)
        private static final int[] DX = {-1, 1, 0, 0};
        private static final int[] DY = {0, 0, -1, 1};

        private final Maze maze;

        public PathSimulator(Maze maze) {
            this.maze = maze;
        }

        /**
         * Iterates through all 4! permutations of direction mappings.
         */
        public int countSuccessfulPermutations(String instructions) {
            int[] permutation = new int[4];
            boolean[] used = new boolean[4];
            return backtrackPermutations(instructions, permutation, used, 0);
        }

        private int backtrackPermutations(String instructions, int[] perm, boolean[] used, int depth) {
            if (depth == 4) {
                return simulatePath(instructions, perm) ? 1 : 0;
            }

            int count = 0;
            for (int i = 0; i < 4; i++) {
                if (!used[i]) {
                    used[i] = true;
                    perm[depth] = i;
                    count += backtrackPermutations(instructions, perm, used, depth + 1);
                    used[i] = false;
                }
            }
            return count;
        }

        private boolean simulatePath(String instructions, int[] perm) {
            int curR = maze.getStartRow();
            int curC = maze.getStartCol();

            for (int i = 0; i < instructions.length(); i++) {
                // Map the instruction digit to a specific direction in the permutation
                int directionIdx = perm[instructions.charAt(i) - '0'];

                int nextC = curC + DX[directionIdx];
                int nextR = curR + DY[directionIdx];

                if (maze.isValidMove(nextR, nextC)) {
                    curR = nextR;
                    curC = nextC;
                    // If we hit the end point during the sequence, it's a success
                    if (maze.isEnd(curR, curC)) {
                        return true;
                    }
                } else {
                    // Hit a wall or boundary
                    return false;
                }
            }

            // Check if final position is the end point
            return curR == maze.getEndRow() && curC == maze.getEndCol();
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * A simulator that calculates how many digit permutations allow a player 
 * to navigate a maze from a starting point 'S' to an exit 'E'.
 */
public class MazeSimulator {

    // All 24 permutations of the digits 0, 1, 2, 3.
    private static final String[] PERMUTATIONS = {
            "1230", "1203", "1320", "1302", "1023", "1032",
            "2130", "2103", "2310", "2301", "2013", "2031",
            "3210", "3201", "3120", "3102", "3021", "3012",
            "0231", "0213", "0321", "0312", "0123", "0132"
    };

    /**
     * Represents the possible directions of movement.
     * The index in the permutation maps to these directions:
     * 0: UP, 1: LEFT, 2: RIGHT, 3: DOWN
     */
    enum Direction {
        UP(-1, 0),
        LEFT(0, -1),
        RIGHT(0, 1),
        DOWN(1, 0);

        final int deltaRow;
        final int deltaCol;

        Direction(int deltaRow, int deltaCol) {
            this.deltaRow = deltaRow;
            this.deltaCol = deltaCol;
        }
    }

    /**
     * Represents a coordinate on the grid.
     */
    static class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }

        Position move(Direction direction) {
            return new Position(this.row + direction.deltaRow, this.col + direction.deltaCol);
        }
    }

    /**
     * Represents the maze grid and provides boundary/collision logic.
     */
    static class Maze {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private Position startPosition;

        Maze(int rows, int cols, Scanner scanner) {
            this.rows = rows;
            this.cols = cols;
            this.grid = new char[rows][cols];
            parseGrid(scanner);
        }

        private void parseGrid(Scanner scanner) {
            for (int r = 0; r < rows; r++) {
                String rowString = scanner.next();
                for (int c = 0; c < cols; c++) {
                    grid[r][c] = rowString.charAt(c);
                    if (grid[r][c] == 'S') {
                        startPosition = new Position(r, c);
                    }
                }
            }
        }

        public boolean isWithinBounds(Position pos) {
            return pos.row >= 0 && pos.row < rows && pos.col >= 0 && pos.col < cols;
        }

        public char getCell(Position pos) {
            return grid[pos.row][pos.col];
        }

        public Position getStartPosition() {
            return startPosition;
        }
    }

    /**
     * Handles the execution of the simulation trials.
     */
    static class SimulationEngine {
        private final Maze maze;

        SimulationEngine(Maze maze) {
            this.maze = maze;
        }

        public int runAllPermutations(String commands) {
            int successCount = 0;
            for (String permutation : PERMUTATIONS) {
                if (simulatePath(permutation, commands)) {
                    successCount++;
                }
            }
            return successCount;
        }

        private boolean simulatePath(String permutation, String commands) {
            Position currentPos = maze.getStartPosition();

            for (char cmdChar : commands.toCharArray()) {
                // Find which direction the current command maps to in this permutation
                int directionIndex = permutation.indexOf(cmdChar);

                // If the command character isn't in the permutation, skip it
                if (directionIndex == -1) {
                    continue;
                }

                Direction direction = Direction.values()[directionIndex];
                currentPos = currentPos.move(direction);

                // Check for failure conditions
                if (!maze.isWithinBounds(currentPos) || maze.getCell(currentPos) == '#') {
                    return false;
                }

                // Check for success condition
                if (maze.getCell(currentPos) == 'E') {
                    return true;
                }
            }
            return false;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        Maze maze = new Maze(rows, cols, scanner);
        String commandSequence = scanner.next();

        SimulationEngine engine = new SimulationEngine(maze);
        int successfulPaths = engine.runAllPermutations(commandSequence);

        System.out.println(successfulPaths);
        scanner.close();
    }
}

import java.util.Scanner;

/**
 * A solver for the maze path permutation problem.
 * The goal is to find how many ways we can assign the digits 0-3 to the 
 * four cardinal directions such that a sequence of commands leads from 
 * the start ('S') to the exit ('E') without hitting walls ('#') or boundaries.
 */
public class MazeSolver {

    // Cardinal direction vectors: Right, Down, Left, Up
    private static final int[][] DIRECTIONS = {
        {0, 1},  // Right
        {1, 0},  // Down
        {0, -1}, // Left
        {-1, 0}  // Up
    };

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final String commandSequence;
    private final int startRow;
    private final int startCol;

    public MazeSolver(int rows, int cols, char[][] grid, String commandSequence) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.commandSequence = commandSequence;

        // Locate the starting position 'S'
        int sRow = -1;
        int sCol = -1;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'S') {
                    sRow = r;
                    sCol = c;
                    break;
                }
            }
            if (sRow != -1) break;
        }
        this.startRow = sRow;
        this.startCol = sCol;
    }

    /**
     * Starts the permutation generation and returns the count of valid mappings.
     */
    public int solve() {
        return countValidPermutations(0, new int[4], new boolean[4]);
    }

    /**
     * Uses recursion (DFS) to generate all permutations of direction indices (0-3)
     * and maps them to the digits 0-3.
     * 
     * @param depth Current digit we are assigning a direction to.
     * @param mapping The current assignment of digit -> direction index.
     * @param used A tracker to ensure we use each direction only once.
     * @return The number of valid mappings found from this state.
     */
    private int countValidPermutations(int depth, int[] mapping, boolean[] used) {
        if (depth == 4) {
            return simulatePath(mapping) ? 1 : 0;
        }

        int validCount = 0;
        for (int i = 0; i < 4; i++) {
            if (!used[i]) {
                used[i] = true;
                mapping[depth] = i;
                validCount += countValidPermutations(depth + 1, mapping, used);
                used[i] = false; // Backtrack
            }
        }
        return validCount;
    }

    /**
     * Simulates the movement through the maze based on a specific digit-to-direction mapping.
     * 
     * @param mapping An array where mapping[digit] = index in DIRECTIONS.
     * @return true if the path reaches 'E', false if it hits '#' or goes out of bounds.
     */
    private boolean simulatePath(int[] mapping) {
        int currentRow = startRow;
        int currentCol = startCol;

        for (char commandChar : commandSequence.toCharArray()) {
            int digit = commandChar - '0';
            int directionIndex = mapping[digit];

            currentRow += DIRECTIONS[directionIndex][0];
            currentCol += DIRECTIONS[directionIndex][1];

            // Check boundaries
            if (isOutOfBounds(currentRow, currentCol)) {
                return false;
            }

            char cell = grid[currentRow][currentCol];
            if (cell == 'E') {
                return true; // Successfully reached the exit
            } else if (cell == '#') {
                return false; // Hit a wall
            }
        }

        return false; // Finished sequence without reaching 'E'
    }

    private boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
        }

        String commands = scanner.next();

        MazeSolver solver = new MazeSolver(rows, cols, grid, commands);
        System.out.println(solver.solve());

        scanner.close();
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Represents the possible directions the bot can move.
 * Encapsulates the row and column offsets for each direction.
 */
enum Direction {
    UP(-1, 0),
    DOWN(1, 0),
    LEFT(0, -1),
    RIGHT(0, 1);

    private final int rowOffset;
    private final int colOffset;

    Direction(int rowOffset, int colOffset) {
        this.rowOffset = rowOffset;
        this.colOffset = colOffset;
    }

    public int getRowOffset() { return rowOffset; }
    public int getColOffset() { return colOffset; }

    public static Direction fromIndex(int index) {
        Direction[] values = values();
        return values[index];
    }
}

/**
 * Represents the game board, managing grid boundaries, walls, and special locations.
 */
class GameGrid {
    private final char[][] matrix;
    private final int rows;
    private final int cols;
    private int startRow;
    private int startCol;

    public GameGrid(int rows, int cols, String[] gridRows) {
        this.rows = rows;
        this.cols = cols;
        this.matrix = new char[rows][cols];
        parseGrid(gridRows);
    }

    private void parseGrid(String[] gridRows) {
        for (int i = 0; i < rows; i++) {
            String rowStr = gridRows[i];
            for (int j = 0; j < cols; j++) {
                char cell = rowStr.charAt(j);
                matrix[i][j] = cell;
                if (cell == 'S') {
                    startRow = i;
                    startCol = j;
                }
            }
        }
    }

    public boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }

    public boolean isWall(int r, int c) {
        return matrix[r][c] == '#';
    }

    public boolean isExit(int r, int c) {
        return matrix[r][c] == 'E';
    }

    public int getStartRow() { return startRow; }
    public int getStartCol() { return startCol; }
}

/**
 * Utility to generate all possible permutations of directions.
 */
class PermutationGenerator {
    public List<Direction[]> generatePermutations(Direction[] directions) {
        List<Direction[]> results = new ArrayList<>();
        backtrack(directions, new ArrayList<>(), new boolean[directions.length], results);
        return results;
    }

    private void backtrack(Direction[] original, List<Direction> current, boolean[] used, List<Direction[]> results) {
        if (current.size() == original.length) {
            results.add(current.toArray(new Direction[0]));
            return;
        }

        for (int i = 0; i < original.length; i++) {
            if (used[i]) continue;

            used[i] = true;
            current.add(original[i]);
            backtrack(original, current, used, results);
            current.remove(current.size() - 1);
            used[i] = false;
        }
    }
}

/**
 * Orchestrates the movement simulation.
 */
class BotSimulator {
    private final GameGrid grid;

    public BotSimulator(GameGrid grid) {
        this.grid = grid;
    }

    /**
     * Simulates a single permutation sequence based on the digit map.
     * @param directionOrder The ordered permutation of directions.
     * @param digitMap The string of digits mapping to the directionOrder.
     * @return true if the bot reaches the exit 'E'.
     */
    public boolean simulate(Direction[] directionOrder, String digitMap) {
        int currentRow = grid.getStartRow();
        int currentCol = grid.getStartCol();

        for (int i = 0; i < digitMap.length(); i++) {
            int directionIndex = Character.getNumericValue(digitMap.charAt(i));
            Direction move = directionOrder[directionIndex];

            currentRow += move.getRowOffset();
            currentCol += move.getColOffset();

            if (grid.isOutOfBounds(currentRow, currentCol) || grid.isWall(currentRow, currentCol)) {
                return false;
            }

            if (grid.isExit(currentRow, currentCol)) {
                return true;
            }
        }
        return false;
    }
}

public class BuggyBot {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // consume newline

        String[] gridData = new String[rows];
        for (int i = 0; i < rows; i++) {
            gridData[i] = scanner.nextLine();
        }

        String moveSequence = scanner.nextLine();
        scanner.close();

        // Initialize components
        GameGrid grid = new GameGrid(rows, cols, gridData);
        PermutationGenerator generator = new PermutationGenerator();
        BotSimulator simulator = new BotSimulator(grid);

        // Generate all permutations of the 4 basic directions
        Direction[] baseDirections = Direction.values();
        List<Direction[]> permutations = generator.generatePermutations(baseDirections);

        // Count how many permutations successfully reach the exit
        long successCount = permutations.stream()
                .filter(p -> simulator.simulate(p, moveSequence))
                .count();

        System.out.println(successCount);
    }
}

import java.io.*;
import java.util.*;

/**
 * A program that calculates how many permutations of direction mappings 
 * allow a path from a starting point 'S' to an ending point 'E' 
 * on a grid given a sequence of numeric commands.
 */
public class GridPathSolver {

    private static final int[] ROW_OFFSETS = {1, -1, 0, 0};
    private static final int[] COL_OFFSETS = {0, 0, 1, -1};
    private static final int NUM_DIRECTIONS = 4;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            solve(reader, out);
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            out.close();
        }
    }

    private static void solve(FastReader reader, PrintWriter out) throws IOException {
        int rowCount = reader.nextInt();
        int colCount = reader.nextInt();

        Grid grid = new Grid(rowCount, colCount);
        for (int i = 0; i < rowCount; i++) {
            String rowString = reader.next();
            for (int j = 0; j < colCount; j++) {
                char cell = rowString.charAt(j);
                if (cell == '#') {
                    grid.setWall(i, j, true);
                } else if (cell == 'S') {
                    grid.setStart(i, j);
                } else if (cell == 'E') {
                    grid.setEnd(i, j);
                }
            }
        }

        String commands = reader.next();
        out.print(countSuccessfulPathPermutations(grid, commands));
    }

    /**
     * Iterates through all permutations of direction mappings and counts 
     * how many satisfy the condition of reaching the end.
     */
    private static int countSuccessfulPathPermutations(Grid grid, String commands) {
        // directionMapping[i] represents which direction index (0-3) 
        // is used when the command 'i' is received.
        int[] directionMapping = {0, 1, 2, 3};
        int successCount = 0;

        do {
            if (simulatePath(grid, commands, directionMapping)) {
                successCount++;
            }
        } while (nextPermutation(directionMapping));

        return successCount;
    }

    /**
     * Simulates the movement on the grid based on the current direction mapping.
     * 
     * @return true if the end position is reached, false otherwise.
     */
    private static boolean simulatePath(Grid grid, String commands, int[] directionMapping) {
        int curR = grid.getStartR();
        int curC = grid.getStartC();

        for (int i = 0; i < commands.length(); i++) {
            int commandId = commands.charAt(i) - '0';
            int directionIdx = directionMapping[commandId];

            curR += ROW_OFFSETS[directionIdx];
            curC += COL_OFFSETS[directionIdx];

            if (curR == grid.getEndR() && curC == grid.getEndC()) {
                return true;
            }

            if (!grid.isValidMove(curR, curC)) {
                return false;
            }
        }
        return false;
    }

    /**
     * Standard algorithm to generate the next lexicographical permutation.
     */
    private static boolean nextPermutation(int[] array) {
        int i = array.length - 2;
        while (i >= 0 && array[i] >= array[i + 1]) {
            i--;
        }

        if (i < 0) {
            return false;
        }

        int j = array.length - 1;
        while (array[j] <= array[i]) {
            j--;
        }

        swap(array, i, j);
        reverse(array, i + 1, array.length - 1);
        return true;
    }

    private static void swap(int[] array, int i, int j) {
        int temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }

    private static void reverse(int[] array, int start, int end) {
        while (start < end) {
            swap(array, start++, end--);
        }
    }

    /**
     * Represents the game grid and its properties.
     */
    static class Grid {
        private final int rows;
        private final int cols;
        private final boolean[][] isWall;
        private int startR, startC;
        private int endR, endC;

        public Grid(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            this.isWall = new boolean[rows][cols];
        }

        public void setWall(int r, int c, boolean wall) {
            isWall[r][c] = wall;
        }

        public void setStart(int r, int c) {
            this.startR = r;
            this.startC = c;
        }

        public void setEnd(int r, int c) {
            this.endR = r;
            this.endC = c;
        }

        public boolean isValidMove(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && !isWall[r][c];
        }

        public int getStartR() { return startR; }
        public int getStartC() { return startC; }
        public int getEndR() { return endR; }
        public int getEndC() { return endC; }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solution to find how many direction-to-command mappings 
 * allow a path from Start to End in a grid.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            MazeSolver solver = new MazeSolver(reader);
            out.println(solver.solve());
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    static class MazeSolver {
        private final FastReader reader;

        public MazeSolver(FastReader reader) {
            this.reader = reader;
        }

        public int solve() throws IOException {
            int rows = reader.scanInt();
            int cols = reader.scanInt();

            char[][] grid = new char[rows][cols];
            int startR = -1, startC = -1;
            int endR = -1, endC = -1;

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    grid[r][c] = reader.scanChar();
                    if (grid[r][c] == 'S') {
                        startR = r;
                        startC = c;
                    } else if (grid[r][c] == 'E') {
                        endR = r;
                        endC = c;
                    }
                }
            }

            String commandsStr = reader.scanString();
            int[] commands = commandsStr.chars().map(c -> c - '0').toArray();

            Maze maze = new Maze(grid, rows, cols);
            Position startPos = new Position(startR, startC);
            Position endPos = new Position(endR, endC);

            // Generate all 24 permutations of directions (0-3)
            // A permutation maps the command digit (0,1,2,3) to a direction index
            List<int[]> permutations = PermutationGenerator.generatePermutations(new int[]{0, 1, 2, 3});

            int successfulMappings = 0;
            for (int[] mapping : permutations) {
                if (canReachEnd(maze, startPos, endPos, commands, mapping)) {
                    successfulMappings++;
                }
            }

            return successfulMappings;
        }

        /**
         * Simulates the path using a specific mapping of command digits to directions.
         */
        private boolean canReachEnd(Maze maze, Position start, Position end, int[] commands, int[] mapping) {
            Position current = new Position(start.r, start.c);

            for (int cmd : commands) {
                int directionIdx = mapping[cmd];
                int nextR = current.r + Direction.DR[directionIdx];
                int nextC = current.c + Direction.DC[directionIdx];

                if (!maze.isValidMove(nextR, nextC)) {
                    return false;
                }

                current.r = nextR;
                current.c = nextC;

                if (current.equals(end)) {
                    return true;
                }
            }

            return current.equals(end);
        }
    }

    /**
     * Represents movement directions.
     */
    static class Direction {
        // 0: Up, 1: Down, 2: Left, 3: Right (matches standard coordinate shifts)
        static final int[] DR = {-1, 1, 0, 0};
        static final int[] DC = {0, 0, -1, 1};
    }

    /**
     * Represents a point in the 2D grid.
     */
    static class Position {
        int r, c;

        Position(int r, int c) {
            this.r = r;
            this.c = c;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Position)) return false;
            Position position = (Position) o;
            return r == position.r && c == position.c;
        }

        @Override
        public int hashCode() {
            return Objects.hash(r, c);
        }
    }

    /**
     * Encapsulates the grid data and boundary logic.
     */
    static class Maze {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        Maze(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
        }

        public boolean isValidMove(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != '#';
        }
    }

    /**
     * Utility to generate all permutations of an array.
     */
    static class PermutationGenerator {
        public static List<int[]> generatePermutations(int[] nums) {
            List<int[]> result = new ArrayList<>();
            backtrack(result, nums, 0);
            return result;
        }

        private static void backtrack(List<int[]> result, int[] nums, int start) {
            if (start == nums.length) {
                result.add(nums.clone());
                return;
            }
            for (int i = start; i < nums.length; i++) {
                swap(nums, start, i);
                backtrack(result, nums, start + 1);
                swap(nums, start, i);
            }
        }

        private static void swap(int[] nums, int i, int j) {
            int temp = nums[i];
            nums[i] = nums[j];
            nums[j] = temp;
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private final BufferedInputStream bis;
        private final byte[] buffer = new byte[8192];
        private int bufferPtr = 0;
        private int bytesRead = 0;

        public FastReader(InputStream is) {
            this.bis = new BufferedInputStream(is);
        }

        public int scanInt() throws IOException {
            int c = read();
            while (isWhitespace(c)) c = read();
            boolean neg = (c == '-');
            if (neg) c = read();
            int res = 0;
            do {
                res = res * 10 + (c - '0');
                c = read();
            } while (!isWhitespace(c));
            return neg ? -res : res;
        }

        public char scanChar() throws IOException {
            int c = read();
            while (isWhitespace(c)) c = read();
            return (char) c;
        }

        public String scanString() throws IOException {
            int c = read();
            while (isWhitespace(c)) c = read();
            StringBuilder sb = new StringBuilder();
            while (!isWhitespace(c)) {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        private int read() throws IOException {
            if (bufferPtr == bytesRead) fillBuffer();
            return (bytesRead == -1) ? -1 : buffer[bufferPtr++];
        }

        private void fillBuffer() throws IOException {
            bytesRead = bis.read(buffer, 0, buffer.length);
            bufferPtr = 0;
        }

        private boolean isWhitespace(int c) {
            return c == -1 || c == ' ' || c == '\n' || c == '\r' || c == '\t';
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to solve a grid navigation problem where a sequence of commands 
 * is executed based on a permutation of four possible directions.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        FastWriter writer = new FastWriter(System.out);

        GridPathSolver solver = new GridPathSolver(reader);
        writer.println(solver.solve());

        writer.close();
    }

    /**
     * Handles the core logic of the grid traversal problem.
     */
    static class GridPathSolver {
        private static final int[] ROW_OFFSETS = {-1, 0, 1, 0}; // Up, Left, Down, Right
        private static final int[] COL_OFFSETS = {0, -1, 0, 1};

        private final FastReader reader;
        private int rows;
        private int cols;
        private char[][] grid;
        private int startRow, startCol;
        private int endRow, endCol;
        private String commandSequence;

        private int successfulPathCount;
        private final int[] directionMapping = new int[4];
        private final boolean[] directionUsed = new boolean[4];

        public GridPathSolver(FastReader reader) {
            this.reader = reader;
        }

        /**
         * Reads input and executes the solving algorithm.
         * @return the number of valid direction permutations.
         */
        public int solve() {
            readGrid();
            commandSequence = reader.next();

            successfulPathCount = 0;
            generatePermutations(0);

            return successfulPathCount;
        }

        private void readGrid() {
            rows = reader.nextInt();
            cols = reader.nextInt();
            grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = reader.next().charAt(0);
                    if (grid[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                    } else if (grid[i][j] == 'E') {
                        endRow = i;
                        endCol = j;
                    }
                }
            }
        }

        /**
         * Recursively generates all permutations of the 4 directions (0-3).
         */
        private void generatePermutations(int position) {
            if (position == 4) {
                if (isPathSuccessful()) {
                    successfulPathCount++;
                }
                return;
            }

            for (int i = 0; i < 4; i++) {
                if (!directionUsed[i]) {
                    directionUsed[i] = true;
                    directionMapping[position] = i;
                    generatePermutations(position + 1);
                    directionUsed[i] = false;
                }
            }
        }

        /**
         * Simulates the movement based on the current permutation of directions.
         * @return true if the end point 'E' is reached without hitting walls or boundaries.
         */
        private boolean isPathSuccessful() {
            int currentRow = startRow;
            int currentCol = startCol;

            for (int i = 0; i < commandSequence.length(); i++) {
                int commandDigit = commandSequence.charAt(i) - '0';
                // Map the command (0-3) to a direction in our current permutation
                int directionIdx = directionMapping[commandDigit];

                currentRow += ROW_OFFSETS[directionIdx];
                currentCol += COL_OFFSETS[directionIdx];

                if (!isInsideBounds(currentRow, currentCol) || grid[currentRow][currentCol] == '#') {
                    return false;
                }

                if (currentRow == endRow && currentCol == endCol) {
                    return true;
                }
            }
            return false;
        }

        private boolean isInsideBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Fast I/O utility for reading input.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }

    /**
     * Fast I/O utility for writing output.
     */
    static class FastWriter {
        private final PrintWriter writer;

        public FastWriter(OutputStream outputStream) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public void println(Object message) {
            writer.println(message);
        }

        public void close() {
            writer.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * A solver that finds how many permutations of directions satisfy a specific 
 * movement sequence in a maze.
 */
public class MazePathSolver {

    public static void main(String[] args) {
        try {
            MazeInputReader reader = new MazeInputReader();
            Maze maze = reader.readMaze();
            String sequence = reader.readSequence();

            MazeSolver solver = new MazeSolver(maze, sequence);
            int result = solver.solve();

            System.out.println(result);
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }
}

/**
 * Represents a coordinate in the maze.
 */
record Position(int row, int col) {}

/**
 * Represents the possible movement directions.
 */
enum Direction {
    UP('u', -1, 0),
    DOWN('d', 1, 0),
    LEFT('l', 0, -1),
    RIGHT('r', 0, 1);

    private final char symbol;
    private final int dr;
    private final int dc;

    Direction(char symbol, int dr, int dc) {
        this.symbol = symbol;
        this.dr = dr;
        this.dc = dc;
    }

    public int getDr() { return dr; }
    public int getDc() { return dc; }
}

/**
 * Encapsulates the maze grid and its properties.
 */
class Maze {
    private final char[][] grid;
    private final int rows;
    private final int cols;
    private Position start;
    private Position end;

    public Maze(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.grid = new char[rows][cols];
    }

    public void setCell(int r, int c, char value) {
        grid[r][c] = value;
        if (value == 'S') {
            start = new Position(r, c);
        } else if (value == 'E') {
            end = new Position(r, c);
        }
    }

    public boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public boolean isEnd(int r, int c) {
        return r == end.row() && c == end.col();
    }

    public boolean isWall(int r, int c) {
        char cell = grid[r][c];
        // A wall is anything that isn't a path (.), the start (S), or the end (E)
        return cell != '.' && cell != 'S' && cell != 'E';
    }

    public Position getStart() { return start; }
}

/**
 * Handles the logic of finding valid direction permutations.
 */
class MazeSolver {
    private final Maze maze;
    private final String sequence;
    private int validCount = 0;
    private final Direction[] directions = Direction.values();

    public MazeSolver(Maze maze, String sequence) {
        this.maze = maze;
        this.sequence = sequence;
    }

    public int solve() {
        validCount = 0;
        generatePermutations(0, new Direction[4], new boolean[4]);
        return validCount;
    }

    /**
     * Standard backtracking to generate all permutations of the 4 directions.
     */
    private void generatePermutations(int depth, Direction[] currentPermutation, boolean[] used) {
        if (depth == 4) {
            if (isPathSuccessful(currentPermutation)) {
                validCount++;
            }
            return;
        }

        for (int i = 0; i < 4; i++) {
            if (!used[i]) {
                used[i] = true;
                currentPermutation[depth] = directions[i];
                generatePermutations(depth + 1, currentPermutation, used);
                used[i] = false;
            }
        }
    }

    /**
     * Simulates the path given a specific permutation of directions.
     */
    private boolean isPathSuccessful(Direction[] permutation) {
        Position current = maze.getStart();

        for (int i = 0; i < sequence.length(); i++) {
            // Convert char digit to int index (e.g., '1' -> 1)
            int dirIdx = sequence.charAt(i) - '0';
            Direction move = permutation[dirIdx];

            int nextR = current.row() + move.getDr();
            int nextC = current.col() + move.getDc();

            if (!maze.isWithinBounds(nextR, nextC)) {
                return false;
            }

            if (maze.isEnd(nextR, nextC)) {
                return true;
            }

            if (maze.isWall(nextR, nextC)) {
                return false;
            }

            current = new Position(nextR, nextC);
        }

        return false;
    }
}

/**
 * Helper class to handle input parsing.
 */
class MazeInputReader {
    private final BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

    public Maze readMaze() throws IOException {
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());

        Maze maze = new Maze(n, m);
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            for (int j = 0; j < m; j++) {
                maze.setCell(i, j, line.charAt(j));
            }
        }
        return maze;
    }

    public String readSequence() throws IOException {
        return br.readLine();
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver that calculates how many permutations of direction mappings 
 * allow a path to reach an exit 'E' from a starting point 'S' 
 * given a specific sequence of movement instructions.
 */
public class DirectionPermutationSolver {

    // Directional movement vectors: Right, Left, Down, Up
    private static final int[] MOVE_X = {0, 0, 1, -1};
    private static final int[] MOVE_Y = {1, -1, 0, 0};

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int startX;
    private final int startY;

    public DirectionPermutationSolver(int rows, int cols, char[][] grid, int startX, int startY) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.startX = startX;
        this.startY = startY;
    }

    /**
     * Iterates through all 24 permutations of the direction mapping 
     * and counts how many successfully reach the exit.
     * 
     * @param instructions String of digits representing movement types.
     * @return The count of valid permutations.
     */
    public int solve(String instructions) {
        int[] directionMapping = {0, 1, 2, 3};
        int successCount = 0;

        do {
            if (canReachExit(instructions, directionMapping)) {
                successCount++;
            }
        } while (nextPermutation(directionMapping));

        return successCount;
    }

    /**
     * Simulates the path based on the provided mapping of digits to directions.
     */
    private boolean canReachExit(String instructions, int[] mapping) {
        int currentX = startX;
        int currentY = startY;

        // Check if the starting position is already the exit
        if (grid[currentX][currentY] == 'E') {
            return true;
        }

        for (int i = 0; i < instructions.length(); i++) {
            int digit = instructions.charAt(i) - '0';
            int directionIndex = mapping[digit];

            currentX += MOVE_X[directionIndex];
            currentY += MOVE_Y[directionIndex];

            if (isInvalidMove(currentX, currentY)) {
                return false;
            }

            if (grid[currentX][currentY] == 'E') {
                return true;
            }
        }

        return false;
    }

    private boolean isInvalidMove(int x, int y) {
        return x < 0 || x >= rows || y < 0 || y >= cols || grid[x][y] == '#';
    }

    /**
     * Standard algorithm to transform an array into its next lexicographical permutation.
     */
    private boolean nextPermutation(int[] array) {
        int i = array.length - 2;
        while (i >= 0 && array[i] >= array[i + 1]) {
            i--;
        }

        if (i < 0) {
            return false;
        }

        int j = array.length - 1;
        while (array[j] <= array[i]) {
            j--;
        }

        swap(array, i, j);
        reverse(array, i + 1, array.length - 1);
        return true;
    }

    private void swap(int[] array, int i, int j) {
        int temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }

    private void reverse(int[] array, int start, int end) {
        while (start < end) {
            swap(array, start++, end--);
        }
    }

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);
            int n = reader.nextInt();
            int m = reader.nextInt();

            char[][] grid = new char[n][m];
            int startX = -1;
            int startY = -1;

            for (int i = 0; i < n; i++) {
                String rowStr = reader.next();
                grid[i] = rowStr.toCharArray();
                for (int j = 0; j < m; j++) {
                    if (grid[i][j] == 'S') {
                        startX = i;
                        startY = j;
                    }
                }
            }

            String instructions = reader.next();

            if (startX == -1) {
                System.out.println(0);
                return;
            }

            DirectionPermutationSolver solver = new DirectionPermutationSolver(n, m, grid, startX, startY);
            System.out.println(solver.solve(instructions));

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Main class to execute the grid-based pathfinding puzzle solver.
 */
public class Main {

    public static void main(String[] args) {
        // Use try-with-resources to ensure I/O streams are closed automatically
        try (FastReader in = new FastReader(System.in);
             FastWriter out = new FastWriter(System.out)) {

            PathfindingSolver solver = new PathfindingSolver();
            solver.solve(in, out);

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Handles the core logic of the pathfinding puzzle.
     */
    static class PathfindingSolver {
        // Directional vectors: Up, Right, Down, Left
        private static final int[] DX = {-1, 0, 1, 0};
        private static final int[] DY = {0, 1, 0, -1};

        private int startRow, startCol;
        private int endRow, endCol;
        private char[][] grid;

        /**
         * Parses input, computes permutations, and finds how many direction mappings
         * allow a path from 'S' to 'E'.
         */
        public void solve(FastReader in, FastWriter out) {
            String rowsStr = in.next();
            if (rowsStr == null) return;

            int rows = Integer.parseInt(rowsStr);
            int cols = in.nextInt();
            grid = new char[rows][cols];

            // Initialize grid and locate Start/End points
            for (int i = 0; i < rows; i++) {
                String line = in.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                    } else if (grid[i][j] == 'E') {
                        endRow = i;
                        endCol = j;
                    }
                }
            }

            String commandSequence = in.next();
            // The problem asks to permute the mapping of commands to directions (0, 1, 2, 3)
            Set<String> directionPermutations = PermutationGenerator.generate("0123");

            int validMappingCount = 0;
            for (String permutation : directionPermutations) {
                if (isPathPossible(commandSequence, permutation)) {
                    validMappingCount++;
                }
            }

            out.printLine(validMappingCount);
        }

        /**
         * Simulates the movement through the grid based on the provided command sequence
         * and the specific direction mapping (permutation).
         * 
         * @param commands A string representing the sequence of commands to execute.
         * @param mapping A permutation string mapping commands to direction indices.
         * @return true if the end 'E' is reached, false if a wall is hit, bounds are exceeded, 
         *         or moves run out.
         */
        private boolean isPathPossible(String commands, String mapping) {
            int currR = startRow;
            int currC = startCol;
            int commandIdx = 0;
            int totalCommands = commands.length();

            while (true) {
                // 1. Check Boundary conditions
                if (currR < 0 || currR >= grid.length || currC < 0 || currC >= grid[0].length) {
                    return false;
                }
                // 2. Check Obstacles
                if (grid[currR][currC] == '#') {
                    return false;
                }
                // 3. Check Goal
                if (grid[currR][currC] == 'E') {
                    return true;
                }
                // 4. Check if moves are exhausted
                if (commandIdx >= totalCommands) {
                    return false;
                }

                // 5. Execute movement
                char command = commands.charAt(commandIdx);
                int directionIndex = mapping.indexOf(command);

                // If the command character isn't in our mapping, the path is invalid
                if (directionIndex == -1) {
                    return false;
                }

                currR += DX[directionIndex];
                currC += DY[directionIndex];
                commandIdx++;
            }
        }
    }

    /**
     * Utility class to generate all possible permutations of a given string.
     */
    static class PermutationGenerator {
        public static Set<String> generate(String input) {
            Set<String> results = new HashSet<>();
            backtrack(input.toCharArray(), 0, results);
            return results;
        }

        private static void backtrack(char[] chars, int start, Set<String> results) {
            if (start == chars.length) {
                results.add(new String(chars));
                return;
            }
            for (int i = start; i < chars.length; i++) {
                swap(chars, start, i);
                backtrack(chars, start + 1, results);
                swap(chars, start, i); // Backtrack
            }
        }

        private static void swap(char[] chars, int i, int j) {
            char temp = chars[i];
            chars[i] = chars[j];
            chars[j] = temp;
        }
    }

    /**
     * High-performance input reader using BufferedReader and StringTokenizer.
     */
    static class FastReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            this.reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            try {
                while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                }
                return tokenizer.nextToken();
            } catch (IOException e) {
                return null;
            }
        }

        public int nextInt() {
            String next = next();
            return (next != null) ? Integer.parseInt(next) : 0;
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }

    /**
     * High-performance output writer using PrintWriter.
     */
    static class FastWriter implements AutoCloseable {
        private final PrintWriter writer;

        public FastWriter(OutputStream outputStream) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public void printLine(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                writer.print(objects[i]);
                if (i < objects.length - 1) {
                    writer.print(" ");
                }
            }
            writer.println();
        }

        @Override
        public void close() {
            writer.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to solve the "New Year and Buggy Bot" problem.
 * The goal is to find how many command-to-direction mappings allow a bot 
 * to reach the exit 'E' without hitting walls '#' or boundaries.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        RobotSimulator solver = new RobotSimulator();
        solver.solve(reader, writer);

        writer.flush();
        writer.close();
    }

    static class RobotSimulator {
        // Direction vectors: 0: Up, 1: Down, 2: Left, 3: Right
        private static final int[] DR = {-1, 1, 0, 0};
        private static final int[] DC = {0, 0, -1, 1};

        private int rows;
        private int cols;
        private char[][] grid;
        private String commands;
        private int startRow;
        private int startCol;

        /**
         * Executes the simulation logic.
         */
        public void solve(FastReader sc, PrintWriter out) {
            this.rows = sc.nextInt();
            this.cols = sc.nextInt();
            this.grid = new char[rows][cols];

            for (int r = 0; r < rows; r++) {
                String line = sc.nextLine();
                for (int c = 0; c < cols; c++) {
                    grid[r][c] = line.charAt(c);
                    if (grid[r][c] == 'S') {
                        startRow = r;
                        startCol = c;
                    }
                }
            }
            this.commands = sc.nextLine();

            out.println(countValidMappings());
        }

        /**
         * Iterates through all 24 permutations of direction mappings 
         * and counts how many result in reaching the exit.
         */
        private int countValidMappings() {
            int validCount = 0;
            int[] commandToDir = new int[4];

            // We represent a permutation by assigning which command (0-3) 
            // corresponds to which direction (0:Up, 1:Down, 2:Left, 3:Right).
            // i, j, k, l are the command indices.
            for (int i = 0; i < 4; i++) {
                for (int j = 0; j < 4; j++) {
                    if (j == i) continue;
                    for (int k = 0; k < 4; k++) {
                        if (k == i || k == j) continue;
                        for (int l = 0; l < 4; l++) {
                            if (l == i || l == j || l == k) continue;

                            // Map the chosen command indices to physical directions
                            commandToDir[i] = 0; // Command i goes UP
                            commandToDir[j] = 1; // Command j goes DOWN
                            commandToDir[k] = 2; // Command k goes LEFT
                            commandToDir[l] = 3; // Command l goes RIGHT

                            if (simulate(commandToDir)) {
                                validCount++;
                            }
                        }
                    }
                }
            }
            return validCount;
        }

        /**
         * Simulates the bot's movement based on a specific command mapping.
         * 
         * @param mapping An array where mapping[command] = directionIndex.
         * @return true if the bot reaches 'E', false otherwise.
         */
        private boolean simulate(int[] mapping) {
            int r = startRow;
            int c = startCol;

            // If already at exit
            if (grid[r][c] == 'E') return true;

            for (int i = 0; i < commands.length(); i++) {
                int command = commands.charAt(i) - '0';
                int direction = mapping[command];

                r += DR[direction];
                c += DC[direction];

                // Check boundaries and obstacles
                if (r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] == '#') {
                    return false;
                }

                // Check if exit is reached
                if (grid[r][c] == 'E') {
                    return true;
                }
            }

            // If commands finished and not at exit
            return grid[r][c] == 'E';
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String nextLine() {
            try {
                return br.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

/**
 * MazeSolver determines how many unique mappings of command digits (0-3) 
 * to cardinal directions (Up, Down, Left, Right) will lead a traveler 
 * from a starting point 'S' to an exit 'E' without hitting walls '#'.
 */
public class MazeSolver {

    // Directional offsets corresponding to: Right, Left, Up, Down
    // These replace the obfuscated logic in the original code.
    private static final int[] ROW_OFFSETS = {0, 0, -1, 1};
    private static final int[] COL_OFFSETS = {1, -1, 0, 0};

    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = reader.nextGrid(rows, cols);
            int[] commands = reader.nextDigitArray();

            Position startPos = findStartPosition(grid, rows, cols);

            if (startPos == null) {
                out.println(0);
            } else {
                int result = solve(grid, rows, cols, startPos, commands);
                out.println(result);
            }
        } catch (Exception e) {
            // In a production environment, use a logging framework.
        } finally {
            out.close();
        }
    }

    /**
     * Orchestrates the permutation generation and counting.
     */
    private static int solve(char[][] grid, int rows, int cols, Position start, int[] commands) {
        int[] mapping = new int[4]; // Maps digit 0-3 to a direction index 0-3
        boolean[] usedDirections = new boolean[4];
        return countSuccessfulMappings(0, mapping, usedDirections, grid, rows, cols, start, commands);
    }

    /**
     * Uses backtracking to generate all 4! (24) permutations of direction mappings.
     */
    private static int countSuccessfulMappings(int digitIndex, int[] mapping, boolean[] usedDirections,
                                               char[][] grid, int rows, int cols, 
                                               Position start, int[] commands) {
        // Base case: All 4 digits have been mapped to a direction
        if (digitIndex == 4) {
            return simulatePath(grid, rows, cols, start, commands, mapping) ? 1 : 0;
        }

        int count = 0;
        for (int dirIdx = 0; dirIdx < 4; dirIdx++) {
            if (!usedDirections[dirIdx]) {
                usedDirections[dirIdx] = true;
                mapping[digitIndex] = dirIdx;
                count += countSuccessfulMappings(digitIndex + 1, mapping, usedDirections, grid, rows, cols, start, commands);
                usedDirections[dirIdx] = false; // Backtrack
            }
        }
        return count;
    }

    /**
     * Simulates the movement on the grid given a specific direction mapping.
     */
    private static boolean simulatePath(char[][] grid, int rows, int cols, Position start, 
                                        int[] commands, int[] mapping) {
        int currentRow = start.row;
        int currentCol = start.col;

        for (int cmd : commands) {
            // Check if current position is out of bounds or a wall
            if (isOutOfBounds(currentRow, currentCol, rows, cols) || grid[currentRow][currentCol] == '#') {
                return false;
            }

            // Check if we have already reached the exit
            if (grid[currentRow][currentCol] == 'E') {
                return true;
            }

            // Move based on the mapping for the current command digit
            int directionIndex = mapping[cmd];
            currentRow += ROW_OFFSETS[directionIndex];
            currentCol += COL_OFFSETS[directionIndex];
        }

        // Final check: did the last move land us on the exit?
        return !isOutOfBounds(currentRow, currentCol, rows, cols) && grid[currentRow][currentCol] == 'E';
    }

    private static boolean isOutOfBounds(int r, int c, int rows, int cols) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }

    private static Position findStartPosition(char[][] grid, int rows, int cols) {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'S') {
                    return new Position(r, c);
                }
            }
        }
        return null;
    }

    /**
     * Data carrier for grid coordinates.
     */
    private static class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Optimized reader for fast input processing.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(java.io.InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public char[][] nextGrid(int n, int m) {
            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = next().toCharArray();
            }
            return grid;
        }

        public int[] nextDigitArray() {
            String s = next();
            int[] digits = new int[s.length()];
            for (int i = 0; i < s.length(); i++) {
                digits[i] = s.charAt(i) - '0';
            }
            return digits;
        }
    }
}

