/**
 * Represents a coordinate in the 2D grid.
 */
class Point {
    final int x;
    final int y;

    Point(int x, int y) {
        this.x = x;
        this.y = y;
    }
}

/**
 * Handles the core logic of solving the pathfinding permutation problem.
 */
class PathSolver {
    private static final int[] DX = {-1, 0, 1, 0}; // Up, Right, Down, Left
    private static final int[] DY = {0, 1, 0, -1};
    private static final int NUM_DIRECTIONS = 4;

    private final FastReader reader;
    private int rows;
    private int cols;
    private char[][] grid;
    private int[] instructionSequence;
    private Point start;
    private Point end;

    public PathSolver(FastReader reader) {
        this.reader = reader;
    }

    /**
     * Executes the solving process.
     * @return The number of valid permutations.
     */
    public int solve() throws IOException {
        rows = reader.nextInt();
        cols = reader.nextInt();
        grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            grid[i] = line.toCharArray();
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'S') {
                    start = new Point(i, j);
                } else if (grid[i][j] == 'E') {
                    end = new Point(i, j);
                }
            }
        }

        String dirString = reader.next();
        instructionSequence = new int[dirString.length()];
        for (int i = 0; i < dirString.length(); i++) {
            instructionSequence[i] = dirString.charAt(i) - '0';
        }

        int[] permutation = new int[NUM_DIRECTIONS];
        boolean[] used = new boolean[NUM_DIRECTIONS];
        return countValidPermutations(0, permutation, used);
    }

    /**
     * Recursively generates permutations of the 4 directions.
     */
    private int countValidPermutations(int depth, int[] permutation, boolean[] used) {
        if (depth == NUM_DIRECTIONS) {
            return isValidPath(permutation) ? 1 : 0;
        }

        int count = 0;
        for (int i = 0; i < NUM_DIRECTIONS; i++) {
            if (!used[i]) {
                used[i] = true;
                permutation[depth] = i;
                count += countValidPermutations(depth + 1, permutation, used);
                used[i] = false;
            }
        }
        return count;
    }

    /**
     * Checks if a specific mapping of instructions leads to the end point.
     */
    private boolean isValidPath(int[] permutation) {
        int currX = start.x;
        int currY = start.y;

        for (int instructionIndex : instructionSequence) {
            // The instruction digit is an index into our current permutation mapping
            int moveType = permutation[instructionIndex];

            currX += DX[moveType];
            currY += DY[moveType];

            if (!isWithinBoundsAndWalkable(currX, currY)) {
                return false;
            }
            if (isGoal(currX, currY)) {
                return true;
            }
        }
        return isGoal(currX, currY);
    }

    private boolean isWithinBoundsAndWalkable(int x, int y) {
        return x >= 0 && x < rows && y >= 0 && y < cols && grid[x][y] != '#';
    }

    private boolean isGoal(int x, int y) {
        return x == end.x && y == end.y;
    }
}

