/**
 * Represents the possible movement directions in the maze.
 */
enum Direction {
    DOWN(1, 0),
    RIGHT(0, 1),
    UP(-1, 0),
    LEFT(0, -1);

    private final int rowOffset;
    private final int colOffset;

    Direction(int rowOffset, int colOffset) {
        this.rowOffset = rowOffset;
        this.colOffset = colOffset;
    }

    public int getRowOffset() { return rowOffset; }
    public int getColOffset() { return colOffset; }
}

/**
 * Represents the Maze grid and current state.
 */
class Maze {
    private final char[][] grid;
    private final int rows;
    private final int cols;

    private int currRow;
    private int currCol;
    private int startRow;
    private int startCol;

    public Maze(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        findStartAndEnd();
        reset();
    }

    private void findStartAndEnd() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'S') {
                    startRow = r;
                    startCol = c;
                }
            }
        }
    }

    public void reset() {
        this.currRow = startRow;
        this.currCol = startCol;
    }

    /**
     * Attempts to move the player in the given direction.
     * @param dir The direction to move.
     * @return true if the move was successful, false if hitting a wall or boundary.
     */
    public boolean move(Direction dir) {
        int nextRow = currRow + dir.getRowOffset();
        int nextCol = currCol + dir.getColOffset();

        if (isOutOfBounds(nextRow, nextCol) || grid[nextRow][nextCol] == '#') {
            return false;
        }

        currRow = nextRow;
        currCol = nextCol;
        return true;
    }

    public boolean isAtGoal() {
        return grid[currRow][currCol] == 'E';
    }

    private boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }
}

/**
 * Utility to generate all permutations of a character set.
 */
class PermutationGenerator {
    /**
     * Generates all permutations of a given string using backtracking.
     */
    public static List<String> getAllPermutations(String input) {
        List<String> results = new ArrayList<>();
        backtrack(input.toCharArray(), 0, results);
        return results;
    }

    private static void backtrack(char[] chars, int index, List<String> results) {
        if (index == chars.length) {
            results.add(new String(chars));
            return;
        }
        for (int i = index; i < chars.length; i++) {
            swap(chars, index, i);
            backtrack(chars, index + 1, results);
            swap(chars, index, i); // backtrack
        }
    }

    private static void swap(char[] chars, int i, int j) {
        char temp = chars[i];
        chars[i] = chars[j];
        chars[j] = temp;
    }
}

/**
 * Orchestrates the simulation logic.
 */
class MazeSimulator {
    private final Maze maze;
    private final Direction[] directions = Direction.values();

    public MazeSimulator(Maze maze) {
        this.maze = maze;
    }

    /**
     * Counts how many direction mappings satisfy the instructions.
     */
    public int countSuccessfulMappings(String instructions, List<String> permutations) {
        int successCount = 0;

        for (String perm : permutations) {
            if (isMappingSuccessful(instructions, perm)) {
                successCount++;
            }
        }
        return successCount;
    }

    private boolean isMappingSuccessful(String instructions, String perm) {
        maze.reset();

        // Map instruction characters to direction indices based on current permutation
        // mapping[char] = directionIndex
        Map<Character, Integer> mapping = new HashMap<>();
        for (int i = 0; i < perm.length(); i++) {
            mapping.put(perm.charAt(i), i);
        }

        for (char instChar : instructions.toCharArray()) {
            Integer dirIdx = mapping.get(instChar);

            // If the instruction character is part of our permutation set, move
            if (dirIdx != null) {
                if (!maze.move(directions[dirIdx])) {
                    return false; // Hit a wall or boundary
                }
            }

            // Check if we reached the goal after the move
            if (maze.isAtGoal()) {
                return true;
            }
        }

        return false;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) return;
        int n = sc.nextInt();
        int m = sc.nextInt();
        sc.nextLine(); // Consume the newline left by nextInt()

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = sc.nextLine();
            grid[i] = line.toCharArray();
        }

        String instructions = sc.hasNextLine() ? sc.nextLine() : "";

        // Setup simulation
        Maze maze = new Maze(n, m, grid);
        MazeSimulator simulator = new MazeSimulator(maze);

        // All possible mappings of '0','1','2','3' to the 4 directions
        List<String> permutations = PermutationGenerator.getAllPermutations("0123");

        int result = simulator.countSuccessfulMappings(instructions, permutations);
        System.out.println(result);

        sc.close();
    }
}

