            }

            String moveSequence = reader.nextString();

            PathfindingSolver solver = new PathfindingSolver(rows, cols, gridLines, moveSequence);
            out.println(solver.countValidPermutations());
        } catch (Exception e) {
            // In a real-world production app, use a logger
            System.err.println("Error processing input: " + e.getMessage());
        } finally {
            out.close();
        }
    }

    /**
     * Handles the logic for finding how many movement permutations 
     * lead the character from 'S' to 'E'.
     */
    static class PathfindingSolver {
        private final Grid grid;
        private final String moveSequence;

        // Direction vectors: Right, Left, Down, Up
        private static final int[] ROW_OFFSETS = {0, 0, 1, -1};
        private static final int[] COL_OFFSETS = {1, -1, 0, 0};

        public PathfindingSolver(int rows, int cols, String[] lines, String moveSequence) {
            this.grid = new Grid(rows, cols, lines);
            this.moveSequence = moveSequence;
        }

        /**
         * Iterates through all 24 permutations of the 4 directions.
         * @return The count of permutations that successfully reach the end.
         */
        public int countValidPermutations() {
            int[] permutation = {0, 1, 2, 3};
            int validCount = 0;

            // Check the first permutation
            if (canReachEnd(permutation)) {
                validCount++;
            }

            // Check all subsequent permutations
            while (PermutationUtils.nextPermutation(permutation)) {
                if (canReachEnd(permutation)) {
                    validCount++;
                }
            }

            return validCount;
        }

        /**
         * Simulates the path based on the current permutation of directions.
         */
        private boolean canReachEnd(int[] permutation) {
            int currentRow = grid.getStartRow();
            int currentCol = grid.getStartCol();

            for (int i = 0; i < moveSequence.length(); i++) {
                int moveIndex = moveSequence.charAt(i) - '0';
                int directionIdx = permutation[moveIndex];

                currentRow += ROW_OFFSETS[directionIdx];
                currentCol += COL_OFFSETS[directionIdx];

                // 1. Check if we reached the target
                if (grid.isEnd(currentRow, currentCol)) {
                    return true;
                }

                // 2. Check if we hit a boundary or a wall
                if (!grid.isValidMove(currentRow, currentCol)) {
                    return false;
                }
            }

            return false;
        }
    }

    /**
     * Represents the game board and provides spatial queries.
     */
    static class Grid {
        private final char[][] cells;
        private final int rows;
        private final int cols;
        private int startRow, startCol;
        private int endRow, endCol;

        public Grid(int rows, int cols, String[] lines) {
            this.rows = rows;
            this.cols = cols;
            this.cells = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    char c = lines[i].charAt(j);
                    cells[i][j] = c;
                    if (c == 'S') {
                        startRow = i;
                        startCol = j;
                    } else if (c == 'E') {
                        endRow = i;
                        endCol = j;
                    }
                }
            }
        }

        public boolean isValidMove(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && cells[r][c] != '#';
        }

        public boolean isEnd(int r, int c) {
            return r == endRow && c == endCol;
        }

        public int getStartRow() { return startRow; }
        public int getStartCol() { return startCol; }
    }

    /**
     * Utility class for lexicographical permutation generation.
     */
    static class PermutationUtils {
        /**
         * Standard algorithm to transform an array into its next lexicographical permutation.
         * @return true if a next permutation was found, false if it was the last one.
         */
        public static boolean nextPermutation(int[] array) {
            int i = array.length - 2;
            while (i >= 0 && array[i] >= array[i + 1]) {
                i--;
            }

            if (i < 0) {
                return false;
            }

            int j = array.length - 1;
            while (array[j] <= array[i]) {
                j--;
            }

            swap(array, i, j);
            reverse(array, i + 1, array.length - 1);
            return true;
        }

        private static void swap(int[] array, int i, int j) {
            int temp = array[i];
            array[i] = array[j];
            array[j] = temp;
        }

        private static void reverse(int[] array, int start, int end) {
            while (start < end) {
                swap(array, start++, end--);
            }
        }
    }

    /**
     * Efficient reader for large input volumes.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream is) {
            this.reader = new BufferedReader(new InputStreamReader(is));
        }

        public String nextString() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextString());
        }
    }
}

