/**
 * A solution to simulate movement through a maze based on various movement strategies.
 */
public class Solution {

    public static void main(String[] args) {
        MazeSolver solver = new MazeSolver(System.in);
        solver.solve();
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Point point = (Point) o;
            return r == point.r && c == point.c;
        }

        @Override
        public int hashCode() {
            return Objects.hash(r, c);
        }
    }

    /**
     * Handles the logic of reading the maze and simulating the movement paths.
     */
    static class MazeSolver {
        private final FastReader reader;
        private int rows, cols;
        private char[][] maze;
        private Point startPos;
        private Point endPos;
        private int[] movementCommands;

        // Original magic values from the provided code translated to direction vectors (dr, dc)
        // 1   -> {0, 1}   (Right)
        // -1  -> {0, -1}  (Left)
        // 100 -> {1, 0}   (Down)
        // -100-> {-1, 0}  (Up)
        private static final int[][] RAW_MAP = {
            {1, -1, 100, -100}, {1, -1, -100, 100},
            {1, 100, -1, -100}, {1, 100, -100, -1},
            {1, -100, -1, 100}, {1, -100, 100, -1},
            {-1, 1, -100, 100}, {-1, 1, 100, -100},
            {-1, 100, -100, 1}, {-1, 100, 1, -100},
            {-1, -100, 100, 1}, {-1, -100, 1, 100},
            {100, 1, -1, -100}, {100, 1, -100, -1},
            {100, -1, 1, -100}, {100, -1, -100, 1},
            {100, -100, 1, -1}, {100, -100, -1, 1},
            {-100, 1, -1, 100}, {-100, 1, 100, -1},
            {-100, -1, 100, 1}, {-100, -1, 1, 100},
            {-100, 100, 1, -1}, {-100, 100, -1, 1}
        };

        private final int[][][] strategies;

        public MazeSolver(InputStream inputStream) {
            this.reader = new FastReader(inputStream);
            this.strategies = initializeStrategies();
        }

        /**
         * Converts the original integer-based movement map into a structured 3D array 
         * of delta-row and delta-column values.
         */
        private int[][][] initializeStrategies() {
            int[][][] strategyVectors = new int[RAW_MAP.length][4][2];
            for (int i = 0; i < RAW_MAP.length; i++) {
                for (int j = 0; j < 4; j++) {
                    int val = RAW_MAP[i][j];
                    if (val == 1) {
                        strategyVectors[i][j] = new int[]{0, 1};
                    } else if (val == -1) {
                        strategyVectors[i][j] = new int[]{0, -1};
                    } else if (val == 100) {
                        strategyVectors[i][j] = new int[]{1, 0};
                    } else if (val == -100) {
                        strategyVectors[i][j] = new int[]{-1, 0};
                    }
                }
            }
            return strategyVectors;
        }

        public void solve() {
            readInput();
            int successfulPaths = countSuccessfulPaths();
            System.out.println(successfulPaths);
        }

        private void readInput() {
            rows = reader.nextInt();
            cols = reader.nextInt();
            maze = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    char cell = line.charAt(j);
                    maze[i][j] = cell;
                    if (cell == 'S') {
                        startPos = new Point(i, j);
                    } else if (cell == 'E') {
                        endPos = new Point(i, j);
                    }
                }
            }

            String orderStr = reader.next();
            movementCommands = new int[orderStr.length()];
            for (int i = 0; i < orderStr.length(); i++) {
                // Converts '0'-'9' char to int 0-9
                movementCommands[i] = orderStr.charAt(i) - '0';
            }
        }

        private int countSuccessfulPaths() {
            int ans = 0;
            for (int[][] strategy : strategies) {
                if (simulatePath(strategy)) {
                    ans++;
                }
            }
            return ans;
        }

        private boolean simulatePath(int[][] strategy) {
            Point current = startPos;

            for (int command : movementCommands) {
                // The original code assumes commands are in the range 0-3 based on map size
                if (command < 0 || command >= 4) break;

                int dr = strategy[command][0];
                int dc = strategy[command][1];

                int nextR = current.r + dr;
                int nextC = current.c + dc;

                if (isInvalidMove(nextR, nextC)) {
                    return false;
                }

                current = new Point(nextR, nextC);

                if (current.equals(endPos)) {
                    return true;
                }
            }
            return false;
        }

        private boolean isInvalidMove(int r, int c) {
            return r < 0 || r >= rows || c < 0 || c >= cols || maze[r][c] == '#';
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

