/**
 * A program to find the number of ways to assign directions to digits (0-3)
 * such that a given sequence of moves leads from a starting point 'S'
 * to an exit 'E' without hitting obstacles '#' or boundaries.
 */
public class MazeSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] grid = new char[rows][cols];
            Position startPos = null;

            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == 'S') {
                        startPos = new Position(i, j);
                    }
                }
            }

            String instructions = reader.next();
            Maze maze = new Maze(grid, startPos);
            int validPathsCount = solve(maze, instructions);

            out.println(validPathsCount);
        } catch (Exception e) {
            // In a real production environment, use a proper logging framework
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Orchestrates the permutation of digit-to-direction mappings and counts valid paths.
     */
    private static int solve(Maze maze, String instructions) {
        List<int[]> permutations = new ArrayList<>();
        generatePermutations(new int[]{0, 1, 2, 3}, 0, permutations);

        int validPaths = 0;
        for (int[] p : permutations) {
            if (isPathValid(maze, instructions, p)) {
                validPaths++;
            }
        }
        return validPaths;
    }

    /**
     * Simulates the movement based on a specific digit-to-direction mapping.
     * 
     * @param p An array where p[0] is the digit for LEFT, p[1] for RIGHT, 
     *          p[2] for UP, and p[3] for DOWN.
     */
    private static boolean isPathValid(Maze maze, String instructions, int[] p) {
        Position current = maze.getStart();

        for (int i = 0; i < instructions.length(); i++) {
            int digit = instructions.charAt(i) - '0';
            Direction moveDir = getDirectionFromDigit(digit, p);

            current = current.move(moveDir);

            if (!maze.isValidPosition(current) || maze.isObstacle(current)) {
                return false;
            }

            if (maze.isExit(current)) {
                return true;
            }
        }

        // If we finished all instructions and didn't reach 'E', it's invalid.
        return maze.isExit(current);
    }

    private static Direction getDirectionFromDigit(int digit, int[] mapping) {
        if (digit == mapping[0]) return Direction.LEFT;
        if (digit == mapping[1]) return Direction.RIGHT;
        if (digit == mapping[2]) return Direction.UP;
        return Direction.DOWN; // digit == mapping[3]
    }

    /**
     * Generates all permutations of a given array using backtracking.
     */
    private static void generatePermutations(int[] arr, int index, List<int[]> result) {
        if (index == arr.length) {
            result.add(arr.clone());
            return;
        }
        for (int i = index; i < arr.length; i++) {
            swap(arr, index, i);
            generatePermutations(arr, index + 1, result);
            swap(arr, index, i);
        }
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    // --- Domain Models ---

    enum Direction {
        LEFT(0, -1), RIGHT(0, 1), UP(-1, 0), DOWN(1, 0);

        final int dr, dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }

    static class Position {
        final int r, c;

        Position(int r, int c) {
            this.r = r;
            this.c = c;
        }

        Position move(Direction dir) {
            return new Position(this.r + dir.dr, this.c + dir.dc);
        }
    }

    static class Maze {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final Position start;

        Maze(char[][] grid, Position start) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
            this.start = start;
        }

        boolean isValidPosition(Position pos) {
            return pos.r >= 0 && pos.r < rows && pos.c >= 0 && pos.c < cols;
        }

        boolean isObstacle(Position pos) {
            return grid[pos.r][pos.c] == '#';
        }

        boolean isExit(Position pos) {
            return grid[pos.r][pos.c] == 'E';
        }

        Position getStart() {
            return start;
        }
    }

    /**
     * Utility class for fast I/O.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

