/**
 * Defines the movement logic for each direction character.
 * Note: The delta values preserve the specific coordinate mapping from the original code.
 */
enum Direction {
    RIGHT('>', 1, 0),
    LEFT('<', -1, 0),
    UP('^', 0, 1),
    DOWN('v', 0, -1);

    private final char symbol;
    private final int rowDelta;
    private final int colDelta;

    Direction(char symbol, int rowDelta, int colDelta) {
        this.symbol = symbol;
        this.rowDelta = rowDelta;
        this.colDelta = colDelta;
    }

    public static Direction fromChar(char c) {
        for (Direction dir : values()) {
            if (dir.symbol == c) return dir;
        }
        throw new IllegalArgumentException("Invalid direction symbol: " + c);
    }
}

