    }
}

/**
 * Handles the logic of simulating robot movement sequences.
 */
class RobotSimulator {
    private final Grid grid;
    private final String wayPattern;

    public RobotSimulator(Grid grid, String wayPattern) {
        this.grid = grid;
        this.wayPattern = wayPattern;
    }

    /**
     * Simulates a single move sequence.
     * @param moveSequence A permutation of direction characters.
     * @return true if the robot reaches the exit 'E' during the sequence.
     */
    public boolean simulate(String moveSequence) {
        Position currentPos = grid.getStartPosition();

        for (char patternChar : wayPattern.toCharArray()) {
            // The original logic uses digits in 'way' to index into the 'move' string
            int moveIndex = Character.getNumericValue(patternChar);
            char directionChar = moveSequence.charAt(moveIndex);
            Direction direction = Direction.fromChar(directionChar);

            currentPos = currentPos.move(direction);

            if (grid.isOutOfBounds(currentPos) || grid.isObstacle(currentPos)) {
                return false;
            }

            if (grid.isExit(currentPos)) {
                return true;
            }
        }
        return false;
    }
}

