/**
 * Handles the logic of simulating paths based on direction permutations.
 */
class PathSolver {
    private final Grid grid;
    private final String commands;

    // Mapping indices: 0: Down, 1: Left, 2: Up, 3: Right
    private static final int[][] DIRECTIONS = {
        {1, 0},  
        {0, -1}, 
        {-1, 0}, 
        {0, 1}   
    };

    public PathSolver(Grid grid, String commands) {
        this.grid = grid;
        this.commands = commands;
    }

    /**
     * Iterates through all 24 possible direction mappings and counts successful paths.
     */
    public int countValidMappings() {
        List<int[]> permutations = generatePermutations(new int[]{0, 1, 2, 3});
        int validCount = 0;

        for (int[] mapping : permutations) {
            if (isPathSuccessful(mapping)) {
                validCount++;
            }
        }
        return validCount;
    }

    /**
     * Simulates the path given a specific digit-to-direction mapping.
     */
    private boolean isPathSuccessful(int[] mapping) {
        int r = grid.getStartRow();
        int c = grid.getStartCol();

        // Check if start position is already the end
        if (grid.getCell(r, c) == 'E') {
            return true;
        }

        for (int i = 0; i < commands.length(); i++) {
            int digit = commands.charAt(i) - '0';
            int dirIdx = mapping[digit];

            r += DIRECTIONS[dirIdx][0];
            c += DIRECTIONS[dirIdx][1];

            if (grid.isOutOfBounds(r, c) || grid.getCell(r, c) == '#') {
                return false;
            }
            if (grid.getCell(r, c) == 'E') {
                return true;
            }
        }
        return false;
    }

    private List<int[]> generatePermutations(int[] arr) {
        List<int[]> result = new ArrayList<>();
        backtrack(arr, 0, result);
        return result;
    }

    private void backtrack(int[] arr, int index, List<int[]> result) {
        if (index == arr.length) {
            result.add(arr.clone());
            return;
        }
        for (int i = index; i < arr.length; i++) {
            swap(arr, index, i);
            backtrack(arr, index + 1, result);
            swap(arr, index, i);
        }
    }

    private void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

/**
 * High-performance input reader for large datasets.
 */
class FastReader {
    private final InputStream stream;
    private final byte[] buffer = new byte[8192];
    private int curChar;
    private int numChars;

    public FastReader(InputStream stream) {
        this.stream = stream;
    }

    private int read() {
        if (numChars == -1) throw new InputMismatchException();
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buffer);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0) return -1;
        }
        return buffer[curChar++];
    }

    public int nextInt() {
        int c = read();
        while (isSpaceChar(c)) c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public String readString() {
        int c = read();
        while (isSpaceChar(c)) c = read();
        StringBuilder res = new StringBuilder();
        do {
            res.appendCodePoint(c);
            c = read();
        } while (!isSpaceChar(c));
        return res.toString();
    }

    private boolean isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }
}

