/**
 * Problem: Count how many permutations of direction mappings (0-3) 
 * allow a path to reach the end 'E' from start 'S' without hitting obstacles '#'.
 */
public class MazeSolverApp {

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);
            MazeSolver solver = new MazeSolver(reader);
            solver.solve();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Represents the game board and its properties.
     */
    static class Maze {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private int startRow, startCol;
        private int endRow, endCol;

        public Maze(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            findSpecialPoints();
        }

        private void findSpecialPoints() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                    } else if (grid[i][j] == 'E') {
                        endRow = i;
                        endCol = j;
                    }
                }
            }
        }

        public boolean isValidMove(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != '#';
        }

        public boolean isAtEnd(int r, int c) {
            return r == endRow && c == endCol;
        }

        public int getStartRow() { return startRow; }
        public int getStartCol() { return startCol; }
    }

    /**
     * Handles the logic of simulating paths and finding permutations.
     */
    static class MazeSolver {
        private final FastReader reader;

        // Physical directions mapping: Down, Left, Up, Right
        private final int[] rowOffsets = {1, 0, -1, 0};
        private final int[] colOffsets = {0, -1, 0, 1};

        public MazeSolver(FastReader reader) {
            this.reader = reader;
        }

        public void solve() throws IOException {
            int n = reader.nextInt();
            int m = reader.nextInt();
            char[][] gridData = reader.readCharGrid(n, m);
            char[] commands = reader.nextString().toCharArray();

            Maze maze = new Maze(n, m, gridData);
            int successCount = countValidPermutations(maze, commands);

            System.out.println(successCount);
        }

        private int countValidPermutations(Maze maze, char[] commands) {
            int successCount = 0;
            int[] mapping = {0, 1, 2, 3};

            do {
                if (simulatePath(maze, commands, mapping)) {
                    successCount++;
                }
            } while (nextPermutation(mapping));

            return successCount;
        }

        private boolean simulatePath(Maze maze, char[] commands, int[] mapping) {
            int currR = maze.getStartRow();
            int currC = maze.getStartCol();

            for (char cmdChar : commands) {
                // Map the command digit to a physical direction index via the permutation array
                int directionIdx = mapping[cmdChar - '0'];

                currR += rowOffsets[directionIdx];
                currC += colOffsets[directionIdx];

                if (!maze.isValidMove(currR, currC)) {
                    return false; // Hit a wall or boundary
                }

                if (maze.isAtEnd(currR, currC)) {
                    return true; // Successfully reached the end
                }
            }
            return false;
        }

        /**
         * Standard lexicographical next permutation algorithm.
         */
        private boolean nextPermutation(int[] array) {
            int i = array.length - 2;
            while (i >= 0 && array[i] >= array[i + 1]) {
                i--;
            }

            if (i < 0) return false;

            int j = array.length - 1;
            while (array[j] <= array[i]) {
                j--;
            }

            swap(array, i, j);
            reverse(array, i + 1, array.length - 1);
            return true;
        }

        private void swap(int[] array, int i, int j) {
            int temp = array[i];
            array[i] = array[j];
            array[j] = temp;
        }

        private void reverse(int[] array, int start, int end) {
            while (start < end) {
                swap(array, start++, end--);
            }
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream is) {
            this.reader = new BufferedReader(new InputStreamReader(is));
        }

        public String nextString() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(nextString());
        }

        public char[] nextStringAsCharArray() throws IOException {
            return nextString().toCharArray();
        }

        public char[][] readCharGrid(int rows, int cols) throws IOException {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = nextString();
                grid[i] = line.toCharArray();
            }
            return grid;
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * MazeSolver calculates how many permutations of direction mappings 
 * result in a path that reaches the exit 'E' without hitting a wall '#'.
 */
public class MazeSolver {

    // Direction vectors: Left, Right, Up, Down
    private static final int[][] DIRECTIONS = {
        {0, -1}, 
        {0, 1}, 
        {-1, 0}, 
        {1, 0}
    };

    private char[][] grid;
    private int startRow;
    private int startCol;
    private String moveSequence;
    private final int rows;
    private final int cols;

    public MazeSolver(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        // Initialize grid with padding to avoid boundary checks
        this.grid = new char[rows + 2][cols + 2];
        for (int i = 0; i < rows + 2; i++) {
            Arrays.fill(this.grid[i], '#');
        }
    }

    public void setCell(int r, int c, char value) {
        grid[r][c] = value;
        if (value == 'S') {
            this.startRow = r;
            this.startCol = c;
        }
    }

    public void setMoveSequence(String moveSequence) {
        this.moveSequence = moveSequence;
    }

    /**
     * Iterates through all 24 permutations of the 4 directions to 
     * count how many satisfy the movement sequence.
     */
    public int solve() {
        int successfulPathCount = 0;

        // Generate permutations of {0, 1, 2, 3} using nested loops
        for (int a = 0; a < 4; a++) {
            for (int b = 0; b < 4; b++) {
                if (b == a) continue;
                for (int c = 0; c < 4; c++) {
                    if (c == a || c == b) continue;

                    // The 4th index is mathematically determined
                    int d = 6 - (a + b + c);
                    int[] permutation = {a, b, c, d};

                    if (canReachExit(permutation)) {
                        successfulPathCount++;
                    }
                }
            }
        }
        return successfulPathCount;
    }

    /**
     * Simulates the movement based on the provided direction permutation.
     */
    private boolean canReachExit(int[] directionMapping) {
        int currentRow = startRow;
        int currentCol = startCol;

        for (int i = 0; i < moveSequence.length(); i++) {
            // Convert char digit to index for the permutation array
            int moveIdx = moveSequence.charAt(i) - '0';
            int dirIdx = directionMapping[moveIdx];

            int[] offset = DIRECTIONS[dirIdx];
            currentRow += offset[0];
            currentCol += offset[1];

            char cell = grid[currentRow][currentCol];
            if (cell == '#') {
                return false; // Hit a wall
            }
            if (cell == 'E') {
                return true; // Reached the exit
            }
        }
        return false;
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        try {
            int n = reader.nextInt();
            int m = reader.nextInt();

            MazeSolver solver = new MazeSolver(n, m);

            for (int i = 1; i <= n; i++) {
                String rowContent = reader.next();
                for (int j = 1; j <= m; j++) {
                    solver.setCell(i, j, rowContent.charAt(j - 1));
                }
            }

            solver.setMoveSequence(reader.next());
            System.out.println(solver.solve());

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Efficient utility for reading input.
     */
    static class FastReader {
        private BufferedReader reader;
