        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * A program to solve a maze navigation problem by testing all possible
 * direction-to-command mappings.
 */
public class MazeNavigator {

    /**
     * Represents a coordinate in the maze grid.
     */
    public record Position(int row, int col) {}

    /**
     * Represents cardinal directions and their respective movement offsets.
     */
    public enum Direction {
        UP(-1, 0),
        DOWN(1, 0),
        RIGHT(0, 1),
        LEFT(0, -1);

        private final int rowDelta;
        private final int colDelta;

        Direction(int rowDelta, int colDelta) {
            this.rowDelta = rowDelta;
            this.colDelta = colDelta;
        }

        public int getRowDelta() { return rowDelta; }
        public int getColDelta() { return colDelta; }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        String[] grid = new String[rows];
        Position startPosition = null;

        // Parse the grid and locate the starting point 'S'
        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next();
            int sIndex = grid[i].indexOf('S');
            if (sIndex != -1) {
                startPosition = new Position(i, sIndex);
            }
        }

        // Parse the sequence of movement commands
        String instructions = scanner.next();

        MazeSolver solver = new MazeSolver(grid, startPosition);
        int successfulPaths = solver.countSuccessfulMappings(instructions);

        System.out.println(successfulPaths);
        scanner.close();
    }

    /**
     * Handles the logic of simulating the maze and calculating permutations.
     */
    static class MazeSolver {
        private final String[] grid;
        private final Position startPosition;
        private final Direction[] directions = Direction.values();

        public MazeSolver(String[] grid, Position startPosition) {
            this.grid = grid;
            this.startPosition = startPosition;
        }

        /**
         * Counts how many permutations of direction mappings lead to the exit 'E'.
         * 
         * @param instructions The sequence of command digits.
         * @return The number of valid permutations.
         */
        public int countSuccessfulMappings(String instructions) {
            int successCount = 0;
            List<int[]> permutations = new ArrayList<>();
            generatePermutations(new ArrayList<>(), new boolean[4], permutations);

            for (int[] mapping : permutations) {
                if (canReachExit(mapping, instructions)) {
                    successCount++;
                }
            }
            return successCount;
        }

        /**
         * Simulates a single path given a specific command-to-direction mapping.
         *
         * @param mapping An array where index 'i' contains the Direction index for command 'i'.
         * @param instructions The sequence of movement commands.
         * @return true if 'E' is reached, false otherwise.
         */
        private boolean canReachExit(int[] mapping, String instructions) {
            int currentRow = startPosition.row();
            int currentCol = startPosition.col();

            for (char cmdChar : instructions.toCharArray()) {
                int command = cmdChar - '0';
                int directionIndex = mapping[command];
                Direction move = directions[directionIndex];

                int nextRow = currentRow + move.getRowDelta();
                int nextCol = currentCol + move.getColDelta();

                // 1. Boundary Check
                if (isOutOfBounds(nextRow, nextCol)) {
                    return false;
                }

                // 2. Wall Check
                char targetCell = grid[nextRow].charAt(nextCol);
                if (targetCell == '#') {
                    return false;
                }

                // 3. Destination Check
                if (targetCell == 'E') {
                    return true;
                }

                // 4. Update current position
                currentRow = nextRow;
                currentCol = nextCol;
            }

            return false;
        }

        private boolean isOutOfBounds(int r, int c) {
            return r < 0 || r >= grid.length || c < 0 || c >= grid[0].length();
        }

        /**
         * Generates all permutations of {0, 1, 2, 3}.
         */
        private void generatePermutations(List<Integer> current, boolean[] used, List<int[]> results) {
            if (current.size() == 4) {
                results.add(current.stream().mapToInt(i -> i).toArray());
                return;
            }

            for (int i = 0; i < 4; i++) {
                if (!used[i]) {
                    used[i] = true;
                    current.add(i);
                    generatePermutations(current, used, results);
                    current.remove(current.size() - 1);
                    used[i] = false;
                }
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for the grid path permutation problem.
 * The goal is to find how many ways we can map the instruction digits (0-3)
 * to physical directions (UP, DOWN, LEFT, RIGHT) such that the path 
 * reaches the destination without hitting obstacles or boundaries.
 */
public class Main {
    public static void main(String[] args) {
        try (FastScanner sc = new FastScanner(System.in);
             PrintWriter out = new PrintWriter(System.out)) {

            GridPathSolver solver = new GridPathSolver(sc);
            out.println(solver.solve());
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

enum Direction {
    UP(-1, 0),
    DOWN(1, 0),
    LEFT(0, -1),
    RIGHT(0, 1);

    final int dr;
    final int dc;

    Direction(int dr, int dc) {
        this.dr = dr;
        this.dc = dc;
    }
}

class GridPathSolver {
    private final FastScanner scanner;
    private int rows;
    private int cols;
    private boolean[][] isWalkable;
    private int startRow, startCol;
    private int endRow, endCol;
    private int[] instructions;
    private int successfulPermutationsCount;

    public GridPathSolver(FastScanner scanner) {
        this.scanner = scanner;
    }

    public int solve() {
        parseGrid();
        parseInstructions();

        successfulPermutationsCount = 0;
        Direction[] mapping = new Direction[4];
        boolean[] usedDirections = new boolean[4];

        // Generate all 4! (24) permutations of Direction mappings
        generatePermutations(mapping, usedDirections, 0);

        return successfulPermutationsCount;
    }

    private void parseGrid() {
        rows = scanner.nextInt();
        cols = scanner.nextInt();
        isWalkable = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                char cell = line.charAt(j);
                if (cell == '#') {
                    isWalkable[i][j] = false;
                } else {
                    isWalkable[i][j] = true;
                    if (cell == 'S') {
                        startRow = i;
                        startCol = j;
                    } else if (cell == 'E') {
                        endRow = i;
                        endCol = j;
                    }
                }
            }
        }
    }

    private void parseInstructions() {
        String instString = scanner.next();
        instructions = new int[instString.length()];
        for (int i = 0; i < instString.length(); i++) {
            instructions[i] = instString.charAt(i) - '0';
        }
    }

    /**
     * Recursive backtracking to generate all permutations of directions for the 4 possible digits.
     * @param mapping The current mapping of digit (index) to Direction.
     * @param used A boolean array to track which directions have been assigned.
     * @param digitIndex The current digit (0-3) we are assigning a direction to.
     */
    private void generatePermutations(Direction[] mapping, boolean[] used, int digitIndex) {
        if (digitIndex == 4) {
            if (simulatePath(mapping)) {
                successfulPermutationsCount++;
            }
            return;
        }

        Direction[] allDirections = Direction.values();
        for (int i = 0; i < allDirections.length; i++) {
            if (!used[i]) {
                used[i] = true;
                mapping[digitIndex] = allDirections[i];
                generatePermutations(mapping, used, digitIndex + 1);
                used[i] = false;
            }
        }
    }

    /**
     * Simulates the path based on a specific mapping of digits to directions.
     */
    private boolean simulatePath(Direction[] mapping) {
        int r = startRow;
        int c = startCol;

        for (int digit : instructions) {
            Direction move = mapping[digit];
            r += move.dr;
            c += move.dc;

            // Boundary and obstacle check
            if (r < 0 || r >= rows || c < 0 || c >= cols || !isWalkable[r][c]) {
                return false;
            }

            // Destination check
            if (r == endRow && c == endCol) {
                return true;
            }
        }

        return false;
    }
}

/**
 * Optimized Scanner for fast integer and string reading.
 */
class FastScanner implements AutoCloseable {
    private final InputStream stream;
    private final byte[] buffer = new byte[1024];
    private int curChar;
    private int numChars;

    public FastScanner(InputStream stream) {
        this.stream = stream;
    }

    private int read() {
        if (numChars == -1) return -1;
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buffer);
            } catch (IOException e) {
                return -1;
            }
            if (numChars <= 0) return -1;
        }
        return buffer[curChar++];
    }

    public String next() {
        int c = read();
        while (isSpaceChar(c)) c = read();
        StringBuilder res = new StringBuilder();
        do {
            res.appendCodePoint(c);
            c = read();
        } while (!isSpaceChar(c));
        return res.toString();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    private boolean isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    @Override
    public void close() throws IOException {
        stream.close();
    }
}

