/**
 * Scorify calculates how many ways a set of digit-to-direction mappings 
 * allow a path to reach an exit 'E' from a starting point 'S' on a grid.
 */
public class Scorify {

    private static final char[] DIRECTIONS = {'D', 'U', 'R', 'L'};

    public static void main(String[] args) {
        FastReader reader = new FastReader();

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            int startRow = 0, startCol = 0;
            int endRow = 0, endCol = 0;

            // Parse the grid and locate Start (S) and End (E) positions
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                    } else if (grid[i][j] == 'E') {
                        endRow = i;
                        endCol = j;
                    }
                }
            }

            String instructions = reader.next();
            int validMappingCount = 0;

            // There are 4 instructions digits (0-3), and each can be one of 4 directions.
            // We iterate through all 4^4 (256) possible mappings.
            char[] mapping = new char[4];
            for (char d0 : DIRECTIONS) {
                mapping[0] = d0;
                for (char d1 : DIRECTIONS) {
                    mapping[1] = d1;
                    for (char d2 : DIRECTIONS) {
                        mapping[2] = d2;
                        for (char d3 : DIRECTIONS) {
                            mapping[3] = d3;

                            if (simulatePath(grid, startRow, startCol, endRow, endCol, instructions, mapping)) {
                                validMappingCount++;
                            }
                        }
                    }
                }
            }

            System.out.println(validMappingCount);

        } catch (Exception e) {
            // In a production environment, use a proper logging framework
            e.printStackTrace();
        }
    }

    /**
     * Simulates the movement based on the provided mapping and instruction string.
     * 
     * @return true if the path reaches the end point 'E' without hitting a wall or boundary.
     */
    private static boolean simulatePath(char[][] grid, int startR, int startC, 
                                        int endR, int endC, String instructions, char[] mapping) {
        int currR = startR;
        int currC = startC;
        int rows = grid.length;
        int cols = grid[0].length;

        for (int i = 0; i < instructions.length(); i++) {
            int digit = instructions.charAt(i) - '0';
            char dir = mapping[digit];

            // Update position based on direction
            switch (dir) {
                case 'D': currR++; break;
                case 'U': currR--; break;
                case 'R': currC++; break;
                case 'L': currC--; break;
            }

            // Check for out of bounds or obstacle
            if (currR < 0 || currR >= rows || currC < 0 || currC >= cols || grid[currR][currC] == '#') {
                return false;
            }

            // Check if target reached
            if (currR == endR && currC == endC) {
                return true;
            }
        }

        return false;
    }

    /**
     * Efficient reader for large input datasets.
     */
    private static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader() {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

