/**
 * MazeNavigator simulates different command-to-direction mappings 
 * to determine how many ways a sequence of instructions can lead 
 * from a starting point 'S' to an exit 'E' without hitting walls '#'.
 */
public class MazeNavigator {

    // Direction vectors for cardinal movements: Left, Right, Up, Down
    private static final int[][] BASE_DIRECTIONS = {
        {0, -1}, // Left
        {0, 1},  // Right
        {-1, 0}, // Up
        {1, 0}   // Down
    };

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            // Read grid dimensions
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            int startRow = -1;
            int startCol = -1;

            // Read grid and locate starting position 'S'
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                grid[i] = line.toCharArray();
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                    }
                }
            }

            // Read instructions and convert to integer array for performance
            String instructionString = reader.next();
            int[] instructions = new int[instructionString.length()];
            for (int i = 0; i < instructionString.length(); i++) {
                instructions[i] = instructionString.charAt(i) - '0';
            }

            // Calculate and output the result
            int result = solve(grid, startRow, startCol, instructions);
            out.println(result);

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Orchestrates the permutation generation and simulation.
     */
    private static int solve(char[][] grid, int startRow, int startCol, int[] instructions) {
        if (startRow == -1) return 0;

        List<int[]> permutations = new ArrayList<>();
        int[] p = {0, 1, 2, 3};
        generatePermutations(p, 0, permutations);

        int validMappingCount = 0;
        for (int[] perm : permutations) {
            // Map command digit to a physical direction based on the current permutation
            int[][] mapping = new int[4][2];
            mapping[perm[0]] = BASE_DIRECTIONS[0];
            mapping[perm[1]] = BASE_DIRECTIONS[1];
            mapping[perm[2]] = BASE_DIRECTIONS[2];
            mapping[perm[3]] = BASE_DIRECTIONS[3];

            if (canReachExit(grid, startRow, startCol, instructions, mapping)) {
                validMappingCount++;
            }
        }
        return validMappingCount;
    }

    /**
     * Simulates the movement through the grid for a specific command mapping.
     */
    private static boolean canReachExit(char[][] grid, int startRow, int startCol, 
                                        int[] instructions, int[][] mapping) {
        int currentRow = startRow;
        int currentCol = startCol;
        int totalRows = grid.length;
        int totalCols = grid[0].length;

        for (int command : instructions) {
            int[] move = mapping[command];
            currentRow += move[0];
            currentCol += move[1];

            // Check bounds
            if (currentRow < 0 || currentRow >= totalRows || 
                currentCol < 0 || currentCol >= totalCols) {
                return false;
            }

            // Check for walls
            if (grid[currentRow][currentCol] == '#') {
                return false;
            }

            // Check if exit is reached
            if (grid[currentRow][currentCol] == 'E') {
                return true;
            }
        }
        return false;
    }

    /**
     * Standard backtracking algorithm to generate all permutations of an array.
     */
    private static void generatePermutations(int[] arr, int index, List<int[]> result) {
        if (index == arr.length) {
            result.add(arr.clone());
            return;
        }
        for (int i = index; i < arr.length; i++) {
            swap(arr, index, i);
            generatePermutations(arr, index + 1, result);
            swap(arr, index, i); // backtrack
        }
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Solution to find the number of valid direction mappings that allow 
 * an agent to reach the exit 'E' from start 'S' given a command string.
 */
public class Solution {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        solve(reader);
    }

    private static void solve(FastReader reader) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        char[][] grid = new char[rows][cols];
        int startRow = -1;
        int startCol = -1;

        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            grid[i] = line.toCharArray();
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        String commands = reader.next();
        int validMappingsCount = countValidMappings(grid, startRow, startCol, commands);
        System.out.println(validMappingsCount);
    }

    /**
     * Iterates through all permutations of direction mappings and counts successful paths.
     */
    private static int countValidMappings(char[][] grid, int startR, int startC, String commands) {
        // Directions: 0: Up, 1: Down, 2: Left, 3: Right
        int[][] moveVectors = {
            {-1, 0}, // Up
            {1, 0},  // Down
            {0, -1}, // Left
            {0, 1}   // Right
        };

        // p[i] = index of the moveVector assigned to command digit 'i'
        int[] p = {0, 1, 2, 3};
        int count = 0;

        do {
            if (simulate(grid, startR, startC, commands, p, moveVectors)) {
                count++;
            }
        } while (nextPermutation(p));

        return count;
    }

    /**
     * Simulates the movement based on a specific permutation of direction mappings.
     * @return true if 'E' is reached without hitting a wall or boundary.
     */
    private static boolean simulate(char[][] grid, int startR, int startC, String commands, int[] p, int[][] vectors) {
        int currR = startR;
        int currC = startC;
        int rows = grid.length;
        int cols = grid[0].length;

        for (int i = 0; i < commands.length(); i++) {
            int commandDigit = commands.charAt(i) - '0';
            int vectorIdx = p[commandDigit];

            currR += vectors[vectorIdx][0];
            currC += vectors[vectorIdx][1];

            // Check boundaries and obstacles
            if (currR < 0 || currR >= rows || currC < 0 || currC >= cols || grid[currR][currC] == '#') {
                return false;
            }

            // Check if exit reached
            if (grid[currR][currC] == 'E') {
                return true;
            }
        }

        return false;
    }

    /**
     * Standard algorithm to generate the next lexicographical permutation.
     */
    private static boolean nextPermutation(int[] array) {
        int i = array.length - 2;
        while (i >= 0 && array[i] >= array[i + 1]) {
            i--;
        }
        if (i < 0) return false;

        int j = array.length - 1;
        while (array[j] <= array[i]) {
            j--;
        }

        swap(array, i, j);
        reverse(array, i + 1);
        return true;
    }

    private static void swap(int[] array, int i, int j) {
        int temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }

    private static void reverse(int[] array, int start) {
        int end = array.length - 1;
        while (start < end) {
            swap(array, start++, end--);
        }
    }

    /**
     * Efficient reader for large input sets.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

