    /**
     * Represents a coordinate in the 2D grid.
     */
    static class Position {
        final int r, c;

        Position(int r, int c) {
            this.r = r;
            this.c = c;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Position)) return false;
            Position position = (Position) o;
            return r == position.r && c == position.c;
        }

        @Override
        public int hashCode() {
            return Objects.hash(r, c);
        }
    }

    /**
     * Encapsulates movement logic and direction offsets.
     */
    enum Direction {
        U(-1, 0), D(1, 0), L(0, -1), R(0, 1);

        final int dr, dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }

        static Direction fromChar(char c) {
            return switch (c) {
                case 'u' -> U;
                case 'd' -> D;
                case 'l' -> L;
                case 'r' -> R;
                default -> throw new IllegalArgumentException("Invalid direction character: " + c);
            };
        }
    }

    /**
     * Represents the maze layout and handles collision/boundary logic.
     */
    static class Maze {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final Position start;
        private final Position end;

        public Maze(String[] lines, int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            this.grid = new char[rows][cols];
            Position startPos = null;
            Position endPos = null;

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    char cell = lines[i].charAt(j);
                    grid[i][j] = cell;
                    if (cell == 'S') startPos = new Position(i, j);
                    else if (cell == 'E') endPos = new Position(i, j);
                }
            }
            this.start = startPos;
            this.end = endPos;
        }

        public boolean isWalkable(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != '#';
        }

        public boolean isEnd(int r, int c) {
            return r == end.r && c == end.c;
        }

        public Position getStart() { return start; }
    }

    /**
     * Logic for simulating paths and calculating permutations.
     */
    static class MazeSolver {
        private final Maze maze;

        public MazeSolver(Maze maze) {
            this.maze = maze;
        }

        /**
         * Finds how many unique permutations of {U, D, L, R} assigned to {0, 1, 2, 3}
         * result in the path reaching the end.
         */
        public int countSuccessfulPermutations(String instructions) {
            List<Direction> directions = Arrays.asList(Direction.U, Direction.D, Direction.L, Direction.R);
            List<List<Direction>> allPermutations = new ArrayList<>();
            generatePermutations(new ArrayList<>(), directions, allPermutations);

            int successfulPathCount = 0;
            for (List<Direction> permutation : allPermutations) {
                if (simulate(instructions, permutation)) {
                    successfulPathCount++;
                }
            }
            return successfulPathCount;
        }

        private boolean simulate(String instructions, List<Direction> permutation) {
            int curR = maze.getStart().r;
            int curC = maze.getStart().c;
            boolean reachedEnd = false;

            for (int i = 0; i < instructions.length(); i++) {
                char cmd = instructions.charAt(i);
                Direction moveDir;

                // If command is a placeholder '0'-'3', use permutation. 
                // Otherwise, treat it as a literal 'u','d','l','r'.
                if (cmd >= '0' && cmd <= '3') {
                    moveDir = permutation.get(cmd - '0');
                } else {
                    moveDir = Direction.fromChar(cmd);
                }

                curR += moveDir.dr;
                curC += moveDir.dc;

                if (!maze.isWalkable(curR, curC)) {
                    break;
                }

                if (maze.isEnd(curR, curC)) {
                    reachedEnd = true;
                }
            }
            return reachedEnd;
        }

        private void generatePermutations(List<Direction> current, List<Direction> remaining, List<List<Direction>> result) {
            if (remaining.isEmpty()) {
                result.add(new ArrayList<>(current));
                return;
            }
            for (int i = 0; i < remaining.size(); i++) {
                current.add(remaining.get(i));
                List<Direction> nextRemaining = new ArrayList<>(remaining);
                nextRemaining.remove(i);
                generatePermutations(current, nextRemaining, result);
                current.remove(current.size() - 1);
            }
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream is) {
            this.reader = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver for determining the number of valid direction mappings that allow 
 * a path to reach an exit ('E') from a starting point ('S') on a grid.
 */
public class DirectionalPathSolver {

    // Directional offsets: 0=Up, 1=Down, 2=Right, 3=Left
    private static final int[] ROW_OFFSETS = {-1, 1, 0, 0};
    private static final int[] COL_OFFSETS = {0, 0, 1, -1};
    private static final int NUM_DIRECTIONS = 4;

    private final char[][] grid;
    private final String instructions;
    private final int rows;
    private final int cols;
    private final int startRow;
    private final int startCol;

    private int validMappingsCount = 0;

    public DirectionalPathSolver(int rows, int cols, char[][] grid, String instructions, int startRow, int startCol) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.instructions = instructions;
        this.startRow = startRow;
        this.startCol = startCol;
    }

    /**
     * Orchestrates the permutation generation and counting.
     * @return Total count of valid direction mappings.
     */
    public int solve() {
        validMappingsCount = 0;
        int[] currentMapping = new int[NUM_DIRECTIONS];
        boolean[] usedDirections = new boolean[NUM_DIRECTIONS];

        generateMappings(currentMapping, usedDirections, 0);

        return validMappingsCount;
    }

    /**
     * Uses backtracking to generate all permutations of directions {0, 1, 2, 3}.
     */
    private void generateMappings(int[] mapping, boolean[] used, int depth) {
        if (depth == NUM_DIRECTIONS) {
            if (canReachExit(mapping)) {
                validMappingsCount++;
            }
            return;
        }

        for (int dir = 0; dir < NUM_DIRECTIONS; dir++) {
            if (!used[dir]) {
                used[dir] = true;
                mapping[depth] = dir;
                generateMappings(mapping, used, depth + 1);
                used[dir] = false;
            }
        }
    }

    /**
     * Iteratively simulates the path based on the provided direction mapping.
     * @param mapping An array where mapping[digit] = direction index.
     * @return true if the exit 'E' is reached, false otherwise.
     */
    private boolean canReachExit(int[] mapping) {
        int currR = startRow;
        int currC = startCol;
        int instructionIndex = 0;

        while (true) {
            // 1. Check boundaries and obstacles
            if (isOutOfBounds(currR, currC) || grid[currR][currC] == '#') {
                return false;
            }

            // 2. Check if we have reached the exit
            if (grid[currR][currC] == 'E') {
                return true;
            }

            // 3. Check if we ran out of instructions before finding the exit
            if (instructionIndex == instructions.length()) {
                return false;
            }

            // 4. Process the next instruction
            int commandDigit = instructions.charAt(instructionIndex) - '0';
            int direction = mapping[commandDigit];

            currR += ROW_OFFSETS[direction];
            currC += COL_OFFSETS[direction];
            instructionIndex++;
        }
    }

    private boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }

    public static void main(String[] args) {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int n = sc.nextInt();
            int m = sc.nextInt();
            char[][] grid = new char[n][m];
            int startR = -1;
            int startC = -1;

            for (int i = 0; i < n; i++) {
                String rowStr = sc.next();
                for (int j = 0; j < m; j++) {
                    grid[i][j] = rowStr.charAt(j);
                    if (grid[i][j] == 'S') {
                        startR = i;
                        startC = j;
                    }
                }
            }

            String instructions = sc.next();

            DirectionalPathSolver solver = new DirectionalPathSolver(n, m, grid, instructions, startR, startC);
            out.println(solver.solve());

        } catch (Exception e) {
            // In a real-world application, use a logging framework.
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Efficient utility class for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver that finds how many permutations of direction mappings allow
 * an agent to reach a target 'E' from a start 'S' given a sequence of commands.
 */
public class DirectionMappingSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            Grid grid = new Grid(rows, cols);
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    char cell = line.charAt(j);
                    if (cell == '#') {
                        grid.setObstacle(i, j, true);
                    } else if (cell == 'S') {
                        grid.setStart(i, j);
                    } else if (cell == 'E') {
                        grid.setEnd(i, j);
                    }
                }
            }

            String commandSequence = reader.next();
            Solver solver = new Solver(grid, commandSequence);
            System.out.println(solver.solve());

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Represents the grid environment.
     */
    static class Grid {
        private final int rows;
        private final int cols;
        private final boolean[][] isObstacle;
        private int startRow, startCol;
        private int endRow, endCol;

        public Grid(int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            this.isObstacle = new boolean[rows][cols];
        }

        public void setObstacle(int r, int c, boolean value) {
            isObstacle[r][c] = value;
        }

        public void setStart(int r, int c) {
            this.startRow = r;
            this.startCol = c;
        }

        public void setEnd(int r, int c) {
            this.endRow = r;
            this.endCol = c;
        }

        public boolean isObstacle(int r, int c) {
            return isObstacle[r][c];
        }

        public boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public int getStartRow() { return startRow; }
        public int getStartCol() { return startCol; }
        public int getEndRow() { return endRow; }
        public int getEndCol() { return endCol; }
    }

    /**
     * Logic for simulating the path and finding permutations.
     */
    static class Solver {
        private final Grid grid;
        private final String commands;
        private int successCount = 0;

        // Direction offsets: 0: Down, 1: Right, 2: Left, 3: Up
        private static final int[] DX = {1, 0, 0, -1};
        private static final int[] DY = {0, 1, -1, 0};

        public Solver(Grid grid, String commands) {
            this.grid = grid;
            this.commands = commands;
        }

        public int solve() {
            int[] directionMapping = new int[4];
            boolean[] used = new boolean[4];
            generatePermutations(0, directionMapping, used);
            return successCount;
        }

        /**
         * Recursively generates all 4! permutations of direction mappings.
         */
        private void generatePermutations(int depth, int[] mapping, boolean[] used) {
            if (depth == 4) {
                if (simulatePath(mapping)) {
                    successCount++;
                }
                return;
            }

            for (int i = 0; i < 4; i++) {
                if (!used[i]) {
                    used[i] = true;
                    mapping[depth] = i;
                    generatePermutations(depth + 1, mapping, used);
                    used[i] = false;
                }
            }
        }

        /**
         * Simulates movement based on the provided mapping.
         * 
         * @param mapping An array where mapping[digit] = directionIndex
         * @return true if the agent reaches the end position.
         */
        private boolean simulatePath(int[] mapping) {
            int currR = grid.getStartRow();
            int currC = grid.getStartCol();

            for (int i = 0; i < commands.length(); i++) {
                int cmdDigit = commands.charAt(i) - '0';
                int direction = mapping[cmdDigit];

                int nextR = currR + DX[direction];
                int nextC = currC + DY[direction];

                // Validate move
                if (!grid.isWithinBounds(nextR, nextC) || grid.isObstacle(nextR, nextC)) {
                    return false;
                }

                currR = nextR;
                currC = nextC;

                // Check if target is reached
                if (currR == grid.getEndRow() && currC == grid.getEndCol()) {
                    return true;
                }
            }
            return false;
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.Scanner;

/**
 * PathfindingSolver calculates the number of ways to map digits (0-3) 
 * to directions (Up, Down, Left, Right) such that a path starting 
 * from 'S' reaches 'E' without hitting walls ('#') or boundaries.
 */
public class PathfindingSolver {

    /**
     * Represents the four cardinal directions and their coordinate offsets.
     */
    private enum Direction {
        UP(-1, 0), 
        DOWN(1, 0), 
        LEFT(0, -1), 
        RIGHT(0, 1);

        final int dr;
        final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }

    /**
     * Represents a coordinate in the grid.
     */
    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final String commands;

    private Point startPoint;
    private Point endPoint;
    private int successfulMappingCount = 0;

    public PathfindingSolver(int rows, int cols, char[][] grid, String commands) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.commands = commands;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) {
            return;
        }

        int n = sc.nextInt();
        int m = sc.nextInt();
        sc.nextLine(); // Consume trailing newline

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String line = sc.nextLine();
            for (int j = 0; j < m; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        String commandStr = sc.hasNext() ? sc.next() : "";

        PathfindingSolver solver = new PathfindingSolver(n, m, grid, commandStr);
        solver.solve();

        sc.close();
    }

    /**
     * Orchestrates the finding of points, permutation generation, and result output.
     */
    public void solve() {
        findSpecialPoints();

        if (startPoint == null || endPoint == null) {
            System.out.println(0);
            return;
        }

        // The four possible directions we want to map to digits 0, 1, 2, and 3
        Direction[] directionMapping = {
            Direction.UP, 
            Direction.DOWN, 
            Direction.LEFT, 
            Direction.RIGHT
        };

        generateAndTestPermutations(directionMapping, 0);
        System.out.println(successfulMappingCount);
    }

    /**
     * Scans the grid once to locate the Start ('S') and End ('E') points.
     */
    private void findSpecialPoints() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'S') {
                    startPoint = new Point(i, j);
                } else if (grid[i][j] == 'E') {
                    endPoint = new Point(i, j);
                }
            }
        }
    }

    /**
     * Standard backtracking algorithm to generate all 4! permutations of directions.
     */
    private void generateAndTestPermutations(Direction[] mapping, int index) {
        if (index == mapping.length) {
            if (isPathSuccessful(mapping)) {
                successfulMappingCount++;
            }
            return;
        }

        for (int i = index; i < mapping.length; i++) {
            swap(mapping, index, i);
            generateAndTestPermutations(mapping, index + 1);
            swap(mapping, index, i); // Backtrack
        }
    }

    private void swap(Direction[] arr, int i, int j) {
        Direction temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Simulates the movement based on the current digit-to-direction mapping.
     * 
     * @param mapping An array where mapping[digit] is the direction for that digit.
     * @return true if the path reaches 'E', false if it hits a wall or boundary.
     */
    private boolean isPathSuccessful(Direction[] mapping) {
        int currR = startPoint.r;
        int currC = startPoint.c;

        for (int i = 0; i < commands.length(); i++) {
            int digit = commands.charAt(i) - '0';

            // Defensive check for input digits
            if (digit < 0 || digit >= 4) {
                return false;
            }

            Direction move = mapping[digit];
            currR += move.dr;
            currC += move.dc;

            // Check if target reached
            if (currR == endPoint.r && currC == endPoint.c) {
                return true;
            }

            // Check if out of bounds or hits a wall
            if (isOutOfBounds(currR, currC) || grid[currR][currC] == '#') {
                return false;
            }
        }

        return false;
    }

    private boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }
}

import java.util.*;

/**
 * A solver for the maze navigation problem.
 * Finds how many permutations of direction mappings satisfy a given sequence of moves
 * to reach the exit 'E' from start 'S' without hitting walls '#'.
 */
public class MazeNavigationSolver {

    // Movement offsets: 0: Up, 1: Down, 2: Left, 3: Right
    private static final int[][] DIRECTION_OFFSETS = {
        {-1, 0}, // Up
        {1, 0},  // Down
        {0, -1}, // Left
        {0, 1}   // Right
    };

    private final char[][] maze;
    private final int rows;
    private final int cols;
    private final int startRow;
    private final int startCol;

    public MazeNavigationSolver(int rows, int cols, char[][] maze) {
        this.rows = rows;
        this.cols = cols;
        this.maze = maze;

        // Find the starting position 'S' during initialization
        int sR = 0, sC = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (maze[i][j] == 'S') {
                    sR = i;
                    sC = j;
                }
            }
        }
        this.startRow = sR;
        this.startCol = sC;
    }

    /**
     * Solves the maze by testing all permutations of direction mappings.
     * @param moveSequence A string of digits representing the command sequence.
     * @return The number of valid direction permutations.
     */
    public int solve(String moveSequence) {
        List<int[]> permutations = new ArrayList<>();
        int[] base = {0, 1, 2, 3};
        generatePermutations(base, 0, permutations);

        int validPathCount = 0;
        for (int[] permutation : permutations) {
            if (simulatePath(permutation, moveSequence)) {
                validPathCount++;
            }
        }
        return validPathCount;
    }

    /**
     * Simulates the movement for a specific permutation of directions.
     * @param permutation Mapping of command (0-3) to direction index (0-3).
     * @param sequence The sequence of commands to execute.
     * @return True if the exit 'E' is reached successfully.
     */
    private boolean simulatePath(int[] permutation, String sequence) {
        int currentRow = startRow;
        int currentCol = startCol;

        for (int i = 0; i < sequence.length(); i++) {
            int command = sequence.charAt(i) - '0';
            int directionIdx = permutation[command];

            currentRow += DIRECTION_OFFSETS[directionIdx][0];
            currentCol += DIRECTION_OFFSETS[directionIdx][1];

            if (!isValidMove(currentRow, currentCol)) {
                return false; // Hit a wall or boundary
            }

            if (maze[currentRow][currentCol] == 'E') {
                return true; // Successfully reached the exit
            }
        }
        return false; // Finished sequence without reaching exit
    }

    private boolean isValidMove(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && maze[r][c] != '#';
    }

    /**
     * Standard recursive algorithm to generate all permutations of an array.
     */
    private void generatePermutations(int[] arr, int index, List<int[]> result) {
        if (index == arr.length) {
            result.add(arr.clone());
            return;
        }
        for (int i = index; i < arr.length; i++) {
            swap(arr, index, i);
            generatePermutations(arr, index + 1, result);
            swap(arr, index, i); // backtrack
        }
    }

    private void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] maze = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String rowString = scanner.next();
            for (int j = 0; j < cols; j++) {
                maze[i][j] = rowString.charAt(j);
            }
        }

        String moveSequence = scanner.next();

        MazeNavigationSolver solver = new MazeNavigationSolver(rows, cols, maze);
        System.out.println(solver.solve(moveSequence));

        scanner.close();
    }
}

import java.util.Scanner;

/**
 * MazeSolver solves a grid-based navigation puzzle where we must determine 
 * how many unique mappings of digits (0-3) to directions (Up, Down, Left, Right)
 * result in the character successfully reaching the exit 'E'.
 */
public class MazeSolver {

    // Direction constants
    private static final int UP = 0;
    private static final int DOWN = 1;
    private static final int LEFT = 2;
    private static final int RIGHT = 3;

    // Row and Column deltas for the directions above
    private static final int[] ROW_DELTAS = {-1, 1, 0, 0};
    private static final int[] COL_DELTAS = {0, 0, -1, 1};

    private int rows;
    private int cols;
    private char[][] grid;
    private char[] instructions;
    private int startRow;
    private int startCol;

    /**
     * Represents the maze environment and the logic to simulate movement.
     */
    private class Maze {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        Maze(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        /**
         * Simulates the path based on a digit-to-direction mapping.
         * 
         * @param digitToDir An array where index is the instruction digit (0-3) 
         *                   and value is the direction (UP, DOWN, LEFT, or RIGHT).
         * @return true if the 'E' (Exit) is reached without hitting walls or bounds.
         */
        boolean simulate(int[] digitToDir, int startR, int startC, char[] path) {
            int currentRow = startR;
            int currentCol = startC;

            for (char instructionChar : path) {
                int digit = instructionChar - '0';
                int direction = digitToDir[digit];

                currentRow += ROW_DELTAS[direction];
                currentCol += COL_DELTAS[direction];

                // Check bounds
                if (currentRow < 0 || currentRow >= rows || currentCol < 0 || currentCol >= cols) {
                    return false;
                }

                // Check for walls
                if (grid[currentRow][currentCol] == '#') {
                    return false;
                }

                // Check for exit
                if (grid[currentRow][currentCol] == 'E') {
                    return true;
                }
            }

            return false;
        }
    }

    public void solve() {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        // 1. Parse Input
        this.rows = scanner.nextInt();
        this.cols = scanner.nextInt();
        this.grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            String rowString = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = rowString.charAt(j);
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        this.instructions = scanner.next().toCharArray();
        Maze maze = new Maze(rows, cols, grid);

        // 2. Calculate Successful Permutations
        int successCount = countValidMappings(maze);

        // 3. Output result
        System.out.println(successCount);
        scanner.close();
    }

    /**
     * Iterates through all 24 permutations of assigning the digits {0, 1, 2, 3}
     * to the four movement directions.
     */
    private int countValidMappings(Maze maze) {
        int count = 0;

        // We use four nested loops to find all permutations of {0, 1, 2, 3}.
        // i, j, k, l represent which digit is assigned to UP, DOWN, LEFT, and RIGHT respectively.
        for (int upDigit = 0; upDigit < 4; upDigit++) {
            for (int downDigit = 0; downDigit < 4; downDigit++) {
                if (downDigit == upDigit) continue;

                for (int leftDigit = 0; leftDigit < 4; leftDigit++) {
                    if (leftDigit == upDigit || leftDigit == downDigit) continue;

                    for (int rightDigit = 0; rightDigit < 4; rightDigit++) {
                        if (rightDigit == upDigit || rightDigit == downDigit || rightDigit == leftDigit) {
                            continue;
                        }

                        // Construct the mapping array for the current permutation
                        int[] digitToDir = new int[4];
                        digitToDir[upDigit] = UP;
                        digitToDir[downDigit] = DOWN;
                        digitToDir[leftDigit] = LEFT;
                        digitToDir[rightDigit] = RIGHT;

                        if (maze.simulate(digitToDir, startRow, startCol, instructions)) {
                            count++;
                        }
                    }
                }
            }
        }
        return count;
    }

    public static void main(String[] args) {
        new MazeSolver().solve();
    }
}

import java.util.*;

/**
 * BuggyBot simulates a robot navigating a maze.
 * The robot's movement is determined by a mapping of digits (0-3) to directions.
 * There are 24 possible mappings; this program counts how many lead to the exit.
 */
public class BuggyBot {

    /**
     * Represents a directional movement in the 2D grid.
     */
    enum Direction {
        LEFT(0, -1), RIGHT(0, 1), UP(-1, 0), DOWN(1, 0);

        final int dr, dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }

    /**
     * Represents a coordinate position in the maze.
     */
    static class Position {
        final int row, col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }

        Position move(Direction dir) {
            return new Position(row + dir.dr, col + dir.dc);
        }
    }

    /**
     * Manages the maze grid and provides spatial queries.
     */
    static class Maze {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        Maze(String[] mazeRows) {
            this.rows = mazeRows.length;
            this.cols = mazeRows[0].length();
            this.grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = mazeRows[i].toCharArray();
            }
        }

        char getCell(int r, int c) {
            return grid[r][c];
        }

        boolean isOutOfBounds(int r, int c) {
            return r < 0 || r >= rows || c < 0 || c >= cols;
        }

        boolean isObstacle(int r, int c) {
            return isOutOfBounds(r, c) || grid[r][c] == '#';
        }

        Position findPosition(char target) {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == target) {
                        return new Position(i, j);
                    }
                }
            }
            return null;
        }
    }

    /**
     * Contains logic to simulate the bot's journey through the maze.
     */
    static class Simulator {
        private final Maze maze;
        private final Position start;
        private final String commands;

        Simulator(Maze maze, Position start, String commands) {
            this.maze = maze;
            this.start = start;
            this.commands = commands;
        }

        /**
         * Simulates the bot's movement using a specific digit-to-direction mapping.
         * 
         * @param mapping An array where index [0-3] corresponds to the direction for that digit.
         * @return true if the bot reaches the 'E' cell.
         */
        boolean simulate(Direction[] mapping) {
            Position current = start;

            for (int i = 0; i < commands.length(); i++) {
                int digit = commands.charAt(i) - '0';
                Direction dir = mapping[digit];
                Position next = current.move(dir);

                // If the bot hits a wall or goes out of bounds, the path fails
                if (maze.isObstacle(next.row, next.col)) {
                    return false;
                }

                // If the bot reaches the exit, the path is successful
                if (maze.getCell(next.row, next.col) == 'E') {
                    return true;
                }

                // The bot can only continue moving if the cell is a path ('.') or the starting point ('S')
                char nextCell = maze.getCell(next.row, next.col);
                if (nextCell == '.' || nextCell == 'S') {
                    current = next;
                } else {
                    return false;
                }
            }
            return false;
        }
    }

    public static void main(String[] args) {
        Scanner scn = new Scanner(System.in);

        if (!scn.hasNextInt()) return;
        int n = scn.nextInt();
        int m = scn.nextInt();

        String[] mazeRows = new String[n];
        for (int i = 0; i < n; i++) {
            mazeRows[i] = scn.next();
        }
        String commands = scn.next();

        Maze maze = new Maze(mazeRows);
        Position startPos = maze.findPosition('S');
        Position endPos = maze.findPosition('E');

        if (startPos == null || endPos == null) {
            System.out.println(0);
            return;
        }

        Simulator simulator = new Simulator(maze, startPos, commands);

        // Generate all 24 possible mappings of {0,1,2,3} -> {L,R,U,D}
        List<Direction[]> allMappings = new ArrayList<>();
        generateMappings(Direction.values(), new boolean[4], new Direction[4], 0, allMappings);

        int successCount = 0;
        for (Direction[] mapping : allMappings) {
            if (simulator.simulate(mapping)) {
                successCount++;
            }
        }

        System.out.println(successCount);
        scn.close();
    }

    /**
     * Recursive backtracking to generate all permutations of Direction mappings.
     */
    private static void generateMappings(Direction[] source, boolean[] used, Direction[] current, int depth, List<Direction[]> results) {
        if (depth == source.length) {
            results.add(current.clone());
            return;
        }

        for (int i = 0; i < source.length; i++) {
            if (!used[i]) {
                used[i] = true;
                current[depth] = source[i];
                generateMappings(source, used, current, depth + 1, results);
                used[i] = false;
            }
        }
    }
}

