/**
 * Represents a direction in the 2D grid.
 */
class Direction {
    final int dr;
    final int dc;

    Direction(int dr, int dc) {
        this.dr = dr;
        this.dc = dc;
    }
}

/**
 * Represents the game board, storing the grid and essential landmarks.
 */
class Maze {
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private int startRow, startCol;
    private int endRow, endCol;

    public Maze(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        findLandmarks();
    }

    private void findLandmarks() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'S') {
                    startRow = r;
                    startCol = c;
                } else if (grid[r][c] == 'E') {
                    endRow = r;
                    endCol = c;
                }
            }
        }
    }

    public boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public boolean isWall(int r, int c) {
        return grid[r][c] == '#';
    }

    public int getStartRow() { return startRow; }
    public int getStartCol() { return startCol; }
    public int getEndRow() { return endRow; }
    public int getEndCol() { return endCol; }
}

/**
 * Contains the core logic for solving the maze puzzle.
 */
class MazeSolver {
    private static final Direction[] BASE_DIRECTIONS = {
        new Direction(-1, 0), // Up
        new Direction(1, 0),  // Down
        new Direction(0, -1), // Left
        new Direction(0, 1)   // Right
    };

    public void solve(FastReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = in.next().toCharArray();
        }

        Maze maze = new Maze(n, m, grid);
        int[] moveSequence = parseMoveSequence(in.next());

        List<Direction[]> allMappings = new ArrayList<>();
        generatePermutations(new Direction[4], new boolean[4], 0, allMappings);

        int successfulPathsCount = 0;
        for (Direction[] mapping : allMappings) {
            if (isPathSuccessful(maze, moveSequence, mapping)) {
                successfulPathsCount++;
            }
        }

        out.println(successfulPathsCount);
    }

    private int[] parseMoveSequence(String sequence) {
        int[] moves = new int[sequence.length()];
        for (int i = 0; i < sequence.length(); i++) {
            moves[i] = sequence.charAt(i) - '0';
        }
        return moves;
    }

    /**
     * Recursively generates all 24 permutations of the 4 directions.
     */
    private void generatePermutations(Direction[] current, boolean[] used, int depth, List<Direction[]> results) {
        if (depth == 4) {
            results.add(current.clone());
            return;
        }

        for (int i = 0; i < 4; i++) {
            if (!used[i]) {
                used[i] = true;
                current[depth] = BASE_DIRECTIONS[i];
                generatePermutations(current, used, depth + 1, results);
                used[i] = false;
            }
        }
    }

    /**
     * Simulates the movement on the maze using a specific direction mapping.
     */
    private boolean isPathSuccessful(Maze maze, int[] moves, Direction[] mapping) {
        int currentRow = maze.getStartRow();
        int currentCol = maze.getStartCol();

        for (int moveDigit : moves) {
            Direction dir = mapping[moveDigit];
            currentRow += dir.dr;
            currentCol += dir.dc;

            // Check if we reached the goal
            if (currentRow == maze.getEndRow() && currentCol == maze.getEndCol()) {
                return true;
            }

            // Check for failure conditions: out of bounds or hitting a wall
            if (!maze.isWithinBounds(currentRow, currentCol) || maze.isWall(currentRow, currentCol)) {
                return false;
            }
        }

        return false;
    }
}

/**
 * Utility class for fast input reading.
 */
class FastReader {
    private BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream));
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreElements()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                return null;
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }
}

