/**
 * A program to solve a maze navigation problem by testing all possible 
 * permutations of direction mappings for a given sequence of moves.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        MazeSolver solver = new MazeSolver(reader);
        solver.solve(out);

        out.flush();
        out.close();
    }

    /**
     * Represents the possible movement directions in the grid.
     */
    enum Direction {
        RIGHT(0, 1),
        LEFT(0, -1),
        UP(1, 0),   // Note: Per original logic, 'U' increases row index
        DOWN(-1, 0); // Note: Per original logic, 'D' decreases row index

        final int dRow;
        final int dCol;

        Direction(int dRow, int dCol) {
            this.dRow = dRow;
            this.dCol = dCol;
        }
    }

    /**
     * Represents the Maze environment.
     */
    static class Maze {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private int startRow;
        private int startCol;

        public Maze(int rows, int cols, String[] gridLines) {
            this.rows = rows;
            this.cols = cols;
            this.grid = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                String line = gridLines[i];
                for (int j = 0; j < cols; j++) {
                    char c = line.charAt(j);
                    if (c == 'S') {
                        startRow = i;
                        startCol = j;
                    }
                    grid[i][j] = c;
                }
            }
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }
        public int getStartRow() { return startRow; }
        public int getStartCol() { return startCol; }

        public boolean isOutOfBounds(int r, int c) {
            return r < 0 || r >= rows || c < 0 || c >= cols;
        }

        public boolean isWall(int r, int c) {
            return grid[r][c] == '#';
        }

        public boolean isEnd(int r, int c) {
            return grid[r][c] == 'E';
        }
    }

    /**
     * Handles the logic of finding valid direction permutations.
     */
    static class MazeSolver {
        private final FastReader reader;

        public MazeSolver(FastReader reader) {
            this.reader = reader;
        }

        public void solve(PrintWriter out) {
            int n = reader.nextInt();
            int m = reader.nextInt();

            String[] gridLines = new String[n];
            for (int i = 0; i < n; i++) {
                gridLines[i] = reader.next();
            }

            Maze maze = new Maze(n, m, gridLines);
            String digitSequence = reader.next();

            out.println(countValidPermutations(maze, digitSequence));
        }

        private int countValidPermutations(Maze maze, String digits) {
            int validCount = 0;
            Direction[] directions = Direction.values();

            // Generate all permutations of the 4 directions using nested loops
            // to assign a unique direction to each digit (0, 1, 2, 3).
            for (int i = 0; i < 4; i++) {
                for (int j = 0; j < 4; j++) {
                    if (j == i) continue;
                    for (int k = 0; k < 4; k++) {
                        if (k == i || k == j) continue;
                        for (int l = 0; l < 4; l++) {
                            if (l == i || l == j || l == k) continue;

                            Direction[] mapping = {
                                directions[i], 
                                directions[j], 
                                directions[k], 
                                directions[l]
                            };

                            if (isPathSuccessful(maze, digits, mapping)) {
                                validCount++;
                            }
                        }
                    }
                }
            }
            return validCount;
        }

        private boolean isPathSuccessful(Maze maze, String digits, Direction[] mapping) {
            int currR = maze.getStartRow();
            int currC = maze.getStartCol();

            for (int i = 0; i < digits.length(); i++) {
                int digit = digits.charAt(i) - '0';
                Direction move = mapping[digit];

                currR += move.dRow;
                currC += move.dCol;

                if (maze.isOutOfBounds(currR, currC) || maze.isWall(currR, currC)) {
                    return false;
                }

                if (maze.isEnd(currR, currC)) {
                    return true;
                }
            }
            return false;
        }
    }

    /**
     * Efficient input reader for large datasets.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * A refactored version of the BuggyRobot1 program.
 * This program calculates how many unique direction permutations allow a robot
 * to reach an exit 'E' from a starting position 'S' on a grid, following 
 * a sequence of instructions.
 */
public class BuggyRobot1 {

    private static final char START_CHAR = 'S';
    private static final char EXIT_CHAR = 'E';
    private static final char WALL_CHAR = '#';

    // Physical movement offsets corresponding to directions 0, 1, 2, 3
    private static final int[] DX = {0, 0, 1, -1};
    private static final int[] DY = {1, -1, 0, 0};
    private static final int NUM_DIRECTIONS = 4;

    public static void main(String[] args) {
        FastReader reader = new FastReader();

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] grid = new char[rows][cols];
            int startX = 0, startY = 0;

            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                grid[i] = line.toCharArray();
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == START_CHAR) {
                        startX = i;
                        startY = j;
                    }
                }
            }

            String instructionStr = reader.next();
            int[] instructions = new int[instructionStr.length()];
            for (int i = 0; i < instructionStr.length(); i++) {
                instructions[i] = instructionStr.charAt(i) - '0';
            }

            int successfulPermutations = countSuccessfulPaths(grid, startX, startY, instructions);
            System.out.println(successfulPermutations);

        } catch (Exception e) {
            // In a real-world scenario, use a logger.
            e.printStackTrace();
        }
    }

    /**
     * Orchestrates the simulation by generating all permutations of directions
     * and counting how many lead to the exit.
     */
    private static int countSuccessfulPaths(char[][] grid, int startX, int startY, int[] instructions) {
        List<int[]> permutations = new ArrayList<>();
        generatePermutations(new int[]{0, 1, 2, 3}, 0, permutations);

        int count = 0;
        int rows = grid.length;
        int cols = grid[0].length;

        for (int[] p : permutations) {
            if (simulate(grid, startX, startY, instructions, p, rows, cols)) {
                count++;
            }
        }
        return count;
    }

    /**
     * Simulates the robot's movement for a specific direction mapping.
     * 
     * @param grid The grid map.
     * @param sx Starting X coordinate.
     * @param sy Starting Y coordinate.
     * @param instructions Sequence of instruction indices.
     * @param mapping The permutation mapping instruction index to physical direction.
     * @param rows Grid height.
     * @param cols Grid width.
     * @return true if the robot reaches the exit 'E'.
     */
    private static boolean simulate(char[][] grid, int sx, int sy, int[] instructions, 
                                    int[] mapping, int rows, int cols) {
        int curX = sx;
        int curY = sy;

        for (int instructionIdx : instructions) {
            int directionIdx = mapping[instructionIdx];
            curX += DX[directionIdx];
            curY += DY[directionIdx];

            // Check bounds
            if (curX < 0 || curX >= rows || curY < 0 || curY >= cols) {
                return false;
            }

            // Check cell content
            char cell = grid[curX][curY];
            if (cell == EXIT_CHAR) {
                return true;
            }
            if (cell == WALL_CHAR) {
                return false;
            }
        }

        return false;
    }

    /**
     * Standard backtracking algorithm to generate all permutations of an array.
     */
    private static void generatePermutations(int[] arr, int index, List<int[]> result) {
        if (index == arr.length) {
            result.add(arr.clone());
            return;
        }
        for (int i = index; i < arr.length; i++) {
            swap(arr, index, i);
            generatePermutations(arr, index + 1, result);
            swap(arr, index, i);
        }
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Fast I/O utility for reading large inputs.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.ArrayList;
