/**
 * A solver for the maze navigation problem.
 * The goal is to find how many unique mappings of command digits to 
 * directions (Up, Down, Left, Right) allow a path from 'S' to 'E'.
 */
public class MazeSolver {

    /**
     * Represents a coordinate in the 2D maze.
     */
    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Encapsulates the maze grid and boundary/collision logic.
     */
    private static class Maze {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        public Maze(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        public boolean isWalkable(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != '#';
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }
        public char getCell(int r, int c) { return grid[r][c]; }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) return;

        int rows = sc.nextInt();
        int cols = sc.nextInt();
        char[][] grid = new char[rows][cols];

        Point start = null;
        Point end = null;

        // Parse the maze grid
        for (int r = 0; r < rows; r++) {
            String line = sc.next();
            for (int c = 0; c < cols; c++) {
                grid[r][c] = line.charAt(c);
                if (grid[r][c] == 'S') {
                    start = new Point(r, c);
                } else if (grid[r][c] == 'E') {
                    end = new Point(r, c);
                }
            }
        }

        String commands = sc.next();
        Maze maze = new Maze(rows, cols, grid);

        System.out.println(solve(maze, start, end, commands));
    }

    /**
     * Iterates through all possible direction permutations and counts successful paths.
     */
    private static int solve(Maze maze, Point start, Point end, String commands) {
        int validMappings = 0;
        List<int[]> permutations = new ArrayList<>();

        // Generate all permutations of the 4 direction indices: 0, 1, 2, 3
        generatePermutations(new int[]{0, 1, 2, 3}, 0, permutations);

        // Movement vectors: 0: Up, 1: Down, 2: Left, 3: Right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int[] p : permutations) {
            // p[i] represents the movement index mapped to command digit 'i'
            if (simulatePath(maze, start, end, commands, p, dr, dc)) {
                validMappings++;
            }
        }

        return validMappings;
    }

    /**
     * Simulates the movement for a specific command-to-direction mapping.
     * 
     * @param p Array where p[digit] = movement_index (0-3)
     * @return true if the path reaches the end point successfully
     */
    private static boolean simulatePath(Maze maze, Point start, Point end, String commands, 
                                        int[] p, int[] dr, int[] dc) {
        int currR = start.r;
        int currC = start.c;

        for (int i = 0; i < commands.length(); i++) {
            int digit = commands.charAt(i) - '0';
            int moveIdx = p[digit];

            currR += dr[moveIdx];
            currC += dc[moveIdx];

            // Check for boundary or wall collision
            if (!maze.isWalkable(currR, currC)) {
                return false;
            }

            // Check if the target is reached
            if (currR == end.r && currC == end.c) {
                return true;
            }
        }

        return false;
    }

    /**
     * Standard backtracking algorithm to generate all permutations of an array.
     */
    private static void generatePermutations(int[] arr, int index, List<int[]> result) {
        if (index == arr.length) {
            result.add(arr.clone());
            return;
        }
        for (int i = index; i < arr.length; i++) {
            swap(arr, index, i);
            generatePermutations(arr, index + 1, result);
            swap(arr, index, i); // backtrack
        }
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * RobotPathSolver simulates a robot moving through a grid based on a sequence of commands.
 * It tests all possible mappings of command IDs (0-3) to physical directions (Up, Down, Left, Right)
 * to find how many mappings allow the robot to reach the exit 'E' without hitting walls '#'.
 */
public class RobotPathSolver {

    /**
     * Represents the four possible movement directions.
     */
    enum Direction {
        UP(-1, 0),
        DOWN(1, 0),
        LEFT(0, -1),
        RIGHT(0, 1);

        private final int rowDelta;
        private final int colDelta;

        Direction(int rowDelta, int colDelta) {
            this.rowDelta = rowDelta;
            this.colDelta = colDelta;
        }

        public int getRowDelta() { return rowDelta; }
        public int getColDelta() { return colDelta; }
    }

    /**
     * Represents the game map.
     */
    static class Grid {
        private final int rows;
        private final int cols;
        private final char[][] cells;
        private final int startRow;
        private final int startCol;

        public Grid(int rows, int cols, char[][] cells, int startRow, int startCol) {
            this.rows = rows;
            this.cols = cols;
            this.cells = cells;
            this.startRow = startRow;
            this.startCol = startCol;
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }
        public char getCell(int r, int c) { return cells[r][c]; }
        public int getStartRow() { return startRow; }
        public int getStartCol() { return startCol; }

        public boolean isOutOfBounds(int r, int c) {
            return r < 0 || r >= rows || c < 0 || c >= cols;
        }
    }

    public static void main(String[] args) {
        try {
            RobotPathSolver solver = new RobotPathSolver();
            solver.run();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    public void run() throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        // 1. Parse Dimensions
        String line = reader.readLine();
        if (line == null) return;
        StringTokenizer st = new StringTokenizer(line);
        int rows = Integer.parseInt(st.nextToken());
        int cols = Integer.parseInt(st.nextToken());

        // 2. Parse Map
        char[][] cells = new char[rows][cols];
        int startRow = -1;
        int startCol = -1;

        for (int i = 0; i < rows; i++) {
            String rowString = reader.readLine();
            for (int j = 0; j < cols; j++) {
                cells[i][j] = rowString.charAt(j);
                if (cells[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                }
            }
        }
        Grid grid = new Grid(rows, cols, cells, startRow, startCol);

        // 3. Parse Commands
        // Handles both "012" and "0 1 2" formats
        String commandLine = reader.readLine().replaceAll("\\s+", "");
        int[] commands = new int[commandLine.length()];
        for (int i = 0; i < commandLine.length(); i++) {
            commands[i] = Character.getNumericValue(commandLine.charAt(i));
        }

        // 4. Solve
        System.out.println(countSuccessfulMappings(grid, commands));
    }

    /**
     * Iterates through all 24 permutations of mapping command IDs {0,1,2,3} to directions.
     */
    private int countSuccessfulMappings(Grid grid, int[] commands) {
        int successfulCount = 0;
        int[] cmdIds = {0, 1, 2, 3};

        // We use nested loops to generate all permutations of which command ID 
        // maps to which direction.
        for (int up : cmdIds) {
            for (int down : cmdIds) {
                if (down == up) continue;
                for (int left : cmdIds) {
                    if (left == up || left == down) continue;
                    for (int right : cmdIds) {
                        if (right == up || right == down || right == left) continue;

                        // mapping[commandId] = Direction
                        Direction[] mapping = new Direction[4];
                        mapping[up] = Direction.UP;
                        mapping[down] = Direction.DOWN;
                        mapping[left] = Direction.LEFT;
                        mapping[right] = Direction.RIGHT;

                        if (simulate(grid, commands, mapping)) {
                            successfulCount++;
                        }
                    }
                }
            }
        }
        return successfulCount;
    }

    /**
     * Simulates the robot's movement using a specific direction mapping.
     * 
     * @return true if the robot hits 'E' without hitting '#' or going out of bounds.
     */
    private boolean simulate(Grid grid, int[] commands, Direction[] mapping) {
        int currentRow = grid.getStartRow();
        int currentCol = grid.getStartCol();

        for (int cmd : commands) {
            Direction dir = mapping[cmd];
            currentRow += dir.getRowDelta();
            currentCol += dir.getColDelta();

            if (grid.isOutOfBounds(currentRow, currentCol)) {
                return false;
            }

            char currentCell = grid.getCell(currentRow, currentCol);
            if (currentCell == '#') {
                return false;
            }
            if (currentCell == 'E') {
                return true;
            }
        }

        return false; // Finished all commands without hitting 'E'
    }
}

import java.util.*;

/**
 * A refactored solution to solve the maze movement problem.
 * The goal is to find how many digit-to-direction mappings allow a path from 'S' to 'E'.
 */
public class MazeSolver {

    // Direction deltas: Up, Down, Left, Right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        // Parse dimensions
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // Parse grid
        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String rowString = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = rowString.charAt(j);
            }
        }

        // Parse movement instructions
        String instructions = scanner.next();
        scanner.close();

        Maze maze = new Maze(grid, rows, cols);
        int successfulMappings = solve(maze, instructions);

        System.out.println(successfulMappings);
    }

    /**
     * Orchestrates the solving process by testing all possible direction permutations.
     */
    private static int solve(Maze maze, String instructions) {
        List<int[]> allPermutations = generatePermutations(new int[]{0, 1, 2, 3});
        int successCount = 0;

        for (int[] mapping : allPermutations) {
            if (canReachEnd(maze, instructions, mapping)) {
                successCount++;
            }
        }

        return successCount;
    }

    /**
     * Simulates movement through the maze using a specific digit-to-direction mapping.
     * 
     * @param maze The maze structure.
     * @param instructions The string of movement digits.
     * @param mapping An array where mapping[digit-1] = directionIndex (0-3).
     * @return true if the end position is reached without hitting walls or bounds.
     */
    private static boolean canReachEnd(Maze maze, String instructions, int[] mapping) {
        int currentRow = maze.getStart().row;
        int currentCol = maze.getStart().col;

        for (char cmd : instructions.toCharArray()) {
            int digitIndex = cmd - '1';
            int directionIndex = mapping[digitIndex];

            currentRow += DR[directionIndex];
            currentCol += DC[directionIndex];

            if (maze.isInvalidMove(currentRow, currentCol)) {
                return false;
            }

            if (maze.isEndPosition(currentRow, currentCol)) {
                return true;
            }
        }

        return false;
    }

    /**
     * Generates all possible permutations of the provided array using backtracking.
     */
    private static List<int[]> generatePermutations(int[] array) {
        List<int[]> result = new ArrayList<>();
        backtrack(result, array, 0);
        return result;
    }

    private static void backtrack(List<int[]> result, int[] array, int start) {
        if (start == array.length) {
            result.add(array.clone());
            return;
        }
        for (int i = start; i < array.length; i++) {
            swap(array, start, i);
            backtrack(result, array, start + 1);
            swap(array, start, i); // backtrack
        }
    }

    private static void swap(int[] array, int i, int j) {
        int temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }

    /**
     * Represents a coordinate in the grid.
     */
    static class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Encapsulates the grid data and boundary checking logic.
     */
    static class Maze {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private Position start;
        private Position end;

        Maze(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            findSpecialPoints();
        }

        private void findSpecialPoints() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == 'S') {
                        start = new Position(r, c);
                    } else if (grid[r][c] == 'E') {
                        end = new Position(r, c);
                    }
                }
            }
        }

        public Position getStart() {
            return start;
        }

        /**
         * Checks if a position is outside the grid or hits a wall.
         */
        boolean isInvalidMove(int r, int c) {
            return r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] == '#';
        }

        /**
         * Checks if the given position is the exit.
         */
        boolean isEndPosition(int r, int c) {
            return r == end.row && c == end.col;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution for the Maze Traversal problem.
 * 
 * Problem Summary:
 * Given a maze with a start ('S'), an end ('E'), and walls ('#'), 
 * and a sequence of movement commands (digits '0'-'3'), find how many 
 * unique mappings of command digits to direction vectors (Up, Down, Left, Right)
 * lead from 'S' to 'E'.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            MazeSolver solver = new MazeSolver();
            solver.solve(reader, writer);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Handles the core logic for solving the maze problem.
     */
    static class MazeSolver {

        // Movement vectors: index 0: Down, 1: Right, 2: Up, 3: Left
        private static final int[][] DIRECTION_VECTORS = {
            {1, 0},  // Down
            {0, 1},  // Right
            {-1, 0}, // Up
            {0, -1}  // Left
        };

        private static final int NUM_DIRECTIONS = 4;

        /**
         * Orchestrates the reading of input, permutation generation, and result calculation.
         */
        public void solve(FastReader in, PrintWriter out) {
            int rows = in.nextInt();
            int cols = in.nextInt();

            char[][] maze = new char[rows][cols];
            Position startPosition = null;

            for (int r = 0; r < rows; r++) {
                String rowString = in.next();
                if (rowString == null) break;
                maze[r] = rowString.toCharArray();

                // Identify the starting point 'S' once during input reading
                if (startPosition == null) {
                    for (int c = 0; c < cols; c++) {
                        if (maze[r][c] == 'S') {
                            startPosition = new Position(r, c);
                            break;
                        }
                    }
                }
            }

            String commands = in.next();
            if (commands == null || startPosition == null) {
                out.println(0);
                return;
            }

            // Generate all 24 permutations of the 4 possible direction indices
            List<int[]> directionPermutations = new ArrayList<>();
            generatePermutations(new int[NUM_DIRECTIONS], new boolean[NUM_DIRECTIONS], 0, directionPermutations);

            int successfulMappingCount = 0;
            for (int[] mapping : directionPermutations) {
                if (isPathSuccessful(maze, startPosition, commands, mapping)) {
                    successfulMappingCount++;
                }
            }

            out.println(successfulMappingCount);
        }

        /**
         * Simulates the movement following the command string using a specific mapping.
         * 
         * @param maze The grid containing 'S', 'E', '#', and '.'
         * @param start The starting position
         * @param commands A string of digits representing command indices
         * @param mapping A permutation mapping command indices to direction indices
         * @return true if the path reaches 'E' without hitting walls or boundaries
         */
        private boolean isPathSuccessful(char[][] maze, Position start, String commands, int[] mapping) {
            int currentRow = start.row;
            int currentCol = start.col;
            int maxRows = maze.length;
            int maxCols = maze[0].length;

            for (int i = 0; i < commands.length(); i++) {
                int commandDigit = commands.charAt(i) - '0';
                int directionIndex = mapping[commandDigit];

                currentRow += DIRECTION_VECTORS[directionIndex][0];
                currentCol += DIRECTION_VECTORS[directionIndex][1];

                // Boundary Check
                if (currentRow < 0 || currentRow >= maxRows || currentCol < 0 || currentCol >= maxCols) {
                    return false;
                }

                // Wall Check
                if (maze[currentRow][currentCol] == '#') {
                    return false;
                }

                // Goal Check
                if (maze[currentRow][currentCol] == 'E') {
                    return true;
                }
            }

            return false;
        }

        /**
         * Generates all possible permutations of length 4 using backtracking.
         */
        private void generatePermutations(int[] current, boolean[] used, int depth, List<int[]> results) {
            if (depth == NUM_DIRECTIONS) {
                results.add(current.clone());
                return;
            }

            for (int i = 0; i < NUM_DIRECTIONS; i++) {
                if (!used[i]) {
                    used[i] = true;
                    current[depth] = i;
                    generatePermutations(current, used, depth + 1, results);
                    used[i] = false;
                }
            }
        }
    }

    /**
     * Simple immutable record-like class for coordinate representation.
     */
    static class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Fast I/O utility class for efficient data reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream), 32768);
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input stream", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String token = next();
            return token != null ? Integer.parseInt(token) : 0;
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver for the grid-based pathfinding problem.
 * The goal is to count how many digit-to-direction mappings allow a player 
 * to reach the destination 'E' from starting point 'S'.
 */
public class Main {

    // Direction vectors: 0: Down, 1: Up, 2: Right, 3: Left
    private static final int[] DR = {1, -1, 0, 0};
    private static final int[] DC = {0, 0, 1, -1};

    private static int rows, cols;
    private static char[][] grid;
    private static int startRow, startCol;
    private static int[] path;
    private static int validMappingCount = 0;

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader(System.in);

        // Read grid dimensions
        String firstLine = reader.next();
        if (firstLine == null) return;
        rows = Integer.parseInt(firstLine);
        cols = reader.nextInt();

        grid = new char[rows][cols];
        initializeGrid(reader);

        // Read path sequence
        String pathString = reader.next();
        if (pathString == null) {
            System.out.println(0);
            return;
        }
        path = parsePath(pathString);

        // Generate all permutations of directions assigned to digits 0-3
        generateAndTestPermutations();

        System.out.println(validMappingCount);
    }

    /**
     * Reads the grid and locates the starting position 'S'.
     */
    private static void initializeGrid(FastReader reader) throws IOException {
        for (int i = 0; i < rows; i++) {
            String rowStr = reader.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = rowStr.charAt(j);
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                }
            }
        }
    }

    /**
     * Converts the path string into an integer array for faster access.
     */
    private static int[] parsePath(String pathStr) {
        int[] p = new int[pathStr.length()];
        for (int i = 0; i < pathStr.length(); i++) {
            p[i] = pathStr.charAt(i) - '0';
        }
        return p;
    }

    /**
     * Uses backtracking to find all permutations of direction indices (0-3).
     */
    private static void generateAndTestPermutations() {
        int[] directionMap = new int[4]; // Maps digit (0-3) to a direction index
        boolean[] used = new boolean[4];
        backtrack(directionMap, used, 0);
    }

    private static void backtrack(int[] directionMap, boolean[] used, int index) {
        if (index == 4) {
            if (canReachDestination(directionMap)) {
                validMappingCount++;
            }
            return;
        }

        for (int i = 0; i < 4; i++) {
            if (!used[i]) {
                used[i] = true;
                directionMap[index] = i;
                backtrack(directionMap, used, index + 1);
                used[i] = false;
            }
        }
    }

    /**
     * Simulates the movement on the grid based on a specific digit-to-direction mapping.
     * 
     * @param directionMap An array where directionMap[digit] = directionIndex.
     * @return true if the path reaches 'E' without hitting a wall or going out of bounds.
     */
    private static boolean canReachDestination(int[] directionMap) {
        int r = startRow;
        int c = startCol;

        for (int moveDigit : path) {
            // Boundary check before looking at the current cell
            if (r < 0 || r >= rows || c < 0 || c >= cols) return false;

            // Check cell properties
            if (grid[r][c] == 'E') return true;
            if (grid[r][c] == '#') return false;

            // Perform move
            int dirIdx = directionMap[moveDigit];
            r += DR[dirIdx];
            c += DC[dirIdx];
        }

        // Final check after all moves are completed
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == 'E';
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * Problem: Codeforces 908B - Find the number of ways to reach the exit 'E' 
 * given a sequence of moves and a set of direction permutations.
 */
public class Codeforces908B {

    // Direction vectors: 0: Down, 1: Right, 2: Up, 3: Left
    private static final int[] ROW_OFFSETS = {1, 0, -1, 0};
    private static final int[] COL_OFFSETS = {0, 1, 0, -1};

    private static final char START_CHAR = 'S';
    private static final char EXIT_CHAR = 'E';
    private static final char WALL_CHAR = '#';

    /**
     * Represents a coordinate on the grid.
     */
    private static class Position {
        int row;
        int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
        }

        String sequenceStr = scanner.next();
        int[] moveSequence = parseSequence(sequenceStr);

        Position startPos = findStart(grid, rows, cols);
        if (startPos == null) {
            System.out.println(0);
            return;
        }

        int successfulPaths = countSuccessfulPaths(grid, rows, cols, startPos, moveSequence);
        System.out.println(successfulPaths);

        scanner.close();
    }

    /**
     * Parses the input string of digits into an integer array.
     */
    private static int[] parseSequence(String sequence) {
        int[] moves = new int[sequence.length()];
        for (int i = 0; i < sequence.length(); i++) {
            moves[i] = Character.getNumericValue(sequence.charAt(i));
        }
        return moves;
    }

    /**
     * Locates the starting position 'S' in the grid.
     */
    private static Position findStart(char[][] grid, int rows, int cols) {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == START_CHAR) {
                    return new Position(i, j);
                }
            }
        }
        return null;
    }

    /**
     * Iterates through all permutations of directions to count successful paths.
     */
    private static int countSuccessfulPaths(char[][] grid, int rows, int cols, Position start, int[] sequence) {
        int count = 0;
        List<int[]> permutations = new ArrayList<>();
        generatePermutations(new int[]{0, 1, 2, 3}, 0, permutations);

        for (int[] permutation : permutations) {
            if (simulatePath(grid, rows, cols, start, sequence, permutation)) {
                count++;
            }
        }
        return count;
    }

    /**
     * Standard backtracking algorithm to generate all permutations of an array.
     */
    private static void generatePermutations(int[] array, int index, List<int[]> result) {
        if (index == array.length) {
            result.add(array.clone());
            return;
        }
        for (int i = index; i < array.length; i++) {
            swap(array, index, i);
            generatePermutations(array, index + 1, result);
            swap(array, index, i);
        }
    }

    private static void swap(int[] array, int i, int j) {
        int temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }

    /**
     * Simulates a single path based on the provided direction permutation.
     * 
     * @return true if the path hits the exit 'E', false otherwise.
     */
    private static boolean simulatePath(char[][] grid, int rows, int cols, Position start, int[] sequence, int[] permutation) {
        int currentRow = start.row;
        int currentCol = start.col;

        for (int moveCmd : sequence) {
            // The move command (0-3) tells us which index of the permutation to use
            int directionIdx = permutation[moveCmd];

            currentRow += ROW_OFFSETS[directionIdx];
            currentCol += COL_OFFSETS[directionIdx];

            // Check boundaries
            if (currentRow < 0 || currentRow >= rows || currentCol < 0 || currentCol >= cols) {
                return false;
            }

            // Check obstacles
            if (grid[currentRow][currentCol] == WALL_CHAR) {
                return false;
            }

            // Check goal
            if (grid[currentRow][currentCol] == EXIT_CHAR) {
                return true;
            }
        }

        return false;
    }
}

