/**
 * A solver for the maze path permutation problem.
 * The goal is to find how many unique mappings of digits (0-3) to 
 * directions (N, E, S, W) allow a path to reach the exit 'E'.
 */
public class MazeSolver {

    /**
     * Represents the four cardinal directions and their coordinate offsets.
     */
    enum Direction {
        NORTH(-1, 0),
        EAST(0, 1),
        SOUTH(1, 0),
        WEST(0, -1);

        final int rowOffset;
        final int colOffset;

        Direction(int rowOffset, int colOffset) {
            this.rowOffset = rowOffset;
            this.colOffset = colOffset;
        }
    }

    /**
     * Represents the maze grid and provides spatial queries.
     */
    static class Maze {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final int startRow;
        private final int startCol;

        public Maze(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;

            // Find the starting position 'S'
            int sR = -1;
            int sC = -1;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 'S') {
                        sR = i;
                        sC = j;
                        break;
                    }
                }
                if (sR != -1) break;
            }
            this.startRow = sR;
            this.startCol = sC;
        }

        public boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public char getCell(int r, int c) {
            return grid[r][c];
        }

        public int getStartRow() { return startRow; }
        public int getStartCol() { return startCol; }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        char[][] grid = new char[rows][cols];

        for (int i = 0; i < rows; i++) {
            grid[i] = scanner.next().toCharArray();
        }

        String key = scanner.next();
        scanner.close();

        Maze maze = new Maze(rows, cols, grid);
        int successfulMappings = countValidMappings(maze, key);

        System.out.println(successfulMappings);
    }

    /**
     * Orchestrates the permutation generation and counts successful simulations.
     */
    private static int countValidMappings(Maze maze, String key) {
        Direction[] mapping = new Direction[4];
        Direction[] directions = Direction.values();
        return generatePermutations(maze, key, mapping, directions, 0);
    }

    /**
     * Uses backtracking to generate all 24 permutations of direction mappings.
     */
    private static int generatePermutations(Maze maze, String key, Direction[] mapping, 
                                            Direction[] available, int index) {
        if (index == 4) {
            return simulatePath(maze, key, mapping) ? 1 : 0;
        }

        int count = 0;
        for (int i = index; i < 4; i++) {
            swap(available, index, i);
            mapping[index] = available[index];
            count += generatePermutations(maze, key, mapping, available, index + 1);
            swap(available, index, i); // backtrack
        }
        return count;
    }

    private static void swap(Direction[] arr, int i, int j) {
        Direction temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Simulates the movement through the maze based on the current digit-to-direction mapping.
     * Returns true if the 'E' (exit) is reached.
     */
    private static boolean simulatePath(Maze maze, String key, Direction[] mapping) {
        int currR = maze.getStartRow();
        int currC = maze.getStartCol();

        for (int i = 0; i < key.length(); i++) {
            int digit = key.charAt(i) - '0';
            Direction dir = mapping[digit];

            int nextR = currR + dir.rowOffset;
            int nextC = currC + dir.colOffset;

            // 1. Check bounds
            if (!maze.isWithinBounds(nextR, nextC)) {
                return false;
            }

            char cell = maze.getCell(nextR, nextC);

            // 2. Check walls
            if (cell == '#') {
                return false;
            }

            // 3. Check exit
            if (cell == 'E') {
                return true;
            }

            // Move to next position
            currR = nextR;
            currC = nextC;
        }

        return false;
    }
}

import java.util.*;

/**
 * A solution to determine how many movement permutations allow an agent 
 * starting at 'S' to reach the exit 'E' on a grid without hitting walls '#'.
 */
public class Codeforces {

    // Direction mapping: 0: Down, 1: Left, 2: Right, 3: Up
    private static final int[] DR = {1, 0, 0, -1};
    private static final int[] DC = {0, -1, 1, 0};

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) {
            return;
        }

        int rows = sc.nextInt();
        int cols = sc.nextInt();

        char[][] grid = new char[rows][cols];
        int startRow = 0;
        int startCol = 0;

        // Parse the grid and find the starting position 'S'
        for (int i = 0; i < rows; i++) {
            String line = sc.next();
            grid[i] = line.toCharArray();
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        // The sequence of commands (e.g., "0123")
        String commands = sc.next();

        int successCount = solve(grid, startRow, startCol, commands);
        System.out.println(successCount);

        sc.close();
    }

    /**
     * Orchestrates the simulation by generating all possible command permutations
     * and counting how many result in reaching the exit.
     */
    private static int solve(char[][] grid, int startRow, int startCol, String commands) {
        List<String> permutations = new ArrayList<>();
        generatePermutations("", new boolean[4], permutations);

        int successCount = 0;
        for (String p : permutations) {
            if (canReachExit(grid, startRow, startCol, commands, p)) {
                successCount++;
            }
        }
        return successCount;
    }

    /**
     * Recursively generates all 24 permutations of the digits 0, 1, 2, and 3.
     */
    private static void generatePermutations(String current, boolean[] used, List<String> result) {
        if (current.length() == 4) {
            result.add(current);
            return;
        }

        for (int i = 0; i < 4; i++) {
            if (!used[i]) {
                used[i] = true;
                generatePermutations(current + i, used, result);
                used[i] = false;
            }
        }
    }

    /**
     * Simulates the movement for a specific permutation of command mappings.
     * 
     * @param grid The movement grid.
     * @param startRow Initial row.
     * @param startCol Initial column.
     * @param commands The input command sequence.
     * @param permutation A string mapping which command digit triggers which direction.
     * @return true if 'E' is reached, false if the agent hits a wall or goes out of bounds.
     */
    private static boolean canReachExit(char[][] grid, int startRow, int startCol, String commands, String permutation) {
        int currentRow = startRow;
        int currentCol = startCol;
        int rows = grid.length;
        int cols = grid[0].length;

        for (char cmd : commands.toCharArray()) {
            // Find which direction index this command character triggers
            int directionIdx = -1;
            for (int i = 0; i < 4; i++) {
                if (cmd == permutation.charAt(i)) {
                    directionIdx = i;
                    break;
                }
            }

            // Move agent
            currentRow += DR[directionIdx];
            currentCol += DC[directionIdx];

            // Check boundaries and obstacles
            if (isOutOfBounds(currentRow, currentCol, rows, cols) || grid[currentRow][currentCol] == '#') {
                return false;
            }

            // Check if target reached
            if (grid[currentRow][currentCol] == 'E') {
                return true;
            }
        }

        return false;
    }

    private static boolean isOutOfBounds(int r, int c, int maxR, int maxC) {
        return r < 0 || r >= maxR || c < 0 || c >= maxC;
    }
}

