/**
 * Defines the possible movements and their coordinate offsets.
 */
enum Movement {
    WEST(0, -1),
    NORTH(-1, 0),
    EAST(0, 1),
    SOUTH(1, 0);

    final int dr;
    final int dc;

    Movement(int dr, int dc) {
        this.dr = dr;
        this.dc = dc;
