/**
 * Logic for solving the pathfinding puzzle.
 */
class PathSolver {
    private Grid grid;
    private int[] instructionSequence;
    private Position startPosition;

    public void solve(InputReader in, PrintWriter out) {
        int n = in.nextInt();
        int m = in.nextInt();
        char[][] gridData = in.nextCharTable(n, m);
        this.grid = new Grid(n, m, gridData);
        this.startPosition = grid.findStartingPosition();

        String moveString = in.next();
        this.instructionSequence = new int[moveString.length()];
        for (int i = 0; i < moveString.length(); i++) {
            instructionSequence[i] = moveString.charAt(i) - '0';
        }

        int successfulPaths = countValidPermutations();
        out.println(successfulPaths);
    }

    private int countValidPermutations() {
        List<int[]> permutations = new ArrayList<>();
        generatePermutations(new int[]{0, 1, 2, 3}, 0, permutations);

        int count = 0;
        for (int[] mapping : permutations) {
            if (canReachExit(mapping)) {
                count++;
            }
        }
        return count;
    }

    /**
     * Standard recursive permutation generator.
     */
    private void generatePermutations(int[] arr, int index, List<int[]> result) {
        if (index == arr.length) {
            result.add(arr.clone());
            return;
        }
        for (int i = index; i < arr.length; i++) {
            swap(arr, index, i);
            generatePermutations(arr, index + 1, result);
            swap(arr, index, i);
        }
    }

    private void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Simulates the movement for a specific permutation of directions.
     */
    private boolean canReachExit(int[] directionMapping) {
        Position current = startPosition;

        for (int moveIdx : instructionSequence) {
            int mappedDirIndex = directionMapping[moveIdx];
            Movement move = Movement.fromIndex(mappedDirIndex);

            int nextR = current.row + move.dr;
            int nextC = current.col + move.dc;

            if (grid.isOutOfBounds(nextR, nextC) || grid.isWall(nextR, nextC)) {
                return false;
            }

            current = new Position(nextR, nextC);

            if (grid.getCell(nextR, nextC) == 'E') {
                return true;
            }
        }
        return false;
    }
}

/**
 * High-performance input reader.
 */
class InputReader implements AutoCloseable {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public InputReader(InputStream in) {
        this.reader = new BufferedReader(new InputStreamReader(in));
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            String line = readLine();
            if (line == null) return null;
            tokenizer = new StringTokenizer(line);
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }

    public char[][] nextCharTable(int rows, int columns) {
        char[][] table = new char[rows][columns];
        for (int i = 0; i < rows; i++) {
            String line = next();
            for (int j = 0; j < columns; j++) {
                table[i][j] = line.charAt(j);
            }
        }
        return table;
    }

    private String readLine() {
        try {
            return reader.readLine();
        } catch (IOException e) {
            throw new RuntimeException("Error reading input", e);
        }
    }

    @Override
    public void close() throws IOException {
        reader.close();
    }
}

