import java.util.Scanner;

/**
 * MazeSolver calculates how many unique direction-to-command mappings
 * allow a sequence of moves to successfully reach the exit from the start.
 */
public class MazeSolver {

    // Direction vectors: Right, Left, Up, Down
    private static final int[][] DIRECTIONS = {
            {0, 1},
            {0, -1},
            {-1, 0},
            {1, 0}
    };

    /**
     * Represents a coordinate in the maze.
     */
    private static class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (!(obj instanceof Position)) return false;
            Position other = (Position) obj;
            return this.row == other.row && this.col == other.col;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] maze = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            maze[i] = scanner.next().toCharArray();
        }

        String commandString = scanner.next();
        char[] commands = commandString.toCharArray();

        MazeSolver solver = new MazeSolver();
        int result = solver.solve(rows, cols, maze, commands);
        System.out.println(result);

        scanner.close();
    }

    /**
     * Orchestrates the solving process.
     */
    public int solve(int rows, int cols, char[][] maze, char[] commands) {
        Position startPos = findPosition(maze, 'S');
        Position endPos = findPosition(maze, 'E');

        if (startPos == null || endPos == null) {
            return 0;
        }

        List<int[]> permutations = new ArrayList<>();
        generatePermutations(new int[]{0, 1, 2, 3}, 0, permutations);

        int successCount = 0;
        for (int[] mapping : permutations) {
            if (isPathSuccessful(startPos, endPos, maze, commands, mapping)) {
                successCount++;
            }
        }

        return successCount;
    }

    /**
     * Finds the coordinates of a specific character in the maze.
     */
    private Position findPosition(char[][] maze, char target) {
        for (int r = 0; r < maze.length; r++) {
            for (int c = 0; c < maze[0].length; c++) {
                if (maze[r][c] == target) {
                    return new Position(r, c);
                }
            }
        }
        return null;
    }

    /**
     * Simulates the path based on a specific mapping of command indices to direction indices.
     * 
     * @param mapping An array where mapping[i] is the index of the direction used by command 'i'.
     */
    private boolean isPathSuccessful(Position start, Position end, char[][] maze, char[] commands, int[] mapping) {
        int currentRow = start.row;
        int currentCol = start.col;
        int rows = maze.length;
        int cols = maze[0].length;

        for (char cmd : commands) {
            int commandIdx = cmd - '0';
            int directionIdx = mapping[commandIdx];

            currentRow += DIRECTIONS[directionIdx][0];
            currentCol += DIRECTIONS[directionIdx][1];

            // Check bounds and walls
            if (isOutOfBounds(currentRow, currentCol, rows, cols) || maze[currentRow][currentCol] == '#') {
                return false;
            }

            // Check if exit is reached
            if (currentRow == end.row && currentCol == end.col) {
                return true;
            }
        }

        return false;
    }

    private boolean isOutOfBounds(int r, int c, int rows, int cols) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }

    /**
     * Generates all permutations of the array using backtracking.
     */
    private void generatePermutations(int[] array, int index, List<int[]> results) {
        if (index == array.length) {
            results.add(array.clone());
            return;
        }

        for (int i = index; i < array.length; i++) {
            swap(array, index, i);
            generatePermutations(array, index + 1, results);
            swap(array, index, i); // backtrack
        }
    }

    private void swap(int[] array, int i, int j) {
        int temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }
}

