/**
 * Represents the 2D maze environment.
 */
class Maze {
    private final char[][] grid;
    private final int rows;
    private final int cols;
    private Position startPosition;

    public Maze(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
        findStart();
    }

    private void findStart() {
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'S') {
                    startPosition = new Position(r, c);
                    return;
                }
            }
        }
    }

    public Position getStartPosition() {
        return startPosition;
    }

    public boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }

    public boolean isWall(int r, int c) {
        return grid[r][c] == '#';
    }

    public boolean isExit(int r, int c) {
        return grid[r][c] == 'E';
    }
}

/**
 * Represents a coordinate in the maze.
 */
class Position {
    final int r, c;

    Position(int r, int c) {
        this.r = r;
        this.c = c;
    }
}

/**
 * Encapsulates movement logic.
 */
enum Direction {
    DOWN(1, 0),
    UP(-1, 0),
    RIGHT(0, 1),
    LEFT(0, -1);

    final int dr;
    final int dc;

    Direction(int dr, int dc) {
        this.dr = dr;
        this.dc = dc;
    }

    public static Direction fromIndex(int index) {
        return values()[index];
    }
}

/**
 * Core engine that handles permutation generation and path simulation.
 */
class SolverEngine {
    private final Maze maze;
    private final int[] instructions;

    public SolverEngine(Maze maze, int[] instructions) {
        this.maze = maze;
        this.instructions = instructions;
    }

    /**
     * Solves the problem by iterating through all permutations of direction mappings.
     * @return The count of valid mappings.
     */
    public int solve() {
        int successfulPaths = 0;
        List<int[]> permutations = new ArrayList<>();
        generatePermutations(new int[]{0, 1, 2, 3}, 0, permutations);

        for (int[] mapping : permutations) {
            if (isValidPath(mapping)) {
                successfulPaths++;
            }
        }
        return successfulPaths;
    }

    /**
     * Simulates the path for a specific mapping of digit -> Direction index.
     */
    private boolean isValidPath(int[] digitToDirMapping) {
        Position current = maze.getStartPosition();

        for (int digit : instructions) {
            Direction dir = Direction.fromIndex(digitToDirMapping[digit]);
            int nextR = current.r + dir.dr;
            int nextC = current.c + dir.dc;

            // Check if the move results in an invalid state
            if (maze.isOutOfBounds(nextR, nextC) || maze.isWall(nextR, nextC)) {
                return false;
            }

            current = new Position(nextR, nextC);

            // If we reach the exit, the path is successful
            if (maze.isExit(current.r, current.c)) {
                return true;
            }
        }

        return false;
    }

    /**
     * Standard recursive backtracking to find all permutations of an array.
     */
    private void generatePermutations(int[] arr, int index, List<int[]> result) {
        if (index == arr.length) {
            result.add(arr.clone());
            return;
        }
        for (int i = index; i < arr.length; i++) {
            swap(arr, index, i);
            generatePermutations(arr, index + 1, result);
            swap(arr, index, i);
        }
    }

    private void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

