/**
 * A program that simulates a bot navigating a maze given a sequence of instructions.
 * The goal is to find how many permutations of direction mappings allow the bot 
 * to reach the destination.
 */
public class NewYearAndBuggyBot {

    /**
     * Represents a coordinate in the 2D grid.
     */
    private record Position(int row, int col) {}

    /**
     * Represents the maze grid and its properties.
     */
    private static class Maze {
        private final int rows;
        private final int cols;
        private final boolean[][] wallGrid;
        private final Position start;
        private final Position end;

        public Maze(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.wallGrid = new boolean[rows][cols];

            Position startPos = null;
            Position endPos = null;

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    char cell = grid[r][c];
                    if (cell == 'S') {
                        startPos = new Position(r, c);
                    } else if (cell == 'E') {
                        endPos = new Position(r, c);
                    } else if (cell == '#') {
                        wallGrid[r][c] = true;
                    }
                }
            }
            this.start = startPos;
            this.end = endPos;
        }

        public boolean isWalkable(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && !wallGrid[r][c];
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }
        public Position getStart() { return start; }
        public Position getEnd() { return end; }
    }

    /**
     * Logic for moving the bot through the maze.
     */
    private static class BotSimulator {
        // Mapping based on original code's arithmetic:
        // 0: Left, 1: Up, 2: Right, 3: Down
        private static final int[][] MOVEMENT_VECTORS = {
            {0, -1},  // 0
            {-1, 0},  // 1
            {0, 1},   // 2
            {1, 0}    // 3
        };

        /**
         * Simulates the movement of the bot using a specific permutation of directions.
         *
         * @param maze The maze environment.
         * @param directionMapping An array where index is the instruction digit 
         *                         and value is the actual movement index.
         * @param instructions The sequence of movement instructions.
         * @return true if the bot reaches the end without hitting walls or boundaries.
         */
        public boolean simulate(Maze maze, int[] directionMapping, String instructions) {
            int currR = maze.getStart().row();
            int currC = maze.getStart().col();
            Position target = maze.getEnd();

            for (int i = 0; i < instructions.length(); i++) {
                // If we reached the target before using all instructions, we can stop
                if (currR == target.row() && currC == target.col()) {
                    break;
                }

                int instructionDigit = instructions.charAt(i) - '0';
                int mappedDirection = directionMapping[instructionDigit];

                int[] vector = MOVEMENT_VECTORS[mappedDirection];
                currR += vector[0];
                currC += vector[1];

                if (!maze.isWalkable(currR, currC)) {
                    return false;
                }
            }

            return currR == target.row() && currC == target.col();
        }
    }

    /**
     * Orchestrates the permutation generation and counting.
     */
    private static class Solver {
        private final Maze maze;
        private final String instructions;
        private final BotSimulator simulator;
        private int successCount = 0;

        public Solver(Maze maze, String instructions) {
            this.maze = maze;
            this.instructions = instructions;
            this.simulator = new BotSimulator();
        }

        public int solve() {
            int[] currentPermutation = new int[4];
            boolean[] used = new boolean[4];
            backtrackPermutations(0, currentPermutation, used);
            return successCount;
        }

        private void backtrackPermutations(int depth, int[] current, boolean[] used) {
            if (depth == 4) {
                if (simulator.simulate(maze, current.clone(), instructions)) {
                    successCount++;
                }
                return;
            }

            for (int i = 0; i < 4; i++) {
                if (!used[i]) {
                    used[i] = true;
                    current[depth] = i;
                    backtrackPermutations(depth + 1, current, used);
                    used[i] = false;
                }
            }
        }
    }

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(System.out)) {

            String firstLine = reader.readLine();
            if (firstLine == null) return;

            StringTokenizer st = new StringTokenizer(firstLine);
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            char[][] grid = new char[rows][cols];
            for (int r = 0; r < rows; r++) {
                grid[r] = reader.readLine().toCharArray();
            }

            String instructions = reader.readLine();

            Maze maze = new Maze(rows, cols, grid);
            Solver solver = new Solver(maze, instructions);

            writer.println(solver.solve());
            writer.flush();

        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * MazePathSolver calculates the number of ways to map the digits 0-3 
 * to the four cardinal directions such that a path is successfully 
 * navigated from a starting position to an ending position.
 */
public class MazePathSolver {

    /**
     * Represents a coordinate in the 2D grid.
     */
    static class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (!(obj instanceof Position)) return false;
            Position other = (Position) obj;
            return this.row == other.row && this.col == other.col;
        }
    }

    /**
     * Represents a movement vector in the grid.
     */
    static class Direction {
        final int dr;
        final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }

    /**
     * Encapsulates the maze structure and rules.
     */
    static class Maze {
        final int rows;
        final int cols;
        final boolean[][] walls;
        final Position start;
        final Position end;

        Maze(int rows, int cols, boolean[][] walls, Position start, Position end) {
            this.rows = rows;
            this.cols = cols;
            this.walls = walls;
            this.start = start;
            this.end = end;
        }

        boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        boolean isWall(int r, int c) {
            return walls[r][c];
        }
    }

    public static void main(String[] args) throws IOException {
        FastReader reader = new FastReader();

        // Parse dimensions
        int n = reader.nextInt();
        int m = reader.nextInt();

        boolean[][] walls = new boolean[n][m];
        Position start = null;
        Position end = null;

        // Parse maze layout
        for (int i = 0; i < n; i++) {
            String line = reader.next();
            for (int j = 0; j < m; j++) {
                char c = line.charAt(j);
                if (c == '#') {
                    walls[i][j] = true;
                } else if (c == 'S') {
                    start = new Position(i, j);
                } else if (c == 'E') {
                    end = new Position(i, j);
                }
            }
        }

        // Parse movement instructions
        String instructionStr = reader.next();
        int[] instructions = new int[instructionStr.length()];
        for (int i = 0; i < instructionStr.length(); i++) {
            instructions[i] = instructionStr.charAt(i) - '0';
        }

        Maze maze = new Maze(n, m, walls, start, end);
        System.out.println(countValidMappings(maze, instructions));
    }

    /**
     * Orchestrates the permutation generation and simulation.
     */
    private static int countValidMappings(Maze maze, int[] instructions) {
        Direction[] baseDirections = {
            new Direction(-1, 0), // Up
            new Direction(1, 0),  // Down
            new Direction(0, 1),  // Right
            new Direction(0, -1)  // Left
        };

        List<int[]> permutations = new ArrayList<>();
        generatePermutations(new int[]{0, 1, 2, 3}, 0, permutations);

        int successfulPaths = 0;
        for (int[] p : permutations) {
            Direction[] mapping = new Direction[4];
            for (int i = 0; i < 4; i++) {
                mapping[i] = baseDirections[p[i]];
            }

            if (simulatePath(maze, instructions, mapping)) {
                successfulPaths++;
            }
        }
        return successfulPaths;
    }

    /**
     * Generates all permutations of the given array using recursion.
     */
    private static void generatePermutations(int[] arr, int index, List<int[]> result) {
        if (index == arr.length) {
            result.add(arr.clone());
            return;
        }
        for (int i = index; i < arr.length; i++) {
            swap(arr, index, i);
            generatePermutations(arr, index + 1, result);
            swap(arr, index, i);
        }
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Simulates the movement along the path given a specific direction mapping.
     */
    private static boolean simulatePath(Maze maze, int[] instructions, Direction[] mapping) {
        int curR = maze.start.row;
        int curC = maze.start.col;

        for (int cmd : instructions) {
            // Rule: Before moving, verify current position is valid
            if (!maze.isWithinBounds(curR, curC)) {
                return false;
            }
            // If we have reached the end, stop moving
            if (curR == maze.end.row && curC == maze.end.col) {
                return true;
            }
            // If current position is a wall, the path is invalid
            if (maze.isWall(curR, curC)) {
                return false;
            }

            // Perform movement
            Direction dir = mapping[cmd];
            curR += dir.dr;
            curC += dir.dc;
        }

        // Check if the final position reached after all instructions is the end
        return curR == maze.end.row && curC == maze.end.col;
    }

    /**
     * Utility class for efficient input reading.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

