    private Point endPosition;

    public Grid(int rows, int cols, Scanner scanner) {
        this.rows = rows;
        this.cols = cols;
        this.map = new char[rows][cols];
        initializeMap(scanner);
    }

    private void initializeMap(Scanner scanner) {
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                map[i][j] = line.charAt(j);
                if (map[i][j] == 'S') {
                    startPosition = new Point(i, j);
                } else if (map[i][j] == 'E') {
                    endPosition = new Point(i, j);
                }
            }
        }
    }

    public boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }

    public boolean isWall(int r, int c) {
