/**
 * Handles the logic of simulating movements through the grid.
 */
class PathSimulator {
    private final Grid grid;

    // Directions: 0: Down, 1: Right, 2: Up, 3: Left
    private final int[] dr = {1, 0, -1, 0};
    private final int[] dc = {0, 1, 0, -1};

    public PathSimulator(Grid grid) {
        this.grid = grid;
    }

    public int countSuccessfulPermutations(int[] moveCommands) {
        int successCount = 0;
        List<int[]> permutations = PermutationGenerator.generatePermutations(new int[]{0, 1, 2, 3});

        for (int[] p : permutations) {
            if (canReachEnd(p, moveCommands)) {
                successCount++;
            }
        }
        return successCount;
    }

    private boolean canReachEnd(int[] permutation, int[] commands) {
        Point current = grid.getStartPosition();
        Point target = grid.getEndPosition();

        for (int command : commands) {
            // Map the command to an actual direction index using the current permutation
            int directionIndex = permutation[command];

            int nextR = current.row + dr[directionIndex];
            int nextC = current.col + dc[directionIndex];

            // Check if the next step reaches the goal
            if (nextR == target.row && nextC == target.col) {
                return true;
            }

            // Check if the path is blocked or out of bounds
            if (grid.isOutOfBounds(nextR, nextC) || grid.isWall(nextR, nextC)) {
                return false;
            }

            current = new Point(nextR, nextC);
        }
        return false;
    }
}

/**
 * Utility class to generate all permutations of a given array.
 */
class PermutationGenerator {
    public static List<int[]> generatePermutations(int[] elements) {
        List<int[]> result = new ArrayList<>();
        backtrack(result, elements.clone(), 0);
        return result;
    }

    private static void backtrack(List<int[]> result, int[] current, int index) {
        if (index == current.length) {
            result.add(current.clone());
            return;
        }
        for (int i = index; i < current.length; i++) {
            swap(current, index, i);
            backtrack(result, current, index + 1);
            swap(current, index, i); // backtrack
        }
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

