    /**
     * Represents a coordinate on the grid.
     */
    record Position(int row, int col) {
        public Position move(Direction direction) {
            return new Position(row + direction.getDeltaRow(), col + direction.getDeltaCol());
        }
    }

    /**
     * Defines possible movement directions and their coordinate deltas.
     */
    enum Direction {
        UP(-1, 0),
        DOWN(1, 0),
        LEFT(0, -1),
        RIGHT(0, 1);

        private final int deltaRow;
        private final int deltaCol;

        Direction(int deltaRow, int deltaCol) {
            this.deltaRow = deltaRow;
            this.deltaCol = deltaCol;
        }

        public int getDeltaRow() { return deltaRow; }
        public int getDeltaCol() { return deltaCol; }

        public static Direction fromId(int id) {
            return Direction.values()[id];
        }
    }

    /**
     * Handles the grid structure, boundary checks, and finding key positions.
     */
    static class Maze {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private Position start;
        private Position end;

        public Maze(int rows, int cols, String[] gridLines) {
            this.rows = rows;
            this.cols = cols;
            this.grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = gridLines[i].toCharArray();
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 'S') {
                        start = new Position(i, j);
                    } else if (grid[i][j] == 'E') {
                        end = new Position(i, j);
                    }
                }
            }
        }

        public boolean isWalkable(Position pos) {
            return pos.row() >= 0 && pos.row() < rows &&
                   pos.col() >= 0 && pos.col() < cols &&
                   grid[pos.row()][pos.col()] != '#';
        }

        public Position getStart() { return start; }
        public Position getEnd() { return end; }
    }

    /**
     * Orchestrates the solving process by testing permutations.
     */
    static class MazeSolver {

        public void solve(Scanner scanner, PrintWriter writer) {
            if (!scanner.hasNextInt()) return;

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();
            String[] gridLines = new String[rows];
            for (int i = 0; i < rows; i++) {
                gridLines[i] = scanner.next();
            }

            Maze maze = new Maze(rows, cols, gridLines);
            String commands = scanner.next();

            int successCount = countSuccessfulPermutations(maze, commands);
            writer.println(successCount);
        }

        private int countSuccessfulPermutations(Maze maze, String commands) {
            List<int[]> permutations = new ArrayList<>();
            int[] initial = {0, 1, 2, 3};
            generatePermutations(initial, 0, permutations);

            int successCount = 0;
            for (int[] mapping : permutations) {
                if (simulatePath(maze, commands, mapping)) {
                    successCount++;
                }
            }
            return successCount;
        }

        /**
         * Standard backtracking to generate all 4! (24) permutations.
         */
        private void generatePermutations(int[] arr, int index, List<int[]> result) {
            if (index == arr.length) {
                result.add(arr.clone());
                return;
            }
            for (int i = index; i < arr.length; i++) {
                swap(arr, index, i);
                generatePermutations(arr, index + 1, result);
                swap(arr, index, i);
            }
        }

        private void swap(int[] arr, int i, int j) {
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }

        /**
         * Simulates the movement of the robot based on a specific direction mapping.
         */
        private boolean simulatePath(Maze maze, String commands, int[] directionMapping) {
            Position currentPos = maze.getStart();

            for (int i = 0; i < commands.length(); i++) {
                // The command char tells us which index in our permutation array to look at
                int mappingIndex = commands.charAt(i) - '0';
                int directionId = directionMapping[mappingIndex];
                Direction direction = Direction.fromId(directionId);

                currentPos = currentPos.move(direction);

                if (!maze.isWalkable(currentPos)) {
                    return false;
                }

                if (currentPos.equals(maze.getEnd())) {
                    return true;
                }
            }

            return false;
        }
    }
}

