/**
 * Handles the grid data, boundary checks, and obstacle detection.
 */
class Maze {
    private final int rowCount;
    private final int colCount;
    private final char[][] grid;
    private Position startPosition;
    private Position endPosition;

    // Direction vectors: 0: East, 1: West, 2: South, 3: North
    private static final int[] DELTA_ROW = {0, 0, 1, -1};
    private static final int[] DELTA_COL = {1, -1, 0, 0};

    public Maze(int rows, int cols, Scanner scanner) {
        this.rowCount = rows;
        this.colCount = cols;
        this.grid = new char[rows][cols];
        parseGrid(scanner);
    }

    private void parseGrid(Scanner scanner) {
        for (int i = 0; i < rowCount; i++) {
            String line = scanner.next();
            for (int j = 0; j < colCount; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'S') {
                    startPosition = new Position(i, j);
                } else if (grid[i][j] == 'E') {
                    endPosition = new Position(i, j);
                }
            }
        }
    }

    public boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= rowCount || c < 0 || c >= colCount;
    }

    public boolean isWall(int r, int c) {
        return grid[r][c] == '#';
    }

    public Position getStartPosition() { return startPosition; }
    public Position getEndPosition() { return endPosition; }

    public Position move(Position current, int directionIndex) {
        int nextRow = current.getRow() + DELTA_ROW[directionIndex];
        int nextCol = current.getCol() + DELTA_COL[directionIndex];
        return new Position(nextRow, nextCol);
    }
}

/**
 * Simulates the path using different direction permutations.
 */
class PathSimulator {
    private final Maze maze;
    private final int[] commands;

    public PathSimulator(Maze maze, int[] commands) {
        this.maze = maze;
        this.commands = commands;
    }

    /**
     * Counts how many permutations of {0, 1, 2, 3} lead to the exit.
     */
    public int countSuccessfulMappings() {
        int count = 0;
        List<int[]> permutations = new ArrayList<>();
        generatePermutations(new int[]{0, 1, 2, 3}, 0, permutations);

        for (int[] mapping : permutations) {
            if (isPathSuccessful(mapping)) {
                count++;
            }
        }
        return count;
    }

    /**
     * Recursive backtracking to generate all permutations of direction indices.
     */
    private void generatePermutations(int[] arr, int index, List<int[]> result) {
        if (index == arr.length) {
            result.add(arr.clone());
            return;
        }
        for (int i = index; i < arr.length; i++) {
            swap(arr, index, i);
            generatePermutations(arr, index + 1, result);
            swap(arr, index, i);
        }
    }

    private void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Simulates a single path given a specific direction mapping.
     */
    private boolean isPathSuccessful(int[] directionMapping) {
        Position current = maze.getStartPosition();
        Position target = maze.getEndPosition();

        for (int command : commands) {
            // command is 0-3, mapping[command] gives the actual direction index
            int actualDirection = directionMapping[command];
            Position next = maze.move(current, actualDirection);

            if (maze.isOutOfBounds(next.getRow(), next.getCol()) || 
                maze.isWall(next.getRow(), next.getCol())) {
                return false;
            }

            if (next.equals(target)) {
                return true;
            }

            current = next;
        }

        return false;
    }
}

