            String line = sc.nextLine();
            for (int j = 0; j < cols; j++) {
                char cell = line.charAt(j);
                if (cell == 'S') {
                    startX = i;
                    startY = j;
                } else if (cell == 'E') {
                    endX = i;
                    endY = j;
                } else if (cell == '#') {
                    obstacles[i][j] = true;
                }
            }
        }

        String instructions = sc.hasNextLine() ? sc.nextLine() : "";
        sc.close();

        int successfulPaths = countSuccessfulPermutations(
                startX, startY, endX, endY, 
                obstacles, rows, cols, instructions
        );

        System.out.println(successfulPaths);
    }

    /**
     * Iterates through all 4! (24) permutations of direction mappings to find successful paths.
     */
    private static int countSuccessfulPermutations(
            int startX, int startY, int endX, int endY, 
            boolean[][] obstacles, int rows, int cols, String instructions) {

        int count = 0;
        int[] p = {0, 1, 2, 3};

        // Nested loops to generate all 24 permutations of {0, 1, 2, 3}
        for (int d0 = 0; d0 < 4; d0++) {
            for (int d1 = 0; d1 < 4; d1++) {
                if (d1 == d0) continue;
                for (int d2 = 0; d2 < 4; d2++) {
                    if (d2 == d0 || d2 == d1) continue;
                    for (int d3 = 0; d3 < 4; d3++) {
                        if (d3 == d0 || d3 == d1 || d3 == d2) continue;

                        int[] mapping = {d0, d1, d2, d3};
                        if (simulate(startX, startY, endX, endY, obstacles, rows, cols, instructions, mapping)) {
                            count++;
                        }
                    }
                }
            }
        }
        return count;
    }

    /**
     * Simulates the robot's movement given a specific mapping of instructions to directions.
     * 
     * @param mapping An array where mapping[i] is the direction index for instruction 'i'.
     * @return true if the robot reaches the exit 'E'.
     */
    private static boolean simulate(
            int startX, int startY, int endX, int endY, 
            boolean[][] obstacles, int rows, int cols, 
            String instructions, int[] mapping) {

        int currX = startX;
        int currY = startY;

        for (int i = 0; i < instructions.length(); i++) {
            int instructionVal = instructions.charAt(i) - '0';
            int directionIdx = mapping[instructionVal];

            // Move the robot
            currX += DIRECTIONS[directionIdx][0];
            currY += DIRECTIONS[directionIdx][1];

            // 1. Check if we reached the exit
            if (currX == endX && currY == endY) {
                return true;
            }

            // 2. Check if we hit a boundary
            if (currX < 0 || currX >= rows || currY < 0 || currY >= cols) {
                return false;
            }

            // 3. Check if we hit an obstacle
            if (obstacles[currX][currY]) {
                return false;
            }
        }

        return false;
    }
}

