class PathfindingSolver {

    private final FastReader reader;
    private int rowCount;
    private int colCount;
    private char[][] grid;
    private char[] commands;
    private int startRow;
    private int startCol;

    public PathfindingSolver(InputStream inputStream) {
        this.reader = new FastReader(inputStream);
    }

    /**
     * Orchestrates the reading of input and execution of the solver.
     */
    public void solve() throws IOException {
        // Read grid dimensions
        rowCount = reader.nextInt();
        colCount = reader.nextInt();

        // Read grid layout
        grid = new char[rowCount][colCount];
        for (int i = 0; i < rowCount; i++) {
            String line = reader.next();
            grid[i] = line.toCharArray();
            for (int j = 0; j < colCount; j++) {
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        // Read movement command sequence
        commands = reader.next().toCharArray();

        int validPermutationsCount = countValidDirectionAssignments();
        System.out.println(validPermutationsCount);
    }

    /**
     * Iterates through all possible unique assignments of the digits 0-3 
     * to the four cardinal directions.
     */
    private int countValidDirectionAssignments() {
        int successCount = 0;

        // Try all permutations of digits 0, 1, 2, 3 for directions North, East, South, West
        for (int north = 0; north < 4; north++) {
            for (int east = 0; east < 4; east++) {
                if (east == north) continue;
                for (int south = 0; south < 4; south++) {
                    if (south == north || south == east) continue;
                    for (int west = 0; west < 4; west++) {
                        if (west == north || west == east || west == south) continue;

                        if (canReachEnd(north, east, south, west)) {
                            successCount++;
                        }
                    }
                }
            }
        }
        return successCount;
    }

    /**
     * Simulates the robot's movement based on a specific direction assignment.
     * 
     * @param nDigit Digit assigned to North
     * @param eDigit Digit assigned to East
     * @param sDigit Digit assigned to South
     * @param wDigit Digit assigned to West
     * @return true if the robot reaches 'E' without hitting walls or boundaries
     */
    private boolean canReachEnd(int nDigit, int eDigit, int sDigit, int wDigit) {
        int curX = startRow;
        int curY = startCol;

        // Check initial position
        if (grid[curX][curY] == '#') return false;
        if (grid[curX][curY] == 'E') return true;

        for (char cmdChar : commands) {
            int command = cmdChar - '0';

            // Apply movement based on the current command
            if (command == nDigit) {
                curY++; // North increases column
            } else if (command == eDigit) {
                curX--; // East decreases row
            } else if (command == wDigit) {
                curX++; // West increases row
            } else if (command == sDigit) {
                curY--; // South decreases column
            }

            // Boundary check
            if (curX < 0 || curX >= rowCount || curY < 0 || curY >= colCount) {
                return false;
            }

            // Collision check
            if (grid[curX][curY] == '#') {
                return false;
            }

            // Goal check
            if (grid[curX][curY] == 'E') {
                return true;
            }
        }

        return false;
    }

    /**
     * Fast I/O utility for efficient parsing.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            this.reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

