/**
 * MazePathSolver solves the problem of finding how many ways a set of movement rules 
 * can be assigned to digits such that a path from 'S' to 'E' is successful.
 */
public class MazePathSolver {

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[] commandSequence;
    private final int startRow;
    private final int startCol;

    public MazePathSolver(int rows, int cols, char[][] grid, String directionString) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.commandSequence = parseDirections(directionString);

        // Locate the starting position
        int sR = -1, sC = -1;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'S') {
                    sR = i;
                    sC = j;
                    break;
                }
            }
            if (sR != -1) break;
        }
        this.startRow = sR;
        this.startCol = sC;
    }

    private int[] parseDirections(String directions) {
        int[] seq = new int[directions.length()];
        for (int i = 0; i < directions.length(); i++) {
            seq[i] = directions.charAt(i) - '0';
        }
        return seq;
    }

    /**
     * Generates all permutations of the 4 movement directions and counts 
     * how many lead to the exit 'E'.
     */
    public int countValidPermutations() {
        char[] moves = {'U', 'L', 'R', 'D'};
        int[] count = {0};
        permute(moves, 0, moves.length - 1, count);
        return count[0];
    }

    private void permute(char[] arr, int l, int r, int[] count) {
        if (l == r) {
            if (isPathSuccessful(arr)) {
                count[0]++;
            }
        } else {
            for (int i = l; i <= r; i++) {
                swap(arr, l, i);
                permute(arr, l + 1, r, count);
                swap(arr, l, i); // backtrack
            }
        }
    }

    private void swap(char[] arr, int i, int j) {
        char temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Iteratively checks if the current movement mapping allows reaching 'E'.
     */
    private boolean isPathSuccessful(char[] mapping) {
        int currR = startRow;
        int currC = startCol;

        // Check if starting position is already the exit
        if (grid[currR][currC] == 'E') return true;

        for (int cmdIdx : commandSequence) {
            char move = mapping[cmdIdx];

            if (move == 'U') currR--;
            else if (move == 'D') currR++;
            else if (move == 'L') currC--;
            else if (move == 'R') currC++;

            if (isOutOfBounds(currR, currC) || grid[currR][currC] == '#') {
                return false;
            }
            if (grid[currR][currC] == 'E') {
                return true;
            }
        }
        return false;
    }

    private boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            String line = reader.next();
            if (line == null) return;
            int testCases = Integer.parseInt(line);

            for (int t = 0; t < testCases; t++) {
                int n = reader.nextInt();
                int m = reader.nextInt();
                char[][] grid = new char[n][m];

                for (int i = 0; i < n; i++) {
                    String rowStr = reader.next();
                    grid[i] = rowStr.toCharArray();
                }

                String directions = reader.next();
                MazePathSolver solver = new MazePathSolver(n, m, grid, directions);
                writer.println(solver.countValidPermutations());
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
