/**
 * Main entry point for the program.
 * The problem involves finding how many permutations of direction mappings 
 * allow a character to reach a target 'E' from a starting point 'S'.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        Solver solver = new Solver();
        solver.solve(reader, writer);

        writer.flush();
        writer.close();
    }

    /**
     * Orchestrates the solving process.
     */
    static class Solver {
        public void solve(FastReader in, PrintWriter out) {
            int rows = in.nextInt();
            int cols = in.nextInt();
            char[][] mapData = in.nextCharacterMap(rows, cols);
            String commands = in.nextString();

            Grid grid = new Grid(rows, cols, mapData);
            PathSimulator simulator = new PathSimulator(grid);

            int successCount = countValidPermutations(simulator, commands);
            out.println(successCount);
        }

        private int countValidPermutations(PathSimulator simulator, String commands) {
            int[] directionMapping = {0, 1, 2, 3};
            int successCount = 0;

            do {
                if (simulator.simulate(directionMapping, commands)) {
                    successCount++;
                }
            } while (PermutationUtils.nextPermutation(directionMapping));

            return successCount;
        }
    }

    /**
     * Represents the game grid, containing walls and special points.
     */
    static class Grid {
        private final char[][] cells;
        private final int rows;
        private final int cols;
        private final Point start;
        private final Point end;

        public Grid(int rows, int cols, char[][] cells) {
            this.rows = rows;
            this.cols = cols;
            this.cells = cells;

            Point startPos = null;
            Point endPos = null;

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (cells[r][c] == 'S') {
                        startPos = new Point(r, c);
                    } else if (cells[r][c] == 'E') {
                        endPos = new Point(r, c);
                    }
                }
            }
            this.start = startPos;
            this.end = endPos;
        }

        public boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public boolean isWall(int r, int c) {
            return cells[r][c] == '#';
        }

        public Point getStart() { return start; }
        public Point getEnd() { return end; }
    }

    /**
     * Handles the movement logic across the grid.
     */
    static class PathSimulator {
        private final Grid grid;
        private static final int[] DX = {1, 0, -1, 0};
        private static final int[] DY = {0, -1, 0, 1};

        public PathSimulator(Grid grid) {
            this.grid = grid;
        }

        /**
         * Simulates a path based on a mapping of command digits to direction indices.
         * Returns true if the target 'E' is reached.
         */
        public boolean simulate(int[] mapping, String commands) {
            Point current = grid.getStart();
            Point target = grid.getEnd();

            for (int i = 0; i < commands.length(); i++) {
                int commandDigit = commands.charAt(i) - '0';
                int directionIdx = mapping[commandDigit];

                int nextRow = current.row + DX[directionIdx];
                int nextCol = current.col + DY[directionIdx];

                // Check if movement is valid
                if (!grid.isWithinBounds(nextRow, nextCol) || grid.isWall(nextRow, nextCol)) {
                    return false;
                }

                current = new Point(nextRow, nextCol);

                // If we hit the target, we stop and succeed
                if (current.equals(target)) {
                    return true;
                }
            }

            // If loop ends, check if the final position is the target
            return current.equals(target);
        }
    }

    /**
     * Utility class for permutation generation.
     */
    static class PermutationUtils {
        public static boolean nextPermutation(int[] p) {
            for (int i = p.length - 2; i >= 0; --i) {
                if (p[i] < p[i + 1]) {
                    for (int j = p.length - 1; ; --j) {
                        if (p[j] > p[i]) {
                            swap(p, i, j);
                            reverse(p, i + 1, p.length - 1);
                            return true;
                        }
                    }
                }
            }
            return false;
        }

        private static void swap(int[] p, int i, int j) {
            int temp = p[i];
            p[i] = p[j];
            p[j] = temp;
        }

        private static void reverse(int[] p, int start, int end) {
            while (start < end) {
                swap(p, start++, end--);
            }
        }
    }

    /**
     * Simple data object for coordinates.
     */
    static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point point = (Point) o;
            return row == point.row && col == point.col;
        }

        @Override
        public int hashCode() {
            return Objects.hash(row, col);
        }
    }

    /**
     * Fast I/O class for efficient reading of input streams.
     */
    static class FastReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[8192];
        private int pointer = 0;
        private int bufferLength = 0;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() {
            if (pointer >= bufferLength) {
                pointer = 0;
                try {
                    bufferLength = stream.read(buffer);
                } catch (IOException e) {
                    return -1;
                }
                if (bufferLength <= 0) return -1;
            }
            return buffer[pointer++];
        }

        public int nextInt() {
            int c = readByte();
            while (isSpaceChar(c)) c = readByte();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int res = 0;
            do {
                if (c == ',') c = readByte();
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = readByte();
            } while (!isSpaceChar(c));
            return res * sign;
        }

        public String nextString() {
            int c = readByte();
            while (isSpaceChar(c)) c = readByte();
            StringBuilder sb = new StringBuilder();
            do {
                sb.append((char) c);
                c = readByte();
            } while (!isSpaceChar(c));
            return sb.toString();
        }

        public char[][] nextCharacterMap(int n, int m) {
            char[][] map = new char[n][m];
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    map[i][j] = nextCharacter();
                }
            }
            return map;
        }

        private char nextCharacter() {
            int c = readByte();
            while (isSpaceChar(c)) c = readByte();
            return (char) c;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.util.*;

/**
 * CommandPathSolver solves the problem of finding how many ways a sequence of 
 * digit-based commands can be mapped to directions (Up, Down, Left, Right) 
 * such that the path from a starting point 'S' reaches an ending point 'E' 
 * without hitting walls '#' or going out of bounds.
 */
public class CommandPathSolver {

    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point point = (Point) o;
            return row == point.row && col == point.col;
        }

        @Override
        public int hashCode() {
            return Objects.hash(row, col);
        }
    }

    private static class Grid {
        private final int rows;
        private final int cols;
        private final boolean[][] walls;
        private Point start;
        private Point end;

        public Grid(int rows, int cols, String[] lines) {
            this.rows = rows;
            this.cols = cols;
            this.walls = new boolean[rows][cols];
            parseGrid(lines);
        }

        private void parseGrid(String[] lines) {
            for (int r = 0; r < rows; r++) {
                String line = lines[r];
                for (int c = 0; c < cols; c++) {
                    char cell = line.charAt(c);
                    if (cell == '#') {
                        walls[r][c] = true;
                    } else if (cell == 'S') {
                        start = new Point(r, c);
                    } else if (cell == 'E') {
                        end = new Point(r, c);
                    }
                }
            }
        }

        public boolean isOutOfBounds(int r, int c) {
            return r < 0 || r >= rows || c < 0 || c >= cols;
        }

        public boolean isWall(int r, int c) {
            return walls[r][c];
        }

        public boolean isValidMove(int r, int c) {
            return !isOutOfBounds(r, c) && !isWall(r, c);
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }
        public Point getStart() { return start; }
        public Point getEnd() { return end; }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        String[] gridLines = new String[n];
        for (int i = 0; i < n; i++) {
            gridLines[i] = scanner.next();
        }

        String commands = scanner.next();
        Grid grid = new Grid(n, m, gridLines);

        System.out.println(countValidMappings(grid, commands));
    }

    /**
     * Iterates through all 24 permutations of digits 0-3 mapped to 
     * {Up, Down, Left, Right} and counts how many result in reaching 'E'.
     */
    private static int countValidMappings(Grid grid, String commands) {
        int successCount = 0;
        int[] digits = {0, 1, 2, 3};

        // Generate all permutations of the 4 digits representing 
        // which digit triggers which movement direction.
        for (int d = 0; d <= 3; d++) {
            for (int u = 0; u <= 3; u++) {
                if (u == d) continue;
                for (int l = 0; l <= 3; l++) {
                    if (l == d || l == u) continue;
                    for (int r = 0; r <= 3; r++) {
                        if (r == d || r == u || r == l) continue;

                        // d: Up, u: Down, l: Left, r: Right
                        if (simulatePath(grid, commands, d, u, l, r)) {
                            successCount++;
                        }
                    }
                }
            }
        }
        return successCount;
    }

    /**
     * Simulates the path based on a specific digit-to-direction mapping.
     */
    private static boolean simulatePath(Grid grid, String commands, int up, int down, int left, int right) {
        int currentRow = grid.getStart().row;
        int currentCol = grid.getStart().col;
        Point target = grid.getEnd();

        for (int i = 0; i < commands.length(); i++) {
            int cmdDigit = commands.charAt(i) - '0';

            // Move based on the current digit's mapped direction
            if (cmdDigit == up) currentRow--;
            else if (cmdDigit == down) currentRow++;
            else if (cmdDigit == left) currentCol--;
            else if (cmdDigit == right) currentCol++;

            // Check if we reached the end
            if (currentRow == target.row && currentCol == target.col) {
                return true;
            }

            // Check if we hit a wall or boundary
            if (grid.isOutOfBounds(currentRow, currentCol) || grid.isWall(currentRow, currentCol)) {
                return false;
            }
        }

        return false;
    }
}

import java.util.*;

/**
 * MazeSolver determines how many unique mappings of instruction values (0-3) 
 * to directions (Right, Left, Down, Up) allow an agent to reach the exit 'E' 
 * from the starting point 'S' without hitting walls '#' or boundaries.
 */
public class MazeSolver {

    // Directional offsets representing: {row_offset, col_offset}
    // Indices: 0 = Right, 1 = Left, 2 = Down, 3 = Up
    private static final int[][] DIRECTION_OFFSETS = {
        {0, 1},  // Right
        {0, -1}, // Left
        {1, 0},  // Down
        {-1, 0}  // Up
    };

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        // Read maze dimensions
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // Consume the trailing newline character

        char[][] maze = new char[rows][cols];
        int startRow = -1;
        int startCol = -1;

        // Parse the maze and locate the starting position 'S'
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            for (int j = 0; j < cols; j++) {
                maze[i][j] = line.charAt(j);
                if (maze[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        // Parse the instruction sequence (a string of digits)
        if (!scanner.hasNextLine()) {
            System.out.println(0);
            return;
        }
        String instructionString = scanner.nextLine();
        int[] instructions = parseInstructions(instructionString);

        // Execute solver and output result
        int result = countSuccessfulMappings(maze, startRow, startCol, instructions);
        System.out.println(result);

        scanner.close();
    }

    /**
     * Converts a string of digits into an integer array.
     */
    private static int[] parseInstructions(String s) {
        int[] instructions = new int[s.length()];
        for (int i = 0; i < s.length(); i++) {
            instructions[i] = Character.getNumericValue(s.charAt(i));
        }
        return instructions;
    }

    /**
     * Generates all permutations of instruction-to-direction mappings 
     * and counts how many result in reaching the exit.
     */
    private static int countSuccessfulMappings(char[][] maze, int startRow, int startCol, int[] instructions) {
        int successCount = 0;
        List<int[]> permutations = new ArrayList<>();

        // Generate all permutations of {0, 1, 2, 3}
        generatePermutations(new int[]{0, 1, 2, 3}, 0, permutations);

        for (int[] p : permutations) {
            /*
             * The permutation 'p' assigns a value to each direction:
             * p[0] is the instruction value that triggers "Right"
             * p[1] is the instruction value that triggers "Left"
             * p[2] is the instruction value that triggers "Down"
             * p[3] is the instruction value that triggers "Up"
             */
            int[] valueToDirectionIdx = new int[4];
            valueToDirectionIdx[p[0]] = 0; // Right
            valueToDirectionIdx[p[1]] = 1; // Left
            valueToDirectionIdx[p[2]] = 2; // Down
            valueToDirectionIdx[p[3]] = 3; // Up

            if (simulatePath(maze, startRow, startCol, instructions, valueToDirectionIdx)) {
                successCount++;
            }
        }

        return successCount;
    }

    /**
     * Simulates the agent's movement through the maze based on a specific direction mapping.
     * @return true if the agent reaches 'E', false if they hit a wall, go out of bounds, or finish instructions.
     */
    private static boolean simulatePath(char[][] maze, int startRow, int startCol, 
                                        int[] instructions, int[] valueToDirectionIdx) {
        int currentRow = startRow;
        int currentCol = startCol;
        int maxRows = maze.length;
        int maxCols = maze[0].length;

        for (int instrValue : instructions) {
            int dirIdx = valueToDirectionIdx[instrValue];
            currentRow += DIRECTION_OFFSETS[dirIdx][0];
            currentCol += DIRECTION_OFFSETS[dirIdx][1];

            // 1. Boundary Check
            if (currentRow < 0 || currentRow >= maxRows || currentCol < 0 || currentCol >= maxCols) {
                return false;
            }

            // 2. Obstacle Check
            if (maze[currentRow][currentCol] == '#') {
                return false;
            }

            // 3. Success Check
            if (maze[currentRow][currentCol] == 'E') {
                return true;
            }
        }

        return false;
    }

    /**
     * Standard backtracking algorithm to generate all permutations of the given array.
     */
    private static void generatePermutations(int[] arr, int start, List<int[]> result) {
        if (start == arr.length) {
            result.add(arr.clone());
            return;
        }
        for (int i = start; i < arr.length; i++) {
            swap(arr, start, i);
            generatePermutations(arr, start + 1, result);
            swap(arr, start, i); // Backtrack
        }
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver that calculates how many ways a set of four direction mappings 
 * (for digits 0-3) can guide a path from a start point 'S' to an end point 'E'
 * in a grid without hitting walls '#'.
 */
public class DirectionalPathSolver {

    // Directional vectors: Down, Up, Right, Left
    private static final int[][] DIRECTIONS = {
        {1, 0},  
        {-1, 0}, 
        {0, 1},  
        {0, -1}  
    };

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final String instructions;
    private final int startX, startY;
    private final int endX, endY;

    public DirectionalPathSolver(int rows, int cols, char[][] grid, String instructions) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.instructions = instructions;

        // Locate Start (S) and End (E) points within the grid
        int sX = -1, sY = -1, eX = -1, eY = -1;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'S') {
                    sX = i;
                    sY = j;
                } else if (grid[i][j] == 'E') {
                    eX = i;
                    eY = j;
                }
            }
        }
        this.startX = sX;
        this.startY = sY;
        this.endX = eX;
        this.endY = eY;
    }

    /**
     * Entry point for solving the problem.
     * @return The number of valid digit-to-direction permutations.
     */
    public int solve() {
        int[] mapping = new int[4];
        boolean[] usedDirections = new boolean[4];
        return countPermutations(0, mapping, usedDirections);
    }

    /**
     * Uses backtracking to generate all 4! (24) permutations of direction mappings.
     */
    private int countPermutations(int depth, int[] mapping, boolean[] used) {
        if (depth == 4) {
            return isValidPath(mapping) ? 1 : 0;
        }

        int count = 0;
        for (int i = 0; i < 4; i++) {
            if (!used[i]) {
                used[i] = true;
                mapping[depth] = i; // Map digit 'depth' to direction index 'i'
                count += countPermutations(depth + 1, mapping, used);
                used[i] = false;
            }
        }
        return count;
    }

    /**
     * Validates if a specific mapping leads from Start to End following the instruction string.
     */
    private boolean isValidPath(int[] mapping) {
        int px = startX;
        int py = startY;
        int instructionIndex = 0;

        // Continue moving while not at the end, within bounds, and instructions remain
        while (!(px == endX && py == endY) &&
               px >= 0 && px < rows &&
               py >= 0 && py < cols &&
               instructionIndex < instructions.length()) {

            // If the current position is a wall, the path is invalid
            if (grid[px][py] == '#') {
                return false;
            }

            // Interpret the current instruction digit
            int digit = instructions.charAt(instructionIndex) - '0';
            int directionIndex = mapping[digit];

            // Move the pointer
            px += DIRECTIONS[directionIndex][0];
            py += DIRECTIONS[directionIndex][1];
            instructionIndex++;
        }

        // The path is valid if we ended exactly at the target coordinates
        return px == endX && py == endY;
    }

    public static void main(String[] args) throws IOException {
        FastReader sc = new FastReader(System.in);

        // Handle potential empty input or parsing errors
        String nStr = sc.next();
        if (nStr == null) return;

        int n = Integer.parseInt(nStr);
        int m = sc.nextInt();

        char[][] grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            grid[i] = sc.next().toCharArray();
        }

        String instructions = sc.next();

        DirectionalPathSolver solver = new DirectionalPathSolver(n, m, grid, instructions);
        System.out.println(solver.solve());
    }

    /**
     * Fast I/O utility for handling large datasets.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = new StringTokenizer("");
        }

        public String next() throws IOException {
            while (!tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
