/**
 * This program calculates the number of direction mappings (permutations of D, L, U, R)
 * that allow a path to reach an end point 'E' from a start point 'S' without 
 * hitting walls '#' or boundaries, following a given sequence of instructions.
 */
public class Main {

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        // Read grid dimensions
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        int startR = -1, startC = -1;
        int endR = -1, endC = -1;

        // Read grid and locate 'S' and 'E'
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'S') {
                    startR = i;
                    startC = j;
                } else if (grid[i][j] == 'E') {
                    endR = i;
                    endC = j;
                }
            }
        }

        // Read instructions and convert them to an integer array for faster access
        String instructionStr = scanner.next();
        int[] instructions = new int[instructionStr.length()];
        for (int i = 0; i < instructionStr.length(); i++) {
            instructions[i] = instructionStr.charAt(i) - '0';
        }

        // Generate all 24 permutations of directions
        char[] directions = {'D', 'L', 'U', 'R'};
        List<char[]> allMappings = new ArrayList<>();
        generatePermutations(directions, 0, allMappings);

        // Count how many mappings result in a successful path
        int successfulPathsCount = 0;
        for (char[] mapping : allMappings) {
            if (isSuccessfulPath(grid, startR, startC, endR, endC, instructions, mapping)) {
                successfulPathsCount++;
            }
        }

        out.println(successfulPathsCount);
        out.close();
    }

    /**
     * Generates all possible permutations of the provided character array using backtracking.
     */
    private static void generatePermutations(char[] arr, int index, List<char[]> result) {
        if (index == arr.length) {
            result.add(arr.clone());
            return;
        }
        for (int i = index; i < arr.length; i++) {
            swap(arr, index, i);
            generatePermutations(arr, index + 1, result);
            swap(arr, index, i); // Backtrack
        }
    }

    private static void swap(char[] arr, int i, int j) {
        char temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Simulates the movement along the grid based on the current mapping.
     * Returns true if the 'E' position is reached without hitting walls or boundaries.
     */
    private static boolean isSuccessfulPath(char[][] grid, int startR, int startC, int endR, int endC, 
                                           int[] instructions, char[] mapping) {
        // If start is already end
        if (startR == endR && startC == endC) {
            return true;
        }

        int currentR = startR;
        int currentC = startC;
        int rows = grid.length;
        int cols = grid[0].length;

        for (int instructionIndex : instructions) {
            char direction = mapping[instructionIndex];

            // Update position based on direction
            if (direction == 'D') currentR++;
            else if (direction == 'U') currentR--;
            else if (direction == 'L') currentC--;
            else if (direction == 'R') currentC++;

            // Check for boundary or wall collision
            if (currentR < 0 || currentR >= rows || currentC < 0 || currentC >= cols || grid[currentR][currentC] == '#') {
                return false;
            }

            // Check if target reached
            if (currentR == endR && currentC == endC) {
                return true;
            }
        }

        return false;
    }

    /**
     * Optimized scanner for fast I/O operations.
     */
    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = br.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program that explores possible grid navigation paths based on a set of 
 * direction-mapping permutations and a sequence of instructions.
 */
public class GridPathExplorer {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] gridData = new char[rows][cols];
            int startRow = -1;
            int startCol = -1;

            // Parse grid and locate the starting position 'S'
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                gridData[i] = line.toCharArray();
                for (int j = 0; j < cols; j++) {
                    if (gridData[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                    }
                }
            }

            String instructionString = reader.next();
            Grid grid = new Grid(gridData, startRow, startCol);
            PathFinder pathFinder = new PathFinder(grid, instructionString);

            writer.println(pathFinder.countSuccessfulPaths());
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Represents the navigation grid and its constraints.
     */
    static class Grid {
        private final char[][] cells;
        private final int rows;
        private final int cols;
        private final int startRow;
        private final int startCol;

        public Grid(char[][] cells, int startRow, int startCol) {
            this.cells = cells;
            this.rows = cells.length;
            this.cols = cells[0].length;
            this.startRow = startRow;
            this.startCol = startCol;
        }

        public boolean isInBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public boolean isWall(int r, int c) {
            return cells[r][c] == '#';
        }

        public boolean isExit(int r, int c) {
            return cells[r][c] == 'E';
        }

        public int getStartRow() { return startRow; }
        public int getStartCol() { return startCol; }
    }

    /**
     * Handles the logic for simulating paths and generating direction permutations.
     */
    static class PathFinder {
        // Directional offsets: 0: Right, 1: Left, 2: Down, 3: Up
        private static final int[] ROW_OFFSETS = {0, 0, 1, -1};
        private static final int[] COL_OFFSETS = {1, -1, 0, 0};

        private final Grid grid;
        private final char[] instructions;
        private int successfulPathsCount = 0;

        public PathFinder(Grid grid, String instructions) {
            this.grid = grid;
            this.instructions = instructions.toCharArray();
        }

        /**
         * Orchestrates the permutation generation and path simulation.
         * @return The total number of successful permutations.
         */
        public int countSuccessfulPaths() {
            successfulPathsCount = 0;
            int[] currentMapping = new int[4];
            boolean[] used = new boolean[4];
            generatePermutations(0, currentMapping, used);
            return successfulPathsCount;
        }

        /**
         * Uses backtracking to generate all permutations of the 4 directions {0, 1, 2, 3}.
         */
        private void generatePermutations(int depth, int[] currentMapping, boolean[] used) {
            if (depth == 4) {
                if (simulatePath(currentMapping)) {
                    successfulPathsCount++;
                }
                return;
            }

            for (int i = 0; i < 4; i++) {
                if (!used[i]) {
                    used[i] = true;
                    currentMapping[depth] = i;
                    generatePermutations(depth + 1, currentMapping, used);
                    used[i] = false;
                }
            }
        }

        /**
         * Simulates a path based on a specific mapping of instruction digits to directions.
         * @param mapping An array where mapping[digit] = directionIndex.
         * @return true if the path hits the exit 'E' without hitting a wall or going out of bounds.
         */
        private boolean simulatePath(int[] mapping) {
            int curR = grid.getStartRow();
            int curC = grid.getStartCol();

            for (char cmd : instructions) {
                int instructionDigit = cmd - '0';
                int moveDir = mapping[instructionDigit];

                curR += ROW_OFFSETS[moveDir];
                curC += COL_OFFSETS[moveDir];

                if (!grid.isInBounds(curR, curC) || grid.isWall(curR, curC)) {
                    return false;
                }

                if (grid.isExit(curR, curC)) {
                    return true;
                }
            }
            return false;
        }
    }

    /**
     * Optimized reader for fast input parsing.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
