/**
 * A program that calculates how many unique mappings of command signals to cardinal directions
 * will allow an agent to travel from a start point 'S' to an end point 'E' in a grid.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] gridData = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                gridData[i] = reader.next().toCharArray();
            }

            String commands = reader.next();
            Maze maze = new Maze(gridData);
            CommandSimulator simulator = new CommandSimulator(maze);

            int successfulPaths = simulator.countSuccessfulMappings(commands);
            System.out.println(successfulPaths);

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Represents the game world, containing the grid and boundary logic.
     */
    static class Maze {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final Point start;
        private final Point end;

        public Maze(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;

            Point foundStart = null;
            Point foundEnd = null;

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == 'S') {
                        foundStart = new Point(r, c);
                    } else if (grid[r][c] == 'E') {
                        foundEnd = new Point(r, c);
                    }
                }
            }
            this.start = foundStart;
            this.end = foundEnd;
        }

        public boolean isOutOfBounds(int r, int c) {
            return r < 0 || r >= rows || c < 0 || c >= cols;
        }

        public boolean isWall(int r, int c) {
            return grid[r][c] == '#';
        }

        public boolean isEnd(int r, int c) {
            return r == end.row && c == end.col;
        }

        public Point getStart() { return start; }
    }

    /**
     * Simple data structure for coordinates.
     */
    static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Handles the logic of simulating movement and exploring direction permutations.
     */
    static class CommandSimulator {
        private final Maze maze;
        // Directions: Right, Left, Up, Down
        private final int[][] directions = {{0, 1}, {0, -1}, {-1, 0}, {1, 0}};
        private int successCount = 0;

        public CommandSimulator(Maze maze) {
            this.maze = maze;
        }

        /**
         * Tries all 4! (24) permutations of mapping commands {0,1,2,3} to directions.
         */
        public int countSuccessfulMappings(String commands) {
            successCount = 0;
            int[] permutation = {0, 1, 2, 3};
            generatePermutations(permutation, 0, commands);
            return successCount;
        }

        private void generatePermutations(int[] p, int index, String commands) {
            if (index == p.length) {
                if (simulate(p, commands)) {
                    successCount++;
                }
                return;
            }

            for (int i = index; i < p.length; i++) {
                swap(p, index, i);
                generatePermutations(p, index + 1, commands);
                swap(p, index, i); // backtrack
            }
        }

        private void swap(int[] arr, int i, int j) {
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }

        private boolean simulate(int[] mapping, String commands) {
            int currR = maze.getStart().row;
            int currC = maze.getStart().col;

            for (int i = 0; i < commands.length(); i++) {
                int commandVal = commands.charAt(i) - '0';
                // The mapping array p tells us which direction index corresponds to which command
                int dirIdx = mapping[commandVal];

                currR += directions[dirIdx][0];
                currC += directions[dirIdx][1];

                if (maze.isOutOfBounds(currR, currC) || maze.isWall(currR, currC)) {
                    return false;
                }

                if (maze.isEnd(currR, currC)) {
                    return true;
                }
            }
            return false;
        }
    }

    /**
     * Fast I/O reader for efficient input handling.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

