/**
 * This program calculates how many permutations of a given sequence of directions 
 * allow a robot to reach an exit ('E') from a starting position ('S') on a grid,
 * without hitting walls ('#') or going out of bounds.
 */
public class RobotPathSimulation {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            char[][] gridData = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                gridData[i] = reader.next().toCharArray();
            }

            String sequenceStr = reader.next();
            if (sequenceStr == null) return;

            int[] moveSequence = new int[sequenceStr.length()];
            for (int i = 0; i < sequenceStr.length(); i++) {
                moveSequence[i] = sequenceStr.charAt(i) - '0';
            }

            Grid grid = new Grid(gridData, rows, cols);
            RobotSimulator simulator = new RobotSimulator(grid);

            int successfulPathsCount = simulator.countSuccessfulPermutations(moveSequence);

            System.out.println(successfulPathsCount);

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Represents the possible movement directions on the grid.
     */
    enum Direction {
        RIGHT(0, 1),
        LEFT(0, -1),
        UP(-1, 0),
        DOWN(1, 0);

        final int dx;
        final int dy;

        Direction(int dx, int dy) {
            this.dx = dx;
            this.dy = dy;
        }
    }

    /**
     * Represents the game board, containing the map and boundary logic.
     */
    static class Grid {
        private final char[][] map;
        private final int rows;
        private final int cols;
        private int startX;
        private int startY;

        public Grid(char[][] map, int rows, int cols) {
            this.map = map;
            this.rows = rows;
            this.cols = cols;
            findStartPosition();
        }

        private void findStartPosition() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (map[i][j] == 'S') {
                        startX = i;
                        startY = j;
                        return;
                    }
                }
            }
        }

        public boolean isValidMove(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && map[r][c] != '#';
        }

        public boolean isExit(int r, int c) {
            return map[r][c] == 'E';
        }

        public int getStartX() { return startX; }
        public int getStartY() { return startY; }
    }

    /**
     * Handles the logic of simulating robot movements.
     */
    static class RobotSimulator {
        private final Grid grid;
        private final Direction[] directions = Direction.values();

        public RobotSimulator(Grid grid) {
            this.grid = grid;
        }

        /**
         * Iterates through all permutations of direction mappings and counts successes.
         */
        public int countSuccessfulPermutations(int[] moveSequence) {
            // mapping[digit] returns an index for the 'directions' array
            int[] directionMapping = {0, 1, 2, 3}; 
            int successCount = 0;

            do {
                if (simulatePath(moveSequence, directionMapping)) {
                    successCount++;
                }
            } while (PermutationUtils.nextPermutation(directionMapping));

            return successCount;
        }

        private boolean simulatePath(int[] sequence, int[] mapping) {
            int x = grid.getStartX();
            int y = grid.getStartY();

            for (int digit : sequence) {
                int dirIdx = mapping[digit];
                Direction dir = directions[dirIdx];

                x += dir.dx;
                y += dir.dy;

                if (!grid.isValidMove(x, y)) {
                    return false;
                }
                if (grid.isExit(x, y)) {
                    return true;
                }
            }
            return false;
        }
    }

    /**
     * Utility class for permutation generation.
     */
    static class PermutationUtils {
        /**
         * Transforms the array into the next lexicographical permutation.
         * @return true if a next permutation exists, false if it was the last one.
         */
        public static boolean nextPermutation(int[] array) {
            int i = array.length - 2;
            while (i >= 0 && array[i] >= array[i + 1]) {
                i--;
            }

            if (i < 0) return false;

            int j = array.length - 1;
            while (array[j] <= array[i]) {
                j--;
            }

            swap(array, i, j);
            reverse(array, i + 1, array.length - 1);
            return true;
        }

        private static void swap(int[] array, int i, int j) {
            int temp = array[i];
            array[i] = array[j];
            array[j] = temp;
        }

        private static void reverse(int[] array, int start, int end) {
            while (start < end) {
                swap(array, start++, end--);
            }
        }
    }

    /**
     * Fast I/O reader for efficient input handling.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * A program that simulates robot movements on a grid to determine how many 
 * direction permutations allow the robot to reach an exit.
 */
public class Main {

    // Constants for grid cell types
    private static final char OBSTACLE = '#';
    private static final char EXIT = 'E';
    private static final char START = 'S';

    // Base movement vectors: {deltaRow, deltaCol}
    private static final int[][] BASE_DIRECTIONS = {
        {0, -1}, // Left
        {1, 0},  // Down
        {0, 1},  // Right
        {-1, 0}  // Up
    };

    public static void main(String[] args) {
        FastReader reader = new FastReader();

        try {
            // 1. Parse Grid Dimensions
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            // 2. Parse Grid and find starting position
            Grid grid = new Grid(rows, cols, reader);
            Position startPos = grid.getStartPosition();

            // 3. Parse Move Sequence
            int[] moveSequence = reader.nextIntArray();

            // 4. Calculate successful permutations
            int successfulPermutations = countSuccessfulPaths(grid, startPos, moveSequence);

            // 5. Output result
            System.out.println(successfulPermutations);

        } catch (IOException | NoSuchElementException e) {
            // Handle potential parsing errors
        }
    }

    /**
     * Iterates through all possible permutations of directions and counts how many
     * lead the robot to the exit.
     */
    private static int countSuccessfulPaths(Grid grid, Position startPos, int[] moves) {
        int successCount = 0;
        List<int[]> permutations = PermutationGenerator.generate(new int[]{0, 1, 2, 3});

        for (int[] p : permutations) {
            // Map the base directions to the current permutation
            int[][] directionMapping = new int[4][2];
            for (int i = 0; i < 4; i++) {
                directionMapping[i] = BASE_DIRECTIONS[p[i]];
            }

            if (MovementSimulator.simulate(grid, startPos, moves, directionMapping)) {
                successCount++;
            }
        }
        return successCount;
    }

    /**
     * Represents a coordinate on the grid.
     */
    private static class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Encapsulates the grid data and boundary/collision logic.
     */
    private static class Grid {
        private final int rows;
        private final int cols;
        private final String[] layout;
        private Position startPosition;

        Grid(int rows, int cols, FastReader reader) throws IOException {
            this.rows = rows;
            this.cols = cols;
            this.layout = new String[rows];
            for (int i = 0; i < rows; i++) {
                layout[i] = reader.readLine();
                int startCol = layout[i].indexOf(START);
                if (startCol != -1) {
                    this.startPosition = new Position(i, startCol);
                }
            }
        }

        boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        boolean isObstacle(int r, int c) {
            return layout[r].charAt(c) == OBSTACLE;
        }

        boolean isExit(int r, int c) {
            return layout[r].charAt(c) == EXIT;
        }

        Position getStartPosition() {
            return startPosition;
        }
    }

    /**
     * Handles the simulation logic for a specific direction mapping.
     */
    private static class MovementSimulator {
        static boolean simulate(Grid grid, Position start, int[] moves, int[][] mapping) {
            int currentRow = start.row;
            int currentCol = start.col;

            for (int moveIndex : moves) {
                int[] delta = mapping[moveIndex];
                currentRow += delta[0];
                currentCol += delta[1];

                // Check if the robot hit a boundary
                if (!grid.isValid(currentRow, currentCol)) {
                    return false;
                }
                // Check if the robot hit an obstacle
                if (grid.isObstacle(currentRow, currentCol)) {
                    return false;
                }
                // Check if the robot reached the exit
                if (grid.isExit(currentRow, currentCol)) {
                    return true;
                }
            }
            return false;
        }
    }

    /**
     * Utility to generate all permutations of an integer array.
     */
    private static class PermutationGenerator {
        static List<int[]> generate(int[] elements) {
            List<int[]> result = new ArrayList<>();
            permute(elements, 0, result);
            return result;
        }

        private static void permute(int[] arr, int k, List<int[]> result) {
            if (k == arr.length) {
                result.add(arr.clone());
                return;
            }
            for (int i = k; i < arr.length; i++) {
                swap(arr, k, i);
                permute(arr, k + 1, result);
                swap(arr, k, i); // backtrack
            }
        }

        private static void swap(int[] arr, int i, int j) {
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }
    }

    /**
     * Fast I/O utility for efficient reading.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader() {
            reader = new BufferedReader(new InputStreamReader(System.in));
        }

        String readLine() throws IOException {
            return reader.readLine();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        int[] nextIntArray() throws IOException {
            String line = reader.readLine();
            if (line == null) return new int[0];
            int[] arr = new int[line.length()];
            for (int i = 0; i < line.length(); i++) {
                arr[i] = line.charAt(i) - '0';
            }
            return arr;
        }
    }

    private static class NoSuchElementException extends RuntimeException {}
}

import java.io.*;
import java.util.*;

/**
 * A program to simulate movement on a grid based on various command permutations.
 * The goal is to count how many unique command-to-direction mappings allow 
 * an agent to reach the destination 'E' without hitting obstacles.
 */
public class Main {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            GridSimulator simulator = new GridSimulator(scanner);
            int successfulPaths = simulator.solve();
            out.println(successfulPaths);
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Handles the simulation logic for the grid game.
     */
    static class GridSimulator {
        private static final int NUM_DIRECTIONS = 4;

        // Mapping direction IDs to coordinate changes:
        // 0: Down, 1: Left, 2: Up, 3: Right
        private static final int[] DY = {1, 0, -1, 0};
        private static final int[] DX = {0, -1, 0, 1};

        // All 24 permutations of the four possible directions {0, 1, 2, 3}
        private static final int[][] PERMUTATIONS = {
            {0, 1, 2, 3}, {0, 1, 3, 2}, {0, 2, 3, 1}, {0, 2, 1, 3}, {0, 3, 2, 1}, {0, 3, 1, 2},
            {1, 0, 2, 3}, {1, 0, 3, 2}, {1, 2, 0, 3}, {1, 2, 3, 0}, {1, 3, 0, 2}, {1, 3, 2, 0},
            {2, 0, 1, 3}, {2, 0, 3, 1}, {2, 1, 3, 0}, {2, 1, 0, 3}, {2, 3, 0, 1}, {2, 3, 1, 0},
            {3, 0, 1, 2}, {3, 0, 2, 1}, {3, 1, 0, 2}, {3, 1, 2, 0}, {3, 2, 0, 1}, {3, 2, 1, 0}
        };

        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final int startX;
        private final int startY;
        private final int[] instructions;

        public GridSimulator(FastScanner sc) throws IOException {
            this.rows = sc.nextInt();
            this.cols = sc.nextInt();
            this.grid = new char[rows][cols];

            int tempX = -1;
            int tempY = -1;

            for (int i = 0; i < rows; i++) {
                String line = sc.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                    if (grid[i][j] == 'S') {
                        tempY = i;
                        tempX = j;
                    }
                }
            }
            this.startY = tempY;
            this.startX = tempX;

            String instructionString = sc.next();
            this.instructions = new int[instructionString.length()];
            for (int i = 0; i < instructionString.length(); i++) {
                this.instructions[i] = instructionString.charAt(i) - '0';
            }
        }

        /**
         * Iterates through all possible direction permutations and counts successes.
         * @return Number of permutations that reach 'E'.
         */
        public int solve() {
            int successCount = 0;

            for (int[] permutation : PERMUTATIONS) {
                if (trySimulate(permutation)) {
                    successCount++;
                }
            }

            return successCount;
        }

        /**
         * Simulates the path for a specific direction mapping.
         * @param permutation An array mapping command IDs to direction IDs.
         * @return true if the agent reaches 'E' without hitting walls or boundaries.
         */
        private boolean trySimulate(int[] permutation) {
            int currentX = startX;
            int currentY = startY;

            for (int command : instructions) {
                int direction = permutation[command];
                currentX += DX[direction];
                currentY += DY[direction];

                // Check boundaries and obstacles
                if (isOutOfBounds(currentX, currentY) || grid[currentY][currentX] == '#') {
                    return false;
                }

                // Check if destination reached
                if (grid[currentY][currentX] == 'E') {
                    return true;
                }
            }

            return false;
        }

        private boolean isOutOfBounds(int x, int y) {
            return x < 0 || x >= cols || y < 0 || y >= rows;
        }
    }

    /**
     * Efficient input reader for large datasets.
     */
    static class FastScanner {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int pointer = 0;
        private int bytesRead = 0;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        private int readByte() throws IOException {
            if (pointer >= bytesRead) {
                pointer = 0;
                bytesRead = stream.read(buffer);
                if (bytesRead <= 0) return -1;
            }
            return buffer[pointer++];
        }

        public String next() throws IOException {
            int c = readByte();
            while (c != -1 && c <= 32) c = readByte();
            if (c == -1) return "";
            StringBuilder sb = new StringBuilder();
            while (c > 32) {
                sb.append((char) c);
                c = readByte();
            }
            return sb.toString();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * A refactored solution for the USACO maze problem.
 * The program finds how many permutations of command-to-direction mappings 
 * allow an agent to reach the exit 'E' from start 'S' without hitting walls or boundaries.
 */
public class USACO {

    /**
     * Represents a coordinate in the 2D maze.
     */
    private static class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Encapsulates the maze grid and provides boundary and collision checks.
     */
    private static class Maze {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final Position startPosition;

        Maze(int rows, int cols, char[][] grid, Position startPosition) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.startPosition = startPosition;
        }

        boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        boolean isWall(int r, int c) {
            return grid[r][c] == '#';
        }

        boolean isExit(int r, int c) {
            return grid[r][c] == 'E';
        }
    }

    // Physical directions mapped to row/column offsets: {deltaRow, deltaCol}
    // 0: South, 1: North, 2: East, 3: West
    private static final int[][] DIRECTION_OFFSETS = {
        {1, 0},  // South
        {-1, 0}, // North
        {0, 1},  // East
        {0, -1}  // West
    };

    public static void main(String[] args) {
        try {
            new USACO().solve();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Orchestrates the input reading and the calculation process.
     */
    public void solve() throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        String firstLine = reader.readLine();
        if (firstLine == null) return;

        StringTokenizer st = new StringTokenizer(firstLine);
        int rows = Integer.parseInt(st.nextToken());
        int cols = Integer.parseInt(st.nextToken());

        char[][] grid = new char[rows][cols];
        Position startPos = null;

        for (int i = 0; i < rows; i++) {
            String rowText = reader.readLine();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = rowText.charAt(j);
                if (grid[i][j] == 'S') {
                    startPos = new Position(i, j);
                }
            }
        }

        String commandSequence = reader.readLine();
        if (commandSequence == null) commandSequence = "";

        Maze maze = new Maze(rows, cols, grid, startPos);
        System.out.println(countSuccessfulPermutations(maze, commandSequence));
    }

    /**
     * Generates all 24 permutations of direction mappings and counts how many result in success.
     */
    private int countSuccessfulPermutations(Maze maze, String commands) {
        List<int[]> permutations = new ArrayList<>();
        int[] initialMapping = {0, 1, 2, 3};
        generatePermutations(initialMapping, 0, permutations);

        int successCount = 0;
        for (int[] p : permutations) {
            if (simulatePath(maze, commands, p)) {
                successCount++;
            }
        }
        return successCount;
    }

    /**
     * Standard recursive backtracking to generate all permutations of the mapping array.
     */
    private void generatePermutations(int[] arr, int index, List<int[]> result) {
        if (index == arr.length) {
            result.add(arr.clone());
            return;
        }
        for (int i = index; i < arr.length; i++) {
            swap(arr, index, i);
            generatePermutations(arr, index + 1, result);
            swap(arr, index, i); // Backtrack
        }
    }

    private void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Simulates the agent's path based on a specific mapping of commands to directions.
     * 
     * @param maze The maze object.
     * @param commands The input string of digits.
     * @param permutation An array where p[i] is the command that triggers the i-th physical direction.
     * @return true if the agent reaches the exit 'E' without hitting a wall or boundary.
     */
    private boolean simulatePath(Maze maze, String commands, int[] permutation) {
        // Pre-calculate the row/col movement for each command (0, 1, 2, 3) 
        // to avoid repeated if-checks inside the loop.
        int[] drMap = new int[4];
        int[] dcMap = new int[4];

        for (int dirIdx = 0; dirIdx < 4; dirIdx++) {
            int commandForThisDir = permutation[dirIdx];
            drMap[commandForThisDir] = DIRECTION_OFFSETS[dirIdx][0];
            dcMap[commandForThisDir] = DIRECTION_OFFSETS[dirIdx][1];
        }

        int currentR = maze.startPosition.row;
        int currentC = maze.startPosition.col;

        for (int i = 0; i < commands.length(); i++) {
            int cmd = commands.charAt(i) - '0';

            // If command is outside expected range, skip (defensive programming)
            if (cmd < 0 || cmd > 3) continue;

            currentR += drMap[cmd];
            currentC += dcMap[cmd];

            // Collision check: Boundary or Wall
            if (!maze.isWithinBounds(currentR, currentC) || maze.isWall(currentR, currentC)) {
                return false;
            }

            // Success check: Exit reached
            if (maze.isExit(currentR, currentC)) {
                return true;
            }
        }

        return false;
    }
}

