/**
 * Main entry point for the application.
 * The program is organized into logical components: Problem solvers and algorithmic utilities.
 */
public class Main {

    public static void main(String[] args) {
        Main application = new Main();
        application.run();
    }

    public void run() {
        // In a real application, this might be driven by command-line arguments.
        // For this refactor, we trigger the primary logic (solveB) as per original.
        ProblemB.solve();
    }

    // ========================================================================
    // PROBLEM SOLVERS
    // ========================================================================

    /**
     * Solves Problem A: Counts the occurrences of vowels and specific digits.
     */
    static class ProblemA {
        private static final Set<Character> TARGET_CHARACTERS = Set.of(
                'a', 'i', 'u', 'e', 'o', '1', '3', '5', '7', '9'
        );

        public static void solve() {
            try (Scanner sc = new Scanner(System.in)) {
                if (!sc.hasNext()) return;
                String input = sc.next();
                long count = input.chars()
                        .mapToObj(c -> (char) c)
                        .filter(TARGET_CHARACTERS::contains)
                        .count();
                System.out.println(count);
            }
        }
    }

    /**
     * Solves Problem B: Simulates grid navigation based on instruction permutations.
     */
    static class ProblemB {
        private static final char WALL = '#';
        private static final char START = 'S';
        private static final char END = 'E';

        public static void solve() {
            try (Scanner sc = new Scanner(System.in)) {
                if (!sc.hasNextInt()) return;
                int rows = sc.nextInt();
                int cols = sc.nextInt();
                sc.nextLine(); // Consume newline

                char[][] grid = buildPaddedGrid(sc, rows, cols);
                int startRow = -1;
                int startCol = -1;

                // Locate Start position within the padded grid
                for (int r = 1; r <= rows; r++) {
                    for (int c = 1; c <= cols; c++) {
                        if (grid[r][c] == START) {
                            startRow = r;
                            startCol = c;
                        }
                    }
                }

                String instructions = sc.next();
                System.out.println(countSuccessfulPaths(grid, startRow, startCol, instructions));
            }
        }

        private static char[][] buildPaddedGrid(Scanner sc, int rows, int cols) {
            int paddedRows = rows + 2;
            int paddedCols = cols + 2;
            char[][] grid = new char[paddedRows][paddedCols];

            // Initialize boundaries with walls
            for (int r = 0; r < paddedRows; r++) {
                for (int c = 0; c < paddedCols; c++) {
                    if (r == 0 || r == paddedRows - 1 || c == 0 || c == paddedCols - 1) {
                        grid[r][c] = WALL;
                    }
                }
            }

            // Fill internal grid
            for (int r = 1; r <= rows; r++) {
                String line = sc.nextLine();
                for (int c = 1; c <= cols; c++) {
                    grid[r][c] = line.charAt(c - 1);
                }
            }
            return grid;
        }

        private static long countSuccessfulPaths(char[][] grid, int startR, int startC, String instructions) {
            long successfulPaths = 0;
            List<int[]> permutations = generatePermutations(new int[]{0, 1, 2, 3});

            for (int[] p : permutations) {
                // Map: p[0]=Left, p[1]=Up, p[2]=Right, p[3]=Down
                int leftCmd = p[0];
                int upCmd = p[1];
                int rightCmd = p[2];
                int downCmd = p[3];

                int currR = startR;
                int currC = startC;

                for (char instructionChar : instructions.toCharArray()) {
                    int cmd = instructionChar - '0';

                    if (cmd == leftCmd) currC--;
                    else if (cmd == upCmd) currR--;
                    else if (cmd == rightCmd) currC++;
                    else if (cmd == downCmd) currR++;

                    if (grid[currR][currC] == WALL) break;
                    if (grid[currR][currC] == END) {
                        successfulPaths++;
                        break;
                    }
                }
            }
            return successfulPaths;
        }

        private static List<int[]> generatePermutations(int[] nums) {
            List<int[]> result = new ArrayList<>();
            permute(nums, 0, result);
            return result;
        }

        private static void permute(int[] nums, int start, List<int[]> result) {
            if (start == nums.length) {
                result.add(nums.clone());
                return;
            }
            for (int i = start; i < nums.length; i++) {
                swap(nums, start, i);
                permute(nums, start + 1, result);
                swap(nums, start, i);
            }
        }

        private static void swap(int[] nums, int i, int j) {
            int temp = nums[i];
            nums[i] = nums[j];
            nums[j] = temp;
        }
    }

