    /**
     * Implementation of a Graph using an adjacency matrix.
     */
    static class ArrayGraph implements Graph {
        private final long[][] capacityMatrix;
        private final int vertexNum;

        public ArrayGraph(int n) {
            this.vertexNum = n;
            this.capacityMatrix = new long[n][n];
        }

        @Override
        public void link(int from, int to, long cost) {
            capacityMatrix[from][to] = cost;
        }

        @Override
        public Optional<Long> getCost(int from, int to) {
            long cost = capacityMatrix[from][to];
            return cost > 0 ? Optional.of(cost) : Optional.empty();
        }

        @Override
        public int getVertexNum() {
            return vertexNum;
        }
    }

    /**
     * Implementation of the Ford-Fulkerson algorithm using DFS.
     */
    static class DfsFlowResolver implements FlowResolver {
        private final Graph graph;

        public DfsFlowResolver(Graph graph) {
            this.graph = graph;
        }

        @Override
        public long maxFlow(int from, int to) {
            long totalFlow = 0;
            long currentFlow;
            do {
                currentFlow = findPathFlow(from, to, Long.MAX_VALUE / 3, new boolean[graph.getVertexNum()]);
                totalFlow += currentFlow;
            } while (currentFlow > 0);
            return totalFlow;
        }

        private long findPathFlow(int u, int target, long flow, boolean[] visited) {
            visited[u] = true;
            if (u == target) return flow;

            for (int v = 0; v < graph.getVertexNum(); v++) {
                Optional<Long> capacity = graph.getCost(u, v);
                if (!visited[v] && capacity.isPresent()) {
                    long bottleneck = Math.min(flow, capacity.get());
                    long pushed = findPathFlow(v, target, bottleneck, visited);

                    if (pushed > 0) {
                        graph.link(u, v, capacity.get() - pushed);
                        long reverseCap = graph.getCost(v, u).orElse(0L);
                        graph.link(v, u, reverseCap + pushed);
                        return pushed;
                    }
                }
            }
            return 0;
        }
    }

    /**
     * A Binary Indexed Tree (Fenwick Tree) for prefix sum queries.
     */
    static class BinaryIndexedTree {
        private final long[] tree;

        public BinaryIndexedTree(int size) {
            this.tree = new long[size + 1];
        }

        public void add(int index, long delta) {
            for (int i = index; i < tree.length; i += (i & -i)) {
                tree[i] += delta;
            }
        }

        public long getSum(int index) {
            long sum = 0;
            for (int i = index; i > 0; i -= (i & -i)) {
                sum += tree[i];
            }
            return sum;
        }
    }
}

