/**
 * Handles the logic for simulating paths and calculating valid permutations.
 */
class MazeSolver {
    // Direction vectors: 0: UP, 1: DOWN, 2: LEFT, 3: RIGHT
    private static final int[] DX = {0, 0, -1, 1};
    private static final int[] DY = {-1, 1, 0, 0};
    private static final int NUM_DIRECTIONS = 4;

    private final Maze maze;

    public MazeSolver(Maze maze) {
        this.maze = maze;
    }

    /**
     * Calculates how many permutations of digit-to-direction mappings result in reaching 'E'.
     */
    public int countSuccessfulMappings(String instructions) {
        int successfulCount = 0;
        List<int[]> permutations = new ArrayList<>();
        generatePermutations(new int[NUM_DIRECTIONS], new boolean[NUM_DIRECTIONS], 0, permutations);

        for (int[] mapping : permutations) {
            if (simulatePath(instructions, mapping)) {
                successfulCount++;
            }
        }
        return successfulCount;
    }

    /**
     * Simulates a single path given a specific mapping of digits to directions.
     * mapping[digit] = directionIndex
     */
    private boolean simulatePath(String instructions, int[] digitToDir) {
        Point current = maze.getStartPoint();

        for (int i = 0; i < instructions.length(); i++) {
            int digit = instructions.charAt(i) - '0';
            int dirIdx = digitToDir[digit];

            int nextX = current.x() + DX[dirIdx];
            int nextY = current.y() + DY[dirIdx];

            if (!maze.isWithinBounds(nextX, nextY)) {
                return false;
            }

            char cell = maze.getChar(nextX, nextY);
            if (cell == '#') {
                return false;
            }
            if (cell == 'E') {
                return true;
            }

            current = new Point(nextX, nextY);
        }

        return false;
    }

    /**
     * Generates all permutations of {0, 1, 2, 3} to test all possible direction assignments.
     */
    private void generatePermutations(int[] current, boolean[] used, int index, List<int[]> results) {
        if (index == NUM_DIRECTIONS) {
            results.add(current.clone());
            return;
        }

        for (int i = 0; i < NUM_DIRECTIONS; i++) {
            if (!used[i]) {
                used[i] = true;
                current[index] = i;
                generatePermutations(current, used, index + 1, results);
                used[i] = false;
            }
        }
    }
}

import java.util.Scanner;

/**
 * The MazePathSolver class solves a grid-based pathfinding problem.
 * Given a grid with a start ('S'), an end ('E'), and walls ('#'), 
 * it finds how many permutations of movement mappings allow a sequence 
 * of digits to reach the end position.
 */
public class MazePathSolver {

    private final char[][] grid;
    private final int rows;
    private final int cols;
    private final int startRow;
    private final int startCol;
    private final int endRow;
    private final int endCol;

    // Direction vectors for Up, Down, Right, Left
    private static final int[][] DIRECTIONS = {
            {-1, 0}, // Index 0: Up
            {1, 0},  // Index 1: Down
            {0, 1},  // Index 2: Right
            {0, -1}  // Index 3: Left
    };

    public MazePathSolver(int rows, int cols, char[][] grid, int startRow, int startCol, int endRow, int endCol) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.startRow = startRow;
        this.startCol = startCol;
        this.endRow = endRow;
        this.endCol = endCol;
    }

    /**
     * Iterates through all 24 permutations of directions and counts how many
     * successful paths can be formed using the provided movement sequence.
     * 
     * @param sequence A string of digits representing the movement commands.
     * @return The number of valid direction permutations.
     */
    public int solve(String sequence) {
        int successCount = 0;

        // Generate all 24 permutations of {0, 1, 2, 3} using nested loops.
        // Each index in the permutation array maps a direction to a specific digit.
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                if (i == j) continue;
                for (int k = 0; k < 4; k++) {
                    if (k == i || k == j) continue;
                    for (int l = 0; l < 4; l++) {
                        if (l == i || l == j || l == k) continue;

                        int[] permutation = {i, j, k, l};
                        if (simulatePath(permutation, sequence)) {
                            successCount++;
                        }
                    }
                }
            }
        }
        return successCount;
    }

    /**
     * Simulates the movement through the grid based on a specific mapping of digits to directions.
     * 
     * @param permutation An array where permutation[directionIndex] = digit.
     * @param sequence The sequence of digits to follow.
     * @return true if the end position is reached, false otherwise.
     */
    private boolean simulatePath(int[] permutation, String sequence) {
        int currentRow = startRow;
        int currentCol = startCol;

        // Edge case: If start position is already the end position.
        if (currentRow == endRow && currentCol == endCol) {
            return true;
        }

        for (int i = 0; i < sequence.length(); i++) {
            int digit = sequence.charAt(i) - '0';

            // Find which direction (0-3) this digit corresponds to in the current permutation.
            int directionIdx = -1;
            for (int d = 0; d < 4; d++) {
                if (permutation[d] == digit) {
                    directionIdx = d;
                    break;
                }
            }

            // If the digit is not in the 0-3 range, this permutation is invalid for the input.
            if (directionIdx == -1) {
                return false;
            }

            int nextRow = currentRow + DIRECTIONS[directionIdx][0];
            int nextCol = currentCol + DIRECTIONS[directionIdx][1];

            // Check for walls or boundaries.
            if (isInvalidMove(nextRow, nextCol)) {
                return false;
            }

            currentRow = nextRow;
            currentCol = nextCol;

            // If we reach the destination, the path is successful.
            if (currentRow == endRow && currentCol == endCol) {
                return true;
            }
        }

        return false;
    }

    private boolean isInvalidMove(int r, int c) {
        return r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] == '#';
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) {
            sc.close();
            return;
        }

        int rows = sc.nextInt();
        int cols = sc.nextInt();
        sc.nextLine(); // Consume the remaining newline character

        char[][] grid = new char[rows][cols];
        int startR = 0, startC = 0, endR = 0, endC = 0;

        for (int i = 0; i < rows; i++) {
            String line = sc.nextLine();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'S') {
                    startR = i;
                    startC = j;
                } else if (grid[i][j] == 'E') {
                    endR = i;
                    endC = j;
                }
            }
        }

        String sequence = sc.hasNextLine() ? sc.nextLine() : "";

        MazePathSolver solver = new MazePathSolver(rows, cols, grid, startR, startC, endR, endC);
        System.out.println(solver.solve(sequence));

        sc.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to solve the maze path permutation problem.
 * It finds how many ways we can map 4 directions to digits 0-3 
 * such that a given sequence of moves reaches the exit.
 */
public class MazeProblem {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            char[][] gridData = reader.nextGrid(rows, cols);
            char[] instructions = reader.nextCharArray();

            Maze maze = new Maze(gridData, rows, cols);
            MazeSolver solver = new MazeSolver(maze);

            int validPathCount = solver.countValidPermutations(instructions);
            out.println(validPathCount);

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Represents the directions available in the maze.
     */
    enum Direction {
        RIGHT(0, 1),
        DOWN(1, 0),
        LEFT(0, -1),
        UP(-1, 0);

        final int dr;
        final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }

    /**
     * Holds the maze structure and provides boundary/obstacle validation.
     */
    static class Maze {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private int startRow, startCol;
        private int endRow, endCol;

        public Maze(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
            findSpecialPoints();
        }

        private void findSpecialPoints() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                    } else if (grid[i][j] == 'E') {
                        endRow = i;
                        endCol = j;
                    }
                }
            }
        }

        public boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public boolean isObstacle(int r, int c) {
            return grid[r][c] == '#';
        }

        public boolean isExit(int r, int c) {
            return grid[r][c] == 'E';
        }

        public int getStartRow() { return startRow; }
        public int getStartCol() { return startCol; }
        public int getEndRow() { return endRow; }
        public int getEndCol() { return endCol; }
    }

    /**
     * Logic to simulate paths and iterate through permutations.
     */
    static class MazeSolver {
        private final Maze maze;
        private final Direction[] directions = Direction.values();

        public MazeSolver(Maze maze) {
            this.maze = maze;
        }

        /**
         * Iterates through all 4! permutations of directions to find valid mappings.
         * @param instructions An array of digits representing movement indices.
         * @return Total count of valid direction mappings.
         */
        public int countValidPermutations(char[] instructions) {
            int[] mapping = {0, 1, 2, 3}; // Indices for the directions array
            int validCount = 0;

            do {
                if (isPathSuccessful(instructions, mapping)) {
                    validCount++;
                }
            } while (nextPermutation(mapping));

            return validCount;
        }

        private boolean isPathSuccessful(char[] instructions, int[] mapping) {
            int currentRow = maze.getStartRow();
            int currentCol = maze.getStartCol();

            for (char instruction : instructions) {
                int digit = instruction - '0';
                // Map the digit to a specific direction from our current permutation
                Direction move = directions[mapping[digit]];

                currentRow += move.dr;
                currentCol += move.dc;

                if (!maze.isWithinBounds(currentRow, currentCol) || maze.isObstacle(currentRow, currentCol)) {
                    return false;
                }

                // If we hit the exit at any point in the sequence
                if (maze.isExit(currentRow, currentCol)) {
                    return true;
                }
            }

            // Check if we ended exactly on the exit
            return currentRow == maze.getEndRow() && currentCol == maze.getEndCol();
        }

        /**
         * Standard lexicographical next permutation algorithm.
         */
        private boolean nextPermutation(int[] array) {
            int i = array.length - 2;
            while (i >= 0 && array[i] >= array[i + 1]) {
                i--;
            }

            if (i < 0) return false;

            int j = array.length - 1;
            while (array[j] <= array[i]) {
                j--;
            }

            swap(array, i, j);
            reverse(array, i + 1, array.length - 1);
            return true;
        }

        private void swap(int[] array, int i, int j) {
            int temp = array[i];
            array[i] = array[j];
            array[j] = temp;
        }

        private void reverse(int[] array, int start, int end) {
            while (start < end) {
                swap(array, start++, end--);
            }
        }
    }

    /**
     * Utility class for fast and clean input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public char[][] nextGrid(int rows, int cols) {
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }
            return grid;
        }

        public char[] nextCharArray() {
            return next().toCharArray();
        }
    }
}

import java.util.*;

/**
 * A program that calculates how many direction-to-command mappings 
 * allow a robot to reach an exit in a maze.
 */
public class MazePermutationSolver {

    /**
     * Represents the types of cells available in the maze grid.
     */
    private enum Cell {
        WALL, PATH, EXIT, START
    }

    /**
     * Represents physical directions and their coordinate offsets.
     */
    private enum Direction {
        LEFT(0, -1), 
        UP(-1, 0), 
        RIGHT(0, 1), 
        DOWN(1, 0);

        private final int rowOffset;
        private final int colOffset;

        Direction(int rowOffset, int colOffset) {
            this.rowOffset = rowOffset;
            this.colOffset = colOffset;
        }

        public int getRowOffset() { return rowOffset; }
        public int getColOffset() { return colOffset; }
    }

    /**
     * A simple coordinate representation.
     */
    private static class Point {
        final int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Encapsulates the maze structure and provides boundary and cell checks.
     */
    private static class Maze {
        private final Cell[][] grid;
        private final int rows;
        private final int cols;
        private Point startPoint;

        Maze(int rows, int cols, String[] gridRows) {
            this.rows = rows;
            this.cols = cols;
            this.grid = new Cell[rows][cols];
            initializeGrid(gridRows);
        }

        private void initializeGrid(String[] gridRows) {
            for (int i = 0; i < rows; i++) {
                String rowStr = gridRows[i];
                for (int j = 0; j < cols; j++) {
                    char ch = rowStr.charAt(j);
                    if (ch == '#') {
                        grid[i][j] = Cell.WALL;
                    } else if (ch == 'E') {
                        grid[i][j] = Cell.EXIT;
                    } else if (ch == 'S') {
                        grid[i][j] = Cell.START;
                        startPoint = new Point(i, j);
                    } else {
                        grid[i][j] = Cell.PATH;
                    }
                }
            }
        }

        public boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public Cell getCell(int r, int c) {
            return grid[r][c];
        }

        public Point getStartPoint() {
            return startPoint;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        String[] gridData = new String[rows];
        for (int i = 0; i < rows; i++) {
            gridData[i] = scanner.next();
        }

        String commandSequence = scanner.next();
        Maze maze = new Maze(rows, cols, gridData);

        // Generate all 24 possible mappings of command digits {0,1,2,3} to Directions
        List<Direction[]> mappings = new ArrayList<>();
        generateAllPermutations(new ArrayList<>(), new ArrayList<>(Arrays.asList(Direction.values())), mappings);

        int successfulMappingsCount = 0;
        for (Direction[] mapping : mappings) {
            if (simulatesToExit(maze, commandSequence, mapping)) {
                successfulMappingsCount++;
            }
        }

        System.out.println(successfulMappingsCount);
        scanner.close();
    }

    /**
     * Simulates the movement of the robot given a specific direction mapping.
     * 
     * @param maze The maze grid.
     * @param commands The string of command digits.
     * @param mapping An array where index i is the Direction for command digit i.
     * @return true if the exit is reached, false otherwise.
     */
    private static boolean simulatesToExit(Maze maze, String commands, Direction[] mapping) {
        Point currentPos = maze.getStartPoint();

        for (int i = 0; i < commands.length(); i++) {
            int commandDigit = commands.charAt(i) - '0';
            Direction direction = mapping[commandDigit];

            int nextR = currentPos.r + direction.getRowOffset();
            int nextC = currentPos.c + direction.getColOffset();

            if (!maze.isWithinBounds(nextR, nextC)) {
                break; // Robot hit a boundary
            }

            Cell nextCell = maze.getCell(nextR, nextC);
            if (nextCell == Cell.WALL) {
                break; // Robot hit a wall
            } else if (nextCell == Cell.EXIT) {
                return true; // Robot reached the exit
            } else {
                // Robot moves to a Path or the Start position
                currentPos = new Point(nextR, nextC);
            }
        }

        return false;
    }

    /**
     * Recursively generates all permutations of the provided direction list.
     */
    private static void generateAllPermutations(List<Direction> current, 
                                                List<Direction> remaining, 
                                                List<Direction[]> result) {
        if (remaining.isEmpty()) {
            Direction[] permutation = current.toArray(new Direction[0]);
            result.add(permutation);
            return;
        }

        for (int i = 0; i < remaining.size(); i++) {
            Direction dir = remaining.get(i);

            List<Direction> nextCurrent = new ArrayList<>(current);
            nextCurrent.add(dir);

            List<Direction> nextRemaining = new ArrayList<>(remaining);
            nextRemaining.remove(i);

            generateAllPermutations(nextCurrent, nextRemaining, result);
        }
    }
}

