/**
 * A solver that calculates how many permutations of movement directions 
 * lead a starting point 'S' to an exit 'E' following a specific sequence.
 */
public class GridPathSolver {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner();

        try {
            int rows = sc.nextInt();
            int cols = sc.nextInt();

            Grid grid = new Grid(rows, cols, sc);
            String sequenceStr = sc.next();
            int[] movementSequence = parseSequence(sequenceStr);

            PathSimulator simulator = new PathSimulator(grid, movementSequence);
            System.out.println(simulator.solve());
        } catch (Exception e) {
            // In a production environment, use a proper logging framework.
            e.printStackTrace();
        }
    }

    private static int[] parseSequence(String sequenceStr) {
        int[] seq = new int[sequenceStr.length()];
        for (int i = 0; i < sequenceStr.length(); i++) {
            seq[i] = sequenceStr.charAt(i) - '0';
        }
        return seq;
    }

    /**
     * Represents a coordinate in the grid.
     */
    static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Represents a directional movement vector.
     */
    static class Direction {
        final int dr;
        final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }

    /**
     * Manages the grid boundaries, obstacles, and cell types.
     */
    static class Grid {
        private final char[][] cells;
        private final int rows;
        private final int cols;
        private Point startPoint;

        Grid(int rows, int cols, FastScanner sc) {
            this.rows = rows;
            this.cols = cols;
            this.cells = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String rowStr = sc.next();
                for (int j = 0; j < cols; j++) {
                    cells[i][j] = rowStr.charAt(j);
                    if (cells[i][j] == 'S') {
                        startPoint = new Point(i, j);
                    }
                }
            }
        }

        public boolean isWalkable(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && cells[r][c] != '#';
        }

        public char getCell(int r, int c) {
            return cells[r][c];
        }

        public Point getStartPoint() {
            return startPoint;
        }
    }

    /**
     * Handles the permutation of directions and path simulation.
     */
    static class PathSimulator {
        private final Grid grid;
        private final int[] sequence;
        private final Direction[] baseDirections = {
            new Direction(-1, 0), // Up
            new Direction(0, 1),  // Right
            new Direction(1, 0),  // Down
            new Direction(0, -1)  // Left
        };

        PathSimulator(Grid grid, int[] sequence) {
            this.grid = grid;
            this.sequence = sequence;
        }

        public int solve() {
            List<List<Direction>> permutations = new ArrayList<>();
            generatePermutations(new ArrayList<>(), new ArrayList<>(List.of(baseDirections)), permutations);

            int successfulPaths = 0;
            for (List<Direction> permutation : permutations) {
                if (simulatePath(permutation)) {
                    successfulPaths++;
                }
            }
            return successfulPaths;
        }

        private boolean simulatePath(List<Direction> directionMapping) {
            int curRow = grid.getStartPoint().row;
            int curCol = grid.getStartPoint().col;

            for (int moveIdx : sequence) {
                Direction move = directionMapping.get(moveIdx);
                curRow += move.dr;
                curCol += move.dc;

                if (!grid.isWalkable(curRow, curCol)) {
                    return false;
                }

                if (grid.getCell(curRow, curCol) == 'E') {
                    return true;
                }
            }
            return false;
        }

        private void generatePermutations(List<Direction> current, List<Direction> available, List<List<Direction>> result) {
            if (available.isEmpty()) {
                result.add(new ArrayList<>(current));
                return;
            }
            for (int i = 0; i < available.size(); i++) {
                Direction dir = available.remove(i);
                current.add(dir);
                generatePermutations(current, available, result);
                current.remove(current.size() - 1);
                available.add(i, dir);
            }
        }
    }

    /**
     * Efficient utility for reading input.
     */
    public static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        public FastScanner() {
            this(new BufferedReader(new InputStreamReader(System.in)));
        }

        public FastScanner(Reader in) {
            br = new BufferedReader(in);
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver that finds how many permutations of direction mappings 
 * allow a path from a starting point 'S' to an end point 'E' 
 * given a specific sequence of movement commands.
 */
public class TaskB {

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter writer = new PrintWriter(System.out)) {

            Solver solver = new Solver(reader, writer);
            solver.solve();

        } catch (IOException e) {
            System.err.println("Error reading or writing input: " + e.getMessage());
        }
    }

    /**
     * Orchestrates the input reading, permutation generation, and simulation.
     */
    static class Solver {
        private final BufferedReader reader;
        private final PrintWriter writer;

        // Directional vectors: Down, Right, Up, Left
        private static final int[] DIRECTION_X = {1, 0, -1, 0};
        private static final int[] DIRECTION_Y = {0, 1, 0, -1};

        public Solver(BufferedReader reader, PrintWriter writer) {
            this.reader = reader;
            this.writer = writer;
        }

        public void solve() throws IOException {
            String line = reader.readLine();
            if (line == null) return;

            String[] tokens = line.trim().split("\\s+");
            int rows = Integer.parseInt(tokens[0]);
            int cols = Integer.parseInt(tokens[1]);

            char[][] gridData = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                gridData[i] = reader.readLine().toCharArray();
            }

            char[] moveCommands = reader.readLine().toCharArray();
            Grid grid = new Grid(gridData, rows, cols);
            PathSimulator simulator = new PathSimulator(grid);

            int successfulPaths = 0;

            // The mapping translates a command (0-3) to a direction index (0-3)
            int[] directionMapping = {0, 1, 2, 3};

            // Iterate through all 4! (24) permutations of direction mappings
            do {
                if (simulator.simulate(moveCommands, directionMapping)) {
                    successfulPaths++;
                }
            } while (PermutationUtils.nextPermutation(directionMapping));

            writer.println(successfulPaths);
        }
    }

    /**
     * Represents the game board and stores crucial landmarks.
     */
    static class Grid {
        private final char[][] board;
        private final int rows;
        private final int cols;
        private final int startR;
        private final int startC;

        public Grid(char[][] board, int rows, int cols) {
            this.board = board;
            this.rows = rows;
            this.cols = cols;

            int sR = -1, sC = -1;
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (board[i][j] == 'S') {
                        sR = i;
                        sC = j;
                        break;
                    }
                }
                if (sR != -1) break;
            }
            this.startR = sR;
            this.startC = sC;
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }
        public char getCell(int r, int c) { return board[r][c]; }
        public int getStartR() { return startR; }
        public int getStartC() { return startC; }

        public boolean isOutOfBounds(int r, int c) {
            return r < 0 || r >= rows || c < 0 || c >= cols;
        }
    }

    /**
     * Contains the logic to simulate a single path based on a permutation.
     */
    static class PathSimulator {
        private final Grid grid;
        private static final int[] DX = {1, 0, -1, 0};
        private static final int[] DY = {0, 1, 0, -1};

        public PathSimulator(Grid grid) {
            this.grid = grid;
        }

        /**
         * Simulates the path iteratively. 
         * Returns true if the path reaches 'E' without hitting '#' or going out of bounds.
         */
        public boolean simulate(char[] commands, int[] mapping) {
            int currR = grid.getStartR();
            int currC = grid.getStartC();

            for (char cmdChar : commands) {
                // 1. Check if current position is invalid
                if (grid.isOutOfBounds(currR, currC) || grid.getCell(currR, currC) == '#') {
                    return false;
                }

                // 2. Check if current position is the goal
                if (grid.getCell(currR, currC) == 'E') {
                    return true;
                }

                // 3. Execute movement
                int command = cmdChar - '0';
                int dirIdx = mapping[command];
                currR += DX[dirIdx];
                currC += DY[dirIdx];
            }

            // 4. Check final position after all commands are exhausted
            return !grid.isOutOfBounds(currR, currC) && 
                   grid.getCell(currR, currC) == 'E';
        }
    }

    /**
     * Utility class for generating lexicographical permutations.
     */
    static class PermutationUtils {
        /**
         * Transforms the array into the next lexicographical permutation.
         * @return true if a next permutation exists, false if it's the last one.
         */
        public static boolean nextPermutation(int[] array) {
            int i = array.length - 2;
            while (i >= 0 && array[i] >= array[i + 1]) {
                i--;
            }

            if (i < 0) return false;

            int j = array.length - 1;
            while (array[j] <= array[i]) {
                j--;
            }

            swap(array, i, j);
            reverse(array, i + 1, array.length - 1);
            return true;
        }

        private static void swap(int[] array, int i, int j) {
            int temp = array[i];
            array[i] = array[j];
            array[j] = temp;
        }

        private static void reverse(int[] array, int start, int end) {
            while (start < end) {
                swap(array, start++, end--);
            }
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

/**
 * MazeNavigator solves a puzzle where we must find how many unique mappings 
 * of command digits (0-3) to cardinal directions allow a character 
 * to reach the exit 'E' from the start 'S'.
 */
public class MazeNavigator {

    private static final char START_CELL = 'S';
    private static final char EXIT_CELL = 'E';
    private static final char WALL_CELL = '#';

    // Direction vectors: Right, Left, Down, Up
    private static final int[][] DIRECTIONS = {
        {0, 1},  // 0
        {0, -1}, // 1
        {1, 0},  // 2
        {-1, 0}  // 3
    };

    public static void main(String[] args) {
        FastReader reader = new FastReader();

        int rows = reader.nextInt();
        int cols = reader.nextInt();

        char[][] maze = new char[rows][cols];
        int startRow = -1;
        int startCol = -1;

        // Parse maze and locate the starting position
        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            for (int j = 0; j < cols; j++) {
                maze[i][j] = line.charAt(j);
                if (maze[i][j] == START_CELL) {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        String commands = reader.next();

        // Generate all permutations of directions [0, 1, 2, 3]
        // and count how many valid mappings allow reaching the exit.
        int[] directionMapping = {0, 1, 2, 3};
        int validMappingCount = countValidMappings(directionMapping, 0, maze, startRow, startCol, commands);

        System.out.println(validMappingCount);
    }

    /**
     * Uses backtracking to generate all permutations of the direction mapping.
     */
    private static int countValidMappings(int[] mapping, int index, char[][] maze, 
                                         int startRow, int startCol, String commands) {
        if (index == mapping.length) {
            return canReachExit(maze, mapping, startRow, startCol, commands) ? 1 : 0;
        }

        int count = 0;
        for (int i = index; i < mapping.length; i++) {
            swap(mapping, index, i);
            count += countValidMappings(mapping, index + 1, maze, startRow, startCol, commands);
            swap(mapping, index, i); // backtrack
        }
        return count;
    }

    /**
     * Simulates the movement based on the provided mapping of commands to directions.
     */
    private static boolean canReachExit(char[][] maze, int[] mapping, int startRow, int startCol, String commands) {
        int currentRow = startRow;
        int currentCol = startCol;
        int rows = maze.length;
        int cols = maze[0].length;

        for (int i = 0; i < commands.length(); i++) {
            // Map the command digit (0-3) to a direction index
            int commandDigit = commands.charAt(i) - '0';
            int directionIdx = mapping[commandDigit];

            currentRow += DIRECTIONS[directionIdx][0];
            currentCol += DIRECTIONS[directionIdx][1];

            // Boundary and Collision Check
            if (isOutOfBounds(currentRow, currentCol, rows, cols) || maze[currentRow][currentCol] == WALL_CELL) {
                return false;
            }

            // Success Condition
            if (maze[currentRow][currentCol] == EXIT_CELL) {
                return true;
            }
        }

        return false;
    }

    private static boolean isOutOfBounds(int r, int c, int maxR, int maxC) {
        return r < 0 || r >= maxR || c < 0 || c >= maxC;
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Fast I/O utility for efficient reading of large inputs.
     */
    private static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return "";
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * A program to solve a maze-path puzzle by testing all permutations of 
 * movement directions (Left, Right, Up, Down) against a given digit sequence.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        String[] gridData = new String[rows];
        for (int i = 0; i < rows; i++) {
            gridData[i] = scanner.next();
        }

        String sequence = scanner.next();
        scanner.close();

        Maze maze = new Maze(gridData, rows, cols);
        MazeSolver solver = new MazeSolver(maze);

        int successfulPaths = solver.countSuccessfulPaths(sequence);
        System.out.println(successfulPaths);
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    static class Position {
        final int row;
        final int col;

        Position(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Manages the maze grid, boundaries, and special locations (Start/End).
     */
    static class Maze {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private Position startPos;
        private Position endPos;

        public Maze(String[] gridData, int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            this.grid = new char[rows][cols];
            parseGrid(gridData);
        }

        private void parseGrid(String[] gridData) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    char cell = gridData[r].charAt(c);
                    grid[r][c] = cell;
                    if (cell == 'S') {
                        startPos = new Position(r, c);
                    } else if (cell == 'E') {
                        endPos = new Position(r, c);
                    }
                }
            }
        }

        public boolean isInvalid(Position pos) {
            if (pos.row < 0 || pos.row >= rows || pos.col < 0 || pos.col >= cols) {
                return true;
            }
            return grid[pos.row][pos.col] == '#';
        }

        public boolean isEnd(Position pos) {
            return pos.row == endPos.row && pos.col == endPos.col;
        }

        public Position getStart() {
            return startPos;
        }
    }

    /**
     * Handles the logic of simulating paths through the maze.
     */
    static class MazeSolver {
        private final Maze maze;

        // All 24 permutations of the four directions: Left, Right, Up, Down
        private static final String[] PERMUTATIONS = {
            "LRUD", "LRDU", "LURD", "LUDR", "LDUR", "LDRU",
            "RLUD", "RLDU", "RULD", "RUDL", "RDUL", "RDLU",
            "URLD", "URDL", "ULRD", "ULDR", "UDLR", "UDRL",
            "DRUL", "DRLU", "DURL", "DULR", "DLUR", "DLRU"
        };

        public MazeSolver(Maze maze) {
            this.maze = maze;
        }

        public int countSuccessfulPaths(String sequence) {
            int successCount = 0;
            for (String permutation : PERMUTATIONS) {
                if (simulatePath(sequence, permutation)) {
                    successCount++;
                }
            }
            return successCount;
        }

        /**
         * Simulates a single path based on a permutation of directions.
         * @return true if the path reaches 'E' without hitting a wall or boundary.
         */
        private boolean simulatePath(String sequence, String permutation) {
            Position current = maze.getStart();

            for (int i = 0; i < sequence.length(); i++) {
                // Map the digit in the sequence to an index in the permutation string
                int directionIndex = sequence.charAt(i) - '0';
                char moveDirection = permutation.charAt(directionIndex);

                current = move(current, moveDirection);

                if (maze.isInvalid(current)) {
                    return false;
                }
                if (maze.isEnd(current)) {
                    return true;
                }
            }
            return false;
        }

        private Position move(Position pos, char direction) {
            switch (direction) {
                case 'L': return new Position(pos.row, pos.col - 1);
                case 'R': return new Position(pos.row, pos.col + 1);
                case 'U': return new Position(pos.row - 1, pos.col);
                case 'D': return new Position(pos.row + 1, pos.col);
                default:
                    throw new IllegalArgumentException("Invalid direction: " + direction);
            }
        }
    }
}

import java.util.*;

/**
 * A program to solve a maze navigation problem by testing all possible 
 * direction mappings for a given set of instruction characters.
 */
public class MazePathSolver {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        // Parse grid dimensions
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        int startR = -1, startC = -1;
        int endR = -1, endC = -1;

        // Parse the grid and identify Start (S) and End (E) positions
        for (int i = 0; i < rows; i++) {
            String rowString = scanner.next();
            for (int j = 0; j < cols; j++) {
                grid[i][j] = rowString.charAt(j);
                if (grid[i][j] == 'S') {
                    startR = i;
                    startC = j;
                } else if (grid[i][j] == 'E') {
                    endR = i;
                    endC = j;
                }
            }
        }

        // Parse the instruction sequence
        if (!scanner.hasNext()) {
            return;
        }
        String instructions = scanner.next();

        // Initialize domain models and solver
        Maze maze = new Maze(grid, startR, startC, endR, endC);
        MazeSolver solver = new MazeSolver(maze, instructions);

        // Output the result
        System.out.println(solver.countValidMappings());
        scanner.close();
    }

    // --- Domain Models ---

    /**
     * Represents the possible movements within the maze.
     */
    enum Direction {
        UP(-1, 0), DOWN(1, 0), LEFT(0, -1), RIGHT(0, 1);

        final int dr, dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }

    /**
     * Encapsulates the maze grid and its boundary/obstacle rules.
     */
    static class Maze {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final int startR, startC;
        private final int endR, endC;

        public Maze(char[][] grid, int startR, int startC, int endR, int endC) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
            this.startR = startR;
            this.startC = startC;
            this.endR = endR;
            this.endC = endC;
        }

        public boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public boolean isWall(int r, int c) {
            return grid[r][c] == '#';
        }

        public boolean isEnd(int r, int c) {
            return r == endR && c == endC;
        }

        public int getStartR() { return startR; }
        public int getStartC() { return startC; }
    }

    // --- Business Logic ---

    /**
     * Handles the logic of testing instruction permutations against the maze.
     */
    static class MazeSolver {
        private final Maze maze;
        private final String instructions;

        public MazeSolver(Maze maze, String instructions) {
            this.maze = maze;
            this.instructions = instructions;
        }

        /**
         * Iterates through all 24 permutations of direction mappings
         * and counts how many allow the path to reach the exit 'E'.
         */
        public int countValidMappings() {
            int validCount = 0;
            List<String> permutations = PermutationGenerator.generate("0123");

            for (String p : permutations) {
                if (canReachEndWithMapping(p)) {
                    validCount++;
                }
            }
            return validCount;
        }

        /**
         * Creates a mapping from instruction digits to Directions and simulates the path.
         * @param mappingStr A permutation string where index 0=UP, 1=DOWN, 2=LEFT, 3=RIGHT
         */
        private boolean canReachEndWithMapping(String mappingStr) {
            Map<Character, Direction> mapping = new HashMap<>();
            mapping.put(mappingStr.charAt(0), Direction.UP);
            mapping.put(mappingStr.charAt(1), Direction.DOWN);
            mapping.put(mappingStr.charAt(2), Direction.LEFT);
            mapping.put(mappingStr.charAt(3), Direction.RIGHT);

            return simulatePath(mapping);
        }

        /**
         * Iteratively simulates the movement to avoid StackOverflow on deep paths.
         */
        private boolean simulatePath(Map<Character, Direction> mapping) {
            int currR = maze.getStartR();
            int currC = maze.getStartC();
            int instructionIdx = 0;

            while (true) {
                // 1. Check if the current position is valid (within bounds and not a wall)
                if (!maze.isWithinBounds(currR, currC) || maze.isWall(currR, currC)) {
                    return false;
                }

                // 2. Check if the current position is the exit
                if (maze.isEnd(currR, currC)) {
                    return true;
                }

                // 3. Check if we have exhausted all instructions without hitting the end
                if (instructionIdx >= instructions.length()) {
                    return false;
                }

                // 4. Determine movement based on the instruction and mapping
                char moveChar = instructions.charAt(instructionIdx);
                Direction dir = mapping.get(moveChar);

                if (dir == null) {
                    return false; // Encountered an undefined instruction character
                }

                currR += dir.dr;
                currC += dir.dc;
                instructionIdx++;
            }
        }
    }

    // --- Utilities ---

    /**
     * Utility to generate all possible permutations of a string.
     */
    static class PermutationGenerator {
        public static List<String> generate(String input) {
            List<String> result = new ArrayList<>();
            backtrack(input.toCharArray(), 0, result);
            return result;
        }

        private static void backtrack(char[] chars, int index, List<String> result) {
            if (index == chars.length) {
                result.add(new String(chars));
                return;
            }
            for (int i = index; i < chars.length; i++) {
                swap(chars, index, i);
                backtrack(chars, index + 1, result);
                swap(chars, index, i); // backtrack
            }
        }

        private static void swap(char[] chars, int i, int j) {
            char temp = chars[i];
            chars[i] = chars[j];
            chars[j] = temp;
        }
    }
}

import java.util.*;

/**
 * A simulator that determines how many different command mappings 
 * allow a robot to reach an exit in a maze.
 */
public class RobotMazeSimulator {

    /**
     * Represents a coordinate on the grid.
     */
    private record Position(int row, int col) {
        public Position move(Direction direction) {
            return new Position(row + direction.rowOffset(), col + direction.colOffset());
        }
    }

    /**
     * Represents possible movement directions and their coordinate offsets.
     */
    private enum Direction {
        UP(-1, 0),
        DOWN(1, 0),
        LEFT(0, -1),
        RIGHT(0, 1);

        private final int rowOffset;
        private final int colOffset;

        Direction(int rowOffset, int colOffset) {
            this.rowOffset = rowOffset;
            this.colOffset = colOffset;
        }

        public int rowOffset() { return rowOffset; }
        public int colOffset() { return colOffset; }
    }

    /**
     * Represents the game board, including walls and the start/end positions.
     */
    private static class Maze {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private final Position startPos;

        public Maze(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            this.startPos = findPosition('S');
        }

        private Position findPosition(char target) {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (grid[r][c] == target) {
                        return new Position(r, c);
                    }
                }
            }
            return null;
        }

        public boolean isOutOfBounds(Position pos) {
            return pos.row() < 0 || pos.row() >= rows || pos.col() < 0 || pos.col() >= cols;
        }

        public boolean isWall(Position pos) {
            return grid[pos.row()][pos.col()] == '#';
        }

        public boolean isExit(Position pos) {
            return grid[pos.row()][pos.col()] == 'E';
        }

        public Position getStartPos() {
            return startPos;
        }
    }

    /**
     * Engine responsible for running a single simulation based on a command mapping.
     */
    private static class SimulationEngine {
        public boolean run(Maze maze, String commands, Direction[] commandMapping) {
            Position currentPos = maze.getStartPos();

            for (char cmdChar : commands.toCharArray()) {
                int digit = Character.getNumericValue(cmdChar);
                Direction direction = commandMapping[digit];

                currentPos = currentPos.move(direction);

                if (maze.isOutOfBounds(currentPos) || maze.isWall(currentPos)) {
                    return false;
                }

                if (maze.isExit(currentPos)) {
                    return true;
                }
            }

            return false;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        char[][] grid = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            grid[i] = line.toCharArray();
        }

        String commands = scanner.next();
        Maze maze = new Maze(rows, cols, grid);
        SimulationEngine engine = new SimulationEngine();

        System.out.println(countSuccessfulMappings(maze, commands, engine));
        scanner.close();
    }

    /**
     * Iterates through all 24 permutations of direction mappings to count successes.
     */
    private static int countSuccessfulMappings(Maze maze, String commands, SimulationEngine engine) {
        int successfulCount = 0;
        int[] digits = {0, 1, 2, 3};

        // Generate all permutations of {0, 1, 2, 3}
        // i=Up, j=Left, k=Down, l=Right (matching original logic)
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                if (j == i) continue;
                for (int k = 0; k < 4; k++) {
                    if (k == i || k == j) continue;
                    for (int l = 0; l < 4; l++) {
                        if (l == i || l == j || l == k) continue;

                        Direction[] mapping = new Direction[4];
                        mapping[i] = Direction.UP;
                        mapping[j] = Direction.LEFT;
                        mapping[k] = Direction.DOWN;
                        mapping[l] = Direction.RIGHT;

                        if (engine.run(maze, commands, mapping)) {
                            successfulCount++;
                        }
                    }
                }
            }
        }

        return successfulCount;
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.NoSuchElementException;

/**
 * A utility class for high-performance input reading.
 */
class FastReader {
    private static final InputStream in = System.in;
    private final byte[] buffer = new byte[2048];
    private int pointer = 0;
    private int bufferLength = 0;

    private boolean hasNextByte() {
        if (pointer < bufferLength) return true;
        pointer = 0;
        try {
            bufferLength = in.read(buffer);
        } catch (IOException e) {
            e.printStackTrace();
        }
        return bufferLength > 0;
    }

    public boolean hasNext() {
        while (hasNextByte() && !isPrintable(buffer[pointer])) {
            pointer++;
        }
        return hasNextByte();
    }

    private boolean isPrintable(int ch) {
        return ch >= '!' && ch <= '~';
    }

    private int nextByte() {
        if (!hasNextByte()) return -1;
        return buffer[pointer++];
    }

    public String next() {
        if (!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = -1;
        while (isPrintable(b = nextByte())) {
            sb.appendCodePoint(b);
        }
        return sb.toString();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }
}

/**
 * Solves the maze path problem by trying all possible permutations 
 * of direction mappings for the given command sequence.
 */
public class MazePathFinder {
    private static final int[] ROW_OFFSETS = {-1, 1, 0, 0};
    private static final int[] COL_OFFSETS = {0, 0, -1, 1};

    private int rows;
    private int cols;
    private char[][] maze;
    private int startRow, startCol;
    private int endRow, endCol;
    private char[] commandSequence;

    /**
     * Main execution logic.
     */
    public void solve(FastReader reader, PrintWriter out) {
        this.rows = reader.nextInt();
        this.cols = reader.nextInt();
        this.maze = new char[rows][];

        parseMaze(reader);

        this.commandSequence = reader.next().toCharArray();

        int totalPathsFound = countAllPossiblePaths();
        out.println(totalPathsFound);
    }

    private void parseMaze(FastReader reader) {
        for (int i = 0; i < rows; i++) {
            maze[i] = reader.next().toCharArray();
            for (int j = 0; j < cols; j++) {
                if (maze[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                } else if (maze[i][j] == 'E') {
                    endRow = i;
                    endCol = j;
                }
            }
        }
    }

    /**
     * Iterates through all 24 permutations of direction mappings (0-3).
     */
    private int countAllPossiblePaths() {
        int totalPaths = 0;
        int[] directionMapping = new int[4];

        // Exhaustively generate all permutations of {0, 1, 2, 3}
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                if (i == j) continue;
                for (int k = 0; k < 4; k++) {
                    if (i == k || j == k) continue;
                    for (int l = 0; l < 4; l++) {
                        if (i == l || j == l || k == l) continue;

                        directionMapping[0] = i;
                        directionMapping[1] = j;
                        directionMapping[2] = k;
                        directionMapping[3] = l;

                        totalPaths += performDFS(startRow, startCol, 0, directionMapping);
                    }
                }
            }
        }
        return totalPaths;
    }

    /**
     * Depth First Search to trace the path based on the command sequence.
     * 
     * @param r Current row
     * @param c Current column
     * @param cmdIdx Current index in the command sequence
     * @param mapping The current permutation of direction indices
     * @return Number of paths that reach the end
     */
    private int performDFS(int r, int c, int cmdIdx, int[] mapping) {
        // Goal reached
        if (r == endRow && c == endCol) {
            return 1;
        }
        // Out of commands
        if (cmdIdx == commandSequence.length) {
            return 0;
        }

        // Translate digit command to a direction index
        int commandDigit = commandSequence[cmdIdx] - '0';
        int directionIdx = mapping[commandDigit];

        int nextR = r + ROW_OFFSETS[directionIdx];
        int nextC = c + COL_OFFSETS[directionIdx];

        int pathsFound = 0;
        if (isValidMove(nextR, nextC)) {
            pathsFound = performDFS(nextR, nextC, cmdIdx + 1, mapping);
        }

        return pathsFound;
    }

    private boolean isValidMove(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && maze[r][c] != '#';
    }

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter out = new PrintWriter(System.out);

        try {
            new MazePathFinder().solve(reader, out);
        } finally {
            out.flush();
            out.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program that calculates how many unique direction mappings (0-3) 
 * allow a path to reach an exit 'E' from a starting point 'S'.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        // Read grid dimensions
        String nStr = reader.next();
        if (nStr == null) return;
        int rows = Integer.parseInt(nStr);
        int cols = reader.nextInt();

        // Read grid layout
        char[][] board = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            board[i] = reader.next().toCharArray();
        }

        // Read instruction sequence
        char[] instructionChars = reader.next().toCharArray();
        int[] instructions = new int[instructionChars.length];
        for (int i = 0; i < instructionChars.length; i++) {
            instructions[i] = instructionChars[i] - '0';
        }

        // Initialize domain objects and solver
        Grid grid = new Grid(rows, cols, board);
        PathfindingSolver solver = new PathfindingSolver(grid, instructions);

        // Execute and output result
        int result = solver.solve();
        System.out.println(result);
    }

    /**
     * Represents a coordinate on the grid.
     */
    record Position(int row, int col) {}

    /**
     * Represents a movement vector.
     */
    record Direction(int dr, int dc) {}

    /**
     * Manages the grid state and boundary/collision checks.
     */
    static class Grid {
        private final char[][] board;
        private final int rows;
        private final int cols;
        private final Position startPosition;

        public Grid(int rows, int cols, char[][] board) {
            this.rows = rows;
            this.cols = cols;
            this.board = board;
            this.startPosition = findStart();
        }

        private Position findStart() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (board[r][c] == 'S') {
                        return new Position(r, c);
                    }
                }
            }
            return null;
        }

        public boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public boolean isWall(int r, int c) {
            return board[r][c] == '#';
        }

        public boolean isExit(int r, int c) {
            return board[r][c] == 'E';
        }

        public Position getStartPosition() {
            return startPosition;
        }
    }

    /**
     * Handles the permutation logic and path validation.
     */
    static class PathfindingSolver {
        private final Grid grid;
        private final int[] instructions;
        private final Direction[] availableDirections = {
            new Direction(1, 0),  // 0
            new Direction(0, 1),  // 1
            new Direction(-1, 0), // 2
            new Direction(0, -1)  // 3
        };

        private final Direction[] currentMapping = new Direction[4];
        private final boolean[] usedDirections = new boolean[4];
        private int successfulMappingsCount = 0;

        public PathfindingSolver(Grid grid, int[] instructions) {
            this.grid = grid;
            this.instructions = instructions;
        }

        /**
         * Orchestrates the permutation generation and returns the count of valid paths.
         */
        public int solve() {
            if (grid.getStartPosition() == null) return 0;
            generatePermutations(0);
            return successfulMappingsCount;
        }

        /**
         * Standard backtracking to generate all permutations of directions for mapping 0-3.
         */
        private void generatePermutations(int depth) {
            if (depth == 4) {
                if (isValidPath()) {
                    successfulMappingsCount++;
                }
                return;
            }

            for (int i = 0; i < 4; i++) {
                if (!usedDirections[i]) {
                    usedDirections[i] = true;
                    currentMapping[depth] = availableDirections[i];
                    generatePermutations(depth + 1);
                    usedDirections[i] = false;
                }
            }
        }

        /**
         * Validates if the current mapping satisfies the path requirements.
         */
        private boolean isValidPath() {
            int r = grid.getStartPosition().row();
            int c = grid.getStartPosition().col();

            for (int command : instructions) {
                Direction move = currentMapping[command];
                r += move.dr();
                c += move.dc();

                if (!grid.isWithinBounds(r, c) || grid.isWall(r, c)) {
                    return false;
                }

                if (grid.isExit(r, c)) {
                    return true;
                }
            }
            return false;
        }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next != null ? Integer.parseInt(next) : 0;
        }
    }
}

