/**
 * A program that calculates how many direction-digit permutations 
 * allow a character to reach the 'E' (End) cell in a grid.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int[] dimensions = reader.readIntArray();
            if (dimensions.length < 2) return;

            int rows = dimensions[0];
            int cols = dimensions[1];

            char[][] gridData = new char[rows][];
            for (int i = 0; i < rows; i++) {
                gridData[i] = reader.readLine().toCharArray();
            }

            String commands = reader.readLine();

            Grid grid = new Grid(gridData, rows, cols);
            Solver solver = new Solver(grid, commands);

            out.println(solver.solve());
        } catch (Exception e) {
            // In a real-world scenario, use a logger.
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    record Position(int row, int col) {}

    /**
     * Manages the grid structure and provides boundary and cell validation.
     */
    static class Grid {
        private final char[][] cells;
        private final int rows;
        private final int cols;
        private Position startPosition;

        public Grid(char[][] cells, int rows, int cols) {
            this.cells = cells;
            this.rows = rows;
            this.cols = cols;
            findStartPosition();
        }

        private void findStartPosition() {
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (cells[r][c] == 'S') {
                        this.startPosition = new Position(r, c);
                        return;
                    }
                }
            }
        }

        public boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public char getCell(int r, int c) {
            return cells[r][c];
        }

        public Position getStartPosition() {
            return startPosition;
        }
    }

    /**
     * Contains the logic to solve the problem by permuting direction mappings.
     */
    static class Solver {
        private static final int[] DR = {-1, 1, 0, 0}; // Up, Down, Left, Right
        private static final int[] DC = {0, 0, -1, 1};

        private final Grid grid;
        private final String commands;

        public Solver(Grid grid, String commands) {
            this.grid = grid;
            this.commands = commands;
        }

        /**
         * Iterates through all permutations of digit-to-direction mappings.
         * @return The number of successful permutations.
         */
        public int solve() {
            int successCount = 0;
            // mapping[digit] = directionIndex
            int[] mapping = {0, 1, 2, 3};

            do {
                if (simulate(mapping)) {
                    successCount++;
                }
            } while (nextPermutation(mapping));

            return successCount;
        }

        /**
         * Simulates the movement based on the current direction mapping.
         * @param mapping The current mapping of digit to direction index.
         * @return true if the 'E' cell is reached, false otherwise.
         */
        private boolean simulate(int[] mapping) {
            Position current = grid.getStartPosition();

            for (int i = 0; i < commands.length(); i++) {
                int digit = commands.charAt(i) - '0';
                int dirIdx = mapping[digit];

                int nextR = current.row() + DR[dirIdx];
                int nextC = current.col() + DC[dirIdx];

                if (!grid.isWithinBounds(nextR, nextC)) {
                    return false;
                }

                char cell = grid.getCell(nextR, nextC);
                if (cell == '#') {
                    return false;
                }
                if (cell == 'E') {
                    return true;
                }

                current = new Position(nextR, nextC);
            }

            return false;
        }

        /**
         * Standard lexicographical permutation algorithm.
         */
        private boolean nextPermutation(int[] array) {
            int i = array.length - 2;
            while (i >= 0 && array[i] >= array[i + 1]) {
                i--;
            }

            if (i < 0) return false;

            int j = array.length - 1;
            while (array[j] <= array[i]) {
                j--;
            }

            swap(array, i, j);
            reverse(array, i + 1, array.length - 1);
            return true;
        }

        private void swap(int[] array, int i, int j) {
            int temp = array[i];
            array[i] = array[j];
            array[j] = temp;
        }

        private void reverse(int[] array, int start, int end) {
            while (start < end) {
                swap(array, start++, end--);
            }
        }
    }

    /**
     * Fast I/O reader for efficient input processing.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream is) {
            reader = new BufferedReader(new InputStreamReader(is));
        }

        public String readLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException("Error reading line", e);
            }
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int[] readIntArray() {
            String line = readLine();
            if (line == null || line.isEmpty()) return new int[0];
            String[] parts = line.trim().split("\\s+");
            int[] res = new int[parts.length];
            for (int i = 0; i < parts.length; i++) {
                res[i] = Integer.parseInt(parts[i]);
            }
            return res;
        }
    }
}

