/**
 * Represents the maze environment including the grid and start/end points.
 */
class Maze {
    private final char[][] grid;
    private final int rows;
    private final int cols;
    private final int startRow;
    private final int startCol;
    private final int endRow;
    private final int endCol;

    public Maze(int rows, int cols, char[][] grid, int startRow, int startCol, int endRow, int endCol) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.startRow = startRow;
        this.startCol = startCol;
        this.endRow = endRow;
        this.endCol = endCol;
    }

    public int getRows() { return rows; }
    public int getCols() { return cols; }
    public int getStartRow() { return startRow; }
    public int getStartCol() { return startCol; }
    public int getEndRow() { return endRow; }
    public int getEndCol() { return endCol; }

    public boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public boolean isWall(int r, int c) {
        return grid[r][c] == '#';
    }
}

/**
 * Logic to solve the maze by testing permutations of movement directions.
 */
class MazeSolver {
    // Directions: Up, Right, Down, Left
    private static final int[][] DIRECTIONS = {
        {-1, 0}, {0, 1}, {1, 0}, {0, -1}
    };

    /**
     * Calculates how many permutations of directions allow the sequence of commands
     * to reach the end point without hitting walls or boundaries.
     */
    public int solve(Maze maze, String commandSequence) {
        int count = 0;
        int[] permutation = {0, 1, 2, 3};
        PermutationUtility permutationUtil = new PermutationUtility();

        do {
            if (isValidPath(maze, commandSequence, permutation)) {
                count++;
            }
        } while (permutationUtil.nextPermutation(permutation));

        return count;
    }

    private boolean isValidPath(Maze maze, String commandSequence, int[] permutation) {
        int currentRow = maze.getStartRow();
        int currentCol = maze.getStartCol();

        for (int i = 0; i < commandSequence.length(); i++) {
            // Determine which direction index to use based on the permutation
            int commandIdx = commandSequence.charAt(i) - '0';
            int directionIdx = permutation[commandIdx];

            currentRow += DIRECTIONS[directionIdx][0];
            currentCol += DIRECTIONS[directionIdx][1];

            if (!maze.isWithinBounds(currentRow, currentCol) || maze.isWall(currentRow, currentCol)) {
                return false;
            }

            if (currentRow == maze.getEndRow() && currentCol == maze.getEndCol()) {
                return true;
            }
        }

        // Check if we ended exactly at the destination
        return currentRow == maze.getEndRow() && currentCol == maze.getEndCol();
    }
}

/**
 * Utility to generate the next lexicographical permutation of an array.
 */
class PermutationUtility {
    public boolean nextPermutation(int[] array) {
        if (array.length <= 1) return false;

        int i = array.length - 2;
        while (i >= 0 && array[i] >= array[i + 1]) {
            i--;
        }

        if (i < 0) return false;

        int j = array.length - 1;
        while (array[j] <= array[i]) {
            j--;
        }

        swap(array, i, j);
        reverse(array, i + 1, array.length - 1);
        return true;
    }

    private void swap(int[] array, int i, int j) {
        int temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }

    private void reverse(int[] array, int start, int end) {
        while (start < end) {
            swap(array, start++, end--);
        }
    }
}

