/**
 * PathSolver solves a puzzle where a sequence of digits is mapped to directions (Up, Down, Left, Right).
 * It finds the number of unique direction-to-digit mappings that allow a path to reach 
 * an exit ('E') without hitting walls ('#') or boundaries.
 */
public class PathSolver {

    // Directional offsets: 0: Up, 1: Down, 2: Left, 3: Right
    private static final int[] ROW_OFFSETS = {-1, 1, 0, 0};
    private static final int[] COL_OFFSETS = {0, 0, -1, 1};

    private final Grid grid;
    private final char[] instructionSequence;
    private int validMappingsCount;

    /**
     * Represents the game world, including dimensions and cell types.
     */
    private static class Grid {
        private final char[][] cells;
        private final int rows;
        private final int cols;
        private int startRow;
        private int startCol;

        public Grid(int rows, int cols, String[] lines) {
            this.rows = rows;
            this.cols = cols;
            this.cells = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = lines[i];
                for (int j = 0; j < cols; j++) {
                    cells[i][j] = line.charAt(j);
                    if (cells[i][j] == 'S') {
                        this.startRow = i;
                        this.startCol = j;
                    }
                }
            }
        }

        public boolean isOutOfBounds(int r, int c) {
            return r < 0 || r >= rows || c < 0 || c >= cols;
        }

        public boolean isWall(int r, int c) {
            return cells[r][c] == '#';
        }

        public boolean isExit(int r, int c) {
            return cells[r][c] == 'E';
        }

        public int getStartRow() { return startRow; }
        public int getStartCol() { return startCol; }
    }

    public PathSolver(Grid grid, String instructions) {
        this.grid = grid;
        this.instructionSequence = instructions.toCharArray();
    }

    /**
     * Orchestrates the permutation generation and returns the count of successful paths.
     */
    public int solve() {
        validMappingsCount = 0;
        int[] directionMapping = new int[4]; // mapping[digit] = directionIndex
        boolean[] usedDirections = new boolean[4];

        generatePermutations(directionMapping, usedDirections, 0);

        return validMappingsCount;
    }

    /**
     * Uses backtracking to generate all 24 permutations of assigning directions to digits 0-3.
     */
    private void generatePermutations(int[] mapping, boolean[] usedDirections, int digitIndex) {
        if (digitIndex == 4) {
            if (simulatePath(mapping)) {
                validMappingsCount++;
            }
            return;
        }

        for (int dirIdx = 0; dirIdx < 4; dirIdx++) {
            if (!usedDirections[dirIdx]) {
                usedDirections[dirIdx] = true;
                mapping[digitIndex] = dirIdx;
                generatePermutations(mapping, usedDirections, digitIndex + 1);
                usedDirections[dirIdx] = false;
            }
        }
    }

    /**
     * Simulates the path following the provided mapping of digits to directions.
     */
    private boolean simulatePath(int[] mapping) {
        int currentRow = grid.getStartRow();
        int currentCol = grid.getStartCol();

        for (char instruction : instructionSequence) {
            int digit = instruction - '0';

            // Validate digit is within the expected range [0-3]
            if (digit < 0 || digit > 3) continue;

            int dirIdx = mapping[digit];
            currentRow += ROW_OFFSETS[dirIdx];
            currentCol += COL_OFFSETS[dirIdx];

            if (grid.isOutOfBounds(currentRow, currentCol) || grid.isWall(currentRow, currentCol)) {
                return false;
            }

            if (grid.isExit(currentRow, currentCol)) {
                return true;
            }
        }

        return false;
    }

    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String firstLine = reader.readLine();
            if (firstLine == null) return;

            StringTokenizer st = new StringTokenizer(firstLine);
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            String[] gridLines = new String[rows];
            for (int i = 0; i < rows; i++) {
                gridLines[i] = reader.readLine();
            }

            String instructionString = reader.readLine();
            if (instructionString == null) instructionString = "";

            Grid grid = new Grid(rows, cols, gridLines);
            PathSolver solver = new PathSolver(grid, instructionString);

            System.out.println(solver.solve());

        } catch (IOException | NumberFormatException e) {
            // In a production environment, use a logging framework.
            System.err.println("Error processing input: " + e.getMessage());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * BuggyBot simulates a robot moving on a grid based on a sequence of commands.
 * It calculates how many permutations of available directions allow the robot 
 * to reach an exit without hitting walls or boundaries.
 */
public class BuggyBot {

    private static final int[][] DIRECTIONS = {
        {-1, 0}, // Up
        {0, 1},  // Right
        {1, 0},  // Down
        {0, -1}  // Left
    };

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            GridMap gridMap = new GridMap(reader.next(), rows, cols);
            String commands = reader.next();

            BotSimulator simulator = new BotSimulator(gridMap, commands);
            int successfulPermutations = simulator.countSuccessfulPermutations();

            System.out.println(successfulPermutations);
        } catch (Exception e) {
            // In a real-world scenario, use a logger.
            e.printStackTrace();
        }
    }

    /**
     * Represents a coordinate on the grid.
     */
    private record Point(int x, int y) {}

    /**
     * Represents the game board, containing the map layout and key locations.
     */
    private static class GridMap {
        private final char[][] layout;
        private final int rows;
        private final int cols;
        private final Point start;
        private final Point exit;

        public GridMap(String mapData, int rows, int cols) {
            this.rows = rows;
            this.cols = cols;
            this.layout = new char[rows][cols];

            Point tempStart = null;
            Point tempExit = null;

            for (int i = 0; i < rows; i++) {
                char[] rowChars = mapData.substring(i * cols, (i + 1) * cols).toCharArray();
                for (int j = 0; j < cols; j++) {
                    layout[i][j] = rowChars[j];
                    if (layout[i][j] == 'S') {
                        tempStart = new Point(i, j);
                    } else if (layout[i][j] == 'E') {
                        tempExit = new Point(i, j);
                    }
                }
            }
            this.start = tempStart;
            this.exit = tempExit;
        }

        public boolean isOutOfBounds(int x, int y) {
            return x < 0 || x >= rows || y < 0 || y >= cols;
        }

        public boolean isWall(int x, int y) {
            return layout[x][y] == '#';
        }

        public boolean isExit(int x, int y) {
            return x == exit.x && y == exit.y;
        }

        public Point getStart() { return start; }
    }

    /**
     * Handles the simulation logic.
     */
    private static class BotSimulator {
        private final GridMap gridMap;
        private final String commands;

        public BotSimulator(GridMap gridMap, String commands) {
            this.gridMap = gridMap;
            this.commands = commands;
        }

        public int countSuccessfulPermutations() {
            int count = 0;
            List<int[]> permutations = PermutationGenerator.generate(new int[]{0, 1, 2, 3});

            for (int[] p : permutations) {
                if (simulate(p)) {
                    count++;
                }
            }
            return count;
        }

        private boolean simulate(int[] directionMapping) {
            int currentX = gridMap.getStart().x;
            int currentY = gridMap.getStart().y;

            for (char cmdChar : commands.toCharArray()) {
                int commandIdx = cmdChar - '0';
                int directionIdx = directionMapping[commandIdx];

                int nextX = currentX + DIRECTIONS[directionIdx][0];
                int nextY = currentY + DIRECTIONS[directionIdx][1];

                if (gridMap.isOutOfBounds(nextX, nextY) || gridMap.isWall(nextX, nextY)) {
                    return false;
                }

                currentX = nextX;
                currentY = nextY;

                if (gridMap.isExit(currentX, currentY)) {
                    return true;
                }
            }
            return false;
        }
    }

    /**
     * Utility to generate all permutations of an integer array using Heap's Algorithm.
     */
    private static class PermutationGenerator {
        public static List<int[]> generate(int[] array) {
            List<int[]> result = new ArrayList<>();
            heapPermute(array, array.length, result);
            return result;
        }

        private static void heapPermute(int[] a, int size, List<int[]> result) {
            if (size == 1) {
                result.add(a.clone());
                return;
            }

            for (int i = 0; i < size; i++) {
                heapPermute(a, size - 1, result);

                if (size % 2 == 1) {
                    swap(a, 0, size - 1);
                } else {
                    swap(a, i, size - 1);
                }
            }
        }

        private static void swap(int[] a, int i, int j) {
            int temp = a[i];
            a[i] = a[j];
            a[j] = temp;
        }
    }

    /**
     * Fast I/O implementation for reading large inputs efficiently.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * PathSimulationApp simulates various instruction mappings to find how many 
 * permutations of direction mappings allow a path from 'S' to 'E'.
 */
public class PathSimulationApp {

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            Grid grid = new Grid(rows, cols, reader);
            String instructions = reader.next();

            PathSimulator simulator = new PathSimulator(grid, instructions);
            int validPathCount = simulator.countValidPermutations();

            System.out.println(validPathCount);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Represents a coordinate on the grid.
     */
    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Represents possible movements on the grid.
     */
    private enum Direction {
        DOWN(1, 0),
        UP(-1, 0),
        LEFT(0, -1),
        RIGHT(0, 1);

        final int dr, dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }

    /**
     * Manages the grid layout, boundaries, and obstacles.
     */
    private static class Grid {
        private final int rows;
        private final int cols;
        private final char[][] cells;
        private Point start;
        private Point end;

        public Grid(int rows, int cols, FastReader reader) throws IOException {
            this.rows = rows;
            this.cols = cols;
            this.cells = new char[rows][cols];
            initializeGrid(reader);
        }

        private void initializeGrid(FastReader reader) throws IOException {
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    cells[i][j] = line.charAt(j);
                    if (cells[i][j] == 'S') {
                        start = new Point(i, j);
                    } else if (cells[i][j] == 'E') {
                        end = new Point(i, j);
                    }
                }
            }
        }

        public boolean isOutOfBounds(int r, int c) {
            return r < 0 || r >= rows || c < 0 || c >= cols;
        }

        public boolean isObstacle(int r, int c) {
            return cells[r][c] == '#';
        }

        public boolean isEnd(int r, int c) {
            return cells[r][c] == 'E';
        }

        public Point getStart() { return start; }
        public Point getEnd() { return end; }
    }

    /**
     * Handles the simulation logic for path testing.
     */
    private static class PathSimulator {
        private final Grid grid;
        private final String instructions;
        private final Direction[] directions = Direction.values();

        public PathSimulator(Grid grid, String instructions) {
            this.grid = grid;
            this.instructions = instructions;
        }

        /**
         * Iterates through all permutations of direction mappings and counts valid ones.
         */
        public int countValidPermutations() {
            int validCount = 0;
            List<int[]> permutations = new ArrayList<>();
            generatePermutations(new int[]{0, 1, 2, 3}, 0, permutations);

            for (int[] p : permutations) {
                if (isValidPath(p)) {
                    validCount++;
                }
            }
            return validCount;
        }

        /**
         * Checks if a specific permutation of direction mappings results in reaching 'E'.
         */
        private boolean isValidPath(int[] mapping) {
            int currR = grid.getStart().r;
            int currC = grid.getStart().c;

            for (int i = 0; i < instructions.length(); i++) {
                // Check if current position is invalid
                if (grid.isOutOfBounds(currR, currC) || grid.isObstacle(currR, currC)) {
                    return false;
                }
                // Check if destination is reached mid-instruction
                if (grid.isEnd(currR, currC)) {
                    return true;
                }

                // Move based on instruction digit and mapping
                int digit = instructions.charAt(i) - '0';
                Direction dir = directions[mapping[digit]];
                currR += dir.dr;
                currC += dir.dc;
            }

            // Final check after all instructions are processed
            if (grid.isOutOfBounds(currR, currC) || grid.isObstacle(currR, currC)) {
                return false;
            }
            return grid.isEnd(currR, currC);
        }

        /**
         * Standard recursive algorithm to generate all permutations of an array.
         */
        private void generatePermutations(int[] arr, int k, List<int[]> result) {
            if (k == arr.length) {
                result.add(arr.clone());
                return;
            }
            for (int i = k; i < arr.length; i++) {
                swap(arr, k, i);
                generatePermutations(arr, k + 1, result);
                swap(arr, k, i);
            }
        }

        private void swap(int[] arr, int i, int j) {
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }
    }

    /**
     * Efficient utility for reading input.
     */
    private static class FastReader {
        private BufferedReader br;
        private StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A program to solve a maze traversal problem by finding the number of 
 * valid direction-to-command mappings that lead to an exit.
 */
public class MazePathSolver {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            // Read grid dimensions
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            if (rows <= 0 || cols <= 0) {
                writer.println(0);
            } else {
                // Read the maze grid
                char[][] grid = new char[rows][cols];
                for (int i = 0; i < rows; i++) {
                    grid[i] = reader.next().toCharArray();
                }

                // Read the command sequence (e.g., "0123")
                String commands = reader.next();

                // Solve the problem
                MazeSolver solver = new MazeSolver(rows, cols, grid, commands);
                writer.println(solver.solve());
            }
        } catch (Exception e) {
            // In a real-world application, use a logger here.
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Represents a movement in the 2D grid.
     */
    private static class Direction {
        final int dr;
        final int dc;

        Direction(int dr, int dc) {
            this.dr = dr;
            this.dc = dc;
        }
    }

    /**
     * Encapsulates the maze grid and provides spatial queries.
     */
    private static class Maze {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private int startRow = -1;
        private int startCol = -1;

        public Maze(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
            findAndInitializeStart();
        }

        private void findAndInitializeStart() {
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (grid[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                        // Treat the starting cell as a traversable path
                        grid[i][j] = '.';
                        return;
                    }
                }
            }
        }

        public boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public boolean isWall(int r, int c) {
            return grid[r][c] == '#';
        }

        public boolean isExit(int r, int c) {
            return grid[r][c] == 'E';
        }

        public int getStartRow() {
            return startRow;
        }

        public int getStartCol() {
            return startCol;
        }
    }

    /**
     * Handles the permutation generation and path simulation.
     */
    private static class MazeSolver {
        private static final int DIRECTION_COUNT = 4;
        private final Maze maze;
        private final String commands;

        // Predefined directions: 0: Up, 1: Left, 2: Right, 3: Down
        private final Direction[] directions = {
            new Direction(-1, 0),
            new Direction(0, -1),
            new Direction(0, 1),
            new Direction(1, 0)
        };

        public MazeSolver(int rows, int cols, char[][] grid, String commands) {
            this.maze = new Maze(rows, cols, grid);
            this.commands = commands;
        }

        /**
         * Entry point for the solver logic.
         * @return The number of valid direction mappings.
         */
        public int solve() {
            if (maze.getStartRow() == -1) {
                return 0;
            }
            return countValidPermutations(0, new boolean[DIRECTION_COUNT], new int[DIRECTION_COUNT]);
        }

        /**
         * Recursively generates all permutations of direction mappings.
         * 
         * @param depth The current index in the mapping array we are assigning.
         * @param used Boolean array to track used direction indices.
         * @param mapping The mapping of command digits to direction indices.
         * @return Total count of valid permutations.
         */
        private int countValidPermutations(int depth, boolean[] used, int[] mapping) {
            if (depth == DIRECTION_COUNT) {
                return simulatePath(mapping) ? 1 : 0;
            }

            int totalValid = 0;
            for (int i = 0; i < DIRECTION_COUNT; i++) {
                if (!used[i]) {
                    used[i] = true;
                    mapping[depth] = i;
                    totalValid += countValidPermutations(depth + 1, used, mapping);
                    used[i] = false;
                }
            }
            return totalValid;
        }

        /**
         * Simulates the movement through the maze based on the provided mapping.
         * 
         * @param mapping An array where mapping[digit] = direction_index.
         * @return true if the exit 'E' is reached successfully.
         */
        private boolean simulatePath(int[] mapping) {
            int currentR = maze.getStartRow();
            int currentC = maze.getStartCol();

            for (char cmdChar : commands.toCharArray()) {
                int commandDigit = cmdChar - '0';

                // Safety check for command digits
                if (commandDigit < 0 || commandDigit >= DIRECTION_COUNT) continue;

                int directionIndex = mapping[commandDigit];
                Direction dir = directions[directionIndex];

                currentR += dir.dr;
                currentC += dir.dc;

                // Check for collision or boundary breach
                if (!maze.isWithinBounds(currentR, currentC) || maze.isWall(currentR, currentC)) {
                    return false;
                }

                // Check for success
                if (maze.isExit(currentR, currentC)) {
                    return true;
                }
            }
            return false;
        }
    }

    /**
     * Fast I/O utility for reading large inputs.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String token = next();
            return (token != null) ? Integer.parseInt(token) : 0;
        }
    }
}

import java.util.*;

/**
 * A simulator that finds how many different mappings of direction characters (1-4)
 * to spatial movements (Up, Right, Down, Left) result in reaching an end point.
 */
public class DirectionPermutationProblem {

    /**
     * Represents the types of cells available in the grid.
     */
    enum CellType {
        EMPTY,
        WALL,
        START,
        END
    }

    /**
     * Represents spatial movements and their coordinate offsets.
     */
    enum Direction {
        UP(-1, 0),
        RIGHT(0, 1),
        DOWN(1, 0),
        LEFT(0, -1);

        private final int rowOffset;
        private final int colOffset;

        Direction(int rowOffset, int colOffset) {
            this.rowOffset = rowOffset;
            this.colOffset = colOffset;
        }

        public int getRowOffset() { return rowOffset; }
        public int getColOffset() { return colOffset; }
    }

    /**
     * Represents a coordinate in the grid.
     */
    record Position(int r, int c) {}

    /**
     * Encapsulates the grid structure and boundary/collision logic.
     */
    static class World {
        private final CellType[][] grid;
        private final int rows;
        private final int cols;
        private Position startPosition;

        public World(int rows, int cols, String[] gridLines) {
            this.rows = rows;
            this.cols = cols;
            this.grid = new CellType[rows][cols];
            parseGrid(gridLines);
        }

        private void parseGrid(String[] lines) {
            for (int i = 0; i < rows; i++) {
                String line = lines[i];
                for (int j = 0; j < cols; j++) {
                    char c = line.charAt(j);
                    switch (c) {
                        case '#' -> grid[i][j] = CellType.WALL;
                        case 'S' -> {
                            grid[i][j] = CellType.START;
                            startPosition = new Position(i, j);
                        }
                        case 'E' -> grid[i][j] = CellType.END;
                        default -> grid[i][j] = CellType.EMPTY;
                    }
                }
            }
        }

        public boolean isOutOfBounds(Position pos) {
            return pos.r() < 0 || pos.r() >= rows || pos.c() < 0 || pos.c() >= cols;
        }

        public boolean isWall(Position pos) {
            return isOutOfBounds(pos) || grid[pos.r()][pos.c()] == CellType.WALL;
        }

        public boolean isEnd(Position pos) {
            return !isOutOfBounds(pos) && grid[pos.r()][pos.c()] == CellType.END;
        }

        public Position getStart() {
            return startPosition;
        }
    }

    /**
     * Executes the simulation of the movement sequence.
     */
    static class SimulationEngine {
        /**
         * Simulates the path given a specific mapping of instructions to directions.
         * 
         * @param world The grid environment.
         * @param instructions The sequence of movement digits.
         * @param mapping An array where index 0-3 maps to directions for digits '1'-'4'.
         * @return true if the end point is reached.
         */
        public boolean simulate(World world, String instructions, Direction[] mapping) {
            Position current = world.getStart();

            for (int i = 0; i < instructions.length(); i++) {
                // If we hit a wall or go out of bounds before moving, the path is invalid
                if (world.isWall(current)) return false;

                // If we are already at the end, we succeed
                if (world.isEnd(current)) return true;

                // Map instruction char (e.g., '1') to mapping index (e.g., 0)
                int mappingIndex = Character.getNumericValue(instructions.charAt(i)) - 1;

                if (mappingIndex < 0 || mappingIndex >= mapping.length) return false;

                Direction move = mapping[mappingIndex];
                current = new Position(
                    current.r() + move.getRowOffset(),
                    current.c() + move.getColOffset()
                );
            }

            // Final check: did our last move land us on the end?
            return world.isEnd(current) && !world.isWall(current);
        }
    }

    /**
     * Handles generating all permutations and counting successes.
     */
    static class PermutationService {
        private final World world;
        private final String instructions;
        private final SimulationEngine engine;
        private int successCount = 0;

        public PermutationService(World world, String instructions) {
            this.world = world;
            this.instructions = instructions;
            this.engine = new SimulationEngine();
        }

        public int solve() {
            Direction[] directions = Direction.values();
            generatePermutations(directions, 0);
            return successCount;
        }

        private void generatePermutations(Direction[] arr, int index) {
            if (index == arr.length) {
                if (engine.simulate(world, instructions, arr)) {
                    successCount++;
                }
                return;
            }

            for (int i = index; i < arr.length; i++) {
                swap(arr, index, i);
                generatePermutations(arr, index + 1);
                swap(arr, index, i); // Backtrack
            }
        }

        private void swap(Direction[] arr, int i, int j) {
            Direction temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        String[] gridLines = new String[n];
        for (int i = 0; i < n; i++) {
            gridLines[i] = scanner.next();
        }

        String instructions = scanner.next();

        World world = new World(n, m, gridLines);
        PermutationService service = new PermutationService(world, instructions);

        System.out.println(service.solve());

        scanner.close();
    }
}

import java.util.Scanner;
import java.util.ArrayList;
import java.util.List;

/**
 * A program to solve a maze-following puzzle where digit-to-direction 
 * mappings are unknown and must be discovered by testing all permutations.
 */
public class App {

    // Directional offsets for row and column changes
    // Indices: 0 = Up, 1 = Down, 2 = Left, 3 = Right
    private static final int[] ROW_OFFSETS = {-1, 1, 0, 0};
    private static final int[] COL_OFFSETS = {0, 0, -1, 1};

    // Semantic constants for direction indices to improve readability
    private static final int DIR_UP = 0;
    private static final int DIR_DOWN = 1;
    private static final int DIR_LEFT = 2;
    private static final int DIR_RIGHT = 3;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            scanner.close();
            return;
        }

        // Parse grid dimensions
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // Consume the remaining newline

        char[][] grid = new char[rows][cols];
        int startRow = 0;
        int startCol = 0;

        // Load grid and locate the starting position 'S'
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            grid[i] = line.toCharArray();
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        // Load movement instructions (e.g., "0123")
        String instructionsStr = scanner.nextLine();
        char[] instructions = instructionsStr.toCharArray();

        int successfulMappings = solve(grid, instructions, startRow, startCol);
        System.out.println(successfulMappings);

        scanner.close();
    }

    /**
     * Calculates how many digit-to-direction mappings result in reaching the exit 'E'.
     * 
     * @param grid The maze grid.
     * @param instructions The sequence of direction digits.
     * @param startRow Starting row index.
     * @param startCol Starting column index.
     * @return The count of valid permutations.
     */
    private static int solve(char[][] grid, char[] instructions, int startRow, int startCol) {
        int successfulMappings = 0;
        int[] digits = {0, 1, 2, 3};
        List<int[]> permutations = new ArrayList<>();

        // Generate all 24 permutations of the digits {0, 1, 2, 3}
        generatePermutations(digits, 0, permutations);

        for (int[] p : permutations) {
            // In the original logic:
            // p[0] is the digit for Right, p[1] for Left, p[2] for Up, p[3] for Down
            if (canReachEnd(grid, instructions, p, startRow, startCol)) {
                successfulMappings++;
            }
        }

        return successfulMappings;
    }

    /**
     * Simulates the path based on a specific digit-to-direction mapping.
     * 
     * @param grid The maze grid.
     * @param instructions The sequence of direction digits.
     * @param mapping An array where mapping[0] is the digit for Right, etc.
     * @param startRow Starting row index.
     * @param startCol Starting column index.
     * @return True if the exit 'E' is reached, false otherwise.
     */
    private static boolean canReachEnd(char[][] grid, char[] instructions, int[] mapping, int startRow, int startCol) {
        int currentRow = startRow;
        int currentCol = startCol;

        // Create a fast lookup table: digit -> direction index
        int[] digitToDirIdx = new int[4];
        digitToDirIdx[mapping[0]] = DIR_RIGHT;
        digitToDirIdx[mapping[1]] = DIR_LEFT;
        digitToDirIdx[mapping[2]] = DIR_UP;
        digitToDirIdx[mapping[3]] = DIR_DOWN;

        for (char instructionChar : instructions) {
            int digit = instructionChar - '0';
            int dirIdx = digitToDirIdx[digit];

            currentRow += ROW_OFFSETS[dirIdx];
            currentCol += COL_OFFSETS[dirIdx];

            // Check boundary conditions
            if (isOutOfBounds(grid, currentRow, currentCol)) {
                return false;
            }

            char cell = grid[currentRow][currentCol];
            if (cell == '#') {
                return false; // Obstacle hit
            }
            if (cell == 'E') {
                return true; // Exit reached
            }
        }

        return false;
    }

    private static boolean isOutOfBounds(char[][] grid, int r, int c) {
        return r < 0 || r >= grid.length || c < 0 || c >= grid[0].length;
    }

    /**
     * Generates all possible permutations of the provided array using recursion.
     */
    private static void generatePermutations(int[] arr, int index, List<int[]> result) {
        if (index == arr.length) {
            result.add(arr.clone());
            return;
        }
        for (int i = index; i < arr.length; i++) {
            swap(arr, index, i);
            generatePermutations(arr, index + 1, result);
            swap(arr, index, i); // Backtrack
        }
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

import java.io.*;
import java.util.*;

/**
 * Pathfinder solves a grid navigation problem where we need to determine 
 * how many ways we can map 4 directions to 4 digits such that a command 
 * sequence leads the traveler to an exit 'E' without hitting obstacles.
 */
public class Pathfinder {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        Solver solver = new Solver(reader);
        solver.solve(writer);

        writer.flush();
        writer.close();
    }

    /**
     * Represents a 2D coordinate in the grid.
     */
    static class Point {
        int x, y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    static class Solver {
        private final FastReader reader;
        private static final int[] DX = {-1, 0, 1, 0}; // Up, Left, Down, Right
        private static final int[] DY = {0, -1, 0, 1};
        private int successCount = 0;

        Solver(FastReader reader) {
            this.reader = reader;
        }

        public void solve(PrintWriter out) {
            int n = reader.nextInt();
            int m = reader.nextInt();

            // Initialize grid with padding to handle boundary checks automatically
            char[][] grid = new char[n + 2][m + 2];
            for (int i = 0; i < n + 2; i++) {
                Arrays.fill(grid[i], '*');
            }

            Point start = new Point(0, 0);
            Point end = new Point(0, 0);

            for (int i = 1; i <= n; i++) {
                String row = reader.next();
                for (int j = 1; j <= m; j++) {
                    char cell = row.charAt(j - 1);
                    grid[i][j] = cell;
                    if (cell == 'S') {
                        start.x = i;
                        start.y = j;
                    } else if (cell == 'E') {
                        end.x = i;
                        end.y = j;
                    }
                }
            }

            String commandStr = reader.next();
            char[] command = commandStr.toCharArray();

            // Generate all permutations of the 4 directions {0, 1, 2, 3}
            // representing which direction corresponds to which digit.
            int[] directionMapping = new int[4];
            boolean[] used = new boolean[4];
            generateAndSimulate(0, directionMapping, used, command, grid, start.x, start.y);

            out.println(successCount);
        }

        /**
         * Backtracking function to generate permutations of directions.
         */
        private void generateAndSimulate(int index, int[] mapping, boolean[] used, 
                                         char[] command, char[][] grid, int startX, int startY) {
            if (index == 4) {
                simulate(mapping, command, grid, startX, startY);
                return;
            }

            for (int i = 0; i < 4; i++) {
                if (!used[i]) {
                    used[i] = true;
                    mapping[index] = i;
                    generateAndSimulate(index + 1, mapping, used, command, grid, startX, startY);
                    used[i] = false;
                }
            }
        }

        /**
         * Simulates the path based on the current direction mapping.
         */
        private void simulate(int[] mapping, char[] command, char[][] grid, int startX, int startY) {
            int curX = startX;
            int curY = startY;

            for (char c : command) {
                int digit = c - '0';
                int dirIdx = mapping[digit];

                curX += DX[dirIdx];
                curY += DY[dirIdx];

                char cell = grid[curX][curY];
                // If we hit a wall or the exit, the journey ends.
                if (cell == '*' || cell == '#' || cell == 'E') {
                    if (cell == 'E') {
                        successCount++;
                    }
                    return;
                }
            }

            // If the command completes and we are standing on the exit
            if (grid[curX][curY] == 'E') {
                successCount++;
            }
        }
    }

    /**
     * Fast I/O utility for efficient reading of large inputs.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * PathSimulator simulates all possible mappings of move commands to physical directions
 * to determine how many different direction mappings allow a path to reach the exit.
 */
public class PathSimulator {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            Grid grid = new Grid(rows, cols, reader);
            String moveSequence = reader.next();

            int successfulPathCount = countSuccessfulMappings(grid, moveSequence);
            out.println(successfulPathCount);

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        } finally {
            out.close();
        }
    }

    /**
     * Iterates through all possible permutations of directions and counts how many 
     * result in reaching the exit.
     */
    private static int countSuccessfulMappings(Grid grid, String moveSequence) {
        int count = 0;
        List<int[]> permutations = generatePermutations();

        for (int[] permutation : permutations) {
            if (simulate(grid, moveSequence, permutation)) {
                count++;
            }
        }
        return count;
    }

    /**
     * Simulates a single path based on a specific direction mapping.
     * 
     * @param grid The map layout.
     * @param moves The string of move commands (e.g., "0123").
     * @param mapping An array where mapping[moveDigit] = directionIndex.
     * @return true if the path reaches the exit.
     */
    private static boolean simulate(Grid grid, String moves, int[] mapping) {
        Position currentPos = grid.getStartPos();

        for (char moveChar : moves.toCharArray()) {
            int moveDigit = moveChar - '0';
            int directionIdx = mapping[moveDigit];

            int nextY = currentPos.y() + Direction.DY[directionIdx];
            int nextX = currentPos.x() + Direction.DX[directionIdx];

            if (grid.isWithinBounds(nextX, nextY)) {
                currentPos = new Position(nextX, nextY);
                CellType cellAtNewPos = grid.getCellAt(nextX, nextY);

                if (cellAtNewPos == CellType.EXIT) {
                    return true;
                }
                if (cellAtNewPos == CellType.WALL) {
                    return false;
                }
            } else {
                // Out of bounds
                return false;
            }
        }
        return false;
    }

    /**
     * Generates all 24 permutations of the indices {0, 1, 2, 3}.
     */
    private static List<int[]> generatePermutations() {
        List<int[]> results = new ArrayList<>();
        backtrack(new int[4], new boolean[4], 0, results);
        return results;
    }

    private static void backtrack(int[] current, boolean[] used, int depth, List<int[]> results) {
        if (depth == 4) {
            results.add(current.clone());
            return;
        }
        for (int i = 0; i < 4; i++) {
            if (!used[i]) {
                used[i] = true;
                current[depth] = i;
                backtrack(current, used, depth + 1, results);
                used[i] = false;
            }
        }
    }

    // --- Helper Classes ---

    enum CellType {
        EMPTY, WALL, START, EXIT
    }

    record Position(int x, int y) {}

    /**
     * Represents the movement vectors for the four possible directions.
     */
    static class Direction {
        // 0: Left, 1: Up, 2: Right, 3: Down
        static final int[] DY = {0, -1, 0, 1};
        static final int[] DX = {-1, 0, 1, 0};
    }

    /**
     * Handles grid storage and parsing.
     */
    static class Grid {
        private final int rows;
        private final int cols;
        private final CellType[][] cells;
        private Position startPos;

        public Grid(int rows, int cols, FastReader reader) throws IOException {
            this.rows = rows;
            this.cols = cols;
            this.cells = new CellType[rows][cols];
            parseGrid(reader);
        }

        private void parseGrid(FastReader reader) throws IOException {
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    char c = line.charAt(j);
                    if (c == '#') {
                        cells[i][j] = CellType.WALL;
                    } else if (c == 'S') {
                        cells[i][j] = CellType.START;
                        startPos = new Position(j, i);
                    } else if (c == 'E') {
                        cells[i][j] = CellType.EXIT;
                    } else {
                        cells[i][j] = CellType.EMPTY;
                    }
                }
            }
        }

        public boolean isWithinBounds(int x, int y) {
            return x >= 0 && x < cols && y >= 0 && y < rows;
        }

        public CellType getCellAt(int x, int y) {
            return cells[y][x];
        }

        public Position getStartPos() {
            return startPos;
        }
    }

    /**
     * Efficient reader for large inputs.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream is) {
            reader = new BufferedReader(new InputStreamReader(is));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * A program to simulate grid-based navigation.
 * It counts how many unique mappings of digits (0-3) to directions (Left, Right, Up, Down)
 * result in a path that reaches the exit 'E'.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        try {
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String rowString = scanner.next();
                grid[i] = rowString.toCharArray();
            }

            String instructions = scanner.next();

            GridNavigator navigator = new GridNavigator(grid, instructions);
            System.out.println(navigator.countWinningPermutations());

        } catch (Exception e) {
            System.err.println("Error processing input: " + e.getMessage());
        } finally {
            scanner.close();
        }
    }
}

class GridNavigator {
    private final char[][] grid;
    private final String instructions;
    private final int rows;
    private final int cols;
    private int startRow = -1;
    private int startCol = -1;

    /**
     * Initializes the navigator with the grid and instruction sequence.
     * Locates the starting position 'S' automatically.
     */
    public GridNavigator(char[][] grid, String instructions) {
        this.grid = grid;
        this.instructions = instructions;
        this.rows = grid.length;
        this.cols = grid[0].length;
        findStartingPosition();
    }

    private void findStartingPosition() {
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'S') {
                    this.startRow = i;
                    this.startCol = j;
                    return;
                }
            }
        }
    }

    /**
     * Counts how many permutations of digits 0-3 assigned to [Left, Right, Up, Down]
     * lead to the exit 'E'.
     */
    public int countWinningPermutations() {
        int winningCount = 0;
        List<int[]> permutations = new ArrayList<>();
        int[] digits = {0, 1, 2, 3};

        generatePermutations(digits, 0, permutations);

        for (int[] p : permutations) {
            // p[0] = Left digit, p[1] = Right digit, p[2] = Up digit, p[3] = Down digit
            if (simulatePath(p[0], p[1], p[2], p[3])) {
                winningCount++;
            }
        }
        return winningCount;
    }

    /**
     * Simulates the movement through the grid based on the provided digit mapping.
     */
    private boolean simulatePath(int leftDigit, int rightDigit, int upDigit, int downDigit) {
        int currentRow = startRow;
        int currentCol = startCol;
        int instrIdx = 0;

        while (instrIdx < instructions.length() && isWithinBounds(currentRow, currentCol)) {
            char currentCell = grid[currentRow][currentCol];

            if (currentCell == 'E') {
                return true;
            }
            if (currentCell == '#') {
                return false;
            }

            int moveCommand = instructions.charAt(instrIdx) - '0';

            if (moveCommand == leftDigit) {
                currentCol--;
            } else if (moveCommand == rightDigit) {
                currentCol++;
            } else if (moveCommand == upDigit) {
                currentRow--;
            } else if (moveCommand == downDigit) {
                currentRow++;
            }

            instrIdx++;
        }

        // Final check to see if the last move landed on the exit
        return isWithinBounds(currentRow, currentCol) && grid[currentRow][currentCol] == 'E';
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Standard backtracking algorithm to generate all permutations of a given array.
     */
    private void generatePermutations(int[] arr, int index, List<int[]> result) {
        if (index == arr.length) {
            result.add(arr.clone());
            return;
        }
        for (int i = index; i < arr.length; i++) {
            swap(arr, index, i);
            generatePermutations(arr, index + 1, result);
            swap(arr, index, i); // Backtrack
        }
    }

    private void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

import java.io.*;
import java.util.*;

/**
 * A solution for finding the number of direction-to-digit mappings 
 * that allow a path from a starting point 'S' to an exit 'E' on a grid.
 */
public class GridPathSolver {

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);
            PrintWriter out = new PrintWriter(System.out);

            PathfindingEngine engine = new PathfindingEngine(reader);
            engine.solve(out);

            out.flush();
            out.close();
        } catch (IOException e) {
            System.err.println("An error occurred while processing input: " + e.getMessage());
        }
    }

    /**
     * Represents the movement capabilities in the grid.
     */
    enum Direction {
        UP(-1, 0),
        DOWN(1, 0),
        LEFT(0, -1),
        RIGHT(0, 1);

        final int rowOffset;
        final int colOffset;

        Direction(int rowOffset, int colOffset) {
            this.rowOffset = rowOffset;
            this.colOffset = colOffset;
        }
    }

    /**
     * Represents the game board and its properties.
     */
    private static class Grid {
        private final int rows;
        private final int cols;
        private final char[][] matrix;
        private int startRow;
        private int startCol;

        public Grid(int rows, int cols, FastReader reader) throws IOException {
            this.rows = rows;
            this.cols = cols;
            this.matrix = new char[rows][cols];
            parseGrid(reader);
        }

        private void parseGrid(FastReader reader) throws IOException {
            for (int i = 0; i < rows; i++) {
                String line = reader.nextWord();
                for (int j = 0; j < cols; j++) {
                    matrix[i][j] = line.charAt(j);
                    if (matrix[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                    }
                }
            }
        }

        public boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        public boolean isObstacle(int r, int c) {
            return matrix[r][c] == '#';
        }

        public boolean isExit(int r, int c) {
            return matrix[r][c] == 'E';
        }

        public int getRows() { return rows; }
        public int getCols() { return cols; }
        public int getStartRow() { return startRow; }
        public int getStartCol() { return startCol; }
    }

    /**
     * Handles the core logic of generating mappings and simulating paths.
     */
    private static class PathfindingEngine {
        private final FastReader reader;

        public PathfindingEngine(FastReader reader) {
            this.reader = reader;
        }

        public void solve(PrintWriter out) throws IOException {
            int n = reader.nextInt();
            int m = reader.nextInt();

            Grid grid = new Grid(n, m, reader);
            String sequenceStr = reader.nextWord();
            int[] moveSequence = convertToSequence(sequenceStr);

            List<Direction[]> permutations = new ArrayList<>();
            generatePermutations(new Direction[4], new boolean[4], 0, permutations);

            int successfulMappings = 0;
            for (Direction[] mapping : permutations) {
                if (canReachExit(grid, moveSequence, mapping)) {
                    successfulMappings++;
                }
            }

            out.println(successfulMappings);
        }

        private int[] convertToSequence(String s) {
            int[] seq = new int[s.length()];
            for (int i = 0; i < s.length(); i++) {
                seq[i] = s.charAt(i) - '0';
            }
            return seq;
        }

        /**
         * Generates all 4! permutations of the Direction enum.
         */
        private void generatePermutations(Direction[] current, boolean[] used, int depth, List<Direction[]> results) {
            if (depth == 4) {
                results.add(current.clone());
                return;
            }

            Direction[] allDirs = Direction.values();
            for (int i = 0; i < allDirs.length; i++) {
                if (!used[i]) {
                    used[i] = true;
                    current[depth] = allDirs[i];
                    generatePermutations(current, used, depth + 1, results);
                    used[i] = false;
                }
            }
        }

        /**
         * Simulates the movement on the grid iteratively to avoid StackOverflow.
         */
        private boolean canReachExit(Grid grid, int[] moveSequence, Direction[] mapping) {
            int currR = grid.getStartRow();
            int currC = grid.getStartCol();

            // We iterate up to moveSequence.length to check the state at every step,
            // including the state after the final move.
            for (int step = 0; step <= moveSequence.length; step++) {
                // 1. Boundary and Obstacle Check
                if (!grid.isWithinBounds(currR, currC) || grid.isObstacle(currR, currC)) {
                    return false;
                }

                // 2. Goal Check
                if (grid.isExit(currR, currC)) {
                    return true;
                }

                // 3. If we haven't reached the exit and have no moves left, we fail
                if (step == moveSequence.length) {
                    return false;
                }

                // 4. Perform Move
                int dirIdx = moveSequence[step];
                Direction move = mapping[dirIdx];
                currR += move.rowOffset;
                currC += move.colOffset;
            }

            return false;
        }
    }

    /**
     * Efficient utility for parsing input.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            this.reader = new BufferedReader(new InputStreamReader(input));
        }

        public String nextWord() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(nextWord());
        }
    }
}

import java.util.*;

/**
 * BuggyBot solves a pathfinding puzzle where we must determine how many
 * permutations of direction mappings allow a robot to reach an exit ('E')
 * within a given sequence of moves without hitting obstacles ('#').
 */
public class BuggyBot {

    // Constants representing the grid characters
    private static final char START_CHAR = 'S';
    private static final char END_CHAR = 'E';
    private static final char BLOCK_CHAR = '#';

    /**
     * Represents possible movements in the grid.
     */
    enum Direction {
        DOWN(1, 0),
        RIGHT(0, 1),
        UP(-1, 0),
        LEFT(0, -1);

        final int deltaRow;
        final int deltaCol;

        Direction(int deltaRow, int deltaCol) {
            this.deltaRow = deltaRow;
            this.deltaCol = deltaCol;
        }
    }

    /**
     * Represents a coordinate on the grid.
     */
    static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Manages the game world, including the grid layout and special positions.
     */
    static class GameMap {
        private final char[][] grid;
        private final Point startPosition;
        private final Point endPosition;

        public GameMap(int n, int m, Scanner scanner) {
            // Create a grid with a 1-cell border of blocks to prevent out-of-bounds
            this.grid = new char[n + 2][m + 2];
            for (int i = 0; i < grid.length; i++) {
                Arrays.fill(grid[i], BLOCK_CHAR);
            }

            Point tempStart = null;
            Point tempEnd = null;

            // Fill the inner grid with input data
            for (int i = 1; i <= n; i++) {
                String line = scanner.next();
                for (int j = 1; j <= m; j++) {
                    char cell = line.charAt(j - 1);
                    grid[i][j] = cell;
                    if (cell == START_CHAR) {
                        tempStart = new Point(i, j);
                    } else if (cell == END_CHAR) {
                        tempEnd = new Point(i, j);
                    }
                }
            }
            this.startPosition = tempStart;
            this.endPosition = tempEnd;
        }

        public char getCell(int row, int col) {
            return grid[row][col];
        }

        public Point getStartPosition() {
            return startPosition;
        }

        public Point getEndPosition() {
            return endPosition;
        }
    }

    /**
     * Logic engine to simulate movements and evaluate mappings.
     */
    static class MovementSimulator {
        private final GameMap gameMap;
        private final Direction[] directions = Direction.values();

        public MovementSimulator(GameMap gameMap) {
            this.gameMap = gameMap;
        }

        /**
         * Simulates a specific mapping of digits to directions.
         * 
         * @param moves A string of digits representing the sequence of moves.
         * @param mapping A permutation string where index i defines the direction for digit i.
         * @return true if the robot reaches 'E' without hitting '#'
         */
        public boolean isSuccessful(String moves, String mapping) {
            int currentRow = gameMap.getStartPosition().row;
            int currentCol = gameMap.getStartPosition().col;

            for (char moveChar : moves.toCharArray()) {
                int moveDigit = Character.getNumericValue(moveChar);
                // The mapping defines which direction index (0-3) corresponds to the input digit
                int directionIndex = Character.getNumericValue(mapping.charAt(moveDigit));

                currentRow += directions[directionIndex].deltaRow;
                currentCol += directions[directionIndex].deltaCol;

                char currentCell = gameMap.getCell(currentRow, currentCol);

                if (currentCell == BLOCK_CHAR) {
                    return false;
                } else if (currentCell == END_CHAR) {
                    return true;
                }
            }
            return false;
        }

        /**
         * Orchestrates the permutation generation and counting.
         */
        public int solve(String moves) {
            List<String> allMappings = new ArrayList<>();
            generatePermutations("0123", "", allMappings);

            int validMappingCount = 0;
            for (String mapping : allMappings) {
                if (isSuccessful(moves, mapping)) {
                    validMappingCount++;
                }
            }
            return validMappingCount;
        }

        private void generatePermutations(String remaining, String current, List<String> result) {
            if (remaining.isEmpty()) {
                result.add(current);
                return;
            }
            for (int i = 0; i < remaining.length(); i++) {
                String nextRemaining = remaining.substring(0, i) + remaining.substring(i + 1);
                generatePermutations(nextRemaining, current + remaining.charAt(i), result);
            }
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int m = scanner.nextInt();

        GameMap gameMap = new GameMap(n, m, scanner);
        String moves = scanner.next();

        MovementSimulator simulator = new MovementSimulator(gameMap);
        int result = simulator.solve(moves);

        System.out.println(result);
        scanner.close();
    }
}

import java.util.*;
import java.io.*;

/**
 * Solution simulates different movement permutations to find how many
 * command sequences lead an agent from a starting point 'S' to an exit 'E'
 * without hitting walls '#' or going out of bounds.
 */
public class Solution {

    // Direction offsets corresponding to the mapping:
    // 0: Right (Col+1), 1: Up (Row-1), 2: Left (Col-1), 3: Down (Row+1)
    private static final int[] DR = {0, -1, 0, 1};
    private static final int[] DC = {1, 0, -1, 0};

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            new Solution().solve(reader, writer);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    private void solve(FastReader reader, PrintWriter writer) throws IOException {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        char[][] gridData = new char[rows][cols];
        int startRow = -1;
        int startCol = -1;

        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            for (int j = 0; j < cols; j++) {
                gridData[i][j] = line.charAt(j);
                if (gridData[i][j] == 'S') {
                    startRow = i;
                    startCol = j;
                }
            }
        }

        String commands = reader.next();
        Grid grid = new Grid(gridData);
        int successfulExits = countSuccessfulExits(grid, commands, startRow, startCol);

        writer.println(successfulExits);
    }

    /**
     * Iterates through all 24 permutations of direction mappings and counts successes.
     */
    private int countSuccessfulExits(Grid grid, String commands, int startRow, int startCol) {
        int[] mapping = {0, 1, 2, 3};
        int count = 0;

        do {
            if (simulatePath(grid, commands, mapping, startRow, startCol)) {
                count++;
            }
        } while (nextPermutation(mapping));

        return count;
    }

    /**
     * Simulates the movement based on the current permutation of direction mappings.
     */
    private boolean simulatePath(Grid grid, String commands, int[] mapping, int startRow, int startCol) {
        int currentRow = startRow;
        int currentCol = startCol;

        for (int i = 0; i < commands.length(); i++) {
            // Map the command character (e.g., '0') to a direction index using the current permutation
            int commandIdx = commands.charAt(i) - '0';
            int direction = mapping[commandIdx];

            int nextRow = currentRow + DR[direction];
            int nextCol = currentCol + DC[direction];

            if (grid.isOutOfBounds(nextRow, nextCol) || grid.isWall(nextRow, nextCol)) {
                return false;
            }

            if (grid.isExit(nextRow, nextCol)) {
                return true;
            }

            currentRow = nextRow;
            currentCol = nextCol;
        }

        return false;
    }

    /**
     * Standard algorithm to generate the next lexicographical permutation.
     */
    private boolean nextPermutation(int[] array) {
        int i = array.length - 2;
        while (i >= 0 && array[i] >= array[i + 1]) {
            i--;
        }

        if (i < 0) {
            return false;
        }

        int j = array.length - 1;
        while (array[j] <= array[i]) {
            j--;
        }

        swap(array, i, j);
        reverse(array, i + 1, array.length - 1);
        return true;
    }

    private void swap(int[] array, int i, int j) {
        int temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }

    private void reverse(int[] array, int start, int end) {
        while (start < end) {
            swap(array, start++, end--);
        }
    }

    /**
     * Encapsulates the grid properties and boundary logic.
     */
    static class Grid {
        private final char[][] cells;
        private final int rows;
        private final int cols;

        public Grid(char[][] cells) {
            this.cells = cells;
            this.rows = cells.length;
            this.cols = cells[0].length;
        }

        public boolean isOutOfBounds(int r, int c) {
            return r < 0 || r >= rows || c < 0 || c >= cols;
        }

        public boolean isWall(int r, int c) {
            return cells[r][c] == '#';
        }

        public boolean isExit(int r, int c) {
            return cells[r][c] == 'E';
        }
    }

    /**
     * Fast I/O utility for reading large inputs.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.StringTokenizer;

/**
 * A program to solve the navigation mapping problem.
 * The goal is to find how many ways we can map digits 0-3 to directions
 * (Up, Down, Left, Right) such that a sequence of commands leads to an exit 'E'.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            NavigationTask task = new NavigationTask();
            task.solve(reader, writer);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Represents directions and their movement offsets.
     */
    enum Direction {
        UP(-1, 0),
        DOWN(1, 0),
        LEFT(0, -1),
        RIGHT(0, 1);

        final int rowDelta;
        final int colDelta;

        Direction(int rowDelta, int colDelta) {
            this.rowDelta = rowDelta;
            this.colDelta = colDelta;
        }
    }

    /**
     * Handles the grid boundaries and cell properties.
     */
    static class Grid {
        private final char[][] cells;
        private final int height;
        private final int width;

        public Grid(int height, int width, String[] rows) {
            this.height = height;
            this.width = width;
            this.cells = new char[height][width];
            for (int i = 0; i < height; i++) {
                this.cells[i] = rows[i].toCharArray();
            }
        }

        public int getHeight() { return height; }
        public int getWidth() { return width; }

        public boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < height && c >= 0 && c < width;
        }

        public boolean isWall(int r, int c) {
            return cells[r][c] == '#';
        }

        public boolean isExit(int r, int c) {
            return cells[r][c] == 'E';
        }

        public boolean isStart(int r, int c) {
            return cells[r][c] == 'S';
        }
    }

    /**
     * Contains the core logic for solving the navigation puzzle.
     */
    static class NavigationTask {

        public void solve(FastReader in, PrintWriter out) {
            int height = in.nextInt();
            int width = in.nextInt();
            String[] fieldRows = new String[height];
            for (int i = 0; i < height; i++) {
                fieldRows[i] = in.next();
            }

            Grid grid = new Grid(height, width, fieldRows);
            int startRow = -1;
            int startCol = -1;

            // Locate the starting position 'S'
            outer:
            for (int r = 0; r < height; r++) {
                for (int c = 0; c < width; c++) {
                    if (grid.isStart(r, c)) {
                        startRow = r;
                        startCol = c;
                        break outer;
                    }
                }
            }

            String commands = in.next();
            Direction[] mapping = new Direction[4];
            boolean[] directionUsed = new boolean[Direction.values().length];

            int validMappingsCount = countValidPermutations(0, mapping, directionUsed, commands, grid, startRow, startCol);
            out.println(validMappingsCount);
        }

        /**
         * Uses backtracking to generate all possible permutations of mappings from digits to directions.
         */
        private int countValidPermutations(int digitIndex, Direction[] mapping, boolean[] directionUsed, 
                                           String commands, Grid grid, int startRow, int startCol) {
            if (digitIndex == 4) {
                return simulatePath(mapping, commands, grid, startRow, startCol) ? 1 : 0;
            }

            int count = 0;
            Direction[] directions = Direction.values();
            for (int i = 0; i < directions.length; i++) {
                if (!directionUsed[i]) {
                    directionUsed[i] = true;
                    mapping[digitIndex] = directions[i];
                    count += countValidPermutations(digitIndex + 1, mapping, directionUsed, commands, grid, startRow, startCol);
                    directionUsed[i] = false; // Backtrack
                }
            }
            return count;
        }

        /**
         * Simulates the path for a specific digit-to-direction mapping.
         */
        private boolean simulatePath(Direction[] mapping, String commands, Grid grid, int startRow, int startCol) {
            int currentRow = startRow;
            int currentCol = startCol;

            for (char cmdChar : commands.toCharArray()) {
                int digit = cmdChar - '0';
                Direction dir = mapping[digit];

                currentRow += dir.rowDelta;
                currentCol += dir.colDelta;

                if (!grid.isWithinBounds(currentRow, currentCol) || grid.isWall(currentRow, currentCol)) {
                    return false;
                }

                if (grid.isExit(currentRow, currentCol)) {
                    return true;
                }
            }

            return false;
        }
    }

    /**
     * Fast I/O utility for reading input streams.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            this.reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * Solves the Robot Direction puzzle by finding how many permutations of 
 * digit-to-direction mappings allow the robot to reach the exit 'E'.
 */
public class RobotDirect {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int height = reader.nextInt();
            int width = reader.nextInt();

            String[] gridData = new String[height];
            for (int i = 0; i < height; i++) {
                gridData[i] = reader.next();
            }

            GameMap gameMap = new GameMap(gridData);
            Position startPos = gameMap.findStart();
            String commands = reader.next();

            RobotSimulator simulator = new RobotSimulator(gameMap);
            MappingPermutator permutator = new MappingPermutator(commands, simulator, startPos);

            int validMappingsCount = permutator.countValidMappings();
            System.out.println(validMappingsCount);

        } catch (Exception e) {
            System.err.println("Error processing input: " + e.getMessage());
        }
    }

    /**
     * Represents a coordinate on the grid.
     */
    record Position(int row, int col) {}

    /**
     * Defines possible movement directions and their coordinate offsets.
     */
    enum Direction {
        UP(-1, 0),
        DOWN(1, 0),
        LEFT(0, -1),
        RIGHT(0, 1);

        final int rowOffset;
        final int colOffset;

        Direction(int rowOffset, int colOffset) {
            this.rowOffset = rowOffset;
            this.colOffset = colOffset;
        }

        public static Direction[] valuesArray() {
            return values();
        }
    }

    /**
     * Encapsulates the game board logic.
     */
    static class GameMap {
        private final char[][] grid;
        private final int height;
        private final int width;

        public GameMap(String[] rows) {
            this.height = rows.length;
            this.width = rows[0].length();
            this.grid = new char[height][width];
            for (int i = 0; i < height; i++) {
                grid[i] = rows[i].toCharArray();
            }
        }

        public boolean isOutOfBounds(int r, int c) {
            return r < 0 || r >= height || c < 0 || c >= width;
        }

        public boolean isObstacle(int r, int c) {
            return grid[r][c] == '#';
        }

        public boolean isExit(int r, int c) {
            return grid[r][c] == 'E';
        }

        public Position findStart() {
            for (int r = 0; r < height; r++) {
                for (int c = 0; c < width; c++) {
                    if (grid[r][c] == 'S') {
                        return new Position(r, c);
                    }
                }
            }
            throw new NoSuchElementException("Start position 'S' not found in the grid.");
        }
    }

    /**
     * Handles the simulation of the robot following a command sequence.
     */
    static class RobotSimulator {
        private final GameMap gameMap;

        public RobotSimulator(GameMap gameMap) {
            this.gameMap = gameMap;
        }

        public boolean simulate(String commands, Position start, Direction[] mapping) {
            int currentRow = start.row();
            int currentCol = start.col();

            for (char cmdChar : commands.toCharArray()) {
                int digit = cmdChar - '0';
                Direction dir = mapping[digit];

                currentRow += dir.rowOffset;
                currentCol += dir.colOffset;

                if (gameMap.isOutOfBounds(currentRow, currentCol) || gameMap.isObstacle(currentRow, currentCol)) {
                    return false;
                }

                if (gameMap.isExit(currentRow, currentCol)) {
                    return true;
                }
            }
            return false;
        }
    }

    /**
     * Generates all permutations of direction mappings for the digits 0-3.
     */
    static class MappingPermutator {
        private final String commands;
        private final RobotSimulator simulator;
        private final Position startPos;
        private int validCount = 0;

        public MappingPermutator(String commands, RobotSimulator simulator, Position startPos) {
            this.commands = commands;
            this.simulator = simulator;
            this.startPos = startPos;
        }

        public int countValidMappings() {
            Direction[] currentMapping = new Direction[4];
            boolean[] usedDirections = new boolean[4];
            backtrack(0, currentMapping, usedDirections);
            return validCount;
        }

        private void backtrack(int digitIndex, Direction[] currentMapping, boolean[] usedDirections) {
            if (digitIndex == 4) {
                if (simulator.simulate(commands, startPos, currentMapping)) {
                    validCount++;
                }
                return;
            }

            Direction[] allDirections = Direction.valuesArray();
            for (int i = 0; i < allDirections.length; i++) {
                if (!usedDirections[i]) {
                    usedDirections[i] = true;
                    currentMapping[digitIndex] = allDirections[i];
                    backtrack(digitIndex + 1, currentMapping, usedDirections);
                    usedDirections[i] = false; // Undo for backtracking
                }
            }
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Failed to read input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for the "New Year and Buggy Bot" problem.
 * The goal is to find how many permutations of 4 directions allow a robot 
 * to reach the exit 'E' from start 'S' following a sequence of commands.
 */
public class NewYearAndBuggyBot_908B {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            Solver solver = new Solver(reader);
            solver.solve(writer);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Orchestrates the simulation and permutation generation.
     */
    static class Solver {
        private final FastReader reader;
        private static final int[][] DIRECTIONS = {
            {-1, 0}, // 0: Up
            {1, 0},  // 1: Down
            {0, -1}, // 2: Left
            {0, 1}   // 3: Right
        };

        public Solver(FastReader reader) {
            this.reader = reader;
        }

        public void solve(PrintWriter out) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            String[] mazeRows = new String[rows];
            for (int i = 0; i < rows; i++) {
                mazeRows[i] = reader.next();
            }

            String commands = reader.next();
            Maze maze = new Maze(rows, cols, mazeRows);

            List<int[]> permutations = new ArrayList<>();
            generatePermutations(new int[]{0, 1, 2, 3}, 0, permutations);

            int successfulPaths = 0;
            for (int[] permutation : permutations) {
                if (canReachExit(maze, commands, permutation)) {
                    successfulPaths++;
                }
            }

            out.println(successfulPaths);
        }

        /**
         * Simulates the robot movement for a specific permutation of directions.
         */
        private boolean canReachExit(Maze maze, String commands, int[] permutation) {
            int currR = maze.getStartRow();
            int currC = maze.getStartCol();

            for (char cmdChar : commands.toCharArray()) {
                // The command '0'-'3' maps to an index in our permutation array
                int commandIndex = cmdChar - '0';
                int directionIndex = permutation[commandIndex];

                int nextR = currR + DIRECTIONS[directionIndex][0];
                int nextC = currC + DIRECTIONS[directionIndex][1];

                if (maze.isValidMove(nextR, nextC)) {
                    currR = nextR;
                    currC = nextC;

                    if (maze.isExit(currR, currC)) {
                        return true;
                    }
                } else {
                    // Hits a wall or boundary
                    return false;
                }
            }
            return false;
        }

        /**
         * Standard backtracking algorithm to generate all permutations of an array.
         */
        private void generatePermutations(int[] arr, int index, List<int[]> result) {
            if (index == arr.length) {
                result.add(arr.clone());
                return;
            }
            for (int i = index; i < arr.length; i++) {
                swap(arr, index, i);
                generatePermutations(arr, index + 1, result);
                swap(arr, index, i);
            }
        }

        private void swap(int[] arr, int i, int j) {
            int temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }
    }

    /**
     * Represents the maze grid and provides spatial queries.
     */
    static class Maze {
        private final char[][] grid;
        private final int rows;
        private final int cols;
        private int startRow;
        private int startCol;

        public Maze(int rows, int cols, String[] mazeRows) {
            this.rows = rows;
            this.cols = cols;
            this.grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = mazeRows[i].charAt(j);
                    if (grid[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                    }
                }
            }
        }

        public boolean isValidMove(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != '#';
        }

        public boolean isExit(int r, int c) {
            return grid[r][c] == 'E';
        }

        public int getStartRow() { return startRow; }
        public int getStartCol() { return startCol; }
    }

    /**
     * High-performance input reader.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public void close() throws IOException {
            reader.close();
        }
    }
}

import java.util.Scanner;

/**
 * A solver for the grid navigation problem.
 * The goal is to find how many permutations of digit-to-direction mappings
 * allow a robot to travel from a start point 'S' to an end point 'E'
 * following a specific sequence of command digits.
 */
public class GridNavigationSolver {

    /**
     * Represents a coordinate on the grid.
     * Using a record provides immutable state and automatic equals/hashCode.
     */
    private record Point(int row, int col) {}

    // Directional offsets: Up, Down, Right, Left
    private static final int[][] DIRECTIONS = {
        {-1, 0}, // Index 0: Up
        {1, 0},  // Index 1: Down
        {0, 1},  // Index 2: Right
        {0, -1}  // Index 3: Left
    };

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int[] commandSequence;
    private final Point start;
    private final Point end;

    public GridNavigationSolver(int rows, int cols, char[][] grid, String commandStr) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.commandSequence = parseCommands(commandStr);

        // Locate Start and End points during initialization
        Point startPos = null;
        Point endPos = null;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'S') {
                    startPos = new Point(i, j);
                } else if (grid[i][j] == 'E') {
                    endPos = new Point(i, j);
                }
            }
        }
        this.start = startPos;
        this.end = endPos;
    }

    private int[] parseCommands(String commandStr) {
        int[] cmds = new int[commandStr.length()];
        for (int i = 0; i < commandStr.length(); i++) {
            cmds[i] = commandStr.charAt(i) - '0';
        }
        return cmds;
    }

    /**
     * Calculates the number of valid direction permutations.
     */
    public int countValidMappings() {
        return generatePermutations(new int[4], new boolean[4], 0);
    }

    /**
     * Recursive method to generate all 4! permutations of direction mappings.
     * 
     * @param p The current permutation being built.
     * @param used Boolean array to track used digits in the permutation.
     * @param depth Current recursion depth.
     * @return The count of valid permutations found from this state.
     */
    private int generatePermutations(int[] p, boolean[] used, int depth) {
        if (depth == 4) {
            return simulatePath(p) ? 1 : 0;
        }

        int validCount = 0;
        for (int i = 0; i < 4; i++) {
            if (!used[i]) {
                used[i] = true;
                p[depth] = i;
                validCount += generatePermutations(p, used, depth + 1);
                used[i] = false;
            }
        }
        return validCount;
    }

    /**
     * Simulates the robot movement based on the provided mapping.
     * 
     * @param mapping An array where mapping[i] is the digit associated with direction i.
     * @return true if the robot reaches the end point 'E'.
     */
    private boolean simulatePath(int[] mapping) {
        // digitToDirection[digit] = index in DIRECTIONS array
        int[] digitToDirection = new int[4];
        for (int i = 0; i < 4; i++) {
            digitToDirection[mapping[i]] = i;
        }

        Point current = start;

        // If the robot is already at the end
        if (current.equals(end)) {
            return true;
        }

        for (int commandDigit : commandSequence) {
            int dirIdx = digitToDirection[commandDigit];
            int nextR = current.row + DIRECTIONS[dirIdx][0];
            int nextC = current.col + DIRECTIONS[dirIdx][1];

            if (isInvalidPosition(nextR, nextC)) {
                return false;
            }

            current = new Point(nextR, nextC);

            if (current.equals(end)) {
                return true;
            }
        }

        return false;
    }

    private boolean isInvalidPosition(int r, int c) {
        return r < 0 || r >= rows || c < 0 || c >= cols || grid[r][c] == '#';
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int n = scanner.nextInt();
        int m = scanner.nextInt();
        char[][] grid = new char[n][m];

        for (int i = 0; i < n; i++) {
            String rowLine = scanner.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = rowLine.charAt(j);
            }
        }

        String commands = scanner.next();
        GridNavigationSolver solver = new GridNavigationSolver(n, m, grid, commands);

        System.out.println(solver.countValidMappings());

        scanner.close();
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to calculate the number of ways to map command digits (0-3) 
 * to physical directions (Up, Down, Left, Right) such that a sequence 
 * of commands leads a traveler from a starting point 'S' to an exit 'E'.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            // Read grid dimensions
            String nInput = reader.next();
            if (nInput == null) return;
            int n = Integer.parseInt(nInput);
            int m = reader.nextInt();

            // Read grid rows
            String[] matrix = new String[n];
            for (int i = 0; i < n; i++) {
                matrix[i] = reader.next();
            }

            // Read instruction sequence
            String sequence = reader.next();

            // Solve and output result
            MazeSolver solver = new MazeSolver(matrix, sequence);
            writer.println(solver.countValidDirectionMappings());

        } catch (Exception e) {
            // In a production environment, use a proper logging framework
        } finally {
            writer.close();
        }
    }

    /**
     * Encapsulates the maze grid and provides spatial queries.
     */
    static class Grid {
        private final char[][] cells;
        private final int rows;
        private final int cols;
        private int startRow = -1;
        private int startCol = -1;

        public Grid(String[] matrix) {
            this.rows = matrix.length;
            this.cols = matrix[0].length();
            this.cells = new char[rows][cols];

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    cells[i][j] = matrix[i].charAt(j);
                    if (cells[i][j] == 'S') {
                        startRow = i;
                        startCol = j;
                    }
                }
            }
        }

        public int getStartRow() { return startRow; }
        public int getStartCol() { return startCol; }

        /**
         * Checks if a coordinate is outside the grid or is a wall ('#').
         */
        public boolean isInvalidMove(int r, int c) {
            return r < 0 || r >= rows || c < 0 || c >= cols || cells[r][c] == '#';
        }

        /**
         * Checks if the coordinate is the exit ('E').
         */
        public boolean isExit(int r, int c) {
            return cells[r][c] == 'E';
        }
    }

    /**
     * Contains the core logic for solving the permutation problem.
     */
    static class MazeSolver {
        private final Grid grid;
        private final String sequence;

        // Base directions mapped to indices: 0: Left, 1: Right, 2: Up, 3: Down
        private final int[] baseDx = {0, 0, -1, 1};
        private final int[] baseDy = {-1, 1, 0, 0};

        public MazeSolver(String[] matrix, String sequence) {
            this.grid = new Grid(matrix);
            this.sequence = sequence;
        }

        /**
         * Iterates through all 24 permutations of direction mappings.
         */
        public int countValidDirectionMappings() {
            int[] permutation = {0, 1, 2, 3};
            int validCount = 0;

            do {
                if (canPathReachExit(permutation)) {
                    validCount++;
                }
            } while (nextPermutation(permutation));

            return validCount;
        }

        /**
         * Simulates the path using the current permutation of direction mappings.
         */
        private boolean canPathReachExit(int[] mapping) {
            int[] mappedDx = new int[4];
            int[] mappedDy = new int[4];

            // Map command IDs to physical directions based on the current permutation
            for (int i = 0; i < 4; i++) {
                mappedDx[i] = baseDx[mapping[i]];
                mappedDy[i] = baseDy[mapping[i]];
            }

            int currentRow = grid.getStartRow();
            int currentCol = grid.getStartCol();

            for (int i = 0; i < sequence.length(); i++) {
                int command = sequence.charAt(i) - '0';
                int nextRow = currentRow + mappedDx[command];
                int nextCol = currentCol + mappedDy[command];

                if (grid.isInvalidMove(nextRow, nextCol)) {
                    return false;
                }
                if (grid.isExit(nextRow, nextCol)) {
                    return true;
                }

                currentRow = nextRow;
                currentCol = nextCol;
            }
            return false;
        }

        /**
         * Lexicographical next permutation algorithm.
         */
        private boolean nextPermutation(int[] array) {
            int i = array.length - 2;
            while (i >= 0 && array[i] >= array[i + 1]) {
                i--;
            }

            if (i < 0) return false;

            int j = array.length - 1;
            while (array[j] <= array[i]) {
                j--;
            }

            swap(array, i, j);
            reverse(array, i + 1, array.length - 1);
            return true;
        }

        private void swap(int[] array, int i, int j) {
            int temp = array[i];
            array[i] = array[j];
            array[j] = temp;
        }

        private void reverse(int[] array, int i, int j) {
            while (i < j) {
                swap(array, i++, j--);
            }
        }
    }

    /**
     * Utility class for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            String next = next();
            return next == null ? 0 : Integer.parseInt(next);
        }
    }
}

import java.util.*;
