/**
 * Represents a coordinate on the grid.
 */
final class Point {
    private final int row;
    private final int col;

    public Point(int row, int col) {
        this.row = row;
        this.col = col;
    }

    public int getRow() { return row; }
    public int getCol() { return col; }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        Point point = (Point) o;
        return row == point.row && col == point.col;
    }

    @Override
    public int hashCode() {
        return Objects.hash(row, col);
    }
}

/**
 * Logic for finding the number of direction permutations that lead from Start to End.
 */
class PathSolver {
    private static final Point[] CARDINAL_DIRECTIONS = {
        new Point(0, 1),  // Right
        new Point(1, 0),  // Down
        new Point(0, -1), // Left
        new Point(-1, 0)  // Up
    };

    private final char[][] grid;
    private final int rows;
    private final int cols;
    private final Point start;
    private final Point end;
    private final String directionSequence;

    private int validPathCount = 0;

    public PathSolver(char[][] grid, int rows, int cols, Point start, Point end, String directionSequence) {
        this.grid = grid;
        this.rows = rows;
        this.cols = cols;
        this.start = start;
        this.end = end;
        this.directionSequence = directionSequence;
    }

    /**
     * Entry point for solving the problem.
     * @return Total number of valid direction permutations.
     */
    public int solve() {
        validPathCount = 0;
        Point[] directionMapping = new Point[4];
        boolean[] usedInPermutation = new boolean[4];

        generatePermutations(0, directionMapping, usedInPermutation);
        return validPathCount;
    }

    /**
     * Generates all permutations of the 4 cardinal directions using DFS.
     */
    private void generatePermutations(int depth, Point[] mapping, boolean[] used) {
        if (depth == 4) {
            if (isValidPath(mapping)) {
                validPathCount++;
            }
            return;
        }

        for (int i = 0; i < 4; i++) {
            if (!used[i]) {
                used[i] = true;
                mapping[depth] = CARDINAL_DIRECTIONS[i];
                generatePermutations(depth + 1, mapping, used);
                used[i] = false;
            }
        }
    }

    /**
     * Simulates the movement based on the current direction mapping.
     */
    private boolean isValidPath(Point[] mapping) {
        Point currentPos = start;

        for (int i = 0; i < directionSequence.length(); i++) {
            int dirIndex = directionSequence.charAt(i) - '0';
            Point move = mapping[dirIndex];

            int nextRow = currentPos.getRow() + move.getRow();
            int nextCol = currentPos.getCol() + move.getCol();

            // Check boundaries and obstacles
            if (isOutOfBounds(nextRow, nextCol) || grid[nextRow][nextCol] == '#') {
                return false;
            }

            currentPos = new Point(nextRow, nextCol);

            // If we reach the target at any point in the sequence, it is a success
            if (currentPos.equals(end)) {
                return true;
            }
        }

        return currentPos.equals(end);
    }

    private boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= rows || c < 0 || c >= cols;
    }
}

public class Main {
    public static void main(String[] args) {
        try {
            BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
            String firstLine = br.readLine();
            if (firstLine == null) return;

            StringTokenizer st = new StringTokenizer(firstLine);
            int N = Integer.parseInt(st.nextToken());
