                    if (grid[i][j] == 'S') {
                        start = new Point(i, j);
                    } else if (grid[i][j] == 'E') {
                        end = new Point(i, j);
                    }
                }
            }

            String directionSequence = br.readLine();

            if (start == null || end == null) {
                System.out.println(0);
                return;
            }

            PathSolver solver = new PathSolver(grid, N, M, start, end, directionSequence);
            System.out.println(solver.solve());

        } catch (IOException e) {
