        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

/**
 * MazeSolver solves the problem of finding how many different direction-to-digit 
 * mappings allow a player to reach the exit 'E' from start 'S' without hitting 
 * walls '#' or going out of bounds.
 */
public class MazeSolver {

    // Directional offsets: East, West, North, South
    private static final int[] ROW_OFFSETS = {0, 0, -1, 1};
    private static final int[] COL_OFFSETS = {1, -1, 0, 0};

    public static void main(String[] args) {
        try {
            MazeSolver solver = new MazeSolver();
            solver.run();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    public void run() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int rows = Integer.parseInt(st.nextToken());
        int cols = Integer.parseInt(st.nextToken());

        char[][] maze = new char[rows][cols];
        int startR = 0, startC = 0;
        int exitR = 0, exitC = 0;

        // Parse the maze
        for (int i = 0; i < rows; i++) {
            String line = br.readLine();
            for (int j = 0; j < cols; j++) {
                maze[i][j] = line.charAt(j);
                if (maze[i][j] == 'S') {
                    startR = i;
                    startC = j;
                } else if (maze[i][j] == 'E') {
                    exitR = i;
                    exitC = j;
                }
            }
        }

        // Parse movement instructions
        String instructionLine = br.readLine();
        int[] instructions = new int[instructionLine.length()];
        for (int i = 0; i < instructionLine.length(); i++) {
            instructions[i] = instructionLine.charAt(i) - '0';
        }

        // Solve
        int result = solve(maze, rows, cols, startR, startC, exitR, exitC, instructions);
        System.out.println(result);
    }

    private int solve(char[][] maze, int rows, int cols, int startR, int startC, 
                      int exitR, int exitC, int[] instructions) {

        int successfulMappings = 0;
        List<int[]> directionPermutations = generatePermutations(new int[]{0, 1, 2, 3});

        for (int[] p : directionPermutations) {
            // Create a mapping: digit -> direction index
            // If p[0] = 2, it means digit 2 corresponds to direction index 0
            int[] digitToDir = new int[4];
            for (int i = 0; i < 4; i++) {
                digitToDir[p[i]] = i;
            }

            if (canReachExit(maze, rows, cols, startR, startC, exitR, exitC, instructions, digitToDir)) {
                successfulMappings++;
            }
        }

        return successfulMappings;
    }

    private boolean canReachExit(char[][] maze, int rows, int cols, int startR, int startC, 
                                 int exitR, int exitC, int[] instructions, int[] digitToDir) {
        int currR = startR;
        int currC = startC;

        for (int digit : instructions) {
            int dirIdx = digitToDir[digit];
            int nextR = currR + ROW_OFFSETS[dirIdx];
            int nextC = currC + COL_OFFSETS[dirIdx];

            // Check bounds and walls
            if (nextR < 0 || nextR >= rows || nextC < 0 || nextC >= cols || maze[nextR][nextC] == '#') {
                return false;
            }

            currR = nextR;
            currC = nextC;

            // Check if exit reached
            if (currR == exitR && currC == exitC) {
                return true;
            }
        }

        // If we finished instructions without hitting 'E'
        return false;
    }

    /**
     * Generates all permutations of the given array using backtracking.
     */
    private List<int[]> generatePermutations(int[] nums) {
        List<int[]> result = new ArrayList<>();
        backtrack(nums, 0, result);
        return result;
    }

    private void backtrack(int[] nums, int start, List<int[]> result) {
        if (start == nums.length) {
            result.add(nums.clone());
            return;
        }
        for (int i = start; i < nums.length; i++) {
            swap(nums, start, i);
            backtrack(nums, start + 1, result);
            swap(nums, start, i); // backtrack
        }
    }

    private void swap(int[] nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * Solves the Codeforces 908B problem.
 * The goal is to find how many permutations of direction mappings (0-3) 
 * allow a character starting at 'S' to reach 'E' without hitting '#' or boundaries.
 */
public class Codeforces908B {

    private static final char START = 'S';
    private static final char END = 'E';
    private static final char WALL = '#';

    // Direction vectors corresponding to the mapping order:
    // Index 0: Up, Index 1: Down, Index 2: Left, Index 3: Right
    private static final int[] DR = {-1, 1, 0, 0};
    private static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();
        scanner.nextLine(); // Consume newline

        char[][] grid = new char[rows][cols];
        int startR = 0, startC = 0;

        // Parse grid and locate starting position
        for (int i = 0; i < rows; i++) {
            String line = scanner.nextLine();
            grid[i] = line.toCharArray();
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == START) {
                    startR = i;
                    startC = j;
                }
            }
        }

        String commandString = scanner.next();
        int[] commands = parseCommands(commandString);

        // Generate all permutations of {0, 1, 2, 3}
        List<int[]> permutations = new ArrayList<>();
        generatePermutations(new int[]{0, 1, 2, 3}, 0, permutations);

        int successfulPaths = 0;
        for (int[] p : permutations) {
            if (canReachEnd(grid, rows, cols, startR, startC, commands, p)) {
                successfulPaths++;
            }
        }

        System.out.println(successfulPaths);
        scanner.close();
    }

    /**
     * Converts the input command string into an array of integers.
     */
    private static int[] parseCommands(String commandString) {
        int[] commands = new int[commandString.length()];
        for (int i = 0; i < commandString.length(); i++) {
            commands[i] = commandString.charAt(i) - '0';
        }
        return commands;
    }

    /**
     * Standard backtracking algorithm to generate permutations of an array.
     */
    private static void generatePermutations(int[] arr, int index, List<int[]> result) {
        if (index == arr.length) {
            result.add(arr.clone());
            return;
        }
        for (int i = index; i < arr.length; i++) {
            swap(arr, index, i);
            generatePermutations(arr, index + 1, result);
            swap(arr, index, i); // backtrack
        }
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    /**
     * Simulates the movement of the character based on a specific direction mapping.
     * 
     * @param p The permutation where p[0] is the digit for Up, p[1] for Down, etc.
     */
    private static boolean canReachEnd(char[][] grid, int rows, int cols, 
                                      int startR, int startC, 
                                      int[] commands, int[] p) {
        int currR = startR;
        int currC = startC;

        for (int cmd : commands) {
            // Determine direction based on the current permutation mapping
            // The original logic: if digit == p[0] move Up, if digit == p[1] move Down, etc.
            int dr = 0;
            int dc = 0;

            if (cmd == p[0]) {
                dr = DR[0]; dc = DC[0];
            } else if (cmd == p[1]) {
                dr = DR[1]; dc = DC[1];
            } else if (cmd == p[2]) {
                dr = DR[2]; dc = DC[2];
            } else if (cmd == p[3]) {
                dr = DR[3]; dc = DC[3];
            }

            currR += dr;
            currC += dc;

            // Boundary check
            if (currR < 0 || currR >= rows || currC < 0 || currC >= cols) {
                return false;
            }
            // Obstacle check
            if (grid[currR][currC] == WALL) {
                return false;
            }
            // Success check
            if (grid[currR][currC] == END) {
                return true;
            }
        }

        return false;
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * A program to simulate grid-based pathfinding permutations.
 * It determines how many permutations of movement directions (L, R, U, D)
 * result in reaching an exit 'E' from a starting point 'S'.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        PathSimulationSolver solver = new PathSimulationSolver(rows, cols, scanner);
        int successfulPaths = solver.solve();

        System.out.println(successfulPaths);
        scanner.close();
    }

    /**
     * Orchestrates the grid parsing, permutation generation, and simulation.
     */
    static class PathSimulationSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;
        private final String instructions;
        private int startRow;
        private int startCol;

        public PathSimulationSolver(int rows, int cols, Scanner scanner) {
            this.rows = rows;
            this.cols = cols;
            this.grid = new char[rows][cols];

            // 1. Parse the grid and find the starting position
            parseGrid(scanner);

            // 2. Parse the instruction sequence
            this.instructions = scanner.hasNext() ? scanner.next() : "";
        }

        /**
         * Reads grid characters skipping whitespace and locates 'S'.
         */
        private void parseGrid(Scanner scanner) {
            List<Character> charBuffer = new ArrayList<>();
            while (charBuffer.size() < rows * cols && scanner.hasNext()) {
                String segment = scanner.next();
                for (char c : segment.toCharArray()) {
                    charBuffer.add(c);
                }
            }

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    int index = i * cols + j;
                    if (index < charBuffer.size()) {
                        grid[i][j] = charBuffer.get(index);
                        if (grid[i][j] == 'S') {
                            startRow = i;
                            startCol = j;
                        }
                    }
                }
            }
        }

        /**
         * Executes the simulation for all possible direction permutations.
         * @return The number of permutations that reach the exit 'E'.
         */
        public int solve() {
            List<String> permutations = PermutationGenerator.generate("LRUD");
            int successCount = 0;

            for (String mapping : permutations) {
                if (simulatePath(mapping)) {
                    successCount++;
                }
            }

            return successCount;
        }

        /**
         * Simulates a single permutation of directions.
         * @param directionMapping A 4-character string representing the mapping of 
         *                          digits 0-3 to directions L, R, U, D.
         * @return true if the exit 'E' is reached.
         */
        private boolean simulatePath(String directionMapping) {
            int currentRow = startRow;
            int currentCol = startCol;

            for (int i = 0; i < instructions.length(); i++) {
                int digitIndex = instructions.charAt(i) - '0';

                // Safety check for invalid instruction digits
                if (digitIndex < 0 || digitIndex >= 4) {
                    break;
                }

                char move = directionMapping.charAt(digitIndex);
                applyMove(move, currentRow, currentCol); // Logic moved to update local coords

                // Update coordinates based on the move
                if (move == 'L') currentCol--;
                else if (move == 'R') currentCol++;
                else if (move == 'U') currentRow--;
                else if (move == 'D') currentRow++;

                // Boundary and Obstacle Check
                if (isOutOfBounds(currentRow, currentCol) || grid[currentRow][currentCol] == '#') {
                    break;
                }

                // Goal Check
                if (grid[currentRow][currentCol] == 'E') {
                    return true;
                }
            }

            return false;
        }

        private boolean isOutOfBounds(int r, int c) {
            return r < 0 || r >= rows || c < 0 || c >= cols;
        }

        private void applyMove(char move, int r, int c) {
            // Placeholder for potential expansion of movement logic
        }
    }

    /**
     * Utility class for generating permutations of a string.
     */
    static class PermutationGenerator {
        /**
         * Generates all permutations of the input string.
         */
        public static List<String> generate(String input) {
            List<String> result = new ArrayList<>();
            backtrack(result, "", input);
            return result;
        }

        private static void backtrack(List<String> result, String prefix, String remaining) {
            int n = remaining.length();
            if (n == 0) {
                result.add(prefix);
            } else {
                for (int i = 0; i < n; i++) {
                    String nextPrefix = prefix + remaining.charAt(i);
                    String nextRemaining = remaining.substring(0, i) + remaining.substring(i + 1);
                    backtrack(result, nextPrefix, nextRemaining);
                }
            }
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A refactored solution for a grid-based connectivity problem.
 * The algorithm performs a wave-based BFS where each wave is a 4-connected component,
 * and the next wave is determined by the 5x5 neighborhood of the current component.
 */
public class Main {

    public static void main(String[] args) {
        try {
            FastReader reader = new FastReader(System.in);
            Solver solver = new Solver(reader);
            solver.solve();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    /**
     * Represents a coordinate in the grid.
     */
    static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point point = (Point) o;
            return r == point.r && c == point.c;
        }

        @Override
        public int hashCode() {
            return Objects.hash(r, c);
        }
    }

    static class Solver {
        private final FastReader reader;
        private static final int[] DR = {0, 0, 1, -1};
        private static final int[] DC = {1, -1, 0, 0};

        Solver(FastReader reader) {
            this.reader = reader;
        }

        public void solve() throws IOException {
            int height = reader.nextInt();
            int width = reader.nextInt();

            // Convert 1-based indexing to 0-based
            int startRow = reader.nextInt() - 1;
            int startCol = reader.nextInt() - 1;
            int targetRow = reader.nextInt() - 1;
            int targetCol = reader.nextInt() - 1;

            char[][] grid = new char[height][width];
            for (int i = 0; i < height; i++) {
                grid[i] = reader.next().toCharArray();
            }

            int[][] distances = new int[height][width];
            for (int i = 0; i < height; i++) {
                Arrays.fill(distances[i], -1);
            }

            boolean[][] visited = new boolean[height][width];
            boolean[][] inEndpoints = new boolean[height][width];

            Deque<Point> endpoints = new ArrayDeque<>();

            // Initialize start point
            endpoints.add(new Point(startRow, startCol));
            inEndpoints[startRow][startCol] = true;

            int currentDistance = 0;

            while (!endpoints.isEmpty()) {
                // Move all current frontier points into the current processing queue
                Deque<Point> currentWaveQueue = new ArrayDeque<>();
                while (!endpoints.isEmpty()) {
                    currentWaveQueue.add(endpoints.pollFirst());
                }

                List<Point> exploredInWave = new ArrayList<>();

                // Phase 1: Standard BFS to find the entire 4-connected component
                while (!currentWaveQueue.isEmpty()) {
                    Point p = currentWaveQueue.pollFirst();

                    if (visited[p.r][p.c]) continue;

                    visited[p.r][p.c] = true;
                    distances[p.r][p.c] = currentDistance;
                    exploredInWave.add(p);

                    for (int i = 0; i < 4; i++) {
                        int nr = p.r + DR[i];
                        int nc = p.c + DC[i];

                        if (isValid(nr, nc, height, width) 
                                && grid[nr][nc] == '.' 
                                && !visited[nr][nc]) {
                            currentWaveQueue.add(new Point(nr, nc));
                        }
                    }
                }

                // Phase 2: Determine the next frontier (5x5 area around current component)
                currentDistance++;
                for (Point p : exploredInWave) {
                    for (int dr = -2; dr <= 2; dr++) {
                        for (int dc = -2; dc <= 2; dc++) {
                            if (dr == 0 && dc == 0) continue;

                            int nr = p.r + dr;
                            int nc = p.c + dc;

                            if (isValid(nr, nc, height, width) 
                                    && grid[nr][nc] == '.' 
                                    && !visited[nr][nc] 
                                    && !inEndpoints[nr][nc]) {

                                endpoints.add(new Point(nr, nc));
                                inEndpoints[nr][nc] = true;
                            }
                        }
                    }
                }
            }

            System.out.println(distances[targetRow][targetCol]);
        }

        private boolean isValid(int r, int c, int h, int w) {
            return r >= 0 && r < h && c >= 0 && c < w;
        }
    }

    /**
     * Fast I/O reader for efficient integer and string parsing.
     */
    static class FastReader {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int len = 0;

        public FastReader(InputStream in) {
            this.in = in;
        }

        private int readByte() throws IOException {
            if (ptr >= len) {
                ptr = 0;
                len = in.read(buffer);
                if (len <= 0) return -1;
            }
            return buffer[ptr++] & 0xff;
        }

        public int nextInt() throws IOException {
            int b = readByte();
            while (b != -1 && b <= 32) b = readByte();
            if (b == -1) return 0;

            boolean minus = false;
            if (b == '-') {
                minus = true;
                b = readByte();
            }

            int res = 0;
            while (b >= '0' && b <= '9') {
                res = res * 10 + (b - '0');
                b = readByte();
            }
            return minus ? -res : res;
        }

        public String next() throws IOException {
            int b = readByte();
            while (b != -1 && b <= 32) b = readByte();
            if (b == -1) return "";

            StringBuilder sb = new StringBuilder();
            while (b > 32) {
                sb.append((char) b);
                b = readByte();
            }
            return sb.toString();
        }
    }
}

