/**
 * Represents a coordinate in the 2D grid.
 * Using a record provides immutability and built-in equals/hashCode.
 */
record Point(int row, int col) {}

/**
 * Solves the maze shortest path problem using a 0-1 BFS algorithm.
 */
class MazeSolver {
    private static final int INF = Integer.MAX_VALUE;

    // Directions for standard adjacent moves (Up, Down, Left, Right)
    private static final int[][] ADJACENT_DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    private final int height;
    private final int width;
    private final char[][] grid;
    private final int startRow;
    private final int startCol;
    private final int endRow;
    private final int endCol;

    public MazeSolver(int height, int width, int startRow, int startCol, int endRow, int endCol, char[][] grid) {
        this.height = height;
        this.width = width;
        this.startRow = startRow;
        this.startCol = startCol;
        this.endRow = endRow;
        this.endCol = endCol;
        this.grid = grid;
    }

    /**
     * Executes the 0-1 BFS to find the minimum cost to reach the destination.
     * Cost 0: Moving to an adjacent cell.
     * Cost 1: Jumping to a non-adjacent cell within a 5x5 area.
     * 
     * @return The minimum cost to reach the end point, or Integer.MAX_VALUE if unreachable.
     */
    public int solve() {
        int[][] distances = new int[height][width];
        for (int[] row : distances) {
            Arrays.fill(row, INF);
        }

        Deque<Point> deque = new ArrayDeque<>();

        // Initialize starting position
        Point start = new Point(startRow, startCol);
        distances[startRow][startCol] = 0;
        deque.addFirst(start);

        while (!deque.isEmpty()) {
            Point current = deque.pollFirst();

            if (current.row() == endRow && current.col() == endCol) {
                return distances[endRow][endCol];
            }

            // 1. Process Adjacent Moves (Weight 0)
            for (int[] dir : ADJACENT_DIRECTIONS) {
                int nr = current.row() + dir[0];
                int nc = current.col() + dir[1];
                processNeighbor(current, nr, nc, 0, distances, deque);
            }

            // 2. Process Jump Moves (Weight 1)
            // Jumps are to any cell in a 5x5 area that is not the current cell or an adjacent cell
            for (int dr = -2; dr <= 2; dr++) {
                for (int dc = -2; dc <= 2; dc++) {
                    if (dr == 0 && dc == 0) continue; // Skip current cell

                    // Skip immediate neighbors (already handled by weight 0)
                    if (Math.abs(dr) + Math.abs(dc) == 1) continue;

                    int nr = current.row() + dr;
                    int nc = current.col() + dc;
                    processNeighbor(current, nr, nc, 1, distances, deque);
                }
            }
        }

        return distances[endRow][endCol];
    }

    private void processNeighbor(Point current, int nr, int nc, int weight, int[][] distances, Deque<Point> deque) {
        if (isValid(nr, nc) && grid[nr][nc] != '#') {
            int newDist = distances[current.row()][current.col()] + weight;
            if (newDist < distances[nr][nc]) {
                distances[nr][nc] = newDist;
                if (weight == 0) {
                    deque.addFirst(new Point(nr, nc));
                } else {
                    deque.addLast(new Point(nr, nc));
                }
            }
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < height && c >= 0 && c < width;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) return;

        // Input dimensions and coordinates
        int h = sc.nextInt();
        int w = sc.nextInt();
        int startR = sc.nextInt() - 1; // Convert to 0-indexed
        int startC = sc.nextInt() - 1;
        int endR = sc.nextInt() - 1;
        int endC = sc.nextInt() - 1;

        // Input grid
        char[][] grid = new char[h][w];
        for (int i = 0; i < h; i++) {
            String line = sc.next();
            grid[i] = line.toCharArray();
        }

        MazeSolver solver = new MazeSolver(h, w, startR, startC, endR, endC, grid);
        int result = solver.solve();

        // Output result (prints Integer.MAX_VALUE if unreachable, matching original behavior)
        System.out.println(result == Integer.MAX_VALUE ? "2147483647" : result);

        sc.close();
    }
}

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

/**
 * An optimized and maintainable version of the Maze Solver.
 * The algorithm uses a 0-1 BFS approach where:
 * - Walking to an adjacent cell has a cost of 0.
 * - Using magic to jump within a 5x5 area has a cost of 1.
 */
public class MazeSolverApp {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        try {
            // Input Parsing
            int mazeWidth = scanner.nextInt();
            int mazeHeight = scanner.nextInt();

            // 1-indexed to 0-indexed conversion
            int startX = scanner.nextInt() - 1;
            int startY = scanner.nextInt() - 1;
            int goalX = scanner.nextInt() - 1;
            int goalY = scanner.nextInt() - 1;

            int[][] grid = new int[mazeWidth][mazeHeight];
            for (int i = 0; i < mazeWidth; i++) {
                String rowData = scanner.next();
                for (int j = 0; j < mazeHeight; j++) {
                    grid[i][j] = (rowData.charAt(j) == '#') 
                                 ? MazeSolver.WALL 
                                 : MazeSolver.EMPTY_CELL;
                }
            }

            // Solve
            MazeSolver solver = new MazeSolver(grid, mazeWidth, mazeHeight, goalX, goalY);
            int result = solver.solve(startX, startY);

            System.out.println(result);

        } catch (Exception e) {
            // In a real-world app, use a logging framework
            System.err.println("Error processing maze: " + e.getMessage());
        } finally {
            scanner.close();
        }
    }
}

class MazeSolver {
    public static final int WALL = -2;
    public static final int EMPTY_CELL = -1;

    private final int[][] maze;
    private final int width;
    private final int height;
    private final int goalX;
    private final int goalY;

    /**
     * Represents a state in the maze traversal.
     */
    private static class Node {
        final int x;
        final int y;
        final int cost;

        Node(int x, int y, int cost) {
            this.x = x;
            this.y = y;
            this.cost = cost;
        }
    }

    public MazeSolver(int[][] maze, int width, int height, int goalX, int goalY) {
        this.maze = maze;
        this.width = width;
        this.height = height;
        this.goalX = goalX;
        this.goalY = goalY;
    }

    /**
     * Executes the 0-1 BFS algorithm to find the minimum cost to reach the goal.
     * 
     * @param startX Starting row index.
     * @param startY Starting column index.
     * @return The minimum cost to reach the goal, or -1 if unreachable.
     */
    public int solve(int startX, int startY) {
        Deque<Node> nodeQueue = new ArrayDeque<>();
        nodeQueue.addFirst(new Node(startX, startY, 0));

        while (!nodeQueue.isEmpty()) {
            Node current = nodeQueue.removeFirst();

            // Check if goal reached
            if (current.x == goalX && current.y == goalY) {
                return current.cost;
            }

            // If the cell is not an empty cell, it's either a wall or already visited
            if (maze[current.x][current.y] != EMPTY_CELL) {
                continue;
            }

            // Mark cell as visited by storing the cost
            maze[current.x][current.y] = current.cost;

            // 1. Explore Walking (Weight 0) - Added to front of Deque
            addWalkMoves(current, nodeQueue);

            // 2. Explore Magic (Weight 1) - Added to back of Deque
            addMagicMoves(current, nodeQueue);
        }

        return -1;
    }

    private void addWalkMoves(Node current, Deque<Node> queue) {
        // Cardinal directions: North, South, West, East
        int[] dx = {-1, 1, 0, 0};
        int[] dy = {0, 0, -1, 1};

        for (int i = 0; i < 4; i++) {
            int nextX = current.x + dx[i];
            int nextY = current.y + dy[i];

            if (isValidMove(nextX, nextY)) {
                // Cost remains the same for walking
                queue.addFirst(new Node(nextX, nextY, current.cost));
            }
        }
    }

    private void addMagicMoves(Node current, Deque<Node> queue) {
        // Magic covers a 5x5 area centered on the current position
        for (int i = -2; i <= 2; i++) {
            for (int j = -2; j <= 2; j++) {
                int nextX = current.x + i;
                int nextY = current.y + j;

                // Skip the current cell itself to avoid redundant processing
                if (i == 0 && j == 0) continue;

                if (isValidMove(nextX, nextY)) {
                    // Cost increases by 1 for magic use
                    queue.addLast(new Node(nextX, nextY, current.cost + 1));
                }
            }
        }
    }

    private boolean isValidMove(int x, int y) {
        return x >= 0 && x < width && 
               y >= 0 && y < height && 
               maze[x][y] == EMPTY_CELL;
    }
}

import java.util.*;

/**
 * Represents a coordinate on the grid.
 */
record Position(int row, int col) {}

/**
 * Encapsulates the game board and its rules.
 */
class Grid {
    private final int height;
    private final int width;
    private final char[][] map;

    public Grid(int height, int width, String[] rows) {
        this.height = height;
        this.width = width;
        this.map = new char[height][width];
        for (int i = 0; i < height; i++) {
            this.map[i] = rows[i].toCharArray();
        }
    }

    public boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < height && c >= 0 && c < width;
    }

    public boolean isWalkable(int r, int c) {
        return isWithinBounds(r, c) && map[r][c] != '#';
    }

    public int getHeight() { return height; }
    public int getWidth() { return width; }
}

/**
 * Handles the pathfinding logic to find the minimum number of warps.
 */
class WarpNavigator {
    private static final int UNREACHABLE = Integer.MAX_VALUE;

    public int findMinimumWarps(Grid grid, Position start, Position target) {
        int[][] minWarpsToReach = new int[grid.getHeight()][grid.getWidth()];
        for (int[] row : minWarpsToReach) {
            Arrays.fill(row, UNREACHABLE);
        }

        // 0-1 BFS using a Deque
        Deque<Position> deque = new ArrayDeque<>();

        minWarpsToReach[start.row()][start.col()] = 0;
        deque.addFirst(start);

        while (!deque.isEmpty()) {
            Position current = deque.pollFirst();
            int currentWarps = minWarpsToReach[current.row()][current.col()];

            // If we reached the target, because of 0-1 BFS properties, 
            // the first time we extract it from the deque, it's the shortest path.
            if (current.equals(target)) {
                return currentWarps;
            }

            // Explore the 5x5 area around the current position
            for (int dr = -2; dr <= 2; dr++) {
                for (int dc = -2; dc <= 2; dc++) {
                    if (dr == 0 && dc == 0) continue;

                    int nr = current.row() + dr;
                    int nc = current.col() + dc;

                    if (grid.isWalkable(nr, nc)) {
                        // A "walk" is defined as moving to an adjacent cell (Manhattan distance 1)
                        // A "warp" is any other move within the 5x5 area
                        int moveCost = (Math.abs(dr) + Math.abs(dc) == 1) ? 0 : 1;
                        int newWarps = currentWarps + moveCost;

                        if (newWarps < minWarpsToReach[nr][nc]) {
                            minWarpsToReach[nr][nc] = newWarps;
                            if (moveCost == 0) {
                                deque.addFirst(new Position(nr, nc));
                            } else {
                                deque.addLast(new Position(nr, nc));
                            }
                        }
                    }
                }
            }
        }

        return -1;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        try {
            if (!sc.hasNextInt()) return;
            int height = sc.nextInt();
            int width = sc.nextInt();

            // Input coordinates are 1-indexed, convert to 0-indexed
            Position start = new Position(sc.nextInt() - 1, sc.nextInt() - 1);
            Position target = new Position(sc.nextInt() - 1, sc.nextInt() - 1);

            String[] mapRows = new String[height];
            for (int i = 0; i < height; i++) {
                mapRows[i] = sc.next();
            }

            Grid grid = new Grid(height, width, mapRows);
            WarpNavigator navigator = new WarpNavigator();

            int result = navigator.findMinimumWarps(grid, start, target);
            System.out.println(result);

        } catch (Exception e) {
            // In a production environment, use a logger
            System.err.println("An error occurred during execution: " + e.getMessage());
        } finally {
            sc.close();
        }
    }
}

