/**
 * Handles fast input parsing from the input stream.
 */
class FastReader {
    private final BufferedReader br;
    private StringTokenizer st;

    public FastReader() {
        this.br = new BufferedReader(new InputStreamReader(System.in));
    }

    public String next() throws IOException {
        while (st == null || !st.hasMoreTokens()) {
            String line = br.readLine();
            if (line == null) return null;
            st = new StringTokenizer(line);
        }
        return st.nextToken();
    }

    public int nextInt() throws IOException {
        return Integer.parseInt(next());
    }
}

/**
 * Logic for finding the shortest path on a grid using a 0-1 BFS algorithm.
 */
class GridPathfinder {
    private static final int INF = 1_000_000_000;
    private static final char WALKABLE_CHAR = '.';
    private static final int MOVEMENT_RADIUS = 2;

    private final int rows;
    private final int cols;
    private final char[][] grid;

    public GridPathfinder(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Calculates the shortest distance from start to end point.
     * Uses 0-1 BFS because edge weights are only 0 or 1.
     *
     * @param start The starting Point.
     * @param end   The target Point.
     * @return The shortest distance, or -1 if unreachable.
     */
    public int findShortestPath(Point start, Point end) {
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, INF);
        }

        Deque<Point> deque = new ArrayDeque<>();

        distances[start.row()][start.col()] = 0;
        deque.addFirst(start);

        while (!deque.isEmpty()) {
            Point current = deque.pollFirst();

            // Optimization: if we reached the end, we can't necessarily stop 
            // in 0-1 BFS until the node is polled, but we can check if this is the target.
            if (current.equals(end)) {
                continue; 
            }

            for (int dRow = -MOVEMENT_RADIUS; dRow <= MOVEMENT_RADIUS; dRow++) {
                for (int dCol = -MOVEMENT_RADIUS; dCol <= MOVEMENT_RADIUS; dCol++) {
                    if (dRow == 0 && dCol == 0) continue;

                    int nextRow = current.row() + dRow;
                    int nextCol = current.col() + dCol;

                    if (isValidMove(nextRow, nextCol)) {
                        int moveCost = calculateCost(dRow, dCol);
                        int newDist = distances[current.row()][current.col()] + moveCost;

                        if (newDist < distances[nextRow][nextCol]) {
                            distances[nextRow][nextCol] = newDist;

                            if (moveCost == 0) {
                                deque.addFirst(new Point(nextRow, nextCol));
                            } else {
                                deque.addLast(new Point(nextRow, nextCol));
                            }
                        }
                    }
                }
            }
        }

        int result = distances[end.row()][end.col()];
        return (result == INF) ? -1 : result;
    }

    private boolean isValidMove(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == WALKABLE_CHAR;
    }

    /**
     * Cost is 0 if the cells are adjacent (Manhattan distance 1), 
     * otherwise cost is 1.
     */
    private int calculateCost(int dRow, int dCol) {
        int manhattanDistance = Math.abs(dRow) + Math.abs(dCol);
        return (manhattanDistance == 1) ? 0 : 1;
    }
}

public class Main {
    public static void main(String[] args) {
        try {
            FastReader fr = new FastReader();
            PrintWriter out = new PrintWriter(System.out);

            // Read dimensions
            int n = fr.nextInt();
            int m = fr.nextInt();

            // Read coordinates (converting 1-based to 0-based)
            Point start = new Point(fr.nextInt() - 1, fr.nextInt() - 1);
            Point end = new Point(fr.nextInt() - 1, fr.nextInt() - 1);

            // Read grid
            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = fr.next().toCharArray();
            }

            // Execute pathfinding
            GridPathfinder pathfinder = new GridPathfinder(n, m, grid);
            int shortestPath = pathfinder.findShortestPath(start, end);

            out.println(shortestPath);
            out.flush();
            out.close();

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }
}

