/**
 * A solution to find the shortest path in a grid where:
 * - Moving to an adjacent cell (up, down, left, right) has a cost of 0.
 * - Moving to any cell within a 5x5 window has a cost of 1.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        try {
            // Parsing grid dimensions
            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            // Parsing 1-based coordinates and converting to 0-based
            int startRow = scanner.nextInt() - 1;
            int startCol = scanner.nextInt() - 1;
            int endRow = scanner.nextInt() - 1;
            int endCol = scanner.nextInt() - 1;

            // Parsing the grid
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = scanner.next().toCharArray();
            }

            Pathfinder pathfinder = new Pathfinder(grid, rows, cols);
            int shortestDistance = pathfinder.findShortestPath(startRow, startCol, endRow, endCol);

            System.out.println(shortestDistance);

        } catch (Exception e) {
            // In a real production environment, log the error properly
            // System.err.println("Error processing input: " + e.getMessage());
        } finally {
            scanner.close();
        }
    }

    /**
     * Represents a coordinate in the grid.
     */
    static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Logic for traversing the grid using 0-1 Breadth-First Search.
     */
    static class Pathfinder {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        private static final int[] ROW_OFFSETS = {-1, 1, 0, 0};
        private static final int[] COL_OFFSETS = {0, 0, -1, 1};
        private static final int INF = Integer.MAX_VALUE;

        Pathfinder(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
        }

        public int findShortestPath(int startR, int startC, int endR, int endC) {
            int[][] distances = new int[rows][cols];
            for (int[] row : distances) {
                Arrays.fill(row, INF);
            }

            Deque<Point> deque = new ArrayDeque<>();

            // Initialize starting point
            distances[startR][startC] = 0;
            deque.addFirst(new Point(startR, startC));

            while (!deque.isEmpty()) {
                Point curr = deque.pollFirst();

                // 1. Process 0-weight edges (Adjacent moves)
                for (int i = 0; i < 4; i++) {
                    int nextR = curr.r + ROW_OFFSETS[i];
                    int nextC = curr.c + COL_OFFSETS[i];

                    if (isValid(nextR, nextC) && grid[nextR][nextC] == '.') {
                        if (distances[nextR][nextC] > distances[curr.r][curr.c]) {
                            distances[nextR][nextC] = distances[curr.r][curr.c];
                            // 0-weight edges go to the front of the deque
                            deque.addFirst(new Point(nextR, nextC));
                        }
                    }
                }

                // 2. Process 1-weight edges (5x5 area jumps)
                for (int r = curr.r - 2; r <= curr.r + 2; r++) {
                    for (int c = curr.c - 2; c <= curr.c + 2; c++) {
                        if (isValid(r, c) && grid[r][c] == '.') {
                            if (distances[r][c] > distances[curr.r][curr.c] + 1) {
                                distances[r][c] = distances[curr.r][curr.c] + 1;
                                // 1-weight edges go to the back of the deque
                                deque.addLast(new Point(r, c));
                            }
                        }
                    }
                }
            }

            int result = distances[endR][endC];
            return result == INF ? -1 : result;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }
}

