/**
 * Manages the grid structure and provides movement validation.
 */
class Grid {
    private final char[][] cells;
    private final int height;
    private final int width;

    private static final int[][] WALK_DIRECTIONS = {
        {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };

    Grid(char[][] cells, int height, int width) {
        this.cells = cells;
        this.height = height;
        this.width = width;
    }

    public int getHeight() { return height; }
    public int getWidth() { return width; }

    public boolean isWalkable(int r, int c) {
        return r >= 0 && r < height && c >= 0 && c < width && cells[r][c] == '.';
    }

    public List<Point> getWalkingNeighbors(Point p) {
        List<Point> neighbors = new ArrayList<>();
        for (int[] dir : WALK_DIRECTIONS) {
            int nr = p.row + dir[0];
            int nc = p.col + dir[1];
            if (isWalkable(nr, nc)) {
                neighbors.add(new Point(nr, nc));
            }
        }
        return neighbors;
    }

    public List<Point> getJumpNeighbors(Point p) {
        List<Point> neighbors = new ArrayList<>();
        // A 5x5 area around the point
        for (int dr = -2; dr <= 2; dr++) {
            for (int dc = -2; dc <= 2; dc++) {
                if (dr == 0 && dc == 0) continue;
                int nr = p.row + dr;
                int nc = p.col + dc;
                if (isWalkable(nr, nc)) {
                    neighbors.add(new Point(nr, nc));
                }
            }
        }
        return neighbors;
    }
}

/**
 * Implements the pathfinding algorithm using a multi-phase BFS.
 */
class Pathfinder {
    private final Grid grid;

    Pathfinder(Grid grid) {
        this.grid = grid;
    }

    /**
     * Finds the minimum steps from start to target.
     * Steps are incremented after each "Jump" phase.
     */
    public int findMinimumSteps(Point start, Point target) {
        if (start.equals(target)) return 0;

        Queue<Point> queue = new LinkedList<>();
        boolean[][] visited = new boolean[grid.getHeight()][grid.getWidth()];

        queue.add(start);
        visited[start.row][start.col] = true;

        int steps = 0;

        while (!queue.isEmpty()) {
            // The current level of nodes to process
            List<Point> currentLevel = new ArrayList<>();
            while (!queue.isEmpty()) {
                currentLevel.add(queue.poll());
            }

            // 'jumpSources' includes nodes in the current level AND 
            // nodes discovered during the walk phase (mirroring original logic).
            List<Point> jumpSources = new ArrayList<>(currentLevel);

            // --- Phase 1: Walk Phase (4-direction) ---
            for (Point p : currentLevel) {
                for (Point neighbor : grid.getWalkingNeighbors(p)) {
                    if (!visited[neighbor.row][neighbor.col]) {
                        visited[neighbor.row][neighbor.col] = true;

                        // If destination found during walking, return current steps
                        if (neighbor.equals(target)) return steps;

                        queue.add(neighbor);
                        jumpSources.add(neighbor);
                    }
                }
            }

            // --- Phase 2: Jump Phase (5x5 area) ---
            for (Point source : jumpSources) {
                for (Point jumpNeighbor : grid.getJumpNeighbors(source)) {
                    if (!visited[jumpNeighbor.row][jumpNeighbor.col]) {
                        visited[jumpNeighbor.row][jumpNeighbor.col] = true;
                        queue.add(jumpNeighbor);
                    }
                }
            }

            // Increment steps after the Jump Phase is complete
            steps++;

            // If destination was reached during the Jump Phase, return new step count
            if (visited[target.row][target.col]) {
                return steps;
            }
        }

        return -1;
    }
}

/**
 * Optimized reader for faster input parsing.
