/**
 * A program to find the shortest path in a grid using 0-1 BFS.
 * Moving to an adjacent cell (up, down, left, right) has a cost of 0.
 * Moving to any cell within a 5x5 area has a cost of 1.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            int n = reader.nextInt();
            int m = reader.nextInt();

            // Coordinates are provided 1-indexed in the input
            Point start = new Point(reader.nextInt() - 1, reader.nextInt() - 1);
            Point destination = new Point(reader.nextInt() - 1, reader.nextInt() - 1);

            char[][] grid = new char[n][m];
            for (int i = 0; i < n; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridSolver solver = new GridSolver(n, m, grid);
            int minDistance = solver.findShortestPath(start, destination);

            if (minDistance == Integer.MAX_VALUE) {
                writer.println("-1");
            } else {
                writer.println(minDistance);
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            writer.flush();
            writer.close();
        }
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Handles the grid logic and pathfinding algorithm.
     */
    static class GridSolver {
        private final int rows;
        private final int cols;
        private final char[][] grid;

        // Directions for 0-cost movement (adjacent)
        private static final int[] ROW_ADJACENT = {-1, 1, 0, 0};
        private static final int[] COL_ADJACENT = {0, 0, -1, 1};

        public GridSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        /**
         * Performs a 0-1 BFS to find the shortest path.
         * 
         * @param start The starting point.
         * @param end The destination point.
         * @return The minimum distance, or Integer.MAX_VALUE if unreachable.
         */
        public int findShortestPath(Point start, Point end) {
            int[][] dist = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                Arrays.fill(dist[i], Integer.MAX_VALUE);
            }

            Deque<Point> deque = new ArrayDeque<>();

            // Initial state
            if (isValid(start.row, start.col) && grid[start.row][start.col] != '#') {
                dist[start.row][start.col] = 0;
                deque.addFirst(start);
            }

            while (!deque.isEmpty()) {
                Point current = deque.pollFirst();
                int r = current.row;
                int c = current.col;

                // Optimization: if we reached destination, we can't find a shorter path 
                // for this node because of BFS properties.
                if (r == end.row && c == end.col) {
                    return dist[r][c];
                }

                // 1. Try 0-cost moves (Adjacent neighbors)
                for (int i = 0; i < 4; i++) {
                    int nr = r + ROW_ADJACENT[i];
                    int nc = c + COL_ADJACENT[i];

                    if (isValid(nr, nc) && grid[nr][nc] != '#' && dist[nr][nc] > dist[r][c]) {
                        dist[nr][nc] = dist[r][c];
                        deque.addFirst(new Point(nr, nc));
                    }
                }

                // 2. Try 1-cost moves (5x5 area around the cell)
                for (int dr = -2; dr <= 2; dr++) {
                    for (int dc = -2; dc <= 2; dc++) {
                        int nr = r + dr;
                        int nc = c + dc;

                        if (isValid(nr, nc) && grid[nr][nc] != '#' && dist[nr][nc] > dist[r][c] + 1) {
                            dist[nr][nc] = dist[r][c] + 1;
                            deque.addLast(new Point(nr, nc));
                        }
                    }
                }
            }

            return dist[end.row][end.col];
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Fast I/O utility class.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

