/**
 * A program to find the shortest path between two points in a grid,
 * where movement is allowed between "groups" of connected cells 
 * within a certain proximity.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) return;

        int height = scanner.nextInt();
        int width = scanner.nextInt();
        int startRow = scanner.nextInt() - 1;
        int startCol = scanner.nextInt() - 1;
        int endRow = scanner.nextInt() - 1;
        int endCol = scanner.nextInt() - 1;

        char[][] board = new char[height][width];
        for (int i = 0; i < height; i++) {
            board[i] = scanner.next().toCharArray();
        }

        Grid grid = new Grid(board, height, width);
        ComponentFinder componentFinder = new ComponentFinder(grid);
        ComponentMap componentMap = componentFinder.findComponents();

        int startGroupId = componentMap.getGroupId(startRow, startCol);
        int endGroupId = componentMap.getGroupId(endRow, endCol);

        // If start and end are in the same group, distance is 0
        if (startGroupId != 0 && startGroupId == endGroupId) {
            System.out.println(0);
            return;
        }

        // If start or end is a wall, no path exists
        if (startGroupId == 0 || endGroupId == 0) {
            System.out.println(-1);
            return;
        }

        GraphBuilder graphBuilder = new GraphBuilder(grid, componentMap);
        Graph componentGraph = graphBuilder.build();

        Pathfinder pathfinder = new Pathfinder(componentGraph);
        int distance = pathfinder.findShortestPath(startGroupId, endGroupId);

        System.out.println(distance);
    }
}

/**
 * Represents the grid structure.
 */
class Grid {
    private final char[][] cells;
    private final int height;
    private final int width;

    public Grid(char[][] cells, int height, int width) {
        this.cells = cells;
        this.height = height;
        this.width = width;
    }

    public boolean isWalkable(int r, int c) {
        return r >= 0 && r < height && c >= 0 && c < width && cells[r][c] == '.';
    }

    public boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < height && c >= 0 && c < width;
    }

    public int getHeight() { return height; }
    public int getWidth() { return width; }
}

/**
 * Stores the mapping of grid coordinates to component IDs.
 */
class ComponentMap {
    private final int[][] groupIds;
    private final int totalGroups;

    public ComponentMap(int[][] groupIds, int totalGroups) {
        this.groupIds = groupIds;
        this.totalGroups = totalGroups;
    }

    public int getGroupId(int r, int c) {
        return groupIds[r][c];
    }

    public int getTotalGroups() {
        return totalGroups;
    }
}

/**
 * Handles the identification of connected components (groups) using BFS.
 */
class ComponentFinder {
    private final Grid grid;
    private static final int[] ROW_OFFSETS = {1, 0, -1, 0};
    private static final int[] COL_OFFSETS = {0, 1, 0, -1};

    public ComponentFinder(Grid grid) {
        this.grid = grid;
    }

    public ComponentMap findComponents() {
        int h = grid.getHeight();
        int w = grid.getWidth();
        int[][] groupIds = new int[h][w];
        int currentGroupId = 1;

        for (int r = 0; r < h; r++) {
            for (int c = 0; c < w; c++) {
                if (grid.isWalkable(r, c) && groupIds[r][c] == 0) {
                    bfs(r, c, currentGroupId, groupIds);
                    currentGroupId++;
                }
            }
        }
        return new ComponentMap(groupIds, currentGroupId - 1);
    }

    private void bfs(int startR, int startC, int groupId, int[][] groupIds) {
        Queue<Point> queue = new ArrayDeque<>();
        groupIds[startR][startC] = groupId;
        queue.add(new Point(startR, startC));

        while (!queue.isEmpty()) {
            Point curr = queue.poll();

            for (int i = 0; i < 4; i++) {
                int nextR = curr.row + ROW_OFFSETS[i];
                int nextC = curr.col + COL_OFFSETS[i];

                if (grid.isWalkable(nextR, nextC) && groupIds[nextR][nextC] == 0) {
                    groupIds[nextR][nextC] = groupId;
                    queue.add(new Point(nextR, nextC));
                }
            }
        }
    }
}

/**
 * Builds a graph where each node is a component.
 */
class GraphBuilder {
    private final Grid grid;
    private final ComponentMap componentMap;
    private static final int PROXIMITY_RANGE = 2;

    public GraphBuilder(Grid grid, ComponentMap componentMap) {
        this.grid = grid;
        this.componentMap = componentMap;
    }

    public Graph build() {
        int numGroups = componentMap.getTotalGroups();
        List<Edge>[] adjacencyList = new ArrayList[numGroups + 1];
        for (int i = 0; i <= numGroups; i++) {
            adjacencyList[i] = new ArrayList<>();
        }

        // To avoid duplicate edges between the same two groups efficiently
        Set<Long> seenEdges = new HashSet<>();

        for (int r = 0; r < grid.getHeight(); r++) {
            for (int c = 0; c < grid.getWidth(); c++) {
                int currentGroup = componentMap.getGroupId(r, c);
                if (currentGroup == 0) continue;

                // Check 5x5 neighborhood
                for (int dr = -PROXIMITY_RANGE; dr <= PROXIMITY_RANGE; dr++) {
                    for (int dc = -PROXIMITY_RANGE; dc <= PROXIMITY_RANGE; dc++) {
                        int nr = r + dr;
                        int nc = c + dc;

                        if (grid.isWithinBounds(nr, nc) && grid.isWalkable(nr, nc)) {
                            int neighborGroup = componentMap.getGroupId(nr, nc);

                            if (neighborGroup != 0 && neighborGroup != currentGroup) {
                                // Use a bit-packed long to represent a unique undirected edge {min, max}
                                long edgeKey = getEdgeKey(currentGroup, neighborGroup);
                                if (seenEdges.add(edgeKey)) {
                                    adjacencyList[currentGroup].add(new Edge(neighborGroup, 1));
                                    adjacencyList[neighborGroup].add(new Edge(currentGroup, 1));
                                }
                            }
                        }
                    }
                }
            }
        }
        return new Graph(adjacencyList, numGroups);
    }

    private long getEdgeKey(int g1, int g2) {
        int min = Math.min(g1, g2);
        int max = Math.max(g1, g2);
        return ((long) min << 32) | (max & 0xFFFFFFFFL);
    }
}

class Graph {
    final List<Edge>[] adjacencyList;
    final int nodeCount;

    Graph(List<Edge>[] adjacencyList, int nodeCount) {
        this.adjacencyList = adjacencyList;
        this.nodeCount = nodeCount;
    }
}

/**
 * Implements Dijkstra's algorithm to find the shortest path in the component graph.
 */
class Pathfinder {
    private final Graph graph;
    private static final int INF = Integer.MAX_VALUE;

    public Pathfinder(Graph graph) {
        this.graph = graph;
    }

    public int findShortestPath(int startId, int endId) {
        int[] distances = new int[graph.nodeCount + 1];
        Arrays.fill(distances, INF);
        distances[startId] = 0;

        PriorityQueue<NodeDistance> pq = new PriorityQueue<>();
        pq.add(new NodeDistance(0, startId));

        while (!pq.isEmpty()) {
            NodeDistance current = pq.poll();

            if (current.distance > distances[current.nodeId]) continue;
            if (current.nodeId == endId) return current.distance;

            for (Edge edge : graph.adjacencyList[current.nodeId]) {
                if (distances[edge.to] > distances[current.nodeId] + edge.cost) {
                    distances[edge.to] = distances[current.nodeId] + edge.cost;
                    pq.add(new NodeDistance(distances[edge.to], edge.to));
                }
            }
        }

        return distances[endId] == INF ? -1 : distances[endId];
    }
}

class Point {
    final int row;
    final int col;

    Point(int row, int col) {
        this.row = row;
        this.col = col;
    }
}

class Edge {
    final int to;
    final int cost;

    Edge(int to, int cost) {
        this.to = to;
        this.cost = cost;
    }
}

class NodeDistance implements Comparable<NodeDistance> {
    final int distance;
    final int nodeId;

    NodeDistance(int distance, int nodeId) {
        this.distance = distance;
        this.nodeId = nodeId;
    }

    @Override
    public int compareTo(NodeDistance other) {
        return Integer.compare(this.distance, other.distance);
    }
}

