        private final char[][] grid;
        private static final long INF = Long.MAX_VALUE;

        // 4-directional movement offsets (Weight 0)
        private static final int[] DR4 = {-1, 1, 0, 0};
        private static final int[] DC4 = {0, 0, -1, 1};

        public GridSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        /**
         * Finds the shortest path using 0-1 BFS.
         * 
         * @return the shortest distance, or -1 if no path exists.
         */
        public long findShortestPath(int startR, int startC, int endR, int endC) {
            // Validate start and end points
            if (!isValid(startR, startC) || !isValid(endR, endC) || 
                grid[startR][startC] != '.' || grid[endR][endC] != '.') {
                return -1;
            }

            long[][] dist = new long[rows][cols];
            for (int i = 0; i < rows; i++) {
                Arrays.fill(dist[i], INF);
            }

            Deque<Node> deque = new ArrayDeque<>();

            // Initialize starting position
            dist[startR][startC] = 0;
            deque.addFirst(new Node(startR, startC));

            while (!deque.isEmpty()) {
                Node current = deque.pollFirst();
                int r = current.r;
                int c = current.c;

                // Target reached
                if (r == endR && c == endC) {
                    return dist[r][c];
                }

                // 1. Explore adjacent neighbors (Weight 0)
                for (int i = 0; i < 4; i++) {
                    int nr = r + DR4[i];
                    int nc = c + DC4[i];

                    if (isValid(nr, nc) && grid[nr][nc] == '.' && dist[nr][nc] > dist[r][c]) {
                        dist[nr][nc] = dist[r][c];
                        deque.addFirst(new Node(nr, nc));
                    }
                }

                // 2. Explore 5x5 jump neighborhood (Weight 1)
                for (int dr = -2; dr <= 2; dr++) {
                    for (int dc = -2; dc <= 2; dc++) {
                        if (dr == 0 && dc == 0) continue; // Skip self

                        int nr = r + dr;
                        int nc = c + dc;

                        if (isValid(nr, nc) && grid[nr][nc] == '.' && dist[nr][nc] > dist[r][c] + 1) {
                            dist[nr][nc] = dist[r][c] + 1;
                            deque.addLast(new Node(nr, nc));
                        }
                    }
                }
            }

            return dist[endR][endC] == INF ? -1 : dist[endR][endC];
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Efficient input reader for large datasets.
     */
    static class FastReader {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastReader(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * Represents a coordinate in the maze grid.
 */
record Point(int row, int col) {}

/**
 * Encapsulates the maze grid and boundary/path validation logic.
 */
class Maze {
    private final int rows;
    private final int cols;
    private final boolean[][] grid;

    public Maze(int rows, int cols, boolean[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    public boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public boolean isPath(int r, int c) {
        return isValid(r, c) && grid[r][c];
    }

    public int getRows() { return rows; }
    public int getCols() { return cols; }
}

/**
 * Handles the pathfinding logic using a multi-level Breadth-First Search.
 */
class MazeSolver {
    private final Maze maze;
    private final Point goal;

    public MazeSolver(Maze maze, Point goal) {
        this.maze = maze;
        this.goal = goal;
    }

    /**
     * Solves the maze finding the minimum number of "warps".
     * 
     * @param start The starting point.
     * @return Minimum warps to reach the goal, or -1 if unreachable.
     */
    public int solve(Point start) {
        if (start.equals(goal)) return 0;
        if (!maze.isPath(start.row(), start.col())) return -1;

        boolean[][] visited = new boolean[maze.getRows()][maze.getCols()];
        Queue<Point> queue = new ArrayDeque<>();

        queue.add(start);
        visited[start.row()][start.col()] = true;

        int warpCount = 0;

        while (!queue.isEmpty()) {
            // 1. Standard BFS Stage: Expand using 4-connectivity (Up, Down, Left, Right)
            Queue<Point> frontArea = new ArrayDeque<>();

            // We process the current 'level' of the BFS
            while (!queue.isEmpty()) {
                Point current = queue.poll();
                frontArea.add(current);

                for (Point neighbor : getNeighbors4(current)) {
                    if (maze.isPath(neighbor.row(), neighbor.col()) && !visited[neighbor.row()][neighbor.col()]) {
                        visited[neighbor.row()][neighbor.col()] = true;
                        if (neighbor.equals(goal)) return warpCount;
                        queue.add(neighbor);
                    }
                }
            }

            // 2. Warp Stage: Expand from the reached points using a 5x5 area
            warpCount++;
            while (!frontArea.isEmpty()) {
                Point current = frontArea.poll();

                // Based on original logic, we only warp from cells that are part of a valid path
                if (maze.isPath(current.row(), current.col())) {
                    for (int dr = -2; dr <= 2; dr++) {
                        for (int dc = -2; dc <= 2; dc++) {
                            int nr = current.row() + dr;
                            int nc = current.col() + dc;
                            Point neighbor = new Point(nr, nc);

                            if (maze.isPath(nr, nc) && !visited[nr][nc]) {
                                visited[nr][nc] = true;
                                if (neighbor.equals(goal)) return warpCount;
                                queue.add(neighbor);
                            }
                        }
                    }
                }
            }

            // If the queue is empty after both stages, the goal is unreachable
            if (queue.isEmpty()) break;
        }

        return -1;
    }

    private List<Point> getNeighbors4(Point p) {
        return List.of(
            new Point(p.row() - 1, p.col()),
            new Point(p.row() + 1, p.col()),
            new Point(p.row(), p.col() - 1),
            new Point(p.row(), p.col() + 1)
        );
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) return;

        int h = sc.nextInt(); // Rows
        int w = sc.nextInt(); // Cols

        // Original input format: startY, startX (1-based)
        int startY = sc.nextInt();
        int startX = sc.nextInt();

        // Original input format: goalY, goalX (1-based)
        int goalY = sc.nextInt();
        int goalX = sc.nextInt();

        boolean[][] grid = new boolean[h][w];
        for (int i = 0; i < h; i++) {
            String line = sc.next();
            for (int j = 0; j < w; j++) {
                grid[i][j] = (line.charAt(j) == '.');
            }
        }

        // Convert 1-based input to 0-based internal coordinates
        // Note: Mapping input logic to row/col: startY/goalY are rows, startX/goalX are cols.
        Point start = new Point(startY - 1, startX - 1);
        Point goal = new Point(goalY - 1, goalX - 1);

        Maze maze = new Maze(h, w, grid);
        MazeSolver solver = new MazeSolver(maze, goal);

        System.out.println(solver.solve(start));
        sc.close();
    }
}

