/**
 * A solver that finds the minimum number of "jumps" required to travel 
 * between components in a grid.
 */
public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();
            int startRow = reader.nextInt() - 1;
            int startCol = reader.nextInt() - 1;
            int endRow = reader.nextInt() - 1;
            int endCol = reader.nextInt() - 1;

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
