/**
 * Represents a coordinate in the grid.
 */
record Point(int r, int c) {}

/**
 * Handles the core logic of navigating the grid.
 */
class GridSolver {
    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int startRow, startCol, endRow, endCol;
    private final boolean[][] visited;

    private static final int[][] DIRECTIONS = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};
    private static final int JUMP_RANGE = 2;

    public GridSolver(int rows, int cols, char[][] grid, int startRow, int startCol, int endRow, int endCol) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.startRow = startRow;
        this.startCol = startCol;
        this.endRow = endRow;
        this.endCol = endCol;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Executes the BFS-based jump algorithm.
     * @return The minimum number of jumps, or -1 if unreachable.
     */
    public int solve() {
        if (grid[startRow][startCol] != '.' || grid[endRow][endCol] != '.') {
            return -1;
        }

        Deque<Point> currentFrontier = new ArrayDeque<>();
        int jumpCount = 0;

        // Initial exploration: find the first connected component
        exploreComponent(startRow, startCol, currentFrontier);

        while (!visited[endRow][endCol]) {
            jumpCount++;
            Deque<Point> nextFrontier = new ArrayDeque<>();

            // Try to jump from every cell in the current component to a new component
            for (Point p : currentFrontier) {
                expandFrontier(p, nextFrontier);
            }

            if (nextFrontier.isEmpty()) {
                return -1;
            }

            currentFrontier = nextFrontier;
        }

        return jumpCount;
    }

    /**
     * Standard BFS to find all connected '.' cells in a component.
     */
    private void exploreComponent(int r, int c, Deque<Point> frontier) {
        Queue<Point> queue = new LinkedList<>();
        Point start = new Point(r, c);

        queue.add(start);
        frontier.add(start);
        visited[r][c] = true;

        while (!queue.isEmpty()) {
            Point curr = queue.poll();

            for (int[] dir : DIRECTIONS) {
                int nr = curr.r() + dir[0];
                int nc = curr.c() + dir[1];

                if (isValid(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    Point next = new Point(nr, nc);
                    queue.add(next);
                    frontier.add(next);
                }
            }
        }
    }

    /**
     * Checks a 5x5 area around a point to find new components to jump to.
     */
    private void expandFrontier(Point p, Deque<Point> nextFrontier) {
        for (int i = Math.max(0, p.r() - JUMP_RANGE); i <= Math.min(rows - 1, p.r() + JUMP_RANGE); i++) {
            for (int j = Math.max(0, p.c() - JUMP_RANGE); j <= Math.min(cols - 1, p.c() + JUMP_RANGE); j++) {
                if (grid[i][j] == '.' && !visited[i][j]) {
                    exploreComponent(i, j, nextFrontier);
                }
            }
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

/**
 * Optimized reader for fast I/O operations.
 */
class FastReader {
    private final InputStream stream;
    private final byte[] buffer = new byte[1024];
    private int curChar;
    private int numChars;

    public FastReader(InputStream stream) {
        this.stream = stream;
    }

    private int read() throws IOException {
        if (numChars == -1) throw new InputMismatchException();
        if (curChar >= numChars) {
            curChar = 0;
            numChars = stream.read(buffer);
            if (numChars <= 0) return -1;
        }
        return buffer[curChar++];
    }

    public int nextInt() throws IOException {
        int c = read();
        while (isSpaceChar(c)) c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9') throw new InputMismatchException();
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public String next() throws IOException {
        int c = read();
        while (isSpaceChar(c)) c = read();
        StringBuilder res = new StringBuilder();
        do {
            res.appendCodePoint(c);
            c = read();
        } while (!isSpaceChar(c));
        return res.toString();
    }

    private boolean isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }
}

import java.util.*;
import java.io.*;

/**
 * Represents a cell in the grid during pathfinding.
 */
class Node {
    final int row;
    final int col;
    final int distance;

    Node(int row, int col, int distance) {
        this.row = row;
        this.col = col;
        this.distance = distance;
    }
}

/**
 * Manages the grid layout and provides spatial queries.
 */
class Grid {
    private final int height;
    private final int width;
    private final boolean[][] walkable;

    public Grid(int height, int width, List<String> lines) {
        this.height = height;
        this.width = width;
        this.walkable = new boolean[height][width];
        for (int i = 0; i < height; i++) {
            String line = lines.get(i);
            for (int j = 0; j < width; j++) {
                walkable[i][j] = (line.charAt(j) == '.');
            }
        }
    }

    public boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < height && c >= 0 && c < width;
    }

    public boolean isWalkable(int r, int c) {
        return isWithinBounds(r, c) && walkable[r][c];
    }

    public int getHeight() { return height; }
    public int getWidth() { return width; }
}

/**
 * Implements the 0-1 BFS algorithm to find the shortest path.
 */
class Pathfinder {
    private final Grid grid;
    private final int[][] distances;
    private boolean targetReached = false;

    private static final int[][] ADJACENT_DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    public Pathfinder(Grid grid) {
        this.grid = grid;
        this.distances = new int[grid.getHeight()][grid.getWidth()];
        for (int[] row : distances) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }
    }

    public void findShortestPath(int startR, int startC, int targetR, int targetC) {
        Deque<Node> deque = new ArrayDeque<>();

        distances[startR][startC] = 0;
        deque.addFirst(new Node(startR, startC, 0));

        while (!deque.isEmpty()) {
            Node current = deque.pollFirst();

            // If we found a better path to this node already, skip processing
            if (current.distance > distances[current.row][current.col]) {
                continue;
            }

            if (current.row == targetR && current.col == targetC) {
                targetReached = true;
                return;
            }

            // 1. Adjacent Moves (Weight 0)
            for (int[] dir : ADJACENT_DIRECTIONS) {
                int nr = current.row + dir[0];
                int nc = current.col + dir[1];

                if (grid.isWalkable(nr, nc) && distances[nr][nc] > current.distance) {
                    distances[nr][nc] = current.distance;
                    deque.addFirst(new Node(nr, nc, current.distance));
                }
            }

            // 2. Warp Moves (Weight 1)
            for (Node warp : getValidWarps(current)) {
                if (distances[warp.row][warp.col] > warp.distance) {
                    distances[warp.row][warp.col] = warp.distance;
                    deque.addLast(warp);
                }
            }
        }
    }

    private List<Node> getValidWarps(Node current) {
        List<Node> warps = new ArrayList<>();
        int r = current.row;
        int c = current.col;
        int nextDist = current.distance + 1;

        // Iterate through a 5x5 area around the current cell
        for (int dr = -2; dr <= 2; dr++) {
            for (int dc = -2; dc <= 2; dc++) {
                int nr = r + dr;
                int nc = c + dc;

                if (!grid.isWalkable(nr, nc)) continue;

                boolean isValidWarp = false;
                if (dr == 0 && Math.abs(dc) == 2) {
                    isValidWarp = true; // Horizontal jump
                } else if (Math.abs(dr) == 1 && dc != 0) {
                    isValidWarp = true; // Diagonal/offset jump
                } else if (Math.abs(dr) == 2) {
                    isValidWarp = true; // Vertical/wide jump
                }

                if (isValidWarp) {
                    warps.add(new Node(nr, nc, nextDist));
                }
            }
        }
        return warps;
    }

    public int getDistanceAt(int r, int c) {
        int d = distances[r][c];
        return (targetReached && d != Integer.MAX_VALUE) ? d : -1;
    }

    public boolean isTargetReached() {
        return targetReached;
    }
}

public class Main {
    public static void main(String[] args) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(System.in))) {
            String line1 = reader.readLine();
            if (line1 == null) return;
            String[] dims = line1.split(" ");
            int H = Integer.parseInt(dims[0]);
            int W = Integer.parseInt(dims[1]);

            String[] startCoords = reader.readLine().split(" ");
            int startR = Integer.parseInt(startCoords[0]) - 1;
            int startC = Integer.parseInt(startCoords[1]) - 1;

            String[] targetCoords = reader.readLine().split(" ");
            int targetR = Integer.parseInt(targetCoords[0]) - 1;
            int targetC = Integer.parseInt(targetCoords[1]) - 1;

            List<String> mapLines = new ArrayList<>(H);
            for (int i = 0; i < H; i++) {
                mapLines.add(reader.readLine());
            }

            Grid grid = new Grid(H, W, mapLines);
            Pathfinder pathfinder = new Pathfinder(grid);
            pathfinder.findShortestPath(startR, startC, targetR, targetC);

            if (pathfinder.isTargetReached()) {
                System.out.println(pathfinder.getDistanceAt(targetR, targetC));
            } else {
                System.out.println("-1");
            }

        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * Refactored solution for finding the shortest path between connected components in a grid.
 * The algorithm groups connected '.' cells into components using Union-Find,
 * then performs a BFS on these components based on a 5x5 proximity rule.
 */
public class Main {

    public static void main(String[] args) {
        try {
            Solver solver = new Solver();
            solver.solve();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    static class Solver {
        public void solve() throws IOException {
            FastReader fr = new FastReader(System.in);
            PrintWriter out = new PrintWriter(System.out);

            int height = fr.nextInt();
            int width = fr.nextInt();
            int startRow = fr.nextInt() - 1;
            int startCol = fr.nextInt() - 1;
            int destRow = fr.nextInt() - 1;
            int destCol = fr.nextInt() - 1;

            char[][] grid = new char[height][width];
            for (int i = 0; i < height; i++) {
                grid[i] = fr.next().toCharArray();
            }

            // Edge case: start or destination is a wall
            if (grid[startRow][startCol] == '#' || grid[destRow][destCol] == '#') {
                out.println("-1");
                out.flush();
                return;
            }

            // Step 1: Group connected '.' cells into components using Union-Find
            UnionFind uf = new UnionFind(height * width);
            for (int r = 0; r < height; r++) {
                for (int c = 0; c < width; c++) {
                    if (grid[r][c] == '.') {
                        // Check adjacent cells (right and down) to union components
                        if (c + 1 < width && grid[r][c + 1] == '.') {
                            uf.union(r * width + c, r * width + (c + 1));
                        }
                        if (r + 1 < height && grid[r + 1][c] == '.') {
                            uf.union(r * width + c, (r + 1) * width + c);
                        }
                    }
                }
            }

            // Step 2: Efficiently store which cells belong to which component
            // Using a flat array (allCells) and offsets to save memory vs List<Integer>[]
            int[] componentCellCounts = new int[height * width];
            for (int i = 0; i < height * width; i++) {
                if (grid[i / width][i % width] == '.') {
                    componentCellCounts[uf.find(i)]++;
                }
            }

            int[] componentOffsets = new int[height * width + 1];
            for (int i = 0; i < height * width; i++) {
                componentOffsets[i + 1] = componentOffsets[i] + componentCellCounts[i];
            }

            int[] allCells = new int[height * width];
            int[] currentOffsetTracker = Arrays.copyOf(componentOffsets, height * width + 1);
            for (int i = 0; i < height * width; i++) {
                if (grid[i / width][i % width] == '.') {
                    int root = uf.find(i);
                    allCells[currentOffsetTracker[root]++] = i;
                }
            }

            // Step 3: BFS on the components
            int startComp = uf.find(startRow * width + startCol);
            int destComp = uf.find(destRow * width + destCol);
            int[] dist = new int[height * width];
            Arrays.fill(dist, -1);

            Queue<Integer> queue = new ArrayDeque<>();
            queue.add(startComp);
            dist[startComp] = 0;

            while (!queue.isEmpty()) {
                int u = queue.poll();
                if (u == destComp) break;

                // For every cell in component 'u', check its 5x5 neighborhood
                for (int i = componentOffsets[u]; i < componentOffsets[u + 1]; i++) {
                    int cellIdx = allCells[i];
                    int r = cellIdx / width;
                    int c = cellIdx % width;

                    for (int dr = -2; dr <= 2; dr++) {
                        for (int dc = -2; dc <= 2; dc++) {
                            int nr = r + dr;
                            int nc = c + dc;

                            if (nr >= 0 && nr < height && nc >= 0 && nc < width && grid[nr][nc] == '.') {
                                int v = uf.find(nr * width + nc);
                                if (v != u && dist[v] == -1) {
                                    dist[v] = dist[u] + 1;
                                    queue.add(v);
                                }
                            }
                        }
                    }
                }
            }

            out.println(dist[destComp]);
            out.flush();
        }
    }

    static class UnionFind {
        private final int[] parent;
        private final int[] rank;

        public UnionFind(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        public int find(int i) {
            if (parent[i] == i) return i;
            return parent[i] = find(parent[i]); // Path compression
        }

        public void union(int i, int j) {
            int rootI = find(i);
            int rootJ = find(j);
            if (rootI != rootJ) {
                // Union by rank
                if (rank[rootI] < rank[rootJ]) {
                    parent[rootI] = rootJ;
                } else if (rank[rootI] > rank[rootJ]) {
                    parent[rootJ] = rootI;
                } else {
                    parent[rootI] = rootJ;
                    rank[rootJ]++;
                }
            }
        }
    }

    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;

/**
 * A program to find the shortest path between two points in a maze
 * by treating connected components of traversable space as graph nodes.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNextInt()) return;

        int height = scanner.nextInt();
        int width = scanner.nextInt();

        int startRow = scanner.nextInt() - 1;
        int startCol = scanner.nextInt() - 1;

        int targetRow = scanner.nextInt() - 1;
        int targetCol = scanner.nextInt() - 1;

        String[] mazeGrid = new String[height];
        for (int i = 0; i < height; i++) {
            mazeGrid[i] = scanner.next();
        }

        MazeSolver solver = new MazeSolver(height, width, mazeGrid);
        int result = solver.solve(startRow, startCol, targetRow, targetCol);
        System.out.println(result);
    }

    private static class MazeSolver {
        private final int height;
        private final int width;
        private final String[] maze;

        // Directions for 4-way connectivity (Up, Down, Left, Right)
        private static final int[] ROW_OFFSETS = {-1, 1, 0, 0};
        private static final int[] COL_OFFSETS = {0, 0, -1, 1};

        public MazeSolver(int height, int width, String[] maze) {
            this.height = height;
            this.width = width;
            this.maze = maze;
        }

        /**
         * Represents a coordinate in the grid.
         */
        private static class Point {
            final int r, c;
            Point(int r, int c) {
                this.r = r;
                this.c = c;
            }
        }

        /**
         * Represents the state of a BFS traversal through component nodes.
         */
        private static class TraversalState {
            final int componentId;
            final int distance;

            TraversalState(int componentId, int distance) {
                this.componentId = componentId;
                this.distance = distance;
            }
        }

        public int solve(int startRow, int startCol, int targetRow, int targetCol) {
            int[][] componentMap = identifyComponents();

            int startComponent = componentMap[startRow][startCol];
            int targetComponent = componentMap[targetRow][targetCol];

            // If start or end is a wall, or components cannot be identified
            if (startComponent == 0 || targetComponent == 0) {
                // Original logic: if they are on the same wall, return 0, 
                // but based on component logic, we return -1 if they aren't valid components.
                return (startRow == targetRow && startCol == targetCol) ? 0 : -1;
            }

            Map<Integer, Set<Integer>> adjacencyList = buildComponentGraph(componentMap);
            return findShortestPath(startComponent, targetComponent, adjacencyList);
        }

        /**
         * Phase 1: Identify connected components of '.' cells using Flood Fill (BFS).
         */
        private int[][] identifyComponents() {
            int[][] componentMap = new int[height][width];
            int currentComponentId = 0;

            for (int i = 0; i < height; i++) {
                for (int j = 0; j < width; j++) {
                    if (maze[i].charAt(j) == '.' && componentMap[i][j] == 0) {
                        currentComponentId++;
                        floodFill(i, j, currentComponentId, componentMap);
                    }
                }
            }
            return componentMap;
        }

        private void floodFill(int startR, int startC, int id, int[][] componentMap) {
            Deque<Point> queue = new ArrayDeque<>();
            queue.add(new Point(startR, startC));
            componentMap[startR][startC] = id;

            while (!queue.isEmpty()) {
                Point curr = queue.poll();

                for (int i = 0; i < 4; i++) {
                    int nr = curr.r + ROW_OFFSETS[i];
                    int nc = curr.c + COL_OFFSETS[i];

                    if (isValid(nr, nc) && maze[nr].charAt(nc) == '.' && componentMap[nr][nc] == 0) {
                        componentMap[nr][nc] = id;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
        }

        /**
         * Phase 2: Build a graph where each node is a component ID.
         * An edge exists if two components have cells in close proximity.
         */
        private Map<Integer, Set<Integer>> buildComponentGraph(int[][] componentMap) {
            Map<Integer, Set<Integer>> adjacencyList = new HashMap<>();

            for (int i = 0; i < height; i++) {
                for (int j = 0; j < width; j++) {
                    if (maze[i].charAt(j) == '#') continue;

                    int currentComp = componentMap[i][j];

                    // Look in the specific window defined in the original algorithm
                    for (int h = i; h <= Math.min(i + 2, height - 1); h++) {
                        for (int w = Math.max(0, j - 2); w <= Math.min(j + 2, width - 1); w++) {
                            if (maze[h].charAt(w) == '#') continue;

                            int neighborComp = componentMap[h][w];
                            if (neighborComp != 0 && neighborComp != currentComp) {
                                adjacencyList.computeIfAbsent(currentComp, k -> new HashSet<>()).add(neighborComp);
                                adjacencyList.computeIfAbsent(neighborComp, k -> new HashSet<>()).add(currentComp);
                            }
                        }
                    }
                }
            }
            return adjacencyList;
        }

        /**
         * Phase 3: Perform BFS on the component graph to find the shortest path.
         */
        private int findShortestPath(int startId, int targetId, Map<Integer, Set<Integer>> adj) {
            if (startId == targetId) return 0;

            Deque<TraversalState> queue = new ArrayDeque<>();
            queue.add(new TraversalState(startId, 0));

            Set<Integer> visited = new HashSet<>();
            visited.add(startId);

            while (!queue.isEmpty()) {
                TraversalState current = queue.poll();

                if (current.componentId == targetId) {
                    return current.distance;
                }

                Set<Integer> neighbors = adj.getOrDefault(current.componentId, Collections.emptySet());
                for (int neighborId : neighbors) {
                    if (!visited.contains(neighborId)) {
                        visited.add(neighborId);
                        queue.add(new TraversalState(neighborId, current.distance + 1));
                    }
                }
            }

            return -1;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < height && c >= 0 && c < width;
        }
    }
}

