 */
class Node implements Comparable<Node> {
    final int row;
    final int col;
    final int distance;

    Node(int row, int col, int distance) {
        this.row = row;
        this.col = col;
        this.distance = distance;
    }

    @Override
    public int compareTo(Node other) {
        return Integer.compare(this.distance, other.distance);
    }
}

/**
 * Handles the pathfinding logic using Dijkstra's algorithm.
 */
class GridPathfinder {
    private static final int INF = Integer.MAX_VALUE;
    private static final int[] VERTICAL_DIR = {1, 0, -1, 0};
    private static final int[] HORIZONTAL_DIR = {0, 1, 0, -1};

    private final int height;
    private final int width;
    private final char[][] grid;

    public GridPathfinder(int height, int width, char[][] grid) {
        this.height = height;
        this.width = width;
        this.grid = grid;
    }

    /**
     * Finds the shortest path from start to goal.
     * 
     * @param startRow Starting row index
     * @param startCol Starting column index
     * @param goalRow  Goal row index
     * @param goalCol  Goal column index
     * @return The minimum distance, or -1 if unreachable.
     */
    public int findShortestPath(int startRow, int startCol, int goalRow, int goalCol) {
        int[][] minDistance = new int[height][width];
        for (int[] row : minDistance) {
            Arrays.fill(row, INF);
        }

        PriorityQueue<Node> priorityQueue = new PriorityQueue<>();

        minDistance[startRow][startCol] = 0;
        priorityQueue.add(new Node(startRow, startCol, 0));

        while (!priorityQueue.isEmpty()) {
            Node current = priorityQueue.poll();

            // If we found a shorter way to this node already, skip processing
            if (current.distance > minDistance[current.row][current.col]) {
                continue;
            }

            // If we reached the destination, we can return early in Dijkstra
            if (current.row == goalRow && current.col == goalCol) {
                return current.distance;
            }

            // Type 1: Orthogonal movement (cost 0)
            processMovement(current, 0, priorityQueue, minDistance);

            // Type 2: 5x5 area movement (cost 1)
            processAreaMovement(current, priorityQueue, minDistance);
        }

        return minDistance[goalRow][goalCol] == INF ? -1 : minDistance[goalRow][goalCol];
    }

    private void processMovement(Node current, int costIncrement, PriorityQueue<Node> pq, int[][] minDistance) {
        for (int i = 0; i < 4; i++) {
            int nextRow = current.row + VERTICAL_DIR[i];
            int nextCol = current.col + HORIZONTAL_DIR[i];

            updateIfBetter(current, nextRow, nextCol, costIncrement, pq, minDistance);
        }
    }

    private void processAreaMovement(Node current, PriorityQueue<Node> pq, int[][] minDistance) {
        for (int i = -2; i <= 2; i++) {
            for (int j = -2; j <= 2; j++) {
                // Skip the current cell as cost 0 movement is handled separately
                if (i == 0 && j == 0) continue;

                int nextRow = current.row + i;
                int nextCol = current.col + j;

                updateIfBetter(current, nextRow, nextCol, 1, pq, minDistance);
            }
        }
    }

    private void updateIfBetter(Node current, int nr, int nc, int costInc, PriorityQueue<Node> pq, int[][] minDistance) {
        if (isValid(nr, nc) && grid[nr][nc] == '.') {
            int nextDist = current.distance + costInc;
            if (nextDist < minDistance[nr][nc]) {
                minDistance[nr][nc] = nextDist;
                pq.add(new Node(nr, nc, nextDist));
            }
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < height && c >= 0 && c < width;
    }
}

