/**
 * Represents a point in the grid with its associated distance from the start.
 */
record Node(int row, int col, int distance) {}

/**
 * Handles the logic for finding the shortest path in a grid with specific movement rules.
 */
class GridPathfinder {
    private static final int[][] CARDINAL_DIRECTIONS = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};
    private static final int JUMP_RANGE = 2;

    private final int rows;
    private final int cols;
    private final char[][] grid;
    private final int startRow;
    private final int startCol;
    private final int endRow;
    private final int endCol;

    public GridPathfinder(int rows, int cols, char[][] grid, int startRow, int startCol, int endRow, int endCol) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
        this.startRow = startRow;
        this.startCol = startCol;
        this.endRow = endRow;
        this.endCol = endCol;
    }

    /**
     * Finds the shortest path using 0-1 Breadth-First Search.
     * Cardinal moves have cost 0, while jumps within a 5x5 area have cost 1.
     * 
     * @return The minimum distance to the destination, or -1 if unreachable.
     */
    public int findShortestPath() {
        if (grid[startRow][startCol] == '#' || grid[endRow][endCol] == '#') {
            return -1;
        }

        Deque<Node> deque = new ArrayDeque<>();
        int[][] minDistance = new int[rows][cols];
        for (int[] row : minDistance) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }

        deque.addFirst(new Node(startRow, startCol, 0));
        minDistance[startRow][startCol] = 0;

        while (!deque.isEmpty()) {
            Node current = deque.pollFirst();

            if (current.row() == endRow && current.col() == endCol) {
                return current.distance();
            }

            // If we found a shorter path to this cell already, skip processing
            if (current.distance() > minDistance[current.row()][current.col()]) {
                continue;
            }

            // 1. Cardinal Moves (Cost 0)
            for (int[] dir : CARDINAL_DIRECTIONS) {
                int nextR = current.row() + dir[0];
                int nextC = current.col() + dir[1];

                if (isValidMove(nextR, nextC) && minDistance[nextR][nextC] > current.distance()) {
                    minDistance[nextR][nextC] = current.distance();
                    deque.addFirst(new Node(nextR, nextC, current.distance()));
                }
            }

            // 2. Jump Moves (Cost 1) - Any cell in the 5x5 area around current cell
            for (int dr = -JUMP_RANGE; dr <= JUMP_RANGE; dr++) {
                for (int dc = -JUMP_RANGE; dc <= JUMP_RANGE; dc++) {
                    if (dr == 0 && dc == 0) continue;

                    int nextR = current.row() + dr;
                    int nextC = current.col() + dc;

                    if (isValidMove(nextR, nextC) && minDistance[nextR][nextC] > current.distance() + 1) {
                        minDistance[nextR][nextC] = current.distance() + 1;
                        deque.addLast(new Node(nextR, nextC, current.distance() + 1));
                    }
                }
            }
        }

        return -1;
    }

    private boolean isValidMove(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != '#';
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) return;

        int h = sc.nextInt();
        int w = sc.nextInt();

        // Convert 1-based input to 0-based indexing
        int startR = sc.nextInt() - 1;
        int startC = sc.nextInt() - 1;
        int endR = sc.nextInt() - 1;
        int endC = sc.nextInt() - 1;

        char[][] grid = new char[h][w];
        for (int i = 0; i < h; i++) {
            grid[i] = sc.next().toCharArray();
        }

        GridPathfinder pathfinder = new GridPathfinder(h, w, grid, startR, startC, endR, endC);
        int result = pathfinder.findShortestPath();

        System.out.println(result);
        sc.close();
    }
}

