/**
 * A program to find the shortest path in a grid where:
 * - Cardinal moves (Up, Down, Left, Right) have a cost of 0.
 * - Any other move within a 5x5 window has a cost of 1.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            int height = reader.nextInt();
            int width = reader.nextInt();

            // Input is 1-indexed in the problem, converting to 0-indexed
            int startRow = reader.nextInt() - 1;
            int startCol = reader.nextInt() - 1;
            int targetRow = reader.nextInt() - 1;
            int targetCol = reader.nextInt() - 1;

            boolean[][] isTraversable = new boolean[height][width];
            for (int i = 0; i < height; i++) {
                String line = reader.next();
                for (int j = 0; j < width; j++) {
                    if (line.charAt(j) == '.') {
                        isTraversable[i][j] = true;
                    }
                }
            }

            GridPathfinder pathfinder = new GridPathfinder(height, width, isTraversable);
            int result = pathfinder.findShortestPath(startRow, startCol, targetRow, targetCol);

            System.out.println(result);

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Represents a coordinate point in the grid.
     */
    private static class Node {
        final int r, c;

        Node(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Encapsulates the grid traversal logic using 0-1 BFS.
     */
    private static class GridPathfinder {
        private final int height;
        private final int width;
        private final boolean[][] isTraversable;

        public GridPathfinder(int height, int width, boolean[][] isTraversable) {
            this.height = height;
            this.width = width;
            this.isTraversable = isTraversable;
        }

        /**
         * Finds the minimum cost to reach the target using 0-1 BFS.
         * 0-weight edges: Cardinal neighbors.
         * 1-weight edges: Non-cardinal neighbors within a 5x5 window.
         */
        public int findShortestPath(int startR, int startC, int targetR, int targetC) {
            int[][] distances = new int[height][width];
            for (int[] row : distances) {
                Arrays.fill(row, Integer.MAX_VALUE);
            }

            Deque<Node> deque = new ArrayDeque<>();

            distances[startR][startC] = 0;
            deque.addLast(new Node(startR, startC));

            while (!deque.isEmpty()) {
                Node current = deque.pollFirst();
                int r = current.r;
                int c = current.c;

                // If we reached the target, we can potentially stop early, 
                // but in 0-1 BFS we continue to ensure shortest path properties.
                if (r == targetR && c == targetC) {
                    continue;
                }

                // Explore the 5x5 window
                for (int dr = -2; dr <= 2; dr++) {
                    for (int dc = -2; dc <= 2; dc++) {
                        if (dr == 0 && dc == 0) continue;

                        int nr = r + dr;
                        int nc = c + dc;

                        if (isValidMove(nr, nc)) {
                            // Weight is 0 if it's a cardinal neighbor, 1 otherwise
                            int weight = (Math.abs(dr) + Math.abs(dc) == 1) ? 0 : 1;
                            int newDist = distances[r][c] + weight;

                            if (newDist < distances[nr][nc]) {
                                distances[nr][nc] = newDist;
                                if (weight == 0) {
                                    deque.addFirst(new Node(nr, nc));
                                } else {
                                    deque.addLast(new Node(nr, nc));
                                }
                            }
                        }
                    }
                }
            }

            int finalDist = distances[targetR][targetC];
            return (finalDist == Integer.MAX_VALUE) ? -1 : finalDist;
        }

        private boolean isValidMove(int r, int c) {
            return r >= 0 && r < height && c >= 0 && c < width && isTraversable[r][c];
        }
    }

    /**
     * Efficient input reader for large datasets.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

