/**
 * A solution to find the minimum cost to traverse a grid.
 * 
 * Movement Rules:
 * 1. Moving to an adjacent cell (Up, Down, Left, Right) has a cost of 0.
 * 2. Moving to any cell within a 5x5 area around the current cell has a cost of 1.
 * 3. Cells marked with '#' are obstacles and cannot be traversed.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            // The problem uses 1-based indexing for coordinates; convert to 0-based.
            int startRow = reader.nextInt() - 1;
            int startCol = reader.nextInt() - 1;
            int endRow = reader.nextInt() - 1;
            int endCol = reader.nextInt() - 1;

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridPathfinder pathfinder = new GridPathfinder(grid);
            int result = pathfinder.findMinimumCost(startRow, startCol, endRow, endCol);

            out.println(result);
        } catch (Exception e) {
            // In a production environment, use a proper logging framework.
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Encapsulates the grid traversal logic using a 0-1 Breadth-First Search algorithm.
     */
    static class GridPathfinder {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        private static final int INF = Integer.MAX_VALUE;
        private static final char OBSTACLE = '#';
        private static final int[][] ADJACENT_DIRECTIONS = {
            {1, 0}, {-1, 0}, {0, 1}, {0, -1}
        };

        public GridPathfinder(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
        }

        /**
         * Computes the minimum cost to travel from (startR, startC) to (endR, endC).
         *
         * @return The minimum cost, or -1 if the destination is unreachable.
         */
        public int findMinimumCost(int startR, int startC, int endR, int endC) {
            if (!isValid(startR, startC) || !isValid(endR, endC) || 
                grid[startR][startC] == OBSTACLE || grid[endR][endC] == OBSTACLE) {
                return -1;
            }

            int[][] minCostToReach = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                Arrays.fill(minCostToReach[i], INF);
            }

            // 0-1 BFS uses a Deque to process 0-weight edges at the front 
            // and 1-weight edges at the back.
            Deque<int[]> deque = new ArrayDeque<>();

            minCostToReach[startR][startC] = 0;
            deque.addFirst(new int[]{startR, startC});

            while (!deque.isEmpty()) {
                int[] current = deque.pollFirst();
                int r = current[0];
                int c = current[1];

                // 1. Process 0-cost moves: 4-directional adjacency
                for (int[] dir : ADJACENT_DIRECTIONS) {
                    int nr = r + dir[0];
                    int nc = c + dir[1];

                    if (isValid(nr, nc) && grid[nr][nc] != OBSTACLE) {
                        if (minCostToReach[nr][nc] > minCostToReach[r][c]) {
                            minCostToReach[nr][nc] = minCostToReach[r][c];
                            deque.addFirst(new int[]{nr, nc});
                        }
                    }
                }

                // 2. Process 1-cost moves: any cell in the 5x5 neighborhood
                for (int dr = -2; dr <= 2; dr++) {
                    for (int dc = -2; dc <= 2; dc++) {
                        int nr = r + dr;
                        int nc = c + dc;

                        if (isValid(nr, nc) && grid[nr][nc] != OBSTACLE) {
                            if (minCostToReach[nr][nc] > minCostToReach[r][c] + 1) {
                                minCostToReach[nr][nc] = minCostToReach[r][c] + 1;
                                deque.addLast(new int[]{nr, nc});
                            }
                        }
                    }
                }
            }

            int finalCost = minCostToReach[endR][endC];
            return (finalCost == INF) ? -1 : finalCost;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * A lightweight utility class for fast input reading.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
