/**
 * A solution to find the shortest path in a grid with variable movement costs.
 * Cardinal moves (Up, Down, Left, Right) cost 0.
 * All other moves (Diagonal or jumps up to 2 units) cost 1.
 */
public class Main {

    public static void main(String[] args) {
        try (FastReader reader = new FastReader(System.in);
             PrintWriter writer = new PrintWriter(System.out)) {

            GridPathfinder pathfinder = new GridPathfinder(reader);
            pathfinder.solve(writer);

        } catch (IOException e) {
