/**
 * Represents a coordinate and its cumulative cost in the search algorithm.
 */
class Node implements Comparable<Node> {
    final int row;
    final int col;
    final int cost;

    Node(int row, int col, int cost) {
        this.row = row;
        this.col = col;
        this.cost = cost;
    }

