/**
 * Contains various algorithmic solutions refactored from the original source.
 */
class ProblemSolver {
    private static final int MOD = 1_000_000_007;
    private static final int INF = 1_000_000_000;
    private final FastReader reader;
    private final PrintWriter out;

    public ProblemSolver(FastReader reader, PrintWriter out) {
        this.reader = reader;
        this.out = out;
    }

    /**
     * Problem A: Calculates the required multipliers based on n, x, and t.
     */
    public void solveMultiplierProblem() {
        int n = reader.nextInt();
        int x = reader.nextInt();
        int t = reader.nextInt();

        int multiplier = (int) Math.ceil((double) n / x);
        out.println((long) multiplier * t);
    }

    /**
     * Problem B: Checks if the sum of digits of a number is divisible by 9.
     */
    public void solveDivisibilityByNine() {
        String input = reader.nextLine();
        if (input == null) return;

        int digitSum = 0;
        for (char c : input.toCharArray()) {
            if (Character.isDigit(c)) {
                digitSum = (digitSum + (c - '0')) % 9;
            }
        }
        out.println(digitSum == 0 ? "Yes" : "No");
    }

    /**
     * Problem C: Calculates the sum of differences needed to make all elements at least the running minimum.
     */
    public void solveCumulativeDifference() {
        int n = reader.nextInt();
        int[] values = new int[n];
        for (int i = 0; i < n; i++) {
            values[i] = reader.nextInt();
        }

        long totalDifference = 0;
        int currentMin = 0;
        for (int val : values) {
            if (val < currentMin) {
                totalDifference += (currentMin - val);
            }
            currentMin = Math.max(val, currentMin);
        }
        out.println(totalDifference);
    }

    /**
     * Problem D: Finds the shortest path in a grid with specific movement rules.
     */
    public void solveGridShortestPath() {
        int height = reader.nextInt();
        int width = reader.nextInt();

        int startRow = reader.nextInt() - 1;
        int startCol = reader.nextInt() - 1;

        int endRow = reader.nextInt() - 1;
        int endCol = reader.nextInt() - 1;

        char[][] grid = new char[height][width];
        for (int i = 0; i < height; i++) {
            grid[i] = reader.nextLine().toCharArray();
        }

        int[][] dist = new int[height][width];
        for (int[] row : dist) {
            Arrays.fill(row, INF);
        }

        Queue<int[]> queue = new LinkedList<>();
        dist[startRow][startCol] = 0;
        queue.offer(new int[]{startRow, startCol});

        int[] dr = {1, 0, -1, 0};
        int[] dc = {0, 1, 0, -1};

        while (!queue.isEmpty()) {
            int size = queue.size();
            // Process current level
            List<int[]> currentLevel = new ArrayList<>();
            for (int i = 0; i < size; i++) {
                int[] curr = queue.poll();
                currentLevel.add(curr);
                int r = curr[0];
                int c = curr[1];

                // Standard 4-directional move
                for (int k = 0; k < 4; k++) {
                    int nr = r + dr[k];
                    int nc = c + dc[k];

                    if (isValid(nr, nc, height, width, grid) && dist[nr][nc] > dist[r][c]) {
                        dist[nr][nc] = dist[r][c]; // Original logic maintained
                        queue.offer(new int[]{nr, nc});
                    }
                }
            }

            // Process the 5x5 jump move for nodes reached in this level
            for (int[] node : currentLevel) {
                int r = node[0];
                int c = node[1];

                for (int i = -2; i <= 2; i++) {
                    for (int j = -2; j <= 2; j++) {
                        int nr = r + i;
                        int nc = c + j;

                        if (isValid(nr, nc, height, width, grid) && dist[nr][nc] > dist[r][c] + 1) {
                            dist[nr][nc] = dist[r][c] + 1;
                            queue.offer(new int[]{nr, nc});
                        }
                    }
                }
            }
        }

        out.println(dist[endRow][endCol] >= INF ? -1 : dist[endRow][endCol]);
    }

    private boolean isValid(int r, int c, int h, int w, char[][] grid) {
        return r >= 0 && r < h && c >= 0 && c < w && grid[r][c] != '#';
    }

    /**
     * Problem E: Finds the minimum threshold using binary search.
     */
    public void solveThresholdBinarySearch() {
        int n = reader.nextInt();
        int k = reader.nextInt();
        int[] values = new int[n];
        for (int i = 0; i < n; i++) {
            values[i] = reader.nextInt();
        }

        int low = 1, high = 1 << 30;
        int result = high;

        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (calculateCuts(values, mid) > k) {
                low = mid + 1;
            } else {
                result = mid;
                high = mid - 1;
            }
        }
        out.println(result);
    }

    private int calculateCuts(int[] values, int threshold) {
        int cuts = 0;
        for (int v : values) {
            if (v > threshold) {
                cuts += v / threshold;
            }
        }
        return cuts;
    }

    /**
     * Problem F: Calculates a modular product.
     */
    public void solveModularProduct() {
        int k = reader.nextInt();
        String s = reader.nextLine();
        int n = s.length();
        long product = 1;

        for (int i = 0; i < k; i++) {
            n++;
            product = (product * 26 * n) % MOD;
        }
        out.println(product);
    }

    /**
     * Utility: Checks if s2 is a subsequence of s1.
     */
    public boolean isSubsequence(String s1, String s2) {
        int m = s1.length(), n = s2.length();
        if (m < n) return false;
        int j = n - 1;
        for (int i = m - 1; i >= 0; i--) {
            if (s1.charAt(i) == s2.charAt(j)) {
                j--;
            }
            if (j < 0) return true;
        }
        return false;
    }
}

