 * - Moving to an adjacent cell (4-directionally) has a cost of 0.
 * - Moving to any cell within a 5x5 area has a cost of 1.
 */
public class Main {

    public static void main(String[] args) {
        try {
            GridPathfinder app = new GridPathfinder();
            app.run();
        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
