class GridPathfinder {

    private static final int[] ADJACENT_ROW_OFFSETS = {-1, 1, 0, 0};
    private static final int[] ADJACENT_COL_OFFSETS = {0, 0, -1, 1};
    private static final long INF = Long.MAX_VALUE;

    /**
     * Represents a coordinate in the 2D grid.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Encapsulates the grid and its properties.
     */
    private static class Grid {
        final int height;
        final int width;
        final char[][] cells;

        Grid(int height, int width, char[][] cells) {
            this.height = height;
            this.width = width;
            this.cells = cells;
        }

        boolean isValid(int r, int c) {
            return r >= 0 && r < height && c >= 0 && c < width && cells[r][c] != '#';
        }
    }

    public void run() throws IOException {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        // Read dimensions
        int height = reader.nextInt();
        int width = reader.nextInt();

        // Read coordinates (converted to 0-indexed)
        int startRow = reader.nextInt() - 1;
        int startCol = reader.nextInt() - 1;
        int targetRow = reader.nextInt() - 1;
        int targetCol = reader.nextInt() - 1;

        // Read grid layout
        char[][] cells = new char[height][width];
        for (int r = 0; r < height; r++) {
            for (int c = 0; c < width; c++) {
                cells[r][c] = reader.nextChar();
            }
        }

        Grid grid = new Grid(height, width, cells);
        long result = findShortestPath(grid, new Point(startRow, startCol), new Point(targetRow, targetCol));

        // Output result
        if (result == INF) {
            writer.println("-1");
        } else {
            writer.println(result);
        }

        writer.flush();
        writer.close();
    }

    /**
     * Implementation of 0-1 BFS to find the shortest path in a weighted graph.
     */
    private long findShortestPath(Grid grid, Point start, Point target) {
        long[][] dist = new long[grid.height][grid.width];
        for (int i = 0; i < grid.height; i++) {
            Arrays.fill(dist[i], INF);
        }

        Deque<Point> deque = new ArrayDeque<>();
        dist[start.row][start.col] = 0;
        deque.addFirst(start);

        while (!deque.isEmpty()) {
            Point current = deque.pollFirst();
            int r = current.row;
            int c = current.col;

            // 1. Weight-0 Moves: Move to 4-adjacent cells
            for (int i = 0; i < 4; i++) {
                int nr = r + ADJACENT_ROW_OFFSETS[i];
                int nc = c + ADJACENT_COL_OFFSETS[i];

                if (grid.isValid(nr, nc)) {
                    if (dist[nr][nc] > dist[r][c]) {
                        dist[nr][nc] = dist[r][c];
                        deque.addFirst(new Point(nr, nc));
                    }
                }
            }

            // 2. Weight-1 Moves: Move anywhere in a 5x5 area
            for (int dr = -2; dr <= 2; dr++) {
                for (int dc = -2; dc <= 2; dc++) {
                    int nr = r + dr;
                    int nc = c + dc;

                    if (grid.isValid(nr, nc)) {
                        if (dist[nr][nc] > dist[r][c] + 1) {
                            dist[nr][nc] = dist[r][c] + 1;
                            deque.addLast(new Point(nr, nc));
                        }
                    }
                }
            }
        }

        return dist[target.row][target.col];
    }

    /**
     * Efficient reader for competitive programming-style input.
     */
    private static class FastReader {
        private final BufferedReader reader;

        public FastReader(InputStream input) {
            this.reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int b = reader.read();
            while (b != -1 && Character.isWhitespace(b)) b = reader.read();
            if (b == -1) return null;
            while (b != -1 && !Character.isWhitespace(b)) {
                sb.append((char) b);
                b = reader.read();
            }
            return sb.toString();
        }

        public int nextInt() throws IOException {
            String s = next();
            return (s == null) ? 0 : Integer.parseInt(s);
        }

        public char nextChar() throws IOException {
            int b = reader.read();
            while (b != -1 && Character.isWhitespace(b)) {
                b = reader.read();
            }
            return (char) b;
        }
    }
}

