/**
 * Encapsulates the grid data and boundary/traversability logic.
 */
class Grid {
    private final int height;
    private final int width;
    private final boolean[][] traversable;

    private static final char TRAVERSABLE_CHAR = '.';

    public Grid(int height, int width, FastScanner scanner) {
        this.height = height;
        this.width = width;
        this.traversable = new boolean[height][width];
        initializeGrid(scanner);
    }

    private void initializeGrid(FastScanner scanner) {
        for (int i = 0; i < height; i++) {
            String line = scanner.next();
            for (int j = 0; j < width; j++) {
                traversable[i][j] = (line.charAt(j) == TRAVERSABLE_CHAR);
            }
        }
    }

    public boolean isInside(int x, int y) {
        return x >= 0 && x < height && y >= 0 && y < width;
    }

    public boolean isTraversable(int x, int y) {
        return isInside(x, y) && traversable[x][y];
    }

    public int getHeight() {
        return height;
    }

    public int getWidth() {
        return width;
    }
}

/**
 * Handles the shortest path logic using Dijkstra's algorithm.
 */
class DijkstraSolver {
    private final Grid grid;

    // Cost 0 moves: Adjacent (up, down, left, right)
    private static final int[] WALK_DX = {1, 0, -1, 0};
    private static final int[] WALK_DY = {0, 1, 0, -1};

    // Cost 1 moves: 5x5 area
    private static final int[] WARP_RANGE = {-2, -1, 0, 1, 2};

    public DijkstraSolver(Grid grid) {
        this.grid = grid;
    }

    public int findShortestPath(Coordinate start, Coordinate target) {
        int[][] distances = new int[grid.getHeight()][grid.getWidth()];
        for (int[] row : distances) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }

        PriorityQueue<Node> pq = new PriorityQueue<>();

        distances[start.x()][start.y()] = 0;
        pq.add(new Node(start, 0));

        while (!pq.isEmpty()) {
            Node current = pq.poll();
            int currX = current.coordinate().x();
            int currY = current.coordinate().y();
            int currDist = current.distance();

            // If we found a better path to this node already, skip processing
            if (currDist > distances[currX][currY]) {
                continue;
            }

            // If we reached the target, we can return early because Dijkstra guarantees shortest path
            if (currX == target.x() && currY == target.y()) {
                return currDist;
            }

            // 1. Handle "Walk" moves (Cost 0)
            for (int i = 0; i < 4; i++) {
                processMove(currX + WALK_DX[i], currY + WALK_DY[i], currDist, distances, pq);
            }

            // 2. Handle "Warp" moves (Cost 1)
            for (int dx : WARP_RANGE) {
                for (int dy : WARP_RANGE) {
                    // Note: (0,0) move is cost 1, but Dijkstra will naturally favor the 0-cost walk
                    processMove(currX + dx, currY + dy, currDist + 1, distances, pq);
                }
            }
        }

        int finalDist = distances[target.x()][target.y()];
        return finalDist == Integer.MAX_VALUE ? -1 : finalDist;
    }

    private void processMove(int nextX, int nextY, int newDist, int[][] distances, PriorityQueue<Node> pq) {
        if (grid.isTraversable(nextX, nextY)) {
            if (newDist < distances[nextX][nextY]) {
                distances[nextX][nextY] = newDist;
                pq.add(new Node(new Coordinate(nextX, nextY), newDist));
            }
        }
    }
}

