/**
 * A program to find the shortest path in a grid where cardinal moves cost 0 
 * and jumps within a 5x5 area cost 1.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);

        try {
            // Input reading
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            int startRow = reader.nextInt() - 1; // Convert to 0-indexed
            int startCol = reader.nextInt() - 1;

            int endRow = reader.nextInt() - 1;   // Convert to 0-indexed
            int endCol = reader.nextInt() - 1;

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            // Perform pathfinding
            GridPathfinder pathfinder = new GridPathfinder(grid);
            int result = pathfinder.findShortestPath(startRow, startCol, endRow, endCol);

            // Output result
            System.out.println(result);

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Handles the pathfinding logic using Dijkstra's algorithm.
     */
    static class GridPathfinder {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        private static final int INF = Integer.MAX_VALUE;
        private static final int[] CARDINAL_DX = {1, -1, 0, 0};
        private static final int[] CARDINAL_DY = {0, 0, 1, -1};

        public GridPathfinder(char[][] grid) {
            this.grid = grid;
            this.rows = grid.length;
            this.cols = grid[0].length;
        }

        /**
         * Finds the shortest distance from start to end.
         * Returns -1 if no path exists.
         */
        public int findShortestPath(int startR, int startC, int endR, int endC) {
            // If start or end is an obstacle, return immediately
            if (grid[startR][startC] == '#' || grid[endR][endC] == '#') {
                return -1;
            }

            PriorityQueue<Node> pq = new PriorityQueue<>();
            int[][] minDistance = new int[rows][cols];
            boolean[][] visited = new boolean[rows][cols];

            for (int i = 0; i < rows; i++) {
                Arrays.fill(minDistance[i], INF);
            }

            minDistance[startR][startC] = 0;
            pq.add(new Node(startR, startC, 0));

            while (!pq.isEmpty()) {
                Node current = pq.poll();

                if (current.r == endR && current.c == endC) {
                    return current.dist;
                }

                if (visited[current.r][current.c]) {
                    continue;
                }
                visited[current.r][current.c] = true;

                // 1. Cardinal moves (Cost 0)
                for (int i = 0; i < 4; i++) {
                    int nr = current.r + CARDINAL_DX[i];
                    int nc = current.c + CARDINAL_DY[i];

                    if (isValid(nr, nc) && grid[nr][nc] != '#') {
                        if (minDistance[nr][nc] > current.dist) {
                            minDistance[nr][nc] = current.dist;
                            pq.add(new Node(nr, nc, current.dist));
                        }
                    }
                }

                // 2. Area jump moves (Cost 1) - 5x5 window around current cell
                for (int i = Math.max(0, current.r - 2); i <= Math.min(rows - 1, current.r + 2); i++) {
                    for (int j = Math.max(0, current.c - 2); j <= Math.min(cols - 1, current.c + 2); j++) {
                        if (isValid(i, j) && grid[i][j] != '#' && !visited[i][j]) {
                            if (minDistance[i][j] > current.dist + 1) {
                                minDistance[i][j] = current.dist + 1;
                                pq.add(new Node(i, j, current.dist + 1));
                            }
                        }
                    }
                }
            }

            return -1;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        /**
         * Represents a cell in the grid for the PriorityQueue.
         */
        private static class Node implements Comparable<Node> {
            int r, c, dist;

            Node(int r, int c, int dist) {
                this.r = r;
                this.c = c;
                this.dist = dist;
            }

            @Override
            public int compareTo(Node other) {
                return Integer.compare(this.dist, other.dist);
            }
        }
    }

    /**
     * Optimized reader for fast I/O operations.
     */
    static class FastReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

