    }

    /**
     * Uses Dijkstra's algorithm to find the minimum cost to reach the target.
     */
    public int findShortestPath(int startRow, int startCol, int targetRow, int targetCol) {
        int[][] dist = new int[rows][cols];
        for (int[] row : dist) {
            Arrays.fill(row, INF);
        }

        PriorityQueue<Node> pq = new PriorityQueue<>();

        dist[startRow][startCol] = 0;
        pq.add(new Node(new Point(startRow, startCol), 0));

        while (!pq.isEmpty()) {
            Node current = pq.poll();
            Point p = current.point();
            int d = current.distance();

            // If we found a shorter path to this point already, skip processing
            if (d > dist[p.row()][p.col()]) {
                continue;
            }

            // If we reached the target, we can return early (Dijkstra property)
            if (p.row() == targetRow && p.col() == targetCol) {
                return d;
            }

            // 1. Move to 4-neighbors with cost 0
            for (int i = 0; i < 4; i++) {
                int nr = p.row() + DR[i];
                int nc = p.col() + DC[i];

                if (isWithinBounds(nr, nc) && grid[nr][nc] == '.') {
                    if (dist[nr][nc] > d) {
                        dist[nr][nc] = d;
                        pq.add(new Node(new Point(nr, nc), dist[nr][nc]));
                    }
                }
            }

            // 2. Move to any cell in a 5x5 area with cost 1
            for (int dr = -2; dr <= 2; dr++) {
                for (int dc = -2; dc <= 2; dc++) {
                    if (dr == 0 && dc == 0) continue;

                    int nr = p.row() + dr;
                    int nc = p.col() + dc;

                    if (isWithinBounds(nr, nc) && grid[nr][nc] == '.') {
                        if (dist[nr][nc] > d + 1) {
                            dist[nr][nc] = d + 1;
                            pq.add(new Node(new Point(nr, nc), dist[nr][nc]));
                        }
                    }
                }
            }
        }

        return dist[targetRow][targetCol] == INF ? -1 : dist[targetRow][targetCol];
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

