import java.io.*;
import java.util.*;

/**
 * A solver for the "Wizard in a Maze" problem using Dijkstra's algorithm.
 * The movement rules are:
 * 1. Moving to an adjacent cell (Up, Down, Left, Right) costs 0.
 * 2. Moving to any cell within a 5x5 area around the current cell costs 1.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        MazeSolver solver = new MazeSolver();
        solver.solve(reader, writer);

        writer.flush();
        writer.close();
    }

    /**
     * Represents a state in the maze during the search process.
     */
    static class Node implements Comparable<Node> {
        final int row;
        final int col;
        final int cost;

        public Node(int row, int col, int cost) {
            this.row = row;
            this.col = col;
            this.cost = cost;
        }

        @Override
        public int compareTo(Node other) {
            return Integer.compare(this.cost, other.cost);
        }
    }

    static class MazeSolver {
        private static final char WALL = '#';
        private static final int INF = Integer.MAX_VALUE;

        // Standard 4-directional movement
        private final int[] dr = {1, -1, 0, 0};
        private final int[] dc = {0, 0, 1, -1};

        public void solve(FastReader reader, PrintWriter writer) {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            // Use padding to avoid boundary checks inside the loop
            char[][] grid = new char[rows + 2][cols + 2];
            for (char[] row : grid) {
                Arrays.fill(row, WALL);
            }

            int startRow = reader.nextInt();
            int startCol = reader.nextInt();
            int targetRow = reader.nextInt();
            int targetCol = reader.nextInt();

            for (int i = 1; i <= rows; i++) {
                for (int j = 1; j <= cols; j++) {
                    grid[i][j] = reader.nextChar();
                }
            }

            int result = computeShortestPath(grid, rows, cols, startRow, startCol, targetRow, targetCol);
            writer.println(result);
        }

        private int computeShortestPath(char[][] grid, int rows, int cols, 
                                        int startR, int startC, int targetR, int targetC) {

            int[][] minCost = new int[rows + 2][cols + 2];
            for (int[] row : minCost) {
                Arrays.fill(row, INF);
            }

            PriorityQueue<Node> pq = new PriorityQueue<>();

            minCost[startR][startC] = 0;
            pq.add(new Node(startR, startC, 0));

            while (!pq.isEmpty()) {
                Node current = pq.poll();

                if (current.cost > minCost[current.row][current.col]) {
                    continue;
                }

                if (current.row == targetR && current.col == targetC) {
                    return current.cost;
                }

                // Rule 1: Adjacent movement (Cost 0)
                for (int i = 0; i < 4; i++) {
                    int nr = current.row + dr[i];
                    int nc = current.col + dc[i];

                    if (grid[nr][nc] != WALL && minCost[nr][nc] > current.cost) {
                        minCost[nr][nc] = current.cost;
                        pq.add(new Node(nr, nc, current.cost));
                    }
                }

                // Rule 2: Jump movement within 5x5 area (Cost 1)
                for (int i = -2; i <= 2; i++) {
                    for (int j = -2; j <= 2; j++) {
                        if (i == 0 && j == 0) continue;

                        int nr = current.row + i;
                        int nc = current.col + j;

                        // Check boundaries and wall
                        if (nr >= 1 && nr <= rows && nc >= 1 && nc <= cols) {
                            if (grid[nr][nc] != WALL && minCost[nr][nc] > current.cost + 1) {
                                minCost[nr][nc] = current.cost + 1;
                                pq.add(new Node(nr, nc, current.cost + 1));
                            }
                        }
                    }
                }
            }

            return minCost[targetR][targetC] == INF ? -1 : minCost[targetR][targetC];
        }
    }

    /**
     * Optimized reader for fast I/O performance.
     */
    static class FastReader {
        private final InputStream inputStream;
        private final byte[] buffer = new byte[1024];
        private int curChar;
        private int numChars;

        public FastReader(InputStream stream) {
            this.inputStream = stream;
        }

        private int read() {
            if (numChars == -1) throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = inputStream.read(buffer);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) return -1;
            }
            return buffer[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + (c - '0');
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public char nextChar() {
            int c = read();
            while (isSpaceChar(c)) c = read();
            return (char) c;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A program to find the shortest path between segments in a grid.
 * Segments are connected components of '.' characters.
 * Two segments are connected if any cell in one is within a 5x5 area of the other.
 */
public class Main {

    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int height = reader.nextInt();
            int width = reader.nextInt();

            int startRow = reader.nextInt() - 1;
            int startCol = reader.nextInt() - 1;
            int endRow = reader.nextInt() - 1;
            int endCol = reader.nextInt() - 1;

            char[][] gridData = new char[height][width];
            for (int i = 0; i < height; i++) {
                gridData[i] = reader.next().toCharArray();
            }

            Grid grid = new Grid(height, width, gridData);
            Segmenter segmenter = new Segmenter(grid);
            int[][] segmentMap = segmenter.getSegmentMap();
            int totalSegments = segmenter.getTotalSegments();

            SegmentGraph graph = new SegmentGraph(grid, segmentMap, totalSegments);
            Pathfinder pathfinder = new Pathfinder(graph);

            int startSegment = segmentMap[startRow][startCol];
            int endSegment = segmentMap[endRow][endCol];

            int result = pathfinder.findShortestPath(startSegment, endSegment);
            out.println(result);

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.close();
        }
    }

    /**
     * Represents the game board/grid.
     */
    static class Grid {
        private final int height;
        private final int width;
        private final char[][] cells;

        public Grid(int height, int width, char[][] cells) {
            this.height = height;
            this.width = width;
            this.cells = cells;
        }

        public int getHeight() { return height; }
        public int getWidth() { return width; }
        public char getCell(int r, int c) { return cells[r][c]; }

        public boolean isValid(int r, int c) {
            return r >= 0 && r < height && c >= 0 && c < width;
        }
    }

    /**
     * Handles the identification of connected components (segments) in the grid.
     */
    static class Segmenter {
        private static final int[][] DIRECTIONS = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};
        private final Grid grid;
        private final int[][] segmentMap;
        private int segmentCount = 0;

        public Segmenter(Grid grid) {
            this.grid = grid;
            this.segmentMap = new int[grid.getHeight()][grid.getWidth()];
            identifySegments();
        }

        private void identifySegments() {
            for (int i = 0; i < grid.getHeight(); i++) {
                for (int j = 0; j < grid.getWidth(); j++) {
                    if (segmentMap[i][j] == 0 && grid.getCell(i, j) == '.') {
                        segmentCount++;
                        bfsFillSegment(i, j, segmentCount);
                    }
                }
            }
        }

        private void bfsFillSegment(int startR, int startC, int segmentId) {
            Queue<int[]> queue = new ArrayDeque<>();
            queue.add(new int[]{startR, startC});
            segmentMap[startR][startC] = segmentId;

            while (!queue.isEmpty()) {
                int[] current = queue.poll();
                for (int[] d : DIRECTIONS) {
                    int nr = current[0] + d[0];
                    int nc = current[1] + d[1];

                    if (grid.isValid(nr, nc) && grid.getCell(nr, nc) == '.' && segmentMap[nr][nc] == 0) {
                        segmentMap[nr][nc] = segmentId;
                        queue.add(new int[]{nr, nc});
                    }
                }
            }
        }

        public int[][] getSegmentMap() { return segmentMap; }
        public int getTotalSegments() { return segmentCount; }
    }

    /**
     * Represents the graph where each node is a segment.
     */
    static class SegmentGraph {
        private final List<Set<Integer>> adjacencyList;

        public SegmentGraph(Grid grid, int[][] segmentMap, int totalSegments) {
            // Index 0 is reserved for non-segment cells (walls/empty)
            this.adjacencyList = new ArrayList<>(totalSegments + 1);
            for (int i = 0; i <= totalSegments; i++) {
                adjacencyList.add(new HashSet<>());
            }
            buildGraph(grid, segmentMap);
        }

        private void buildGraph(Grid grid, int[][] segmentMap) {
            int height = grid.getHeight();
            int width = grid.getWidth();

            for (int i = 0; i < height; i++) {
                for (int j = 0; j < width; j++) {
                    int currentSegment = segmentMap[i][j];
                    if (currentSegment == 0) continue;

                    // Check 5x5 window (Chebyshev distance <= 2)
                    for (int dr = -2; dr <= 2; dr++) {
                        for (int dc = -2; dc <= 2; dc++) {
                            int nr = i + dr;
                            int nc = j + dc;

                            if (grid.isValid(nr, nc)) {
                                int neighborSegment = segmentMap[nr][nc];
                                if (neighborSegment != 0 && neighborSegment != currentSegment) {
                                    adjacencyList.get(currentSegment).add(neighborSegment);
                                    adjacencyList.get(neighborSegment).add(currentSegment);
                                }
                            }
                        }
                    }
                }
            }
        }

        public Set<Integer> getNeighbors(int segmentId) {
            return adjacencyList.get(segmentId);
        }
    }

    /**
     * Logic to find the shortest path in the SegmentGraph.
     */
    static class Pathfinder {
        private final SegmentGraph graph;

        public Pathfinder(SegmentGraph graph) {
            this.graph = graph;
        }

        public int findShortestPath(int startNode, int endNode) {
            if (startNode == endNode) return 0;
            if (startNode == 0 || endNode == 0) return -1;

            Queue<Integer> queue = new ArrayDeque<>();
            Map<Integer, Integer> distances = new HashMap<>();

            queue.add(startNode);
            distances.put(startNode, 0);

            while (!queue.isEmpty()) {
                int current = queue.poll();
                int currentDist = distances.get(current);

                if (current == endNode) return currentDist;

                for (int neighbor : graph.getNeighbors(current)) {
                    if (!distances.containsKey(neighbor)) {
                        distances.put(neighbor, currentDist + 1);
                        queue.add(neighbor);
                    }
                }
            }

            return -1;
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

