/**
 * Represents a coordinate in the 2D grid.
 */
class Point {
    final int row;
    final int col;

    public Point(int row, int col) {
        this.row = row;
        this.col = col;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Point)) return false;
        Point point = (Point) o;
        return row == point.row && col == point.col;
    }

    @Override
    public int hashCode() {
        return Objects.hash(row, col);
    }
}

/**
 * Handles high-performance input reading.
 */
class FastReader {
    private final InputStream in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;

    public FastReader(InputStream in) {
        this.in = in;
    }

    private boolean hasNextByte() {
        if (ptr < buflen) return true;
        ptr = 0;
        try {
            buflen = in.read(buffer);
        } catch (IOException e) {
            e.printStackTrace();
        }
        return buflen > 0;
    }

    private int readByte() {
        return hasNextByte() ? buffer[ptr++] : -1;
    }

    private static boolean isPrintableChar(int c) {
        return 33 <= c && c <= 126;
    }

    public boolean hasNext() {
        while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;
        return hasNextByte();
    }

    public String next() {
        if (!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while (isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    public int nextInt() {
        return (int) nextLong();
    }

    public long nextLong() {
        if (!hasNext()) throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b < '0' || '9' < b) throw new NumberFormatException();
        while (true) {
            if ('0' <= b && b <= '9') {
                n *= 10;
                n += b - '0';
            } else if (b == -1 || !isPrintableChar(b)) {
                return minus ? -n : n;
            } else {
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }
}

/**
 * Solves the grid reachability problem using component-based expansion.
 */
class GridSolver {
    private final int height;
    private final int width;
    private final int startRow, startCol;
    private final int goalRow, goalCol;
    private final char[][] grid;
    private final boolean[][] visitedGlobal;

    private static final int[][] DIRECTIONS = {{-1, 0}, {0, -1}, {0, 1}, {1, 0}};

    public GridSolver(int height, int width, int startRow, int startCol, 
                      int goalRow, int goalCol, char[][] grid) {
        this.height = height;
        this.width = width;
        this.startRow = startRow;
        this.startCol = startCol;
        this.goalRow = goalRow;
        this.goalCol = goalCol;
        this.grid = grid;
        this.visitedGlobal = new boolean[height][width];
    }

    /**
     * Performs BFS to check if the goal is reachable from the start point.
     * While traversing, it marks cells in the visitedGlobal array and adds 
     * all discovered cells to the exploredInThisStep set.
     */
    private boolean bfsCheckReachability(Point start, Set<Point> exploredInThisStep) {
        if (start.row == goalRow && start.col == goalCol) return true;

        Deque<Point> queue = new ArrayDeque<>();
        queue.addLast(start);

        while (!queue.isEmpty()) {
            Point current = queue.pollFirst();

            for (int[] dir : DIRECTIONS) {
                int nr = current.row + dir[0];
                int nc = current.col + dir[1];

                if (isOutOfBounds(nr, nc)) continue;
                if (nr == goalRow && nc == goalCol) return true;
                if (grid[nr][nc] == '#' || visitedGlobal[nr][nc]) continue;

                visitedGlobal[nr][nc] = true;
                Point neighbor = new Point(nr, nc);
                exploredInThisStep.add(neighbor);
                queue.addLast(neighbor);
            }
        }
        return false;
    }

    private boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= height || c < 0 || c >= width;
    }

    public int solve() {
        Set<Point> currentFrontier = new HashSet<>();
        currentFrontier.add(new Point(startRow, startCol));

        for (int step = 0; ; step++) {
            Set<Point> exploredInThisStep = new HashSet<>();

            // 1. Process the current frontier
            for (Point p : currentFrontier) {
                visitedGlobal[p.row][p.col] = true;
                exploredInThisStep.add(p);

                if (bfsCheckReachability(p, exploredInThisStep)) {
                    return step;
                }
            }

            // 2. Expand the frontier for the next step based on explored cells
            Set<Point> nextFrontier = new HashSet<>();
            for (Point p : exploredInThisStep) {
                for (int dr = -2; dr <= 2; dr++) {
                    for (int dc = -2; dc <= 2; dc++) {
                        int nr = p.row + dr;
                        int nc = p.col + dc;

                        if (isOutOfBounds(nr, nc)) continue;
                        if (grid[nr][nc] == '#' || visitedGlobal[nr][nc]) continue;

                        nextFrontier.add(new Point(nr, nc));
                    }
                }
            }

            if (nextFrontier.isEmpty()) break;
            currentFrontier = nextFrontier;
        }

        return -1;
    }
}

public class Main {
    public static void main(String[] args) {
        FastReader sc = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int h = sc.nextInt();
            int w = sc.nextInt();
            // Convert to 0-indexed
            int sh = sc.nextInt() - 1;
            int sw = sc.nextInt() - 1;
            int gh = sc.nextInt() - 1;
            int gw = sc.nextInt() - 1;

            char[][] grid = new char[h][];
            for (int i = 0; i < h; i++) {
                grid[i] = sc.next().toCharArray();
            }

            GridSolver solver = new GridSolver(h, w, sh, sw, gh, gw, grid);
            out.println(solver.solve());
        } catch (Exception e) {
            // Handle or log error
        } finally {
            out.close();
        }
    }
}

import java.util.*;

/**
 * A pathfinding solver that finds the shortest distance in a grid.
 * The movement rules are specialized:
 * 1. Traverse any cell within a 4-connected component of empty cells.
 * 2. Jump to any cell within a 5x5 neighborhood of the current component.
 */
public class Main {

    private static final int UNVISITED_EMPTY = Integer.MAX_VALUE;
    private static final int OBSTACLE = -1;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        // Read grid dimensions and starting/target coordinates
        int height = scanner.nextInt();
        int width = scanner.nextInt();
        int startRow = scanner.nextInt();
        int startCol = scanner.nextInt();
        int targetRow = scanner.nextInt();
        int targetCol = scanner.nextInt();

        // Initialize the grid. Using 1-based indexing to match input requirements.
        int[][] grid = new int[height + 1][width + 1];
        for (int i = 1; i <= height; i++) {
            String rowString = scanner.next();
            for (int j = 1; j <= width; j++) {
                grid[i][j] = (rowString.charAt(j - 1) == '.') ? UNVISITED_EMPTY : OBSTACLE;
            }
        }

        int shortestPathDistance = calculateShortestPath(grid, height, width, startRow, startCol, targetRow, targetCol);

        System.out.println(shortestPathDistance);
        scanner.close();
    }

    /**
     * Calculates the shortest path using a specialized Breadth-First Search.
     * 
     * @return The shortest distance to the target, or -1 if unreachable.
     */
    private static int calculateShortestPath(int[][] grid, int h, int w, int startR, int startC, int targetR, int targetC) {
        // Basic validation for starting position
        if (isOutOfBounds(startR, startC, h, w) || grid[startR][startC] == OBSTACLE) {
            return -1;
        }

        Deque<Point> queue = new ArrayDeque<>();
        queue.add(new Point(startR, startC));

        int currentDistance = 0;

        // Direction vectors for 4-connectivity (Up, Down, Left, Right)
        int[] dr4 = {1, 0, -1, 0};
        int[] dc4 = {0, 1, 0, -1};

        while (!queue.isEmpty()) {
            // Phase 1: Explore the entire 4-connected component reachable at the current distance level
            List<Point> component = new ArrayList<>();

            while (!queue.isEmpty()) {
                Point p = queue.poll();

                // If the cell is not an unvisited empty cell, skip it
                if (grid[p.r][p.c] != UNVISITED_EMPTY) {
                    continue;
                }

                // Mark cell as visited with the current distance
                grid[p.r][p.c] = currentDistance;
                component.add(p);

                // Add adjacent 4-connected neighbors to the queue for component expansion
                for (int i = 0; i < 4; i++) {
                    int nr = p.r + dr4[i];
                    int nc = p.c + dc4[i];

                    if (isValid(nr, nc, h, w) && grid[nr][nc] == UNVISITED_EMPTY) {
                        queue.add(new Point(nr, nc));
                    }
                }
            }

            // Phase 2: Expand the frontier by looking at a 5x5 neighborhood around the entire component
            Deque<Point> nextFrontier = new ArrayDeque<>();
            for (Point p : component) {
                for (int i = -2; i <= 2; i++) {
                    for (int j = -2; j <= 2; j++) {
                        int nr = p.r + i;
                        int nc = p.c + j;

                        if (isValid(nr, nc, h, w) && grid[nr][nc] == UNVISITED_EMPTY) {
                            nextFrontier.add(new Point(nr, nc));
                        }
                    }
                }
            }

            // Prepare for the next step
            queue = nextFrontier;
            currentDistance++;
        }

        int finalResult = grid[targetR][targetC];
        return (finalResult == UNVISITED_EMPTY) ? -1 : finalResult;
    }

    /**
     * Checks if a coordinate is within the valid grid boundaries.
     */
    private static boolean isValid(int r, int c, int h, int w) {
        return r >= 1 && r <= h && c >= 1 && c <= w;
    }

    /**
     * Checks if a coordinate is outside the grid boundaries.
     */
    private static boolean isOutOfBounds(int r, int c, int h, int w) {
        return r < 1 || r > h || c < 1 || c > w;
    }

    /**
     * Simple immutable class representing a coordinate.
     */
    private static class Point {
        final int r, c;

        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }
}

