            int minCost = pathfinder.findMinimumCost(startRow, startCol, endRow, endCol);

            System.out.println(minCost);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    /**
     * Represents a specific cell in the grid during traversal.
     */
    record Node(int row, int col, int cost) {}

    /**
     * Logic engine for finding the shortest path using 0-1 BFS.
     */
    static class Pathfinder {
        private final char[][] grid;
        private final int height;
        private final int width;

        // Standard 4-directional movement (Cost: 0)
        private static final int[][] WALK_DIRECTIONS = {
            {0, 1}, {1, 0}, {0, -1}, {-1, 0}
        };

        // Special warp movements (Cost: 1)
        private static final int[][] WARP_DIRECTIONS = {
            {1, 1}, {1, -1}, {-1, 1}, {-1, -1}, {0, 2}, {1, 2}, {2, 2}, {2, 1},
            {2, 0}, {2, -1}, {1, -2}, {0, -2}, {-1, -2}, {-2, -2}, {-2, -1},
            {-2, 0}, {-2, 1}, {-1, 2}, {0, 2}, {2, 2} // Note: Mapped from original arrays
        };

        // Re-mapping the specific original warp arrays to ensure exact logic parity
        private static final int[][] ORIGINAL_WARPS = {
            {1,1}, {1,-1}, {-1,1}, {-1,-1}, {0,2}, {1,2}, {2,2}, {2,1}, 
            {2,0}, {1,-1}, {0,-2}, {-1,-2}, {-2,-2}, {-2,-2}, {-2,-2}, 
            {-2,-1}, {-2,0}, {-1,1}, {0,2}, {2,2}
        };

        // Corrected warp offsets based on the provided input arrays
        private static final int[][] WARP_OFFSETS = {
            {1, 1}, {1, -1}, {-1, 1}, {-1, -1}, {0, 2}, {1, 2}, {2, 2}, {2, 1},
            {2, 0}, {1, -1}, {0, -2}, {-1, -2}, {-2, -2}, {-2, -2}, {-2, -2},
            {-2, -1}, {-2, 0}, {-1, 1}, {0, 2}, {2, 2}
        };

        // Because the original warp arrays were provided as two separate arrays, 
        // we pair them here to maintain logic integrity.
        private static final int[][] ACTUAL_WARPS = {
            {1,1}, {1,-1}, {-1,1}, {-1,-1}, {0,2}, {1,2}, {2,2}, {2,1}, 
            {2,0}, {1,-1}, {0,-2}, {-1,-2}, {-2,-2}, {-2,-2}, {-2,-2}, 
            {-2,-1}, {-2,0}, {-1,1}, {0,2}, {2,2}
        };

        // Actually, let's precisely reconstruct the original's logic:
        private static final int[] W_H = {1,1,-1,-1,0,1,2,2,2,2,2,1,0,-1,-2,-2,-2,-2,-2,-1};
        private static final int[] W_W = {1,-1,1,-1,2,2,2,1,0,-1,-2,-2,-2,-2,-2,-1,0,1,2,2};

        public Pathfinder(char[][] grid, int height, int width) {
            this.grid = grid;
            this.height = height;
            this.width = width;
        }

        /**
         * Finds the minimum cost to travel from start to end using 0-1 BFS.
         * 
         * @return minimum cost, or -1 if unreachable.
         */
        public int findMinimumCost(int startRow, int startCol, int endRow, int endCol) {
            Deque<Node> deque = new ArrayDeque<>();
            int[][] minCostToCell = new int[height][width];

            for (int[] row : minCostToCell) {
                Arrays.fill(row, Integer.MAX_VALUE);
            }

            minCostToCell[startRow][startCol] = 0;
            deque.addFirst(new Node(startRow, startCol, 0));

            while (!deque.isEmpty()) {
                Node current = deque.pollFirst();

                // If we reached the goal, because this is BFS, the first time we 
                // pop the goal, it is guaranteed to be the shortest path.
                if (current.row() == endRow && current.col() == endCol) {
                    return current.cost();
                }

                // Optimization: skip if we've already found a better path to this cell
                if (current.cost() > minCostToCell[current.row()][current.col()]) {
                    continue;
                }

                // 1. Try Walking (Cost 0)
                for (int[] dir : WALK_DIRECTIONS) {
                    processMove(current, current.row() + dir[0], current.col() + dir[1], 0, minCostToCell, deque);
                }

                // 2. Try Warping (Cost 1)
                for (int k = 0; k < W_H.length; k++) {
                    processMove(current, current.row() + W_H[k], current.col() + W_W[k], 1, minCostToCell, deque);
                }
            }

            return -1;
        }

        private void processMove(Node current, int nextRow, int nextCol, int moveCost, int[][] minCostToCell, Deque<Node> deque) {
            if (isValidMove(nextRow, nextCol) && grid[nextRow][nextCol] == '.') {
                int newCost = current.cost() + moveCost;
                if (newCost < minCostToCell[nextRow][nextCol]) {
                    minCostToCell[nextRow][nextCol] = newCost;
                    Node nextNode = new Node(nextRow, nextCol, newCost);

                    // 0-1 BFS logic: 0-cost moves go to the front, 1-cost moves go to the back
                    if (moveCost == 0) {
                        deque.addFirst(nextNode);
                    } else {
                        deque.addLast(nextNode);
                    }
                }
            }
        }

        private boolean isValidMove(int r, int c) {
            return r >= 0 && r < height && c >= 0 && c < width;
        }
    }
}

