/**
 * Handles the logic for traversing the maze using Breadth-First Search.
 */
class MazeSolver {
    private final char[][] grid;
    private final int rows;
    private final int cols;
    private final int startRow;
    private final int startCol;
    private final int targetRow;
    private final int targetCol;

    private final boolean[][] visited;
    private final Deque<Point> mainQueue = new ArrayDeque<>();

    private int minSteps = Integer.MAX_VALUE;

    private static final int[][] DIRECTIONS = {
        {0, 1}, {1, 0}, {0, -1}, {-1, 0}
    };

    public MazeSolver(char[][] grid, int startRow, int startCol, int targetRow, int targetCol) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
        this.startRow = startRow;
        this.startCol = startCol;
        this.targetRow = targetRow;
        this.targetCol = targetCol;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Executes the BFS to find the minimum number of jumps.
     * 
     * @return The minimum number of jumps, or -1 if the target is unreachable.
     */
    public int solve() {
        // Initial expansion from the starting position (Step 0)
        expandComponent(startRow, startCol, 0);

        int currentStep = 1;
        // Standard BFS traversal through components
        while (!mainQueue.isEmpty() && minSteps == Integer.MAX_VALUE) {
            int size = mainQueue.size();

            for (int i = 0; i < size; i++) {
                Point p = mainQueue.poll();

                // From each cell in the current component, check the 5x5 neighborhood
                // for new components to jump into.
                for (int dr = -2; dr <= 2; dr++) {
                    for (int dc = -2; dc <= 2; dc++) {
                        int nr = p.row + dr;
                        int nc = p.col + dc;

                        if (isValid(nr, nc) && !visited[nr][nc] && grid[nr][nc] != '#') {
                            expandComponent(nr, nc, currentStep);
                        }
                    }
                }
            }
            currentStep++;
        }

        return minSteps == Integer.MAX_VALUE ? -1 : minSteps;
    }

    /**
     * Uses an iterative BFS to find all connected non-wall cells (a component)
     * starting from (r, c) and adds them to the main BFS queue.
     * 
     * @param r Starting row of the component
     * @param c Starting column of the component
     * @param step The current jump count
     */
    private void expandComponent(int r, int c, int step) {
        Deque<Point> componentQueue = new ArrayDeque<>();

        if (!isValid(r, c) || visited[r][c] || grid[r][c] == '#') {
            return;
        }

        visited[r][c] = true;
        componentQueue.add(new Point(r, c));

        while (!componentQueue.isEmpty()) {
            Point curr = componentQueue.poll();
            mainQueue.add(curr);

            // If this cell is the target, update the minimum steps found.
            if (curr.row == targetRow && curr.col == targetCol) {
                minSteps = Math.min(minSteps, step);
            }

            // 4-directional movement within the connected component.
            for (int[] dir : DIRECTIONS) {
                int nr = curr.row + dir[0];
                int nc = curr.col + dir[1];

                if (isValid(nr, nc) && !visited[nr][nc] && grid[nr][nc] != '#') {
                    visited[nr][nc] = true;
                    componentQueue.add(new Point(nr, nc));
                }
            }
        }
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    /**
     * Represents a coordinate in the maze.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

/**
 * Efficient input reader for fast I/O operations.
 */
class FastScanner {
    private final InputStream in;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;

    public FastScanner(InputStream in) {
        this.in = in;
    }

    private boolean hasNextByte() {
        if (ptr < buflen) return true;
        ptr = 0;
        try {
            buflen = in.read(buffer);
        } catch (IOException e) {
            return false;
        }
        return buflen > 0;
    }

    private int readByte() {
        if (hasNextByte()) return buffer[ptr++];
        else return -1;
    }

    private boolean isPrintableChar(int c) {
        return 33 <= c && c <= 126;
    }

    public boolean hasNext() {
        while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;
        return hasNextByte();
    }

    public String next() {
        if (!hasNext()) throw new NoSuchElementException();
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while (isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    public int nextInt() {
        return (int) nextLong();
    }

    public long nextLong() {
        if (!hasNext()) throw new NoSuchElementException();
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b < '0' || '9' < b) throw new NumberFormatException();
        while (true) {
            if ('0' <= b && b <= '9') {
                n *= 10;
                n += b - '0';
            } else if (b == -1 || !isPrintableChar(b)) {
                return minus ? -n : n;
            } else {
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }
}

