/**
 * Handles the Dijkstra-based shortest path calculation on a 2D grid.
 */
class GridPathfinder {
    private static final int INF = 1_000_000_000;

    private final int rows;
    private final int cols;
    private final char[][] grid;

    public GridPathfinder(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Finds the shortest path from (startRow, startCol) to (endRow, endCol).
     * The movement rules allow moving to any cell in a 5x5 area around the current cell.
     * Cardinal directions (up, down, left, right) cost 0, while all other moves (diagonal/jumps) cost 1.
     *
     * @return The shortest distance, or -1 if the destination is unreachable.
     */
    public int findShortestPath(int startRow, int startCol, int endRow, int endCol) {
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) {
            Arrays.fill(row, INF);
        }

        PriorityQueue<Node> pq = new PriorityQueue<>();

        distances[startRow][startCol] = 0;
        pq.add(new Node(startRow, startCol, 0));

        while (!pq.isEmpty()) {
            Node current = pq.poll();

            if (current.distance > distances[current.row][current.col]) {
                continue;
            }

            // If we reached the target, we can return early (optimization)
            if (current.row == endRow && current.col == endCol) {
                return current.distance;
            }

            // Explore the 5x5 neighborhood
            for (int dr = -2; dr <= 2; dr++) {
                for (int dc = -2; dc <= 2; dc++) {
                    // Skip the current cell itself
                    if (dr == 0 && dc == 0) continue;

                    int nextRow = current.row + dr;
                    int nextCol = current.col + dc;

                    if (isValidMove(nextRow, nextCol) && grid[nextRow][nextCol] != '#') {
                        int moveCost = isCardinalMove(dr, dc) ? 0 : 1;
                        int newDist = current.distance + moveCost;

                        if (newDist < distances[nextRow][nextCol]) {
                            distances[nextRow][nextCol] = newDist;
                            pq.add(new Node(nextRow, nextCol, newDist));
                        }
                    }
                }
            }
        }

        return distances[endRow][endCol] == INF ? -1 : distances[endRow][endCol];
    }

    private boolean isValidMove(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    private boolean isCardinalMove(int dr, int dc) {
        // A move is cardinal if it changes exactly one coordinate by 1
        return (Math.abs(dr) == 1 && dc == 0) || (Math.abs(dc) == 1 && dr == 0);
    }
}

