class GridMap {
    private final char[][] grid;
    private final int height;
    private final int width;

    public GridMap(char[][] grid, int height, int width) {
        this.grid = grid;
        this.height = height;
        this.width = width;
    }

    public boolean isWalkable(int r, int c) {
        return isWithinBounds(r, c) && grid[r][c] == '.';
    }

    public boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < height && c >= 0 && c < width;
    }

    public int getHeight() { return height; }
    public int getWidth() { return width; }
}

class DijkstraSolver {
    private final GridMap map;
    private static final int INF = Integer.MAX_VALUE;

    public DijkstraSolver(GridMap map) {
        this.map = map;
    }

    /**
     * Finds the minimum cost to travel from start to target using Dijkstra's algorithm.
     */
    public int findShortestPath(int startR, int startC, int targetR, int targetC) {
        int[][] minDistance = new int[map.getHeight()][map.getWidth()];
        for (int[] row : minDistance) {
            Arrays.fill(row, INF);
        }

        PriorityQueue<Node> pq = new PriorityQueue<>();

        minDistance[startR][startC] = 0;
        pq.add(new Node(startR, startC, 0));

        while (!pq.isEmpty()) {
            Node current = pq.poll();

            if (current.row == targetR && current.col == targetC) {
                return current.distance;
            }

            if (current.distance > minDistance[current.row][current.col]) {
                continue;
            }

            exploreNeighbors(current, minDistance, pq);
        }

        return -1; // Path not found
    }

    private void exploreNeighbors(Node current, int[][] minDistance, PriorityQueue<Node> pq) {
        // The problem allows movement in a 5x5 area around the current cell
        for (int dr = -2; dr <= 2; dr++) {
            for (int dc = -2; dc <= 2; dc++) {
                if (dr == 0 && dc == 0) continue;

                int nextR = current.row + dr;
                int nextC = current.col + dc;

                if (map.isWalkable(nextR, nextC)) {
                    int moveCost = calculateCost(dr, dc);
                    int newDist = current.distance + moveCost;

                    if (newDist < minDistance[nextR][nextC]) {
                        minDistance[nextR][nextC] = newDist;
                        pq.add(new Node(nextR, nextC, newDist));
                    }
                }
            }
        }
    }

    /**
     * Rules based on original logic:
     * Orthogonal moves of exactly 1 step cost 0.
     * All other moves within the 5x5 area cost 1.
     */
    private int calculateCost(int dr, int dc) {
        boolean isOrthogonalOneStep = (Math.abs(dr) == 1 && dc == 0) || (Math.abs(dc) == 1 && dr == 0);
        return isOrthogonalOneStep ? 0 : 1;
    }
}

