 */
record Node(int row, int col, int cost) {}

/**
 * Solves the problem of finding the minimum cost to traverse a grid.
 * Uses a 0-1 Breadth-First Search (BFS) algorithm.
 */
class GridPathfinder {
    private static final int COST_ADJACENT = 0;
    private static final int COST_JUMP = 1;

    /**
     * Finds the minimum cost to travel from a starting position to a target position.
     *
     * @param grid      The 2D character grid representing the field.
     * @param startRow  Starting row index.
     * @param startCol  Starting column index.
     * @param targetRow Target row index.
     * @param targetCol Target column index.
     * @return The minimum cost to reach the target, or -1 if unreachable.
     */
    public int findMinimumCost(char[][] grid, int startRow, int startCol, int targetRow, int targetCol) {
        int rows = grid.length;
        int cols = grid[0].length;

        // Distance array to keep track of the minimum cost to reach each cell.
        int[][] minDistance = new int[rows][cols];
        for (int[] row : minDistance) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }

        Deque<Node> deque = new ArrayDeque<>();

        // Initialize the starting position.
        minDistance[startRow][startCol] = 0;
        deque.add(new Node(startRow, startCol, 0));

        while (!deque.isEmpty()) {
            Node current = deque.pollFirst();

            // Optimization: If we found a path to the target, return it immediately.
            if (current.row() == targetRow && current.col() == targetCol) {
                return current.cost();
            }

            // If we have already found a better path to this node, skip processing.
            if (current.cost() > minDistance[current.row()][current.col()]) {
                continue;
            }

            // Explore all possible moves in a 5x5 area around the current cell.
            for (int dr = -2; dr <= 2; dr++) {
                for (int dc = -2; dc <= 2; dc++) {
                    // Skip the current cell itself.
                    if (dr == 0 && dc == 0) continue;

                    int nextRow = current.row() + dr;
                    int nextCol = current.col() + dc;

                    if (isValidMove(grid, rows, cols, nextRow, nextCol)) {
                        // Movement weight: 0 for direct orthogonal neighbors, 1 for others.
                        int weight = isOrthogonal(dr, dc) ? COST_ADJACENT : COST_JUMP;
                        int newCost = current.cost() + weight;

                        if (newCost < minDistance[nextRow][nextCol]) {
                            minDistance[nextRow][nextCol] = newCost;
                            Node nextNode = new Node(nextRow, nextCol, newCost);

                            // 0-1 BFS optimization: weight 0 goes to front, weight 1 goes to back.
                            if (weight == COST_ADJACENT) {
                                deque.addFirst(nextNode);
                            } else {
                                deque.addLast(nextNode);
                            }
                        }
                    }
                }
            }
        }

        return -1; // Target is unreachable.
    }

    private boolean isValidMove(char[][] grid, int rows, int cols, int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '.';
    }

    private boolean isOrthogonal(int dr, int dc) {
        return Math.abs(dr) + Math.abs(dc) == 1;
    }
}

