/**
 * Handles the input parsing and execution of the pathfinding algorithm.
 */
class PathfindingEngine {
    private static final int INF = Integer.MAX_VALUE;
    private static final int UNREACHABLE_THRESHOLD = 5_000_000;

    // Movement directions for cost 0: Up, Down, Left, Right
    private static final int[][] ORTHOGONAL_MOVES = {
        {1, 0}, {-1, 0}, {0, 1}, {0, -1}
    };

    // Movement directions for cost 1: All cells in a 5x5 window excluding the center (0,0)
    private static final List<int[]> EXTENDED_MOVES = new ArrayList<>();

    static {
        for (int dr = -2; dr <= 2; dr++) {
            for (int dc = -2; dc <= 2; dc++) {
                if (dr == 0 && dc == 0) continue;
                EXTENDED_MOVES.add(new int[]{dr, dc});
            }
        }
    }

    private final Scanner scanner;

    public PathfindingEngine(Scanner scanner) {
        this.scanner = scanner;
    }

    /**
     * Reads input and initiates the pathfinding logic.
     */
    public void execute() {
        if (!scanner.hasNextInt()) return;

        int height = scanner.nextInt();
        int width = scanner.nextInt();

        // Coordinates are provided as 1-indexed; convert to 0-indexed
        int startRow = scanner.nextInt() - 1;
        int startCol = scanner.nextInt() - 1;
        int targetRow = scanner.nextInt() - 1;
        int targetCol = scanner.nextInt() - 1;

        boolean[][] isWalkable = new boolean[height][width];
        for (int r = 0; r < height; r++) {
            String rowStr = scanner.next();
            for (int c = 0; c < width; c++) {
                // '#' represents a wall (not walkable)
                isWalkable[r][c] = (rowStr.charAt(c) != '#');
            }
        }

        int minCost = findMinCost(height, width, isWalkable, startRow, startCol, targetRow, targetCol);
        System.out.println(minCost);
    }

    /**
     * Implementation of Dijkstra's algorithm to find the shortest path.
     */
    private int findMinCost(int height, int width, boolean[][] isWalkable, 
                            int startR, int startC, int targetR, int targetC) {

        int[][] minCosts = new int[height][width];
        for (int[] row : minCosts) {
            Arrays.fill(row, INF);
        }

        PriorityQueue<Node> priorityQueue = new PriorityQueue<>();

        // Boundary and walkability check for starting point
        if (isWithinBounds(startR, startC, height, width) && isWalkable[startR][startC]) {
            minCosts[startR][startC] = 0;
            priorityQueue.add(new Node(startR, startC, 0));
        }

        while (!priorityQueue.isEmpty()) {
            Node current = priorityQueue.poll();

            // If we found a shorter path to this node already, skip processing
            if (current.cost > minCosts[current.r][current.c]) {
                continue;
            }

            // 1. Try orthogonal moves (cost 0)
            for (int[] move : ORTHOGONAL_MOVES) {
                relax(current.r + move[0], current.c + move[1], current.cost, 
                      height, width, isWalkable, minCosts, priorityQueue);
            }

            // 2. Try extended moves (cost 1)
            for (int[] move : EXTENDED_MOVES) {
                relax(current.r + move[0], current.c + move[1], current.cost + 1, 
                      height, width, isWalkable, minCosts, priorityQueue);
            }
        }

        int result = minCosts[targetR][targetC];
        return (result >= UNREACHABLE_THRESHOLD) ? -1 : result;
    }

    /**
     * Standard Dijkstra relaxation step.
     */
    private void relax(int nr, int nc, int newCost, int height, int width, 
                       boolean[][] isWalkable, int[][] minCosts, PriorityQueue<Node> pq) {
        if (isWithinBounds(nr, nc, height, width) && isWalkable[nr][nc]) {
            if (newCost < minCosts[nr][nc]) {
                minCosts[nr][nc] = newCost;
                pq.add(new Node(nr, nc, newCost));
            }
        }
    }

    private boolean isWithinBounds(int r, int c, int height, int width) {
        return r >= 0 && r < height && c >= 0 && c < width;
    }

    /**
     * Represents a coordinate and its associated cost in the PriorityQueue.
     */
    private static class Node implements Comparable<Node> {
        final int r, c, cost;

        Node(int r, int c, int cost) {
            this.r = r;
            this.c = c;
            this.cost = cost;
        }

        @Override
        public int compareTo(Node other) {
            return Integer.compare(this.cost, other.cost);
        }
    }
}

