/**
 * Handles the pathfinding logic using Dijkstra's algorithm.
 */
class MazeSolver {
    private final int height;
    private final int width;
    private final char[][] grid;

    // Direction vectors for 8-way movement: 
    // First 4 are orthogonal (Up, Down, Left, Right), last 4 are diagonal.
    private static final int[] DR = {-1, 1, 0, 0, -1, -1, 1, 1};
    private static final int[] DC = {0, 0, -1, 1, -1, 1, -1, 1};

    // Cost mapping: orthogonal moves cost 0, diagonal moves cost 1
    private static final int[] MOVE_COSTS = {0, 0, 0, 0, 1, 1, 1, 1};
    private static final char ROAD = '.';

    /**
     * Represents a point in the grid with its associated cost.
     */
    private static class Node {
        final int r;
        final int c;
        final int cost;

        Node(int r, int c, int cost) {
            this.r = r;
            this.c = c;
            this.cost = cost;
        }
    }

    public MazeSolver(int height, int width, char[][] grid) {
        this.height = height;
        this.width = width;
        this.grid = grid;
    }

    /**
     * Finds the shortest path where cost is defined by the number of diagonal moves.
     * 
     * @return The minimum number of diagonal moves, or -1 if no path exists.
     */
    public int findMinimumDiagonalMoves(int startR, int startC, int endR, int endC) {
        // Boundary check for start/end points
        if (isInvalid(startR, startC) || isInvalid(endR, endC)) {
            return -1;
        }

        int[][] minCosts = new int[height][width];
        for (int[] row : minCosts) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }

        PriorityQueue<Node> priorityQueue = new PriorityQueue<>(Comparator.comparingInt(n -> n.cost));

        minCosts[startR][startC] = 0;
        priorityQueue.add(new Node(startR, startC, 0));

        while (!priorityQueue.isEmpty()) {
            Node current = priorityQueue.poll();

            // If we found a better path already, skip this node
            if (current.cost > minCosts[current.r][current.c]) {
                continue;
            }

            // Target reached
            if (current.r == endR && current.c == endC) {
                return current.cost;
            }

            // Explore neighbors
            for (int i = 0; i < 8; i++) {
                int nextR = current.r + DR[i];
                int nextC = current.c + DC[i];

                if (isValidRoad(nextR, nextC)) {
                    int newCost = current.cost + MOVE_COSTS[i];
                    if (newCost < minCosts[nextR][nextC]) {
                        minCosts[nextR][nextC] = newCost;
                        priorityQueue.add(new Node(nextR, nextC, newCost));
                    }
                }
            }
        }

        return minCosts[endR][endC] == Integer.MAX_VALUE ? -1 : minCosts[endR][endC];
    }

    private boolean isValidRoad(int r, int c) {
        return r >= 0 && r < height && c >= 0 && c < width && grid[r][c] == ROAD;
    }

    private boolean isInvalid(int r, int c) {
        return r < 0 || r >= height || c < 0 || c >= width || grid[r][c] != ROAD;
    }
}

