/**
 * Represents the game map/grid.
 */
class Grid {
    private final int height;
    private final int width;
    private final char[][] cells;

    public Grid(int height, int width, char[][] cells) {
        this.height = height;
        this.width = width;
        this.cells = cells;
    }

    public boolean isWalkable(int row, int col) {
        return row >= 0 && row < height && 
               col >= 0 && col < width && 
               cells[row][col] == '.';
    }

    public int getHeight() { return height; }
    public int getWidth() { return width; }
}

/**
 * Logic for finding the shortest path using Dijkstra's algorithm.
 */
class PathFinder {
    private static final int SEARCH_RANGE = 2;

    public int findMinimumCost(Grid grid, Coordinate start, Coordinate destination) {
        PriorityQueue<Node> priorityQueue = new PriorityQueue<>();
        boolean[][] visited = new boolean[grid.getHeight()][grid.getWidth()];

        priorityQueue.add(new Node(start.getRow(), start.getCol(), 0));

        while (!priorityQueue.isEmpty()) {
            Node current = priorityQueue.poll();

            if (visited[current.getRow()][current.getCol()]) {
                continue;
            }
            visited[current.getRow()][current.getCol()] = true;

            // Check if we reached the destination
            if (current.getRow() == destination.getRow() && 
                current.getCol() == destination.getCol()) {
                return current.getCost();
            }

            exploreNeighbors(grid, current, priorityQueue, visited);
        }

        return -1; // Path not found
    }

    private void exploreNeighbors(Grid grid, Node current, PriorityQueue<Node> pq, boolean[][] visited) {
        for (int dr = -SEARCH_RANGE; dr <= SEARCH_RANGE; dr++) {
            for (int dc = -SEARCH_RANGE; dc <= SEARCH_RANGE; dc++) {
                if (dr == 0 && dc == 0) continue;

                int nextRow = current.getRow() + dr;
                int nextCol = current.getCol() + dc;

                if (grid.isWalkable(nextRow, nextCol)) {
                    // Orthogonal moves (Manhattan distance 1) cost 0, others cost 1
                    int moveCost = (Math.abs(dr) + Math.abs(dc) == 1) ? 0 : 1;
                    pq.add(new Node(nextRow, nextCol, current.getCost() + moveCost));
                }
            }
        }
    }
}

/**
 * Utility class for fast I/O operations.
 */
class FastScanner {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastScanner(InputStream in) {
        reader = new BufferedReader(new InputStreamReader(in));
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }
}

