import java.util.*;

/**
 * The GridNavigator class provides a way to find the shortest path in a grid
 * where movement involves "jumps" from cells that are connected to walls.
 */
class GridNavigator {

    private static final int UNVISITED = -1;
    private static final int WALL = -2;

    private final int height;
    private final int width;
    private final char[][] grid;
    private final int[][] componentId;
    private final List<Component> components;

    /**
     * Represents a connected component of non-wall cells.
     */
    private static class Component {
        final int id;
        final List<Point> cells = new ArrayList<>();
        boolean isWallAdjacent = false;

        Component(int id) {
            this.id = id;
        }
    }

    /**
     * Represents a coordinate in the grid.
     */
    private record Point(int row, int col) {}

    public GridNavigator(int height, int width, char[][] grid) {
        this.height = height;
        this.width = width;
        this.grid = grid;
        this.componentId = new int[height][width];
        for (int[] row : componentId) {
            Arrays.fill(row, -1);
        }
        this.components = new ArrayList<>();
        precomputeComponents();
    }

    /**
     * Pre-calculates connected components of non-wall cells and identifies
     * which components are adjacent to at least one wall ('#').
     */
    private void precomputeComponents() {
        int currentId = 0;
        for (int r = 0; r < height; r++) {
            for (int c = 0; c < width; c++) {
                if (grid[r][c] != '#' && componentId[r][c] == -1) {
                    Component comp = new Component(currentId++);
                    bfsLabelComponent(r, c, comp);
                    components.add(comp);
                }
            }
        }
    }

    private void bfsLabelComponent(int startR, int startC, Component comp) {
        Queue<Point> queue = new ArrayDeque<>();
        Point start = new Point(startR, startC);
        queue.add(start);
        componentId[startR][startC] = comp.id;

        int[] dr = {0, 0, 1, -1};
        int[] dc = {1, -1, 0, 0};

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            comp.cells.add(curr);

            // Check if this cell is adjacent to a wall
            for (int i = 0; i < 4; i++) {
                int nr = curr.row + dr[i];
                int nc = curr.col + dc[i];
                if (isValid(nr, nc)) {
                    if (grid[nr][nc] == '#') {
                        comp.isWallAdjacent = true;
                    } else if (componentId[nr][nc] == -1) {
                        componentId[nr][nc] = comp.id;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
        }
    }

    /**
     * Finds the shortest path from start to target using a BFS approach.
     * Movement is possible via jumps from components that are wall-adjacent.
     */
    public int findShortestPath(int startR, int startC, int targetR, int targetC) {
        if (grid[startR][startC] == '#' || grid[targetR][targetC] == '#') {
            return -1;
        }

        int[][] dist = new int[height][width];
        for (int[] row : dist) {
            Arrays.fill(row, UNVISITED);
        }

        boolean[] visitedComponent = new boolean[components.size()];
        Queue<Point> queue = new ArrayDeque<>();

        Point start = new Point(startR, startC);
        dist[startR][startC] = 0;
        queue.add(start);

        while (!queue.isEmpty()) {
            Point curr = queue.poll();
            int cid = componentId[curr.row][curr.col];

            if (cid == -1 || visitedComponent[cid]) {
                continue;
            }
            visitedComponent[cid] = true;
            Component comp = components.get(cid);
            int currentDist = dist[curr.row][curr.col];

            // All cells in the same component are reachable at the same distance
            for (Point cell : comp.cells) {
                if (dist[cell.row][cell.col] == UNVISITED) {
                    dist[cell.row][cell.col] = currentDist;
                }
                if (cell.row == targetR && cell.col == targetC) {
                    return currentDist;
                }
            }

            // If the component is wall-adjacent, we can jump from any cell in it
            if (comp.isWallAdjacent) {
                for (Point cell : comp.cells) {
                    for (int dr = -2; dr <= 2; dr++) {
                        for (int dc = -2; dc <= 2; dc++) {
                            int nr = cell.row + dr;
                            int nc = cell.col + dc;
                            if (isValid(nr, nc) && grid[nr][nc] != '#' && dist[nr][nc] == UNVISITED) {
                                dist[nr][nc] = currentDist + 1;
                                queue.add(new Point(nr, nc));
                            }
                        }
                    }
                }
            }
        }

        return -1;
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < height && c >= 0 && c < width;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) return;
        int h = sc.nextInt();
        int w = sc.nextInt();
        int startR = sc.nextInt() - 1;
        int startC = sc.nextInt() - 1;
        int targetR = sc.nextInt() - 1;
        int targetC = sc.nextInt() - 1;

        char[][] grid = new char[h][w];
        for (int i = 0; i < h; i++) {
            grid[i] = sc.next().toCharArray();
        }

        GridNavigator navigator = new GridNavigator(h, w, grid);
        int result = navigator.findShortestPath(startR, startC, targetR, targetC);

        System.out.println(result);
        sc.close();
    }
}

