        private final int width;
        private final char[][] cells;

        public Grid(int height, int width, String[] rows) {
            this.height = height;
            this.width = width;
            this.cells = new char[height][width];
            for (int i = 0; i < height; i++) {
                this.cells[i] = rows[i].toCharArray();
            }
        }

        public boolean isValidMove(int r, int c) {
            return r >= 0 && r < height && c >= 0 && c < width && cells[r][c] != OBSTACLE;
        }

        public int getHeight() { return height; }
        public int getWidth() { return width; }
    }

    /**
     * Represents a specific state in the pathfinding search.
     * Using a record ensures immutability, which is crucial for priority queue stability.
     */
    record Node(int row, int col, int cost) {}

    // --- Logic ---

    /**
     * Service responsible for implementing the Dijkstra pathfinding algorithm.
     */
    static class Pathfinder {
        private static final int SEARCH_RADIUS = 2;
        private static final int UNREACHABLE = -1;
        private static final int INF = Integer.MAX_VALUE;

        private final Grid grid;

        public Pathfinder(Grid grid) {
            this.grid = grid;
        }

        /**
         * Calculates the minimum cost to travel from start to target.
         * 
         * @return minimum cost, or -1 if no path exists.
         */
        public int findMinimumCost(int startRow, int startCol, int targetRow, int targetCol) {
            int[][] minCosts = new int[grid.getHeight()][grid.getWidth()];
            for (int[] row : minCosts) {
                Arrays.fill(row, INF);
            }

            PriorityQueue<Node> pq = new PriorityQueue<>(Comparator.comparingInt(Node::cost));

            // Initialize start position
            minCosts[startRow][startCol] = 0;
            pq.add(new Node(startRow, startCol, 0));

            while (!pq.isEmpty()) {
                Node current = pq.poll();

                // Optimization: If we reach the target, Dijkstra guarantees this is the minimum cost
                if (current.row() == targetRow && current.col() == targetCol) {
                    return current.cost();
                }

                // If we found a better path to this cell already, skip this stale entry
                if (current.cost() > minCosts[current.row()][current.col()]) {
                    continue;
                }

                exploreNeighbors(current, minCosts, pq);
            }

            return UNREACHABLE;
        }

        private void exploreNeighbors(Node current, int[][] minCosts, PriorityQueue<Node> pq) {
            for (int dr = -SEARCH_RADIUS; dr <= SEARCH_RADIUS; dr++) {
                for (int dc = -SEARCH_RADIUS; dc <= SEARCH_RADIUS; dc++) {
                    // Skip the cell we are currently on
                    if (dr == 0 && dc == 0) continue;

                    int nr = current.row() + dr;
                    int nc = current.col() + dc;

                    if (grid.isValidMove(nr, nc)) {
                        // Cost logic: Manhattan distance of 1 (orthogonal) costs 0, 
                        // any other move within the radius (diagonal or further) costs 1.
                        int manhattanDist = Math.abs(dr) + Math.abs(dc);
                        int movementCost = (manhattanDist > 1) ? 1 : 0;
                        int newCost = current.cost() + movementCost;

                        if (newCost < minCosts[nr][nc]) {
                            minCosts[nr][nc] = newCost;
                            pq.add(new Node(nr, nc, newCost));
                        }
                    }
                }
            }
        }
    }

    // --- Utilities ---

    /**
     * Fast I/O utility for efficient reading of large inputs.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner(InputStream in) {
            this.reader = new BufferedReader(new InputStreamReader(in));
            this.tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }
    }
}

