 */
public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        // Read dimensions
        int height = scanner.nextInt();
        int width = scanner.nextInt();

        // Read start and end coordinates (converting from 1-based to 0-based indexing)
        int startRow = scanner.nextInt() - 1;
        int startCol = scanner.nextInt() - 1;
        int endRow = scanner.nextInt() - 1;
        int endCol = scanner.nextInt() - 1;

        // Read the maze layout
        char[][] maze = new char[height][width];
        for (int i = 0; i < height; i++) {
            String rowStr = scanner.next();
            for (int j = 0; j < width; j++) {
                maze[i][j] = rowStr.charAt(j);
            }
        }
        scanner.close();

        // Initialize and execute the solver
