/**
 * Represents a coordinate point in the grid with its associated traversal depth.
 */
record Point(int row, int col, int depth) {}

/**
 * Handles the pathfinding logic on a 2D grid.
 */
class GridPathfinder {
    private final int rows;
    private final int cols;
    private final int targetRow;
    private final int targetCol;
    private final char[][] grid;
    private final boolean[][] visited;

    // Directional offsets for orthogonal movement (Up, Down, Left, Right)
    private static final int[][] DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    public GridPathfinder(int rows, int cols, int startRow, int startCol, 
                          int targetRow, int targetCol, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.targetRow = targetRow;
        this.targetCol = targetCol;
        this.grid = grid;
        this.visited = new boolean[rows][cols];
    }

    /**
     * Executes the specialized BFS algorithm.
     * @return The minimum number of jumps required, or -1 if unreachable.
     */
    public int solve(int startRow, int startCol) {
        if (grid[startRow][startCol] == '#') {
            return -1;
        }

        Deque<Point> currentLevelNodes = new ArrayDeque<>();
        currentLevelNodes.add(new Point(startRow, startCol, 0));
        visited[startRow][startCol] = true;

        while (!currentLevelNodes.isEmpty()) {
            // Phase 1: Flood Fill
            // Expand all orthogonally connected '.' cells from the current level.
            Deque<Point> floodFillQueue = new ArrayDeque<>(currentLevelNodes);
            Deque<Point> jumpSources = new ArrayDeque<>();

            while (!floodFillQueue.isEmpty()) {
                Point curr = floodFillQueue.poll();
                jumpSources.add(curr);

                for (int[] dir : DIRECTIONS) {
                    int nr = curr.row() + dir[0];
                    int nc = curr.col() + dir[1];

                    if (isWithinBounds(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                        visited[nr][nc] = true;
                        floodFillQueue.add(new Point(nr, nc, curr.depth()));
                    }
                }
            }

            // Phase 2: Jump
            // From all cells reached in the flood fill, jump to any '.' within a 5x5 area.
            currentLevelNodes.clear();
            while (!jumpSources.isEmpty()) {
                Point curr = jumpSources.poll();

                // Check if we reached the target during the flood fill phase
                if (curr.row() == targetRow && curr.col() == targetCol) {
                    return curr.depth();
                }

                // Explore 5x5 window for jumps
                for (int dr = -2; dr <= 2; dr++) {
                    for (int dc = -2; dc <= 2; dc++) {
                        int nr = curr.row() + dr;
                        int nc = curr.col() + dc;

                        if (isWithinBounds(nr, nc) && grid[nr][nc] == '.' && !visited[nr][nc]) {
                            visited[nr][nc] = true;
                            // Jumping increments the depth level
                            currentLevelNodes.add(new Point(nr, nc, curr.depth() + 1));
                        }
                    }
                }
            }
        }

        return -1;
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }
}

