class GridPathfinder {

    private final char[][] grid;
    private final int height;
    private final int width;

    private static final int INF = Integer.MAX_VALUE;

    /**
     * Represents a coordinate in the grid.
     */
    private static class Node {
        final int x, y;

        Node(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public GridPathfinder(char[][] grid, int height, int width) {
        this.grid = grid;
        this.height = height;
        this.width = width;
    }

    /**
     * Finds the shortest path using a 0-1 Breadth-First Search.
     * 
     * @param sx Start X (1-indexed)
     * @param sy Start Y (1-indexed)
     * @param ex End X (1-indexed)
     * @param ey End Y (1-indexed)
     * @return The minimum cost to reach the destination, or -1 if unreachable.
     */
    public int findShortestPath(int sx, int sy, int ex, int ey) {
        // Convert 1-based indexing to 0-based
        int startX = sx - 1;
        int startY = sy - 1;
        int endX = ex - 1;
        int endY = ey - 1;

        // Boundary and validity check for start/end
        if (!isValid(startX, startY) || !isValid(endX, endY)) {
            return -1;
        }

        int[][] dist = new int[height][width];
        for (int[] row : dist) {
            Arrays.fill(row, INF);
        }

        Deque<Node> deque = new ArrayDeque<>();

        dist[startX][startY] = 0;
        deque.addFirst(new Node(startX, startY));

        int[] dx = {0, 1, 0, -1};
        int[] dy = {-1, 0, 1, 0};

        while (!deque.isEmpty()) {
            Node current = deque.pollFirst();
            int curX = current.x;
            int curY = current.y;

            // If we reached the destination, we can return immediately 
            // because 0-1 BFS guarantees the first pop is the shortest path.
            if (curX == endX && curY == endY) {
                return dist[curX][curY];
            }

            // 1. Free Moves: Adjacent cells (Cost 0)
            for (int i = 0; i < 4; i++) {
                int nextX = curX + dx[i];
                int nextY = curY + dy[i];

                if (isValid(nextX, nextY) && dist[nextX][nextY] > dist[curX][curY]) {
                    dist[nextX][nextY] = dist[curX][curY];
                    deque.addFirst(new Node(nextX, nextY));
                }
            }

            // 2. Magic Moves: 5x5 Area (Cost 1)
            for (int i = -2; i <= 2; i++) {
                for (int j = -2; j <= 2; j++) {
                    int nextX = curX + i;
                    int nextY = curY + j;

                    if (isValid(nextX, nextY) && dist[nextX][nextY] > dist[curX][curY] + 1) {
                        dist[nextX][nextY] = dist[curX][curY] + 1;
                        deque.addLast(new Node(nextX, nextY));
                    }
                }
            }
        }

        return dist[endX][endY] == INF ? -1 : dist[endX][endY];
    }

    /**
     * Checks if the given coordinates are within grid bounds and not a wall.
     */
    private boolean isValid(int x, int y) {
        return x >= 0 && x < height && y >= 0 && y < width && grid[x][y] != '#';
    }
}

