import java.util.Arrays;
import java.util.Deque;
import java.util.StringTokenizer;

/**
 * A program to find the shortest path in a grid using a 0-1 BFS algorithm.
 * Some moves (adjacent) have a cost of 0, while others (within a 5x5 area) have a cost of 1.
 */
public class Main {

    public static void main(String[] args) {
        FastScanner scanner = new FastScanner();

        try {
            int height = scanner.nextInt();
            int width = scanner.nextInt();

            // Coordinates are 1-indexed in input, converting to 0-indexed
            int startY = scanner.nextInt() - 1;
            int startX = scanner.nextInt() - 1;
            int endY = scanner.nextInt() - 1;
            int endX = scanner.nextInt() - 1;

            char[][] grid = new char[height][width];
            for (int y = 0; y < height; y++) {
                grid[y] = scanner.next().toCharArray();
            }

            GridNavigator navigator = new GridNavigator(height, width, grid);
            int shortestPath = navigator.findShortestPath(new Point(startX, startY), new Point(endX, endY));

            System.out.println(shortestPath);

        } catch (Exception e) {
            // In a production environment, use a logger.
            e.printStackTrace();
        }
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Handles the pathfinding logic on the grid.
     */
    static class GridNavigator {
        private static final int INF = 1_000_000_000;
        private static final char OBSTACLE = '#';
        private static final int[] DX = {-1, 1, 0, 0};
        private static final int[] DY = {0, 0, -1, 1};

        private final int height;
        private final int width;
        private final char[][] grid;

        public GridNavigator(int height, int width, char[][] grid) {
            this.height = height;
            this.width = width;
            this.grid = grid;
        }

        /**
         * Uses 0-1 BFS to find the shortest path.
         * 
         * @param start The starting Point.
         * @param end The target Point.
         * @return The minimum distance, or -1 if unreachable.
         */
        public int findShortestPath(Point start, Point end) {
            int[][] dist = new int[height][width];
            for (int[] row : dist) {
                Arrays.fill(row, INF);
            }

            Deque<Point> deque = new ArrayDeque<>();

            dist[start.y][start.x] = 0;
            deque.addFirst(start);

            while (!deque.isEmpty()) {
                Point current = deque.pollFirst();

                // 1. Weight-0 Moves: Move to adjacent cells (up, down, left, right)
                for (int i = 0; i < 4; i++) {
                    int nx = current.x + DX[i];
                    int ny = current.y + DY[i];

                    if (isValid(nx, ny) && dist[ny][nx] > dist[current.y][current.x]) {
                        dist[ny][nx] = dist[current.y][current.x];
                        deque.addFirst(new Point(nx, ny));
                    }
                }

                // 2. Weight-1 Moves: Move to any cell within a 5x5 area
                for (int dy = -2; dy <= 2; dy++) {
                    for (int dx = -2; dx <= 2; dx++) {
                        int nx = current.x + dx;
                        int ny = current.y + dy;

                        if (isValid(nx, ny) && dist[ny][nx] > dist[current.y][current.x] + 1) {
                            dist[ny][nx] = dist[current.y][current.x] + 1;
                            deque.addLast(new Point(nx, ny));
                        }
                    }
                }
            }

            int result = dist[end.y][end.x];
            return result >= INF ? -1 : result;
        }

        private boolean isValid(int x, int y) {
            return y >= 0 && y < height && x >= 0 && x < width && grid[y][x] != OBSTACLE;
        }
    }

    /**
     * Utility class for fast input reading.
     */
    static class FastScanner {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastScanner() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

