            // Read grid dimensions
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            // Read start coordinates (converting 1-based to 0-based)
            int startRow = reader.nextInt() - 1;
            int startCol = reader.nextInt() - 1;

            // Read target coordinates (converting 1-based to 0-based)
            int targetRow = reader.nextInt() - 1;
            int targetCol = reader.nextInt() - 1;

            // Read the grid
            boolean[][] isObstacle = new boolean[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    if (line.charAt(j) == '#') {
                        isObstacle[i][j] = true;
                    }
                }
            }

            // Execute pathfinding
            GridPathfinder pathfinder = new GridPathfinder(rows, cols, isObstacle);
            int minCost = pathfinder.findShortestPath(startRow, startCol, targetRow, targetCol);

            // Output result
            out.println(minCost == Integer.MAX_VALUE ? "-1" : minCost);

        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Represents a coordinate on the grid.
     */
    record Point(int r, int c) {}

    /**
     * Logic for finding the shortest path on the grid.
     */
    static class GridPathfinder {
        private final int rows;
        private final int cols;
        private final boolean[][] isObstacle;

        // Moves with weight 0 (adjacent cells)
        private static final int[][] ZERO_COST_OFFSETS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
        };

        // Moves with weight 1 (diagonals and extended jumps)
        private static final int[][] ONE_COST_OFFSETS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}, // Redundant but maintains original behavior
            {-1, -1}, {-1, 1}, {1, -1}, {1, 1},
            {-2, -2}, {-2, -1}, {-2, 0}, {-2, 1}, {-2, 2},
            {-1, -2}, {0, -2}, {1, -2}, {2, -2}, {2, -1}, {2, 0}, {2, 1}, {2, 2},
            {-1, 2}, {0, 2}, {1, 2}
        };

        public GridPathfinder(int rows, int cols, boolean[][] isObstacle) {
            this.rows = rows;
            this.cols = cols;
            this.isObstacle = isObstacle;
        }

        /**
         * Finds the shortest path using 0-1 BFS.
         * @return the minimum cost to reach target, or Integer.MAX_VALUE if unreachable.
         */
        public int findShortestPath(int startR, int startC, int targetR, int targetC) {
            int[][] distance = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                Arrays.fill(distance[i], Integer.MAX_VALUE);
            }

            Deque<Point> deque = new ArrayDeque<>();

            // Initialize start position
            distance[startR][startC] = 0;
            deque.addFirst(new Point(startR, startC));

            while (!deque.isEmpty()) {
                Point current = deque.pollFirst();

                // Process 0-cost moves
                for (int[] offset : ZERO_COST_OFFSETS) {
                    int nr = current.r() + offset[0];
                    int nc = current.c() + offset[1];

                    if (isValid(nr, nc) && distance[nr][nc] > distance[current.r()][current.c()]) {
                        distance[nr][nc] = distance[current.r()][current.c()];
                        deque.addFirst(new Point(nr, nc));
                    }
                }

                // Process 1-cost moves
                for (int[] offset : ONE_COST_OFFSETS) {
                    int nr = current.r() + offset[0];
                    int nc = current.c() + offset[1];

                    if (isValid(nr, nc) && distance[nr][nc] > distance[current.r()][current.c()] + 1) {
                        distance[nr][nc] = distance[current.r()][current.c()] + 1;
                        deque.addLast(new Point(nr, nc));
                    }
                }
            }

            return distance[targetR][targetC];
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && !isObstacle[r][c];
        }
    }

    /**
     * Optimized reader for fast I/O operations.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }
    }
}

import java.util.*;

/**
 * Represents a single point in the grid during the search process.
 * Using a record ensures immutability and reduces boilerplate.
 */
record Node(int row, int col, int distance) implements Comparable<Node> {
    @Override
    public int compareTo(Node other) {
        return Integer.compare(this.distance, other.distance);
    }
}

/**
 * Handles the grid-based shortest path calculation using Dijkstra's algorithm.
 */
class GridPathfinder {
    private static final int[] DIRECTION_ROW_OFFSETS = {0, 1, 0, -1};
    private static final int[] DIRECTION_COL_OFFSETS = {-1, 0, 1, 0};
    private static final int JUMP_RANGE = 2; // Radius for the 5x5 jump (covers -2 to +2)

    private final int rows;
    private final int cols;
    private final char[][] grid;

    public GridPathfinder(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Finds the shortest path from start to target.
     * 
     * @param startRow Starting row index.
     * @param startCol Starting column index.
     * @param targetRow Target row index.
     * @param targetCol Target column index.
     * @return The minimum distance, or -1 if unreachable.
     */
    public int findShortestPath(int startRow, int startCol, int targetRow, int targetCol) {
        int[][] minDistance = new int[rows][cols];
        boolean[][] visited = new boolean[rows][cols];

        for (int i = 0; i < rows; i++) {
            Arrays.fill(minDistance[i], Integer.MAX_VALUE);
        }

        PriorityQueue<Node> priorityQueue = new PriorityQueue<>();

        minDistance[startRow][startCol] = 0;
        priorityQueue.add(new Node(startRow, startCol, 0));

        while (!priorityQueue.isEmpty()) {
            Node current = priorityQueue.poll();

            if (visited[current.row()][current.col()]) {
                continue;
            }
            visited[current.row()][current.col()] = true;

            // Early exit if target reached
            if (current.row() == targetRow && current.col() == targetCol) {
                return current.distance();
            }

            // 1. Orthogonal movement: Cost 0
            processOrthogonalMoves(current, minDistance, visited, priorityQueue);

            // 2. 5x5 Area jump: Cost 1
            processJumpMoves(current, minDistance, visited, priorityQueue);
        }

        return -1;
    }

    private void processOrthogonalMoves(Node current, int[][] minDistance, boolean[][] visited, PriorityQueue<Node> pq) {
        for (int i = 0; i < 4; i++) {
            int nextRow = current.row() + DIRECTION_ROW_OFFSETS[i];
            int nextCol = current.col() + DIRECTION_COL_OFFSETS[i];

            if (isWalkable(nextRow, nextCol) && !visited[nextRow][nextCol]) {
                // In the original logic, orthogonal movement has a cost of 0
                if (minDistance[nextRow][nextCol] > current.distance()) {
                    minDistance[nextRow][nextCol] = current.distance();
                    pq.add(new Node(nextRow, nextCol, minDistance[nextRow][nextCol]));
                }
            }
        }
    }

    private void processJumpMoves(Node current, int[][] minDistance, boolean[][] visited, PriorityQueue<Node> pq) {
        int jumpCost = current.distance() + 1;

        for (int dr = -JUMP_RANGE; dr <= JUMP_RANGE; dr++) {
            for (int dc = -JUMP_RANGE; dc <= JUMP_RANGE; dc++) {
                int nextRow = current.row() + dr;
                int nextCol = current.col() + dc;

                if (isWalkable(nextRow, nextCol) && !visited[nextRow][nextCol]) {
                    if (minDistance[nextRow][nextCol] > jumpCost) {
                        minDistance[nextRow][nextCol] = jumpCost;
                        pq.add(new Node(nextRow, nextCol, jumpCost));
                    }
                }
            }
        }
    }

    private boolean isWalkable(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] == '.';
    }
}

