import java.util.*;

/**
 * A program to find the minimum number of "jumps" required to traverse a grid.
 * Cardinal moves (up, down, left, right) have a cost of 0.
 * Moves to any cell within a 5x5 area around the current cell have a cost of 1.
 */
public class Main {
    private static final int INF = 1_000_000_000;
    private static final int[] CARDINAL_DR = {-1, 0, 0, 1};
    private static final int[] CARDINAL_DC = {0, -1, 1, 0};

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            if (!scanner.hasNextInt()) return;

            // Parse grid dimensions
            int height = scanner.nextInt();
            int width = scanner.nextInt();

            // Parse coordinates (converting from 1-based to 0-based indexing)
            int startRow = scanner.nextInt() - 1;
            int startCol = scanner.nextInt() - 1;
            int targetRow = scanner.nextInt() - 1;
            int targetCol = scanner.nextInt() - 1;

            // Parse grid structure
            boolean[][] wallMap = new boolean[height][width];
            for (int r = 0; r < height; r++) {
                String line = scanner.next();
                for (int c = 0; c < width; c++) {
                    wallMap[r][c] = (line.charAt(c) == '#');
                }
            }

            Grid grid = new Grid(height, width, wallMap);
            Pathfinder pathfinder = new Pathfinder(grid);

            int minMoves = pathfinder.findMinimumMoves(startRow, startCol, targetRow, targetCol);
            System.out.println(minMoves);
        }
    }

    /**
     * Represents the traversable grid environment.
     */
    static class Grid {
        private final int height;
        private final int width;
        private final boolean[][] walls;

        Grid(int height, int width, boolean[][] walls) {
            this.height = height;
            this.width = width;
            this.walls = walls;
        }

        boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < height && c >= 0 && c < width;
        }

        boolean isWalkable(int r, int c) {
            return isWithinBounds(r, c) && !walls[r][c];
        }

        int getHeight() { return height; }
        int getWidth() { return width; }
    }

    /**
     * Represents a state in the Dijkstra search algorithm.
     */
    static class Node implements Comparable<Node> {
        final int row;
        final int col;
        final int cost;

        Node(int row, int col, int cost) {
            this.row = row;
            this.col = col;
            this.cost = cost;
        }

        @Override
        public int compareTo(Node other) {
            return Integer.compare(this.cost, other.cost);
        }
    }

    /**
     * Encapsulates the pathfinding logic using Dijkstra's algorithm.
     */
    static class Pathfinder {
        private final Grid grid;

        Pathfinder(Grid grid) {
            this.grid = grid;
        }

        /**
         * Calculates the minimum cost to reach the target from the start.
         * 
         * @return minimum cost, or -1 if the target is unreachable.
         */
        int findMinimumMoves(int startR, int startC, int targetR, int targetC) {
            int[][] minCostToReach = new int[grid.getHeight()][grid.getWidth()];
            for (int[] row : minCostToReach) {
                Arrays.fill(row, INF);
            }

            PriorityQueue<Node> priorityQueue = new PriorityQueue<>();

            // Initialization
            minCostToReach[startR][startC] = 0;
            priorityQueue.add(new Node(startR, startC, 0));

            while (!priorityQueue.isEmpty()) {
                Node current = priorityQueue.poll();

                // Standard Dijkstra optimization: skip if we've already found a better path to this node
                if (current.cost > minCostToReach[current.row][current.col]) {
                    continue;
                }

                // Target reached: since we use a PriorityQueue, this is the shortest path
                if (current.row == targetR && current.col == targetC) {
                    return current.cost;
                }

                // 1. Handle Cardinal Moves (Weight: 0)
                // These are movements to adjacent cells that do not increase the jump count.
                for (int i = 0; i < 4; i++) {
                    int nr = current.row + CARDINAL_DR[i];
                    int nc = current.col + CARDINAL_DC[i];

                    if (grid.isWalkable(nr, nc)) {
                        if (current.cost < minCostToReach[nr][nc]) {
                            minCostToReach[nr][nc] = current.cost;
                            priorityQueue.add(new Node(nr, nc, current.cost));
                        }
                    }
                }

                // 2. Handle Jump Moves (Weight: 1)
                // These are movements to any cell within a 5x5 area around the current cell.
                for (int dr = -2; dr <= 2; dr++) {
                    for (int dc = -2; dc <= 2; dc++) {
                        int nr = current.row + dr;
                        int nc = current.col + dc;

                        if (grid.isWalkable(nr, nc)) {
                            int nextCost = current.cost + 1;
                            if (nextCost < minCostToReach[nr][nc]) {
                                minCostToReach[nr][nc] = nextCost;
                                priorityQueue.add(new Node(nr, nc, nextCost));
                            }
                        }
                    }
                }
            }

            return -1;
        }
    }
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/**
 * A program to solve a maze traversal problem using 0-1 Breadth-First Search.
 * The goal is to find the shortest path in a grid where orthogonal moves cost 0 
 * and diagonal or jump moves cost 1.
 */
public class Main {

    public static void main(String[] args) {
        try (FastReader reader = new FastReader(System.in);
             FastWriter writer = new FastWriter(System.out)) {

            // Read dimensions
            int height = reader.nextInt();
            int width = reader.nextInt();

            if (height <= 0 || width <= 0) {
                writer.println(-1);
                return;
            }

            // Read coordinates (converting 1-based indexing to 0-based)
            int startY = reader.nextInt() - 1;
            int startX = reader.nextInt() - 1;
            int goalY = reader.nextInt() - 1;
            int goalX = reader.nextInt() - 1;

            // Read maze grid
            char[][] grid = reader.nextGrid(height);

            // Solve the maze
            MazeSolver solver = new MazeSolver(height, width, grid);
            int result = solver.findShortestPath(startX, startY, goalX, goalY);

            writer.println(result);

        } catch (IOException e) {
            System.err.println("An error occurred during I/O: " + e.getMessage());
        }
    }

    /**
     * Core logic for solving the maze using 0-1 BFS (Dijkstra optimization for weights 0 and 1).
     */
    static class MazeSolver {
        private final int height;
        private final int width;
        private final char[][] grid;

        public MazeSolver(int height, int width, char[][] grid) {
            this.height = height;
            this.width = width;
            this.grid = grid;
        }

        /**
         * Finds the shortest path from (startX, startY) to (goalX, goalY).
         * @return shortest distance, or -1 if unreachable.
         */
        public int findShortestPath(int startX, int startY, int goalX, int goalY) {
            if (isOutOfBounds(startX, startY) || isOutOfBounds(goalX, goalY)) {
                return -1;
            }
            if (startX == goalX && startY == goalY) {
                return 0;
            }

            int[][] distances = new int[height][width];
            for (int[] row : distances) {
                Arrays.fill(row, Integer.MAX_VALUE);
            }

            Deque<Point> deque = new ArrayDeque<>();
            distances[startY][startX] = 0;
            deque.addFirst(new Point(startX, startY));

            while (!deque.isEmpty()) {
                Point current = deque.pollFirst();

                // If we reached the goal, we can return immediately due to BFS properties
                if (current.x == goalX && current.y == goalY) {
                    return distances[current.y][current.x];
                }

                // Explore moves in a 5x5 area around the current point
                for (int dy = -2; dy <= 2; dy++) {
                    for (int dx = -2; dx <= 2; dx++) {
                        if (dx == 0 && dy == 0) continue;

                        int nx = current.x + dx;
                        int ny = current.y + dy;

                        if (isValidMove(nx, ny)) {
                            // Cost logic: Orthogonal moves (dist 1) cost 0, others cost 1
                            int moveCost = (Math.abs(dx) + Math.abs(dy) == 1) ? 0 : 1;
                            int newDistance = distances[current.y][current.x] + moveCost;

                            if (newDistance < distances[ny][nx]) {
                                distances[ny][nx] = newDistance;
                                if (moveCost == 0) {
                                    deque.addFirst(new Point(nx, ny));
                                } else {
                                    deque.addLast(new Point(nx, ny));
                                }
                            }
                        }
                    }
                }
            }

            return -1;
        }

        private boolean isValidMove(int x, int y) {
            return !isOutOfBounds(x, y) && grid[y][x] != '#';
        }

        private boolean isOutOfBounds(int x, int y) {
            return x < 0 || x >= width || y < 0 || y >= height;
        }
    }

    /**
     * Represents a coordinate in the grid.
     */
    static class Point {
        final int x;
        final int y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Fast I/O Reader for efficient input processing.
     */
    static class FastReader implements AutoCloseable {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream in) {
            this.reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
        }

        public String nextString() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(nextString());
        }

        public char[][] nextGrid(int h) throws IOException {
            char[][] grid = new char[h][];
            for (int i = 0; i < h; i++) {
                grid[i] = nextString().toCharArray();
            }
            return grid;
        }

        @Override
        public void close() throws IOException {
            reader.close();
        }
    }

    /**
     * Fast I/O Writer for efficient output processing.
     */
    static class FastWriter implements AutoCloseable {
        private final PrintWriter writer;

        public FastWriter(OutputStream out) {
            this.writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(out, StandardCharsets.UTF_8)));
        }

        public void print(Object obj) {
            writer.print(obj);
        }

        public void println(Object obj) {
            writer.println(obj);
        }

        @Override
        public void close() {
            writer.flush();
            writer.close();
        }
    }
}

