/**
 * A refactored version of the grid shortest path solver.
 * This implementation uses a 0-1 Breadth-First Search (BFS) algorithm to find 
 * the minimum cost to travel between two points on a grid.
 * 
 * Movement rules:
 * - Moving to an adjacent cell (Up, Down, Left, Right) costs 0.
 * - Jumping to any cell within a 5x5 area around the current cell costs 1.
 */
public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        // Read grid dimensions
        int rows = scanner.nextInt();
        int cols = scanner.nextInt();

        // Read start and end coordinates (converting from 1-indexed to 0-indexed)
        int startRow = scanner.nextInt() - 1;
        int startCol = scanner.nextInt() - 1;
        int endRow = scanner.nextInt() - 1;
        int endCol = scanner.nextInt() - 1;

        // Build the grid
        Grid grid = new Grid(rows, cols);
        for (int i = 0; i < rows; i++) {
            String line = scanner.next();
            for (int j = 0; j < cols; j++) {
                // '.' is walkable, anything else (like '#') is an obstacle
                grid.setWalkable(i, j, line.charAt(j) == '.');
            }
        }

        // Calculate the shortest path
        Pathfinder pathfinder = new Pathfinder(grid);
        int minCost = pathfinder.findMinCost(
            new Point(startRow, startCol), 
            new Point(endRow, endCol)
        );

        System.out.println(minCost);
        scanner.close();
    }
}

/**
 * Represents an immutable coordinate on the grid.
 */
final class Point {
    final int r, c;

    Point(int r, int c) {
        this.r = r;
        this.c = c;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Point)) return false;
        Point point = (Point) o;
        return r == point.r && c == point.c;
    }

    @Override
    public int hashCode() {
        return Objects.hash(r, c);
    }
}

/**
 * Encapsulates the grid structure and boundary/walkability logic.
 */
class Grid {
    private final int rows;
    private final int cols;
    private final boolean[][] walkable;

    Grid(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.walkable = new boolean[rows][cols];
    }

    public void setWalkable(int r, int c, boolean isWalkable) {
        walkable[r][c] = isWalkable;
    }

    public boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols;
    }

    public boolean isWalkable(int r, int c) {
        return isWithinBounds(r, c) && walkable[r][c];
    }

    public int getRows() {
        return rows;
    }

    public int getCols() {
        return cols;
    }
}

/**
 * Implements the shortest path algorithm logic.
 */
class Pathfinder {
    private static final int[][] ADJACENT_DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    private static final int JUMP_RADIUS = 2; // Defines the 5x5 area (radius 2)
    private static final int INF = Integer.MAX_VALUE;

    private final Grid grid;

    Pathfinder(Grid grid) {
        this.grid = grid;
    }

    /**
     * Finds the minimum cost to travel from start to end using 0-1 BFS.
     * 
     * @param start The starting coordinate.
     * @param end The destination coordinate.
     * @return The minimum cost, or -1 if the destination is unreachable.
     */
    public int findMinCost(Point start, Point end) {
        // Initial validation
        if (!grid.isWalkable(start.r, start.c) || !grid.isWalkable(end.r, end.c)) {
            return -1;
        }

        int[][] dist = new int[grid.getRows()][grid.getCols()];
        for (int[] row : dist) {
            Arrays.fill(row, INF);
        }

        // Deque is essential for 0-1 BFS: 
        // 0-weight edges are added to the front, 1-weight to the back.
        Deque<Point> deque = new ArrayDeque<>();

        dist[start.r][start.c] = 0;
        deque.addFirst(start);

        while (!deque.isEmpty()) {
            Point current = deque.pollFirst();

            // Optimization: if we reached the end, we found the shortest path
            if (current.equals(end)) {
                return dist[current.r][current.c];
            }

            // 1. Explore 0-cost adjacent neighbors
            for (int[] dir : ADJACENT_DIRECTIONS) {
                int nr = current.r + dir[0];
                int nc = current.c + dir[1];

                if (grid.isWalkable(nr, nc)) {
                    if (dist[nr][nc] > dist[current.r][current.c]) {
                        dist[nr][nc] = dist[current.r][current.c];
                        deque.addFirst(new Point(nr, nc));
                    }
                }
            }

            // 2. Explore 1-cost jump neighbors (5x5 area)
            for (int dr = -JUMP_RADIUS; dr <= JUMP_RADIUS; dr++) {
                for (int dc = -JUMP_RADIUS; dc <= JUMP_RADIUS; dc++) {
                    // Skip the center cell as it is covered by the 0-cost logic
                    if (dr == 0 && dc == 0) continue;

                    int nr = current.r + dr;
                    int nc = current.c + dc;

                    if (grid.isWalkable(nr, nc)) {
                        int newDist = dist[current.r][current.c] + 1;
                        if (dist[nr][nc] > newDist) {
                            dist[nr][nc] = newDist;
                            deque.addLast(new Point(nr, nc));
                        }
                    }
                }
            }
        }

        return dist[end.r][end.c] == INF ? -1 : dist[end.r][end.c];
    }
}

