/**
 * A program to find the shortest path in a grid using 0-1 Breadth-First Search.
 * Some moves have a cost of 0 (adjacent cells) and others a cost of 1 (within a 5x5 area).
 */
public class Main {

    public static void main(String[] args) {
        InputReader reader = new InputReader(System.in);
        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        try {
            solve(reader, out);
        } finally {
            out.close();
        }
    }

    private static void solve(InputReader reader, PrintWriter out) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        // Convert 1-based indexing from input to 0-based indexing
        Position start = new Position(reader.nextInt() - 1, reader.nextInt() - 1);
        Position target = new Position(reader.nextInt() - 1, reader.nextInt() - 1);

        char[][] mapData = new char[rows][cols];
        for (int i = 0; i < rows; i++) {
            mapData[i] = reader.next().toCharArray();
        }

        Grid grid = new Grid(mapData);
        Pathfinder pathfinder = new Pathfinder(grid);

        int result = pathfinder.findShortestPath(start, target);
        out.println(result);
    }

    /**
     * Represents a coordinate in the grid.
     */
    static final class Position {
        final int r;
        final int c;

        Position(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * Manages the grid data and boundary/obstacle validation.
     */
    static final class Grid {
        private final char[][] cells;
        private final int rows;
        private final int cols;
        private static final char WALL = '#';

        Grid(char[][] cells) {
            this.cells = cells;
            this.rows = cells.length;
            this.cols = cells[0].length;
        }

        boolean isWalkable(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && cells[r][c] != WALL;
        }

        int getRows() { return rows; }
        int getCols() { return cols; }
    }

    /**
     * Contains the logic for finding the shortest path using 0-1 BFS.
     */
    static final class Pathfinder {
        private static final int INF = 1_000_000_000;
        private static final int[] ADJACENT_DR = {-1, 1, 0, 0};
        private static final int[] ADJACENT_DC = {0, 0, -1, 1};

        private final Grid grid;

        Pathfinder(Grid grid) {
            this.grid = grid;
        }

        public int findShortestPath(Position start, Position target) {
            int[][] distances = initializeDistances();
            Deque<Position> deque = new ArrayDeque<>();

            distances[start.r][start.c] = 0;
            deque.offer(start);

            while (!deque.isEmpty()) {
                Position current = deque.poll();

                // 1. Cost-0 Moves: Adjacent neighbors
                for (int i = 0; i < 4; i++) {
                    int nr = current.r + ADJACENT_DR[i];
                    int nc = current.c + ADJACENT_DC[i];

                    if (grid.isWalkable(nr, nc)) {
                        if (distances[nr][nc] > distances[current.r][current.c]) {
                            distances[nr][nc] = distances[current.r][current.c];
                            deque.addFirst(new Position(nr, nc));
                        }
                    }
                }

                // 2. Cost-1 Moves: Within a 5x5 area around the current cell
                for (int dr = -2; dr <= 2; dr++) {
                    for (int dc = -2; dc <= 2; dc++) {
                        int nr = current.r + dr;
                        int nc = current.c + dc;

                        if (grid.isWalkable(nr, nc)) {
                            int newDist = distances[current.r][current.c] + 1;
                            if (distances[nr][nc] > newDist) {
                                distances[nr][nc] = newDist;
                                deque.addLast(new Position(nr, nc));
                            }
                        }
                    }
                }
            }

            int finalDist = distances[target.r][target.c];
            return finalDist >= INF ? -1 : finalDist;
        }

        private int[][] initializeDistances() {
            int[][] dist = new int[grid.getRows()][grid.getCols()];
            for (int[] row : dist) {
                Arrays.fill(row, INF);
            }
            return dist;
        }
    }

    /**
     * Fast I/O utility for efficient reading.
     */
    static final class InputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        InputReader(InputStream stream) {
