/**
 * Encapsulates the maze grid and its properties.
 */
class Maze {
    private final char[][] grid;
    private final int height;
    private final int width;

    public Maze(char[][] grid, int height, int width) {
        this.grid = grid;
        this.height = height;
        this.width = width;
    }

