/**
 * Implements Dijkstra's algorithm to find the shortest path in the maze.
 */
class MazePathfinder {
    private final Maze maze;
    private static final int[][] ORTHOGONAL_DIRECTIONS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public MazePathfinder(Maze maze) {
        this.maze = maze;
    }

    /**
     * Finds the shortest path from (startY, startX) to (targetY, targetX).
     * Orthogonal moves have cost 0, and any move within a 5x5 area has cost 1.
     * 
     * @return The minimum cost to reach the target, or -1 if unreachable.
     */
    public int findShortestPath(int startY, int startX, int targetY, int targetX) {
        PriorityQueue<Node> priorityQueue = new PriorityQueue<>();
        int[][] minCostToReach = new int[maze.getHeight()][maze.getWidth()];
        boolean[][] visited = new boolean[maze.getHeight()][maze.getWidth()];

        // Initialize distances with infinity
        for (int[] row : minCostToReach) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }

        // Initial state
        minCostToReach[startY][startX] = 0;
        priorityQueue.add(new Node(startY, startX, 0));

        while (!priorityQueue.isEmpty()) {
            Node current = priorityQueue.poll();

            if (visited[current.y()][current.x()]) {
                continue;
            }
            visited[current.y()][current.x()] = true;

            // Check if we have reached the target
            if (current.y() == targetY && current.x() == targetX) {
                return current.cost();
            }

            // 1. Explore Orthogonal Moves (Cost 0)
            for (int[] dir : ORTHOGONAL_DIRECTIONS) {
                int nextY = current.y() + dir[0];
                int nextX = current.x() + dir[1];

                if (maze.isValid(nextY, nextX) && !visited[nextY][nextX]) {
                    if (current.cost() < minCostToReach[nextY][nextX]) {
                        minCostToReach[nextY][nextX] = current.cost();
                        priorityQueue.add(new Node(nextY, nextX, current.cost()));
                    }
                }
            }

            // 2. Explore Jump Moves within a 5x5 area (Cost 1)
            for (int dy = -2; dy <= 2; dy++) {
                for (int dx = -2; dx <= 2; dx++) {
                    if (dy == 0 && dx == 0) continue;

                    int nextY = current.y() + dy;
                    int nextX = current.x() + dx;
                    int nextCost = current.cost() + 1;

                    if (maze.isValid(nextY, nextX) && !visited[nextY][nextX]) {
                        if (nextCost < minCostToReach[nextY][nextX]) {
                            minCostToReach[nextY][nextX] = nextCost;
                            priorityQueue.add(new Node(nextY, nextX, nextCost));
                        }
                    }
                }
            }
        }

        return -1;
    }
}

