    /**
     * Holds the maze data and provides spatial boundary checks.
     */
    static class Maze {
        private final int height;
        private final int width;
        private final char[][] grid;

        public Maze(int height, int width, char[][] grid) {
            this.height = height;
            this.width = width;
            this.grid = grid;
        }

        public int getHeight() { return height; }
        public int getWidth() { return width; }

        public boolean isWithinBounds(int r, int c) {
            return r >= 0 && r < height && c >= 0 && c < width;
        }

        public boolean isWalkable(int r, int c) {
            return isWithinBounds(r, c) && grid[r][c] == '.';
        }
    }

    /**
     * Logic for solving the maze using a 0-1 Breadth-First Search algorithm.
     */
    static class MazeSolver {
        private static final int INF = 100_000_000;
        private static final int[] ROW_OFFSETS = {0, 0, 1, -1};
        private static final int[] COL_OFFSETS = {1, -1, 0, 0};

        /**
         * Solves the maze. Moving to an adjacent cell has a cost of 0.
         * Moving within a 5x5 area has a cost of 1.
         */
        public int solve(Maze maze, Point start, Point end) {
            int[][] dist = new int[maze.getHeight()][maze.getWidth()];
            for (int[] row : dist) {
                Arrays.fill(row, INF);
            }

            Deque<Point> deque = new ArrayDeque<>();

            dist[start.row][start.col] = 0;
            deque.addFirst(start);

            while (!deque.isEmpty()) {
                Point current = deque.pollFirst();
                int r = current.row;
                int c = current.col;
                int currentDist = dist[r][c];

                // 1. Attempt 0-cost moves: Adjacent cells
                for (int i = 0; i < 4; i++) {
                    int nr = r + ROW_OFFSETS[i];
                    int nc = c + COL_OFFSETS[i];

                    if (maze.isWalkable(nr, nc) && dist[nr][nc] > currentDist) {
                        dist[nr][nc] = currentDist;
                        deque.addFirst(new Point(nr, nc));
                    }
                }

                // 2. Attempt 1-cost moves: 5x5 area jump
                for (int dr = -2; dr <= 2; dr++) {
                    for (int dc = -2; dc <= 2; dc++) {
                        int nr = r + dr;
                        int nc = c + dc;

                        if (maze.isWalkable(nr, nc) && dist[nr][nc] > currentDist + 1) {
                            dist[nr][nc] = currentDist + 1;
                            deque.addLast(new Point(nr, nc));
                        }
                    }
                }
            }

            int result = dist[end.row][end.col];
            return (result >= INF) ? -1 : result;
        }
    }

