/**
 * Implements the 0-1 BFS algorithm to find the shortest path.
 */
class Pathfinder {
    private static final int INF = 100_000_000;
    private static final int[] ROW_DIRECTIONS = {0, 0, 1, -1};
    private static final int[] COL_DIRECTIONS = {1, -1, 0, 0};

    private final Grid grid;

    public Pathfinder(Grid grid) {
        this.grid = grid;
    }

    public int findShortestPath(Point start, Point target) {
        int rows = grid.getRows();
        int cols = grid.getCols();
        int[][] dist = new int[rows][cols];

        for (int i = 0; i < rows; i++) {
            Arrays.fill(dist[i], INF);
        }

        Deque<Point> deque = new ArrayDeque<>();

        // Initial setup
        dist[start.row][start.col] = 0;
        deque.addFirst(start);

        while (!deque.isEmpty()) {
            Point current = deque.pollFirst();
            int r = current.row;
            int c = current.col;
            int currentDist = dist[r][c];

            // 1. Weight 0 Movement: Cardinal neighbors (Up, Down, Left, Right)
            for (int i = 0; i < 4; i++) {
                int nr = r + ROW_DIRECTIONS[i];
                int nc = c + COL_DIRECTIONS[i];

                if (grid.isPassable(nr, nc) && dist[nr][nc] > currentDist) {
                    dist[nr][nc] = currentDist;
                    deque.addFirst(new Point(nr, nc));
                }
            }

            // 2. Weight 1 Movement: 5x5 neighborhood
            for (int dr = -2; dr <= 2; dr++) {
                for (int dc = -2; dc <= 2; dc++) {
                    int nr = r + dr;
                    int nc = c + dc;

                    if (grid.isPassable(nr, nc) && dist[nr][nc] > currentDist + 1) {
                        dist[nr][nc] = currentDist + 1;
                        deque.addLast(new Point(nr, nc));
                    }
                }
            }
        }

        int result = dist[target.row][target.col];
        return (result >= INF) ? -1 : result;
    }
}

