class MazeSolver {
    private final char[][] grid;
    private final int rows;
    private final int cols;

    private static final int[][] ADJACENT_DIRECTIONS = {
        {0, 1}, {0, -1}, {1, 0}, {-1, 0}
    };

    private static final int JUMP_RANGE = 2;
    private static final char OBSTACLE = '#';

    public MazeSolver(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
    }

    /**
     * Finds the minimum cost to reach the target using 0-1 BFS.
     * 
     * @param startRow Starting row index
     * @param startCol Starting column index
     * @param targetRow Destination row index
     * @param targetCol Destination column index
     * @return Minimum cost, or Integer.MAX_VALUE if unreachable.
     */
    public int findMinimumCost(int startRow, int startCol, int targetRow, int targetCol) {
        if (!isValid(startRow, startCol) || !isValid(targetRow, targetCol)) {
            return Integer.MAX_VALUE;
        }

        int[][] distanceMatrix = new int[rows][cols];
        for (int[] row : distanceMatrix) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }

        Deque<Node> deque = new ArrayDeque<>();

        distanceMatrix[startRow][startCol] = 0;
        deque.addFirst(new Node(startRow, startCol));

        while (!deque.isEmpty()) {
            Node current = deque.pollFirst();

            // 1. Try adjacent movement (Cost: 0)
            for (int[] dir : ADJACENT_DIRECTIONS) {
                int nextR = current.row + dir[0];
                int nextC = current.col + dir[1];

                if (isValid(nextR, nextC) && distanceMatrix[nextR][nextC] > distanceMatrix[current.row][current.col]) {
                    distanceMatrix[nextR][nextC] = distanceMatrix[current.row][current.col];
                    deque.addFirst(new Node(nextR, nextC));
                }
            }

            // 2. Try jump movement (Cost: 1) within 5x5 area
            for (int r = current.row - JUMP_RANGE; r <= current.row + JUMP_RANGE; r++) {
                for (int c = current.col - JUMP_RANGE; c <= current.col + JUMP_RANGE; c++) {
                    if (isValid(r, c) && distanceMatrix[r][c] > distanceMatrix[current.row][current.col] + 1) {
                        distanceMatrix[r][c] = distanceMatrix[current.row][current.col] + 1;
                        deque.addLast(new Node(r, c));
                    }
                }
            }
        }

        return distanceMatrix[targetRow][targetCol];
    }

    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != OBSTACLE;
    }

    /**
     * Represents a coordinate point in the grid.
     */
    private static class Node {
        final int row;
        final int col;

        Node(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }
}

