    private static final int COST_JUMP = 1;
    private static final int UNREACHABLE = Integer.MAX_VALUE;

    private static final int[] ROW_DIR = {0, 0, -1, 1};
    private static final int[] COL_DIR = {1, -1, 0, 0};

    public void solve(FastReader in, FastWriter out) throws IOException {
        int rows = in.nextInt();
        int cols = in.nextInt();

        // Adjusting 1-based input to 0-based indexing
        int startRow = in.nextInt() - 1;
        int startCol = in.nextInt() - 1;
        int targetRow = in.nextInt() - 1;
        int targetCol = in.nextInt() - 1;

        String[] grid = in.readStringArray(rows);
        int[][] minDistance = initializeDistanceMatrix(rows, cols);

        Deque<Point> deque = new ArrayDeque<>();

        // Starting point initialization
        minDistance[startRow][startCol] = 0;
        deque.addFirst(new Point(startRow, startCol));

        while (!deque.isEmpty()) {
            Point current = deque.pollFirst();
            int currentDist = minDistance[current.row()][current.col()];

            // 1. Attempt adjacent moves (Cost 0)
            for (int i = 0; i < 4; i++) {
                int nextR = current.row() + ROW_DIR[i];
                int nextC = current.col() + COL_DIR[i];

                if (isValidMove(grid, rows, cols, nextR, nextC)) {
                    if (minDistance[nextR][nextC] > currentDist) {
                        minDistance[nextR][nextC] = currentDist + COST_ADJACENT;
                        deque.addFirst(new Point(nextR, nextC));
                    }
                }
            }

            // 2. Attempt jump moves (Cost 1)
            // Jump area is a 5x5 area around the current cell
            for (int dr = -2; dr <= 2; dr++) {
                for (int dc = -2; dc <= 2; dc++) {
                    int nextR = current.row() + dr;
                    int nextC = current.col() + dc;

                    if (isValidMove(grid, rows, cols, nextR, nextC)) {
                        if (minDistance[nextR][nextC] > currentDist + COST_JUMP) {
                            minDistance[nextR][nextC] = currentDist + COST_JUMP;
                            deque.addLast(new Point(nextR, nextC));
                        }
                    }
                }
            }
        }

        int result = minDistance[targetRow][targetCol];
        out.println(result == UNREACHABLE ? -1 : result);
    }

    private boolean isValidMove(String[] grid, int rows, int cols, int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r].charAt(c) == '.';
    }

    private int[][] initializeDistanceMatrix(int rows, int cols) {
        int[][] matrix = new int[rows][cols];
        for (int[] row : matrix) {
            Arrays.fill(row, UNREACHABLE);
        }
        return matrix;
    }
}

/**
 * Fast I/O utility for reading input.
 */
class FastReader {
    private final InputStream inputStream;
    private final byte[] buffer = new byte[1024];
    private int curChar;
    private int numChars;

    public FastReader(InputStream stream) {
        this.inputStream = stream;
    }

    private int read() throws IOException {
        if (numChars == -1) throw new InputMismatchException();
        if (curChar >= numChars) {
            curChar = 0;
            numChars = inputStream.read(buffer);
            if (numChars <= 0) return -1;
        }
        return buffer[curChar++];
    }

    public int nextInt() throws IOException {
        int c = read();
        while (isSpaceChar(c)) c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9') throw new InputMismatchException();
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public String nextString() throws IOException {
        int c = read();
        while (isSpaceChar(c)) c = read();
        StringBuilder res = new StringBuilder();
        do {
            res.appendCodePoint(c);
            c = read();
        } while (!isSpaceChar(c));
        return res.toString();
    }

    public String[] readStringArray(int size) throws IOException {
        String[] array = new String[size];
        for (int i = 0; i < size; i++) {
            array[i] = nextString();
        }
        return array;
    }

    private boolean isSpaceChar(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }
}

