/**
 * Represents a coordinate in the 2D grid.
 */
record Point(int row, int col) {}

/**
 * Represents a possible move in the grid with an associated cost.
 */
record Move(int dRow, int dCol, int cost) {}

/**
 * Logic for finding the shortest path using 0-1 Breadth-First Search.
 */
class GridPathfinder {
    private final char[][] grid;
    private final int height;
    private final int width;
    private static final int INF = Integer.MAX_VALUE;
    private static final char WALKABLE_CHAR = '.';

    // The original dx/dy logic simplified: 
    // Orthogonal moves are cost 0, all other jumps within a 5x5 area are cost 1.
    private static final List<Move> MOVES = List.of(
        // Orthogonal moves (Cost 0)
        new Move(0, 1, 0), new Move(0, -1, 0), new Move(1, 0, 0), new Move(-1, 0, 0),

        // Diagonal and jump moves (Cost 1)
        new Move(1, 1, 1), new Move(1, -1, 1), new Move(-1, 1, 1), new Move(-1, -1, 1),
        new Move(2, 2, 1), new Move(2, -2, 1), new Move(-2, 2, 1), new Move(-2, -2, 1),
        new Move(2, 1, 1), new Move(2, -1, 1), new Move(-2, 1, 1), new Move(-2, -1, 1),
        new Move(1, 2, 1), new Move(1, -2, 1), new Move(-1, 2, 1), new Move(-1, -2, 1),
        new Move(0, 2, 1), new Move(0, -2, 1), new Move(2, 0, 1), new Move(-2, 0, 1)
    );

    public GridPathfinder(char[][] grid, int height, int width) {
        this.grid = grid;
        this.height = height;
        this.width = width;
    }

    /**
     * Executes 0-1 BFS to find the shortest path from start to end.
     * 
     * @return The minimum cost to reach the end, or -1 if unreachable.
     */
    public long findShortestPath(Point start, Point end) {
        int[][] dist = new int[height][width];
        for (int[] row : dist) {
            Arrays.fill(row, INF);
        }

        if (!isWalkable(start.row(), start.col())) {
            return -1;
        }

        dist[start.row()][start.col()] = 0;
        Deque<Point> deque = new ArrayDeque<>();
        deque.addFirst(start);

        while (!deque.isEmpty()) {
            Point current = deque.pollFirst();

            if (current.equals(end)) {
                return dist[current.row()][current.col()];
            }

            for (Move move : MOVES) {
                int nextR = current.row() + move.dRow();
                int nextC = current.col() + move.dCol();

                if (isWithinBounds(nextR, nextC) && isWalkable(nextR, nextC)) {
                    int newDist = dist[current.row()][current.col()] + move.cost();

                    if (newDist < dist[nextR][nextC]) {
                        dist[nextR][nextC] = newDist;
                        if (move.cost() == 0) {
                            deque.addFirst(new Point(nextR, nextC));
                        } else {
                            deque.addLast(new Point(nextR, nextC));
                        }
                    }
                }
            }
        }

        return dist[end.row()][end.col()] == INF ? -1 : dist[end.row()][end.col()];
    }

    private boolean isWithinBounds(int r, int c) {
        return r >= 0 && r < height && c >= 0 && c < width;
    }

    private boolean isWalkable(int r, int c) {
        return grid[r][c] == WALKABLE_CHAR;
    }
}

