/**
 * Represents a coordinate in the grid.
 */
record Point(int row, int col) {}

/**
 * Handles the BFS logic to find the shortest path.
 */
class Pathfinder {
    private final int height;
    private final int width;
    private final boolean[][] map;
    private final int[][] distances;
    private final Deque<Point> deque;

    // Cardinal directions: Up, Down, Left, Right
    private static final int[][] CARDINAL_OFFSETS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    // Warp/Knight-style movements (Weight 1)
    private static final int[][] WARP_OFFSETS = {
            {-2, -1}, {-2, 1}, {-2, 0}, {2, -1}, {2, 0}, {2, 1},
            {-1, -2}, {0, -2}, {1, -2}, {-1, 2}, {0, 2}, {1, 2},
            {-1, -1}, {-2, -2}, {-1, 1}, {-2, 2}, {1, -1}, {2, -2},
            {1, 1}, {2, 2}
    };

    public Pathfinder(int height, int width, boolean[][] map) {
        this.height = height;
        this.width = width;
        this.map = map;
        this.distances = new int[height][width];
        this.deque = new ArrayDeque<>();
        initializeDistances();
    }

    private void initializeDistances() {
        for (int[] row : distances) {
            Arrays.fill(row, -1);
        }
    }

    /**
     * Performs a 0-1 BFS to find the shortest path from start to end.
     * 
     * @return The shortest distance, or -1 if unreachable.
     */
    public int findShortestPath(int startRow, int startCol, int endRow, int endCol) {
        distances[startRow][startCol] = 0;
        deque.addFirst(new Point(startRow, startCol));

        while (!deque.isEmpty()) {
            Point current = deque.removeFirst();

            // 1. Try standard moves (Weight 0)
            // The original logic triggers "warps" if any cardinal move is blocked 
            // by a wall, boundary, or an already visited cell with a shorter path.
            boolean isCorner = false;
            for (int[] offset : CARDINAL_OFFSETS) {
                if (!tryMove(current, offset[0], offset[1], 0)) {
                    isCorner = true;
                }
            }

            // 2. If a "corner" was detected, try warp moves (Weight 1)
            if (isCorner) {
                for (int[] offset : WARP_OFFSETS) {
                    tryMove(current, offset[0], offset[1], 1);
                }
            }
        }

        return distances[endRow][endCol];
    }

    /**
     * Attempts to move to a new cell. Updates distance if a shorter path is found.
     * 
     * @param p The starting point.
     * @param dr Row offset.
     * @param dc Column offset.
     * @param weight Movement cost (0 or 1).
     * @return true if the move was successful (path updated), false otherwise.
     */
    private boolean tryMove(Point p, int dr, int dc, int weight) {
        int nextRow = p.row() + dr;
        int nextCol = p.col() + dc;

        // Check boundaries and walkability
        if (isOutOfBounds(nextRow, nextCol) || !map[nextRow][nextCol]) {
            return false;
        }

        int newDistance = distances[p.row()][p.col()] + weight;

        // If the cell is unvisited or we found a shorter path
        if (distances[nextRow][nextCol] == -1 || newDistance < distances[nextRow][nextCol]) {
            distances[nextRow][nextCol] = newDistance;

            // 0-1 BFS: Weight 0 moves go to the front, Weight 1 go to the back
            if (weight == 0) {
                deque.addFirst(new Point(nextRow, nextCol));
            } else {
                deque.addLast(new Point(nextRow, nextCol));
            }
            return true;
        }

        return false;
    }

    private boolean isOutOfBounds(int r, int c) {
        return r < 0 || r >= height || c < 0 || c >= width;
    }
}

import java.util.*;

/**
 * A program to find the minimum cost to navigate a grid using a 0-1 BFS algorithm.
 * 
 * Movement rules:
 * 1. Moving to an adjacent cardinal neighbor (Up, Down, Left, Right) has a cost of 0.
 * 2. Moving to any cell within a 5x5 area around the current cell has a cost of 1.
 */
public class Main {
    private static final int UNREACHABLE = 1_000_000_000;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        if (!scanner.hasNextInt()) {
            return;
        }

        // Parse grid dimensions
        int height = scanner.nextInt();
        int width = scanner.nextInt();

        // Parse coordinates (Input is 1-indexed, convert to 0-indexed)
        int startY = scanner.nextInt() - 1;
        int startX = scanner.nextInt() - 1;
        int endY = scanner.nextInt() - 1;
        int endX = scanner.nextInt() - 1;

        // Parse grid layout
        char[][] gridData = new char[height][width];
        for (int i = 0; i < height; i++) {
            String line = scanner.next();
            for (int j = 0; j < width; j++) {
                gridData[i][j] = line.charAt(j);
            }
        }

        Grid grid = new Grid(height, width, gridData);
        Pathfinder pathfinder = new Pathfinder(grid);

        int minCost = pathfinder.findShortestPath(new Point(startY, startX), new Point(endY, endX));

        // Output result
        if (minCost >= UNREACHABLE) {
            System.out.println("-1");
        } else {
            System.out.println(minCost);
        }

        scanner.close();
    }

    /**
     * Represents a coordinate on the 2D grid.
     */
    static class Point {
        private final int y;
        private final int x;

        public Point(int y, int x) {
            this.y = y;
            this.x = x;
        }

        public int getY() { return y; }
        public int getX() { return x; }
    }

    /**
     * Manages grid data and provides utility methods for boundary and obstacle checks.
     */
    static class Grid {
        private final int height;
        private final int width;
        private final boolean[][] obstacles;

        public Grid(int height, int width, char[][] gridData) {
            this.height = height;
            this.width = width;
            this.obstacles = new boolean[height][width];
            for (int i = 0; i < height; i++) {
                for (int j = 0; j < width; j++) {
                    if (gridData[i][j] == '#') {
                        this.obstacles[i][j] = true;
                    }
                }
            }
        }

        public int getHeight() { return height; }
        public int getWidth() { return width; }

        public boolean isWithinBounds(int y, int x) {
            return y >= 0 && y < height && x >= 0 && x < width;
        }

        public boolean isWalkable(int y, int x) {
            return isWithinBounds(y, x) && !obstacles[y][x];
        }
    }

    /**
     * Implementation of the 0-1 Breadth-First Search algorithm.
     */
    static class Pathfinder {
        private final Grid grid;
        private static final int[][] CARDINAL_DIRECTIONS = {
            {0, 1}, {0, -1}, {1, 0}, {-1, 0}
        };

        public Pathfinder(Grid grid) {
            this.grid = grid;
        }

        /**
         * Calculates the minimum cost to move from start to end.
         * 
         * @param start Starting position
         * @param end   Destination position
         * @return Minimum cost or UNREACHABLE
         */
        public int findShortestPath(Point start, Point end) {
            int[][] minDistance = new int[grid.getHeight()][grid.getWidth()];
            for (int[] row : minDistance) {
                Arrays.fill(row, UNREACHABLE);
            }

            Deque<Point> deque = new ArrayDeque<>();

            // Initialize BFS
            minDistance[start.getY()][start.getX()] = 0;
            deque.addFirst(start);

            while (!deque.isEmpty()) {
                Point current = deque.pollFirst();
                int y = current.getY();
                int x = current.getX();

                // Rule 1: Cardinal neighbors have a movement cost of 0
                for (int[] dir : CARDINAL_DIRECTIONS) {
                    int ny = y + dir[0];
                    int nx = x + dir[1];

                    if (grid.isWalkable(ny, nx)) {
                        if (minDistance[ny][nx] > minDistance[y][x]) {
                            minDistance[ny][nx] = minDistance[y][x];
                            deque.addFirst(new Point(ny, nx));
                        }
                    }
                }

                // Rule 2: 5x5 area movement has a movement cost of 1
                int yMin = Math.max(0, y - 2);
                int yMax = Math.min(grid.getHeight() - 1, y + 2);
                int xMin = Math.max(0, x - 2);
                int xMax = Math.min(grid.getWidth() - 1, x + 2);

                for (int ny = yMin; ny <= yMax; ny++) {
                    for (int nx = xMin; nx <= xMax; nx++) {
                        if (grid.isWalkable(ny, nx)) {
                            if (minDistance[ny][nx] > minDistance[y][x] + 1) {
                                minDistance[ny][nx] = minDistance[y][x] + 1;
                                deque.addLast(new Point(ny, nx));
                            }
                        }
                    }
                }
            }

            return minDistance[end.getY()][end.getX()];
        }
    }
}

