/**
 * A refactored solution for finding the shortest path in a grid.
 * The algorithm uses a 0-1 Breadth-First Search (BFS) approach.
 * - Moving to an adjacent cell has a cost of 0.
 * - Moving to any cell within a 5x5 area has a cost of 1.
 */
public class Main {

    public static void main(String[] args) {
