/**
 * Encapsulates the pathfinding logic on the grid.
 */
class MazeSolver {
    private final int height;
    private final int width;
    private final char[][] grid;

    private static final int INF = Integer.MAX_VALUE;
    private static final int[][] ADJACENT_DIRECTIONS = {
        {-1, 0}, {1, 0}, {0, -1}, {0, 1}
    };

    /**
     * Represents a state in the BFS queue.
     */
    private static class Node {
        final int row;
        final int col;
        final int cost;

        Node(int row, int col, int cost) {
            this.row = row;
            this.col = col;
            this.cost = cost;
        }
    }

    public MazeSolver(int height, int width, char[][] grid) {
        this.height = height;
        this.width = width;
        this.grid = grid;
    }

    /**
     * Finds the shortest path from (startRow, startCol) to (targetRow, targetCol).
     * 
     * @return The minimum cost to reach the target, or -1 if unreachable.
     */
    public int findShortestPath(int startRow, int startCol, int targetRow, int targetCol) {
        int[][] minDistances = new int[height][width];
        for (int i = 0; i < height; i++) {
            Arrays.fill(minDistances[i], INF);
        }

        Deque<Node> deque = new ArrayDeque<>();

        // Initialize starting point
        minDistances[startRow][startCol] = 0;
        deque.addFirst(new Node(startRow, startCol, 0));

        while (!deque.isEmpty()) {
            Node current = deque.pollFirst();

            // Optimization: if we already found a better way to this cell, skip it
            if (current.cost > minDistances[current.row][current.col]) {
                continue;
            }

            // 1. Cost-0 Moves: Adjacent neighbors (Up, Down, Left, Right)
            for (int[] dir : ADJACENT_DIRECTIONS) {
                int nextR = current.row + dir[0];
                int nextC = current.col + dir[1];

                if (isValid(nextR, nextC) && grid[nextR][nextC] != '#') {
                    if (minDistances[nextR][nextC] > current.cost) {
                        minDistances[nextR][nextC] = current.cost;
                        deque.addFirst(new Node(nextR, nextC, current.cost));
                    }
                }
            }

            // 2. Cost-1 Moves: Cells within a 5x5 neighborhood
            for (int r = current.row - 2; r <= current.row + 2; r++) {
                for (int c = current.col - 2; c <= current.col + 2; c++) {
                    if (isValid(r, c) && grid[r][c] != '#') {
                        int nextCost = current.cost + 1;
                        if (minDistances[r][c] > nextCost) {
                            minDistances[r][c] = nextCost;
                            deque.addLast(new Node(r, c, nextCost));
                        }
                    }
                }
            }
        }

        int finalDist = minDistances[targetRow][targetCol];
        return (finalDist == INF) ? -1 : finalDist;
    }

    /**
     * Checks if a given coordinate is within the grid boundaries.
     */
    private boolean isValid(int r, int c) {
        return r >= 0 && r < height && c >= 0 && c < width;
    }
}

