            int width = reader.nextInt();

            int startRow = reader.nextInt() - 1;
            int startCol = reader.nextInt() - 1;

            int endRow = reader.nextInt() - 1;
            int endCol = reader.nextInt() - 1;

            char[][] grid = new char[height][width];
            for (int i = 0; i < height; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridPathfinder solver = new GridPathfinder(grid, height, width);
            int result = solver.findShortestPath(startRow, startCol, endRow, endCol);
            System.out.println(result);

        } catch (IOException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    private static class GridPathfinder {
        private final char[][] grid;
        private final int height;
        private final int width;
        private final int[][] componentIds;
        private int componentCount = 0;

        private static final int[] ROW_DIRECTIONS = {-1, 1, 0, 0};
        private static final int[] COL_DIRECTIONS = {0, 0, -1, 1};

        public GridPathfinder(char[][] grid, int height, int width) {
            this.grid = grid;
            this.height = height;
            this.width = width;
            this.componentIds = new int[height][width];
            for (int[] row : componentIds) {
                Arrays.fill(row, -1);
            }
        }

        /**
         * Orchestrates the process of finding the shortest path between two points.
         */
        public int findShortestPath(int startR, int startC, int endR, int endC) {
            labelComponents();
            Set<Integer>[] adjacencyList = buildComponentGraph();

            int startComp = componentIds[startR][startC];
            int endComp = componentIds[endR][endC];

            // If start or end is a wall, no path exists
            if (startComp == -1 || endComp == -1) return -1;
            if (startComp == endComp) return 0;

            return performBreadthFirstSearch(startComp, endComp, adjacencyList);
        }

        /**
         * Uses BFS to group adjacent '.' cells into unique component IDs.
         */
        private void labelComponents() {
            for (int r = 0; r < height; r++) {
                for (int c = 0; c < width; c++) {
                    if (grid[r][c] == '.' && componentIds[r][c] == -1) {
                        bfsLabelComponent(r, c, componentCount++);
                    }
                }
            }
        }

        private void bfsLabelComponent(int startR, int startC, int id) {
            Deque<Point> queue = new ArrayDeque<>();
            componentIds[startR][startC] = id;
            queue.add(new Point(startR, startC));

            while (!queue.isEmpty()) {
                Point curr = queue.poll();

                for (int i = 0; i < 4; i++) {
                    int nr = curr.row + ROW_DIRECTIONS[i];
                    int nc = curr.col + COL_DIRECTIONS[i];

                    if (isValidTraversable(nr, nc)) {
                        componentIds[nr][nc] = id;
                        queue.add(new Point(nr, nc));
                    }
                }
            }
        }

        /**
         * Builds a graph where nodes are component IDs and edges represent 
         * proximity within a 5x5 window.
         */
        @SuppressWarnings("unchecked")
        private Set<Integer>[] buildComponentGraph() {
            Set<Integer>[] adj = new HashSet[componentCount];
            for (int i = 0; i < componentCount; i++) {
                adj[i] = new HashSet<>();
            }

            for (int r = 0; r < height; r++) {
                for (int c = 0; c < width; c++) {
                    int currentId = componentIds[r][c];
                    if (currentId == -1) continue;

                    // Check 5x5 neighborhood (Chebyshev distance <= 2)
                    for (int dr = -2; dr <= 2; dr++) {
                        for (int dc = -2; dc <= 2; dc++) {
                            int nr = r + dr;
                            int nc = c + dc;

                            if (isDifferentComponentInRange(nr, nc, currentId)) {
                                adj[currentId].add(componentIds[nr][nc]);
                            }
                        }
                    }
                }
            }
            return adj;
        }

        private boolean isDifferentComponentInRange(int r, int c, int currentId) {
            return r >= 0 && r < height && c >= 0 && c < width 
                    && grid[r][c] == '.' 
                    && componentIds[r][c] != -1 
                    && componentIds[r][c] != currentId;
        }

        private boolean isValidTraversable(int r, int c) {
            return r >= 0 && r < height && c >= 0 && c < width 
                    && grid[r][c] == '.' 
                    && componentIds[r][c] == -1;
        }

        /**
         * Standard BFS to find the shortest path between two component IDs.
         */
        private int performBreadthFirstSearch(int startId, int endId, Set<Integer>[] adj) {
            int[] distances = new int[componentCount];
            Arrays.fill(distances, -1);

            Deque<Integer> queue = new ArrayDeque<>();
            distances[startId] = 0;
            queue.add(startId);

            while (!queue.isEmpty()) {
                int u = queue.poll();

                if (u == endId) return distances[u];

                for (int v : adj[u]) {
                    if (distances[v] == -1) {
                        distances[v] = distances[u] + 1;
                        queue.add(v);
                    }
                }
            }
            return distances[endId];
        }

        private record Point(int row, int col) {}
    }

    /**
     * Utility class for fast I/O operations.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

