/**
 * A program to find the shortest path on a grid using Dijkstra's algorithm.
 * Movement allows for adjacent moves at 0 cost and jumps within a 5x5 area at 1 cost.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        GridPathfinder pathfinder = new GridPathfinder(reader);
        pathfinder.solve();
    }
}

/**
 * Handles efficient input reading.
 */
class FastReader {
    private final BufferedReader reader;
    private StringTokenizer tokenizer;

    public FastReader(InputStream stream) {
        this.reader = new BufferedReader(new InputStreamReader(stream));
    }

    public String next() {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            try {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            } catch (IOException e) {
                return null;
            }
        }
        return tokenizer.nextToken();
    }

    public int nextInt() {
        String next = next();
        return next == null ? -1 : Integer.parseInt(next);
    }
}

/**
 * Encapsulates the grid logic and pathfinding algorithm.
 */
class GridPathfinder {
    private final FastReader reader;

    public GridPathfinder(FastReader reader) {
        this.reader = reader;
    }

    /**
     * Represents a coordinate on the grid.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Represents a node in the PriorityQueue for Dijkstra.
     */
    private static class Node implements Comparable<Node> {
        final Point point;
        final int distance;

        Node(Point point, int distance) {
            this.point = point;
            this.distance = distance;
        }

        @Override
        public int compareTo(Node other) {
            return Integer.compare(this.distance, other.distance);
        }
    }

    /**
     * Main execution flow.
     */
    public void solve() {
        int height = reader.nextInt();
        int width = reader.nextInt();

        if (height == -1) return;

        // Start and Goal coordinates
        Point start = new Point(reader.nextInt(), reader.nextInt());
        Point goal = new Point(reader.nextInt(), reader.nextInt());

        // Padding the grid with a border of size 1 to simplify boundary checks
        char[][] grid = new char[height + 2][width + 2];
        for (int i = 1; i <= height; i++) {
            String line = reader.next();
            for (int j = 1; j <= width; j++) {
                grid[i][j] = line.charAt(j - 1);
            }
        }

        int result = computeShortestPath(grid, start, goal);
        System.out.println(result);
    }

    /**
     * Implementation of Dijkstra's algorithm for the specific grid movement rules.
     */
    private int computeShortestPath(char[][] grid, Point start, Point goal) {
        int rows = grid.length;
        int cols = grid[0].length;
        int[][] distances = new int[rows][cols];

        for (int[] row : distances) {
            Arrays.fill(row, Integer.MAX_VALUE);
        }

        PriorityQueue<Node> priorityQueue = new PriorityQueue<>();

        distances[start.row][start.col] = 0;
        priorityQueue.add(new Node(start, 0));

        while (!priorityQueue.isEmpty()) {
            Node current = priorityQueue.poll();
            int r = current.point.row;
            int c = current.point.col;

            // Standard Dijkstra: skip if we've already found a shorter path to this node
            if (current.distance > distances[r][c]) {
                continue;
            }

            // Explore a 5x5 neighborhood around the current cell
            for (int dr = -2; dr <= 2; dr++) {
                for (int dc = -2; dc <= 2; dc++) {
                    int nr = r + dr;
                    int nc = c + dc;

                    if (isValid(grid, nr, nc)) {
                        // Movement cost: 0 if adjacent (Manhattan distance <= 1), otherwise 1
                        int movementCost = (Math.abs(dr) + Math.abs(dc) <= 1) ? 0 : 1;
                        int newDist = distances[r][c] + movementCost;

                        if (newDist < distances[nr][nc]) {
                            distances[nr][nc] = newDist;
                            priorityQueue.add(new Node(new Point(nr, nc), newDist));
                        }
                    }
                }
            }
        }

        int finalDistance = distances[goal.row][goal.col];
        // Return -1 if the goal is unreachable, using a threshold to prevent overflow logic errors
        return (finalDistance >= Integer.MAX_VALUE / 2) ? -1 : finalDistance;
    }

    private boolean isValid(char[][] grid, int r, int c) {
        return r >= 0 && r < grid.length && c >= 0 && c < grid[0].length && grid[r][c] == '.';
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.*;

/**
 * A program to find the minimum number of "warps" required to move from a 
 * starting position to a target position on a grid.
 */
public class Main {

    public static void main(String[] args) {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            // 1. Parse Grid Dimensions
            String line = br.readLine();
            if (line == null) return;
            StringTokenizer st = new StringTokenizer(line);
            int rows = Integer.parseInt(st.nextToken());
            int cols = Integer.parseInt(st.nextToken());

            // 2. Parse Start Position (1-indexed to 0-indexed)
            st = new StringTokenizer(br.readLine());
            int startRow = Integer.parseInt(st.nextToken()) - 1;
            int startCol = Integer.parseInt(st.nextToken()) - 1;

            // 3. Parse Target Position (1-indexed to 0-indexed)
            st = new StringTokenizer(br.readLine());
            int targetRow = Integer.parseInt(st.nextToken()) - 1;
            int targetCol = Integer.parseInt(st.nextToken()) - 1;

            // 4. Parse Map
            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = br.readLine().toCharArray();
            }

            // 5. Solve
            MazeSolver solver = new MazeSolver(rows, cols, grid);
            int result = solver.solve(new Point(startRow, startCol), new Point(targetRow, targetCol));

            System.out.println(result);

        } catch (IOException | NumberFormatException e) {
            System.err.println("Error reading input: " + e.getMessage());
        }
    }

    /**
     * Represents a coordinate on the grid.
     */
    static final class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Point)) return false;
            Point point = (Point) o;
            return row == point.row && col == point.col;
        }

        @Override
        public int hashCode() {
            return Objects.hash(row, col);
        }
    }

    /**
     * Handles the logic for finding the shortest path based on warp costs.
     */
    static class MazeSolver {
        private static final int[][] ADJACENT_DIRECTIONS = {
            {-1, 0}, {1, 0}, {0, -1}, {0, 1}
        };
        private static final int WARP_RANGE = 2;

        private final int rows;
        private final int cols;
        private final char[][] grid;

        public MazeSolver(int rows, int cols, char[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        /**
         * Uses 0-1 BFS to find the minimum number of warps.
         * Cost 0: Moving to an adjacent '.' cell.
         * Cost 1: Warping to any '.' cell within a 5x5 area.
         */
        public int solve(Point start, Point target) {
            int[][] minWarps = new int[rows][cols];
            for (int[] row : minWarps) {
                Arrays.fill(row, Integer.MAX_VALUE);
            }

            // Deque is used for 0-1 BFS: 
            // Add cost-0 moves to the front, cost-1 moves to the back.
            Deque<Point> deque = new ArrayDeque<>();

            minWarps[start.row][start.col] = 0;
            deque.addFirst(start);

            while (!deque.isEmpty()) {
                Point current = deque.pollFirst();

                if (current.equals(target)) {
                    return minWarps[current.row][current.col];
                }

                // 1. Attempt adjacent moves (Cost 0)
                for (int[] dir : ADJACENT_DIRECTIONS) {
                    int nr = current.row + dir[0];
                    int nc = current.col + dir[1];

                    if (isValid(nr, nc) && isPassable(nr, nc)) {
                        if (minWarps[nr][nc] > minWarps[current.row][current.col]) {
                            minWarps[nr][nc] = minWarps[current.row][current.col];
                            deque.addFirst(new Point(nr, nc));
                        }
                    }
                }

                // 2. Attempt warp moves (Cost 1)
                // A warp covers a 5x5 area centered at the current point.
                for (int r = current.row - WARP_RANGE; r <= current.row + WARP_RANGE; r++) {
                    for (int c = current.col - WARP_RANGE; c <= current.col + WARP_RANGE; c++) {
                        if (isValid(r, c) && isPassable(r, c) && (r != current.row || c != current.col)) {
                            int newWeight = minWarps[current.row][current.col] + 1;
                            if (minWarps[r][c] > newWeight) {
                                minWarps[r][c] = newWeight;
                                deque.addLast(new Point(r, c));
                            }
                        }
                    }
                }
            }

            int finalResult = minWarps[target.row][target.col];
            return finalResult == Integer.MAX_VALUE ? -1 : finalResult;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }

        private boolean isPassable(int r, int c) {
            return grid[r][c] == '.';
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.PriorityQueue;
import java.util.StringTokenizer;

/**
 * A program to find the minimum "magic cost" to traverse a grid.
 * Moving to an adjacent cell (Manhattan distance 1) costs 0.
 * Moving to any other cell within a 5x5 area costs 1.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter writer = new PrintWriter(System.out);

        try {
            solve(reader, writer);
        } finally {
            writer.close();
        }
    }

    private static void solve(FastReader reader, PrintWriter writer) {
        int rows = reader.nextInt();
        int cols = reader.nextInt();

        // Convert 1-based indexing from input to 0-based indexing
        int startRow = reader.nextInt() - 1;
        int startCol = reader.nextInt() - 1;
        int endRow = reader.nextInt() - 1;
        int endCol = reader.nextInt() - 1;

        boolean[][] traversableGrid = new boolean[rows][cols];
        for (int i = 0; i < rows; i++) {
            String line = reader.next();
            for (int j = 0; j < cols; j++) {
                traversableGrid[i][j] = (line.charAt(j) == '.');
            }
        }

        GridPathfinder pathfinder = new GridPathfinder(rows, cols, traversableGrid);
        int result = pathfinder.findMinimumMagicCost(startRow, startCol, endRow, endCol);

        writer.println(result);
    }

    /**
     * Encapsulates the Dijkstra algorithm logic for grid navigation.
     */
    static class GridPathfinder {
        private final int rows;
        private final int cols;
        private final boolean[][] grid;

        public GridPathfinder(int rows, int cols, boolean[][] grid) {
            this.rows = rows;
            this.cols = cols;
            this.grid = grid;
        }

        public int findMinimumMagicCost(int startRow, int startCol, int endRow, int endCol) {
            int[][] minMagicCosts = new int[rows][cols];
            for (int[] row : minMagicCosts) {
                Arrays.fill(row, Integer.MAX_VALUE);
            }

            PriorityQueue<Node> priorityQueue = new PriorityQueue<>();

            minMagicCosts[startRow][startCol] = 0;
            priorityQueue.add(new Node(startRow, startCol, 0));

            while (!priorityQueue.isEmpty()) {
                Node current = priorityQueue.poll();

                // Optimization: if we found a better path to this node already, skip
                if (current.cost > minMagicCosts[current.row][current.col]) {
                    continue;
                }

                // Target reached
                if (current.row == endRow && current.col == endCol) {
                    return current.cost;
                }

                // Explore all cells in the 5x5 neighborhood (radius 2)
                for (int i = -2; i <= 2; i++) {
                    for (int j = -2; j <= 2; j++) {
                        if (i == 0 && j == 0) continue;

                        int nextR = current.row + i;
                        int nextC = current.col + j;

                        if (isValidMove(nextR, nextC)) {
                            int moveCost = calculateMoveCost(i, j);
                            int totalCost = current.cost + moveCost;

                            if (totalCost < minMagicCosts[nextR][nextC]) {
                                minMagicCosts[nextR][nextC] = totalCost;
                                priorityQueue.add(new Node(nextR, nextC, totalCost));
                            }
                        }
                    }
                }
            }

            return minMagicCosts[endRow][endCol] == Integer.MAX_VALUE ? -1 : minMagicCosts[endRow][endCol];
        }

        private boolean isValidMove(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c];
        }

        /**
         * Cost is 0 if cells are adjacent (Manhattan distance 1), otherwise cost is 1.
         */
        private int calculateMoveCost(int deltaRow, int deltaCol) {
            int manhattanDistance = Math.abs(deltaRow) + Math.abs(deltaCol);
            return (manhattanDistance == 1) ? 0 : 1;
        }
    }

    /**
     * Represents a single point in the grid during traversal.
     */
    static class Node implements Comparable<Node> {
        final int row;
        final int col;
        final int cost;

        Node(int row, int col, int cost) {
            this.row = row;
            this.col = col;
            this.cost = cost;
        }

        @Override
        public int compareTo(Node other) {
            return Integer.compare(this.cost, other.cost);
        }
    }

    /**
     * Efficient input reader for large datasets.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader() {
            this.reader = new BufferedReader(new InputStreamReader(System.in));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException("Error reading input", e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solution to find the shortest path on a grid with 0-cost and 1-cost movements.
 * Uses 0-1 BFS algorithm for optimal performance.
 */
public class Main {

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);

        try {
            int height = sc.nextInt();
            int width = sc.nextInt();

            // Input coordinates are 1-based, converting to 0-based
            int startX = sc.nextInt() - 1;
            int startY = sc.nextInt() - 1;
            int endX = sc.nextInt() - 1;
            int endY = sc.nextInt() - 1;

            char[][] board = new char[height][width];
            for (int i = 0; i < height; i++) {
                String line = sc.next();
                board[i] = line.toCharArray();
            }

            Grid grid = new Grid(board, height, width);
            Pathfinder pathfinder = new Pathfinder(grid);

            int result = pathfinder.findShortestPath(new Point(startX, startY), new Point(endX, endY));
            System.out.println(result);

        } catch (Exception e) {
            // In a real-world production app, we would use a proper logging framework
            e.printStackTrace();
        }
    }

    /**
     * Represents a coordinate on the 2D grid.
     */
    private static class Point {
        final int x, y;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    /**
     * Encapsulates the grid data and boundary/validity logic.
     */
    private static class Grid {
        private final char[][] cells;
        private final int height;
        private final int width;

        Grid(char[][] cells, int height, int width) {
            this.cells = cells;
            this.height = height;
            this.width = width;
        }

        boolean isValid(int x, int y) {
            return x >= 0 && x < height && y >= 0 && y < width && cells[x][y] == '.';
        }

        int getHeight() { return height; }
        int getWidth() { return width; }
    }

    /**
     * Contains the logic for finding the shortest path using 0-1 BFS.
     */
    private static class Pathfinder {
        private final Grid grid;
        private static final int[] DX = {-1, 1, 0, 0};
        private static final int[] DY = {0, 0, -1, 1};
        private static final int INF = Integer.MAX_VALUE;

        Pathfinder(Grid grid) {
            this.grid = grid;
        }

        public int findShortestPath(Point start, Point end) {
            int[][] distances = new int[grid.getHeight()][grid.getWidth()];
            for (int[] row : distances) {
                Arrays.fill(row, INF);
            }

            Deque<Point> deque = new ArrayDeque<>();

            distances[start.x][start.y] = 0;
            deque.addFirst(start);

            while (!deque.isEmpty()) {
                Point curr = deque.pollFirst();
                int currentDist = distances[curr.x][curr.y];

                // Optimization: If we reached the destination, we can return early
                // in a 0-1 BFS because the first time we poll a node, it's the shortest path.
                if (curr.x == end.x && curr.y == end.y) {
                    return currentDist;
                }

                // 1. 0-cost movements: Adjacent cells (4-connectivity)
                for (int i = 0; i < 4; i++) {
                    int nx = curr.x + DX[i];
                    int ny = curr.y + DY[i];

                    if (grid.isValid(nx, ny) && distances[nx][ny] > currentDist) {
                        distances[nx][ny] = currentDist;
                        deque.addFirst(new Point(nx, ny));
                    }
                }

                // 2. 1-cost movements: All cells within a 5x5 neighborhood
                for (int dx = -2; dx <= 2; dx++) {
                    for (int dy = -2; dy <= 2; dy++) {
                        int nx = curr.x + dx;
                        int ny = curr.y + dy;

                        if (grid.isValid(nx, ny) && distances[nx][ny] > currentDist + 1) {
                            distances[nx][ny] = currentDist + 1;
                            deque.addLast(new Point(nx, ny));
                        }
                    }
                }
            }

            return distances[end.x][end.y] == INF ? -1 : distances[end.x][end.y];
        }
    }

    /**
     * High-performance input reader.
     */
    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        public FastScanner(InputStream in) {
            br = new BufferedReader(new InputStreamReader(in));
        }

        public String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A solver that finds the shortest path in a grid using 0-1 BFS.
 * Movement rules:
 * - Orthogonal neighbors (up, down, left, right) have a cost of 0.
 * - All cells in a 5x5 neighborhood around the current cell have a cost of 1.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        try {
            int height = reader.nextInt();
            int width = reader.nextInt();
            int startRow = reader.nextInt() - 1;
            int startCol = reader.nextInt() - 1;
            int targetRow = reader.nextInt() - 1;
            int targetCol = reader.nextInt() - 1;

            int[][] grid = new int[height][width];
            for (int r = 0; r < height; r++) {
                String line = reader.next();
                for (int c = 0; c < width; c++) {
                    if (line.charAt(c) == '#') {
                        grid[r][c] = GridNavigator.WALL;
                    } else {
                        grid[r][c] = GridNavigator.INF;
                    }
                }
            }

            GridNavigator navigator = new GridNavigator(height, width, grid);
            int result = navigator.findShortestPath(startRow, startCol, targetRow, targetCol);

            out.println(result);
        } catch (Exception e) {
            // In a production environment, use a logger.
            e.printStackTrace();
        } finally {
            out.flush();
            out.close();
        }
    }

    /**
     * Represents a coordinate and the distance reached at that coordinate.
     */
    private record Node(int row, int col, int distance) {}

    /**
     * Encapsulates the grid navigation logic.
     */
    static class GridNavigator {
        public static final int INF = Integer.MAX_VALUE;
        public static final int WALL = -1;

        private final int rows;
        private final int cols;
        private final int[][] costGrid;

        public GridNavigator(int rows, int cols, int[][] costGrid) {
            this.rows = rows;
            this.cols = cols;
            this.costGrid = costGrid;
        }

        /**
         * Performs a 0-1 Breadth-First Search to find the shortest path.
         */
        public int findShortestPath(int startR, int startC, int targetR, int targetC) {
            if (costGrid[startR][startC] == WALL) return -1;

            Deque<Node> deque = new ArrayDeque<>();
            costGrid[startR][startC] = 0;
            deque.addFirst(new Node(startR, startC, 0));

            while (!deque.isEmpty()) {
                Node current = deque.pollFirst();

                // If we found a better path to this node already, skip processing.
                if (current.distance() > costGrid[current.row()][current.col()]) {
                    continue;
                }

                // 1. Weight-0 moves: Orthogonal neighbors
                int[][] orthogonalMoves = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
                for (int[] move : orthogonalMoves) {
                    int nr = current.row() + move[0];
                    int nc = current.col() + move[1];

                    if (isValid(nr, nc) && costGrid[nr][nc] != WALL) {
                        if (costGrid[nr][nc] > current.distance()) {
                            costGrid[nr][nc] = current.distance();
                            deque.addFirst(new Node(nr, nc, costGrid[nr][nc]));
                        }
                    }
                }

                // 2. Weight-1 moves: 5x5 Neighborhood
                for (int dr = -2; dr <= 2; dr++) {
                    for (int dc = -2; dc <= 2; dc++) {
                        int nr = current.row() + dr;
                        int nc = current.col() + dc;

                        if (isValid(nr, nc) && costGrid[nr][nc] != WALL) {
                            int newDist = current.distance() + 1;
                            if (costGrid[nr][nc] > newDist) {
                                costGrid[nr][nc] = newDist;
                                deque.addLast(new Node(nr, nc, newDist));
                            }
                        }
                    }
                }
            }

            int result = costGrid[targetR][targetC];
            return (result == INF) ? -1 : result;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols;
        }
    }

    /**
     * Efficient input reader.
     */
    static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A program to find the shortest path in a grid-based maze using a 0-1 BFS algorithm.
 * Movement rules:
 * - Adjacent cells (Up, Down, Left, Right) have a cost of 0.
 * - Any cell within a 5x5 area around the current cell has a cost of 1.
 */
public class Main {

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            // Input Parsing
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            // Coordinates are provided as 1-indexed; convert to 0-indexed
            int startRow = reader.nextInt() - 1;
            int startCol = reader.nextInt() - 1;
            int endRow = reader.nextInt() - 1;
            int endCol = reader.nextInt() - 1;

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            // Execution
            MazeSolver solver = new MazeSolver(grid, rows, cols);
            int result = solver.findShortestPath(startRow, startCol, endRow, endCol);

            // Output
            writer.println(result);
        } catch (Exception e) {
            // In a production environment, use a logger
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }

    /**
     * Represents a coordinate in the 2D grid.
     */
    private static class Point {
        final int row;
        final int col;

        Point(int row, int col) {
            this.row = row;
            this.col = col;
        }
    }

    /**
     * Handles the logic for navigating the maze.
     */
    private static class MazeSolver {
        private final char[][] grid;
        private final int rows;
        private final int cols;

        private static final int[] ADJACENT_ROW_OFFSETS = {-1, 1, 0, 0};
        private static final int[] ADJACENT_COL_OFFSETS = {0, 0, -1, 1};
        private static final int INF = Integer.MAX_VALUE;

        public MazeSolver(char[][] grid, int rows, int cols) {
            this.grid = grid;
            this.rows = rows;
            this.cols = cols;
        }

        /**
         * Finds the shortest distance using 0-1 Breadth-First Search.
         * 
         * @return Shortest distance, or -1 if no path exists.
         */
        public int findShortestPath(int startR, int startC, int endR, int endC) {
            if (!isValid(startR, startC) || !isValid(endR, endC)) {
                return -1;
            }

            int[][] distance = new int[rows][cols];
            for (int i = 0; i < rows; i++) {
                Arrays.fill(distance[i], INF);
            }

            Deque<Point> deque = new ArrayDeque<>();

            distance[startR][startC] = 0;
            deque.addFirst(new Point(startR, startC));

            while (!deque.isEmpty()) {
                Point current = deque.removeFirst();
                int r = current.row;
                int c = current.col;

                // Rule 1: Move to adjacent cells with cost 0
                for (int i = 0; i < 4; i++) {
                    int nr = r + ADJACENT_ROW_OFFSETS[i];
                    int nc = c + ADJACENT_COL_OFFSETS[i];

                    if (isValid(nr, nc) && distance[nr][nc] > distance[r][c]) {
                        distance[nr][nc] = distance[r][c];
                        deque.addFirst(new Point(nr, nc));
                    }
                }

                // Rule 2: Move to any cell in a 5x5 area with cost 1
                for (int dr = -2; dr <= 2; dr++) {
                    for (int dc = -2; dc <= 2; dc++) {
                        int nr = r + dr;
                        int nc = c + dc;

                        if (isValid(nr, nc) && distance[nr][nc] > distance[r][c] + 1) {
                            distance[nr][nc] = distance[r][c] + 1;
                            deque.addLast(new Point(nr, nc));
                        }
                    }
                }
            }

            int finalDist = distance[endR][endC];
            return (finalDist == INF) ? -1 : finalDist;
        }

        private boolean isValid(int r, int c) {
            return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != '#';
        }
    }

    /**
     * Fast I/O utility class.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                try {
                    String line = reader.readLine();
                    if (line == null) return null;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    return null;
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}

import java.util.*;
import java.io.*;

/**
 * A solver for finding the shortest path in a grid using a 0-1 BFS algorithm.
 * The movement rules are:
 * 1. Moving to an adjacent cell (Up, Down, Left, Right) costs 0.
 * 2. Jumping to any cell within a 5x5 area centered at the current cell costs 1.
 */
public class GridPathfinder {

    private static final int INF = 1_000_000;

    private final int rows;
    private final int cols;
    private final char[][] grid;

    /**
     * Represents a single coordinate point in the grid.
     */
    private static class Node {
        final int r;
        final int c;

        Node(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    public GridPathfinder(int rows, int cols, char[][] grid) {
        this.rows = rows;
        this.cols = cols;
        this.grid = grid;
    }

    /**
     * Calculates the minimum cost to travel from the start coordinate to the end coordinate.
     *
     * @param startRow Starting row index (0-indexed)
     * @param startCol Starting column index (0-indexed)
     * @param endRow   Target row index (0-indexed)
     * @param endCol   Target column index (0-indexed)
     * @return The minimum cost, or -1 if the destination is unreachable.
     */
    public int findShortestPath(int startRow, int startCol, int endRow, int endCol) {
        int[][] distances = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            Arrays.fill(distances[i], INF);
        }

        // Deque is used for 0-1 BFS: 0-cost moves are added to the front, 1-cost to the back.
        Deque<Node> deque = new ArrayDeque<>();

        distances[startRow][startCol] = 0;
        deque.addFirst(new Node(startRow, startCol));

        // Direction vectors for 0-cost adjacent movement
        int[] dr = {1, 0, -1, 0};
        int[] dc = {0, 1, 0, -1};

        while (!deque.isEmpty()) {
            Node current = deque.removeFirst();
            int r = current.r;
            int c = current.c;

            // Phase 1: 0-cost moves (Adjacent neighbors)
            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];

                if (isValid(nr, nc) && distances[nr][nc] > distances[r][c]) {
                    distances[nr][nc] = distances[r][c];
                    deque.addFirst(new Node(nr, nc));
                }
            }

            // Phase 2: 1-cost moves (Any cell within a 5x5 area)
            for (int dr5 = -2; dr5 <= 2; dr5++) {
                for (int dc5 = -2; dc5 <= 2; dc5++) {
                    int nr = r + dr5;
                    int nc = c + dc5;

                    if (isValid(nr, nc) && distances[nr][nc] > distances[r][c] + 1) {
                        distances[nr][nc] = distances[r][c] + 1;
                        deque.addLast(new Node(nr, nc));
                    }
                }
            }
        }

        int result = distances[endRow][endCol];
        return (result == INF) ? -1 : result;
    }

    /**
     * Validates if the given coordinates are within bounds and not a wall.
     */
    private boolean isValid(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != '#';
    }

    /**
     * Main entry point to handle I/O and execution.
     */
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            if (!scanner.hasNextInt()) return;

            int rows = scanner.nextInt();
            int cols = scanner.nextInt();

            // Input coordinates are 1-indexed in the original logic, converting to 0-indexed.
            int startRow = scanner.nextInt() - 1;
            int startCol = scanner.nextInt() - 1;
            int endRow = scanner.nextInt() - 1;
            int endCol = scanner.nextInt() - 1;

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = scanner.next();
                for (int j = 0; j < cols; j++) {
                    grid[i][j] = line.charAt(j);
                }
            }

            GridPathfinder solver = new GridPathfinder(rows, cols, grid);
            int result = solver.findShortestPath(startRow, startCol, endRow, endCol);

            writer.println(result);

        } catch (NoSuchElementException e) {
            // Handle potential input errors gracefully
        } finally {
            writer.close();
            scanner.close();
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.StringTokenizer;

/**
 * Represents a coordinate on the grid.
 */
record Point(int row, int col) {}

/**
 * Handles the pathfinding logic on a 2D grid using a 0-1 BFS algorithm.
 */
class GridNavigator {
    private static final int INF = 1_000_000_000;
    private static final int[] ADJACENT_DX = {1, -1, 0, 0};
    private static final int[] ADJACENT_DY = {0, 0, 1, -1};
    private static final char WALL = '#';

    private final char[][] grid;
    private final int rows;
    private final int cols;

    public GridNavigator(char[][] grid) {
        this.grid = grid;
        this.rows = grid.length;
        this.cols = grid[0].length;
    }

    /**
     * Calculates the shortest path from start to target.
     * 
     * @param start  The starting point.
     * @param target The destination point.
     * @return The minimum cost to reach the target, or -1 if unreachable.
     */
    public int findShortestPath(Point start, Point target) {
        int[][] dist = new int[rows][cols];
        for (int[] row : dist) {
            Arrays.fill(row, INF);
        }

        Deque<Point> deque = new ArrayDeque<>();

        dist[start.row()][start.col()] = 0;
        deque.addLast(start);

        while (!deque.isEmpty()) {
            Point current = deque.pollFirst();

            // Type 1: Adjacent moves (Cost 0)
            // These are added to the front of the deque to be processed immediately.
            for (int i = 0; i < 4; i++) {
                int nextR = current.row() + ADJACENT_DX[i];
                int nextC = current.col() + ADJACENT_DY[i];

                if (isSafe(nextR, nextC) && dist[nextR][nextC] > dist[current.row()][current.col()]) {
                    dist[nextR][nextC] = dist[current.row()][current.col()];
                    deque.addFirst(new Point(nextR, nextC));
                }
            }

            // Type 2: 5x5 Area moves (Cost 1)
            // These are added to the back of the deque.
            for (int dr = -2; dr <= 2; dr++) {
                for (int dc = -2; dc <= 2; dc++) {
                    int nextR = current.row() + dr;
                    int nextC = current.col() + dc;

                    if (isSafe(nextR, nextC) && dist[nextR][nextC] > dist[current.row()][current.col()] + 1) {
                        dist[nextR][nextC] = dist[current.row()][current.col()] + 1;
                        deque.addLast(new Point(nextR, nextC));
                    }
                }
            }
        }

        int result = dist[target.row()][target.col()];
        return (result >= INF) ? -1 : result;
    }

    private boolean isSafe(int r, int c) {
        return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != WALL;
    }
}

/**
 * Utility class for fast I/O operations.
 */
class FastReader {
    private final BufferedReader br;
    private StringTokenizer st;

    public FastReader() {
        br = new BufferedReader(new InputStreamReader(System.in));
    }

    public String next() {
        while (st == null || !st.hasMoreElements()) {
            try {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            } catch (IOException e) {
                throw new RuntimeException("Error reading input", e);
            }
        }
        return st.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(next());
    }
}

public class Main {
    public static void main(String[] args) {
        FastReader reader = new FastReader();
        PrintWriter writer = new PrintWriter(System.out);

        try {
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            // Convert 1-based indexing from input to 0-based indexing
            int startRow = reader.nextInt() - 1;
            int startCol = reader.nextInt() - 1;
            int targetRow = reader.nextInt() - 1;
            int targetCol = reader.nextInt() - 1;

            char[][] grid = new char[rows][cols];
            for (int i = 0; i < rows; i++) {
                grid[i] = reader.next().toCharArray();
            }

            GridNavigator navigator = new GridNavigator(grid);
            int result = navigator.findShortestPath(
                    new Point(startRow, startCol),
                    new Point(targetRow, targetCol)
            );

            writer.println(result);
        } catch (Exception e) {
            // In a real production environment, use a proper logger.
            e.printStackTrace();
        } finally {
            writer.close();
        }
    }
}

import java.io.*;
import java.util.*;

/**
 * A program to find the minimum cost to travel between two points on a grid.
 * Movement costs:
 * - Cardinal directions (Up, Down, Left, Right): 0 cost.
 * - Any cell within a 5x5 area: 1 cost.
 */
public class Main {
    private static final int INF = Integer.MAX_VALUE / 2;

    public static void main(String[] args) {
        FastReader reader = new FastReader(System.in);
        PrintWriter writer = new PrintWriter(System.out);

        try {
            // Read grid dimensions
            int rows = reader.nextInt();
            int cols = reader.nextInt();

            // Read start and end coordinates (converting 1-indexed to 0-indexed)
            int startRow = reader.nextInt() - 1;
            int startCol = reader.nextInt() - 1;
            int endRow = reader.nextInt() - 1;
            int endCol = reader.nextInt() - 1;

            // Read grid layout
            boolean[][] isWalkable = new boolean[rows][cols];
            for (int i = 0; i < rows; i++) {
                String line = reader.next();
                for (int j = 0; j < cols; j++) {
                    if (line.charAt(j) == '.') {
                        isWalkable[i][j] = true;
                    }
                }
            }

            int result = solve(rows, cols, startRow, startCol, endRow, endCol, isWalkable);
            writer.println(result);

        } catch (IOException | NoSuchElementException e) {
            // In a production environment, use a logger
        } finally {
            writer.close();
        }
    }

    /**
     * Performs a 0-1 Breadth-First Search to find the shortest path.
     */
    private static int solve(int rows, int cols, int startR, int startC, 
                             int endR, int endC, boolean[][] isWalkable) {

        // Boundary and validity checks
        if (!isValid(startR, startC, rows, cols, isWalkable) || 
            !isValid(endR, endC, rows, cols, isWalkable)) {
            return -1;
        }

        int[][] dist = new int[rows][cols];
        for (int[] row : dist) {
            Arrays.fill(row, INF);
        }

        Deque<Point> deque = new ArrayDeque<>();
        dist[startR][startC] = 0;
        deque.addFirst(new Point(startR, startC));

        // Cardinal directions for 0-cost movement
        int[] dr = {1, -1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        while (!deque.isEmpty()) {
            Point current = deque.pollFirst();
            int r = current.r;
            int c = current.c;

            // 1. Try cardinal moves (Weight = 0)
            for (int i = 0; i < 4; i++) {
                int nr = r + dr[i];
                int nc = c + dc[i];

                if (isValid(nr, nc, rows, cols, isWalkable)) {
                    if (dist[nr][nc] > dist[r][c]) {
                        dist[nr][nc] = dist[r][c];
                        deque.addFirst(new Point(nr, nc));
                    }
                }
            }

            // 2. Try 5x5 area moves (Weight = 1)
            for (int i = -2; i <= 2; i++) {
                for (int j = -2; j <= 2; j++) {
                    int nr = r + i;
                    int nc = c + j;

                    if (isValid(nr, nc, rows, cols, isWalkable)) {
                        if (dist[nr][nc] > dist[r][c] + 1) {
                            dist[nr][nc] = dist[r][c] + 1;
                            deque.addLast(new Point(nr, nc));
                        }
                    }
                }
            }
        }

        int finalDist = dist[endR][endC];
        return (finalDist >= INF) ? -1 : finalDist;
    }

    private static boolean isValid(int r, int c, int rows, int cols, boolean[][] isWalkable) {
        return r >= 0 && r < rows && c >= 0 && c < cols && isWalkable[r][c];
    }

    /**
     * Represents a coordinate on the grid.
     */
    private static class Point {
        final int r, c;
        Point(int r, int c) {
            this.r = r;
            this.c = c;
        }
    }

    /**
     * High-performance input reader.
     */
    private static class FastReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public FastReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreElements()) {
                String line = reader.readLine();
                if (line == null) return null;
                tokenizer = new StringTokenizer(line);
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}
